INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87351, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海盗是在海上抢别人东西的坏人。", "primary_collocate": null, "pronunciation": "hǎi dào", "ipa": "xai˨˩˦ tau˥˩", "syllable_count": 2, "sentences": [{"text": "电影里的海盗戴着黑帽子，还有一条假腿。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "万圣节，弟弟打扮成海盗，拿着一把玩具刀。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海盗坐在船上，黑旗在风中飘着。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏海盗把金子藏在了小岛上。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "故事里的海盗抢了国王的船，国王很生气。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海盗看见一条大船，马上开船追上去。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个海盗只有一只眼睛，孩子们都怕他。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想看有海盗和宝藏的故事书。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海盗抢走别人的东西，所以大家都不喜欢他们。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我讲过一个海盗的故事。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "伙", "label": "量词"}, {"form": "海盗旗", "label": "复合词"}, {"form": "海盜", "label": "繁体"}], "register": "口语", "sense_fingerprint": "在海上抢别人东西的坏人（故事、电影、游戏里的海盗形象）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157c64-73c7-4e54-9585-b5a2f818129e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87351, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "海盗", "is_correct": true, "explanation": "正确答案。海盗（hǎi dào）指在海上抢别人东西的坏人。"}, {"text": "海岛", "is_correct": false, "explanation": "dǎo（第三声）与 dào（第四声）声调不同，意思是海岛。"}, {"text": "海豹", "is_correct": false, "explanation": "bào 与 dào 声母不同（b 与 d），意思是海豹。"}, {"text": "改道", "is_correct": false, "explanation": "gǎi 与 hǎi 声母不同（g 与 h），意思是改变行进路线。"}], "explanations": {"海盗": "正确答案。海盗（hǎi dào）指在海上抢别人东西的坏人。", "海岛": "dǎo（第三声）与 dào（第四声）声调不同，意思是海岛。", "海豹": "bào 与 dào 声母不同（b 与 d），意思是海豹。", "改道": "gǎi 与 hǎi 声母不同（g 与 h），意思是改变行进路线。"}, "sentence_index": null, "correct_answer": "海盗"}, "level_3": {"options": [{"text": "海盗", "is_correct": true, "explanation": "正确。电影里的海盗形象常戴黑帽、有假腿，与句中描写相符。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，不会戴帽子，句意荒谬。"}, {"text": "大树", "is_correct": false, "explanation": "配价：“还有一条假腿”要求主语是有腿的人或动物，“大树”没有腿。"}, {"text": "皮鞋", "is_correct": false, "explanation": "搭配：“戴着黑帽子”要求主语能戴帽子，“皮鞋”不能戴。"}], "explanations": {"海盗": "正确。电影里的海盗形象常戴黑帽、有假腿，与句中描写相符。", "课本": "语义：课本是书，不会戴帽子，句意荒谬。", "大树": "配价：“还有一条假腿”要求主语是有腿的人或动物，“大树”没有腿。", "皮鞋": "搭配：“戴着黑帽子”要求主语能戴帽子，“皮鞋”不能戴。"}, "sentence_index": 0, "correct_answer": "海盗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "街上走来一头海盗。", "explanation": "量词错误。这里应该用〈个〉或〈伙〉。“头”用于大牲畜，不用于指人的海盗。"}, {"text": "院子里种着一棵海盗。", "explanation": "量词错误。这里应该用〈个〉或〈伙〉。“棵”用于植物，不用于指人的海盗。"}, {"text": "书架上摆着一本海盗。", "explanation": "量词错误。这里应该用〈个〉或〈伙〉。“本”用于书册，不用于指人的海盗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87351, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "海盗", "is_correct": true, "explanation": "正确答案。海盗（hǎi dào）指在海上抢别人东西的坏人。"}, {"text": "海报", "is_correct": false, "explanation": "bào 与 dào 声母不同（b 与 d），意思是海报。"}, {"text": "海带", "is_correct": false, "explanation": "dài 与 dào 韵母不同（ai 与 ao），意思是海带，一种海藻。"}, {"text": "黑道", "is_correct": false, "explanation": "hēi（第一声）与 hǎi（第三声）声调不同，意思是黑道，指黑社会。"}], "explanations": {"海盗": "正确答案。海盗（hǎi dào）指在海上抢别人东西的坏人。", "海报": "bào 与 dào 声母不同（b 与 d），意思是海报。", "海带": "dài 与 dào 韵母不同（ai 与 ao），意思是海带，一种海藻。", "黑道": "hēi（第一声）与 hǎi（第三声）声调不同，意思是黑道，指黑社会。"}, "sentence_index": null, "correct_answer": "海盗"}, "level_3": {"options": [{"text": "海盗", "is_correct": true, "explanation": "正确。“那个海盗只有一只眼睛”描写的是人的外貌，与句意相符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子没有眼睛，“只有一只眼睛”的描写不通。"}, {"text": "大海", "is_correct": false, "explanation": "语义：大海是水域，不会只有一只眼睛，句意荒谬。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是人，不会“只有一只眼睛”，也不会让孩子们怕“他”。"}], "explanations": {"海盗": "正确。“那个海盗只有一只眼睛”描写的是人的外貌，与句意相符。", "房子": "语义：房子没有眼睛，“只有一只眼睛”的描写不通。", "大海": "语义：大海是水域，不会只有一只眼睛，句意荒谬。", "汽车": "语义：汽车不是人，不会“只有一只眼睛”，也不会让孩子们怕“他”。"}, "sentence_index": 6, "correct_answer": "海盗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "海盗在大路上拦住了一辆汽车。", "explanation": "这里应该用〈劫匪〉。海盗指海上劫掠的人，陆上大路拦车要说劫匪。"}, {"text": "海盗深夜闯进银行，抢走了钱。", "explanation": "这里应该用〈匪徒〉。海盗只在海上活动，闯进银行抢钱应说匪徒。"}, {"text": "海盗悄悄溜进我家，偷走了电视。", "explanation": "这里应该用〈窃贼〉。海盗指海上劫掠者，入室偷窃应说窃贼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87351, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两个海盗们在海边找到了一箱金子。", "corrected_sentence": "两个海盗在海边找到了一箱金子。", "error_description": "错在“们”：“两个”已表示数量，名词后不能再加“们”，应说“两个海盗”，不能说“两个海盗们”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87351, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只海盗戴着黑帽子，手里拿着一把刀。", "corrected_sentence": "那个海盗戴着黑帽子，手里拿着一把刀。", "error_description": "量词错误：指人的“海盗”应用量词“个”或“伙”，不能用“只”。应说“那个海盗”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
