INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87352, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在海上抢劫船只和财物的强盗。", "primary_collocate": null, "pronunciation": "hǎi dào", "ipa": "xai˨˩˦ tau˥˩", "syllable_count": 2, "sentences": [{"text": "海盗在海上抢走了商人的货物。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这艘货船在海上遇到了海盗。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海军派了两条船去打击海盗。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，海盗常常在海上拦住来往的商船。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那些海盗抢了船上所有的财物，还扣下了船长。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个海盗手里拿着一把长刀，站在船头。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的海军抓住了十几个海盗。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海盗为什么喜欢把宝藏埋在岛上？", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "近年来，这片海上的海盗少多了。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读过一本写海盗的历史书。", "target_word": "海盗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "伙", "label": "量词"}, {"form": "海盗船", "label": "复合词"}, {"form": "海盜", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在海上抢劫船只和财物的强盗（历史或新闻语境中的真实海盗）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '50157c64-73c7-4e54-9585-b5a2f818129e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87352, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "海盗", "is_correct": true, "explanation": "正确答案。海盗（hǎi dào）指在海上抢劫船只和财物的强盗。"}, {"text": "海岛", "is_correct": false, "explanation": "dǎo（第三声）与 dào（第四声）声调不同，意思是海岛。"}, {"text": "海报", "is_correct": false, "explanation": "bào 与 dào 声母不同（b 与 d），意思是海报。"}, {"text": "海带", "is_correct": false, "explanation": "dài 与 dào 韵母不同（ai 与 ao），意思是海带，一种海藻。"}], "explanations": {"海盗": "正确答案。海盗（hǎi dào）指在海上抢劫船只和财物的强盗。", "海岛": "dǎo（第三声）与 dào（第四声）声调不同，意思是海岛。", "海报": "bào 与 dào 声母不同（b 与 d），意思是海报。", "海带": "dài 与 dào 韵母不同（ai 与 ao），意思是海带，一种海藻。"}, "sentence_index": null, "correct_answer": "海盗"}, "level_3": {"options": [{"text": "海盗", "is_correct": true, "explanation": "正确。海盗是在海上抢劫的人，可以做“抢走”的主语。"}, {"text": "海军", "is_correct": false, "explanation": "语义：海军是国家的武装力量，不会在海上抢劫商人，句意不通。"}, {"text": "货物", "is_correct": false, "explanation": "搭配：“抢走”的主语要能施动，“货物”是物品，不能抢。"}, {"text": "农民", "is_correct": false, "explanation": "语义：农民在陆地上耕种，不会在海上抢劫商人的货物，句意不通。"}], "explanations": {"海盗": "正确。海盗是在海上抢劫的人，可以做“抢走”的主语。", "海军": "语义：海军是国家的武装力量，不会在海上抢劫商人，句意不通。", "货物": "搭配：“抢走”的主语要能施动，“货物”是物品，不能抢。", "农民": "语义：农民在陆地上耕种，不会在海上抢劫商人的货物，句意不通。"}, "sentence_index": 0, "correct_answer": "海盗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "海盗在山里拦住过路的行人。", "explanation": "这里应该用〈强盗〉。海盗指在海上劫掠的人，在山里拦路抢劫要用强盗。"}, {"text": "海盗趁人不注意，偷走了钱包。", "explanation": "这里应该用〈盗贼〉。海盗只指海上劫掠者，街上偷钱包应说盗贼。"}, {"text": "海盗在草原上抢走了牧民的羊群。", "explanation": "这里应该用〈土匪〉。海盗只在海上活动，草原上抢牧民的羊群要说土匪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87352, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "海盗", "is_correct": true, "explanation": "正确答案。海盗（hǎi dào）指在海上抢劫船只和财物的强盗。"}, {"text": "海豹", "is_correct": false, "explanation": "bào 与 dào 声母不同（b 与 d），意思是海豹。"}, {"text": "黑道", "is_correct": false, "explanation": "hēi（第一声）与 hǎi（第三声）声调不同，意思是黑道，指黑社会。"}, {"text": "改道", "is_correct": false, "explanation": "gǎi 与 hǎi 声母不同（g 与 h），意思是改变行进路线。"}], "explanations": {"海盗": "正确答案。海盗（hǎi dào）指在海上抢劫船只和财物的强盗。", "海豹": "bào 与 dào 声母不同（b 与 d），意思是海豹。", "黑道": "hēi（第一声）与 hǎi（第三声）声调不同，意思是黑道，指黑社会。", "改道": "gǎi 与 hǎi 声母不同（g 与 h），意思是改变行进路线。"}, "sentence_index": null, "correct_answer": "海盗"}, "level_3": {"options": [{"text": "海盗", "is_correct": true, "explanation": "正确。海军抓住的正是海盗，“抓住”的对象是人。"}, {"text": "萝卜", "is_correct": false, "explanation": "语义：萝卜不是海军抓捕的对象，句意荒谬。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“咖啡”是不可数的物质名词，不能用“十几个”计数。"}, {"text": "课本", "is_correct": false, "explanation": "语义：课本是书，海军不会去抓捕它，句意不通。"}], "explanations": {"海盗": "正确。海军抓住的正是海盗，“抓住”的对象是人。", "萝卜": "语义：萝卜不是海军抓捕的对象，句意荒谬。", "咖啡": "搭配：“咖啡”是不可数的物质名词，不能用“十几个”计数。", "课本": "语义：课本是书，海军不会去抓捕它，句意不通。"}, "sentence_index": 6, "correct_answer": "海盗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们村来了一本海盗。", "explanation": "量词错误。这里应该用〈个〉或〈伙〉。“本”用于书册，不用于指人的海盗。"}, {"text": "码头上站着一条海盗。", "explanation": "量词错误。这里应该用〈个〉或〈伙〉。“条”用于细长的物品，不用于指人的海盗。"}, {"text": "岸边站着一把海盗。", "explanation": "量词错误。这里应该用〈个〉或〈伙〉。“把”用于有柄的器具，不用于指人的海盗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87352, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只海盗在港口抢走了几箱货物。", "corrected_sentence": "一个海盗在港口抢走了几箱货物。", "error_description": "量词错误：指人的“海盗”应用量词“个”或“伙”，不能用“只”（“只”多用于动物和小件物品）。应说“一个海盗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87352, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "三个海盗们在岛上藏了宝藏。", "corrected_sentence": "三个海盗在岛上藏了宝藏。", "error_description": "错在“们”：“三个”已表示数量，名词后不能再加“们”，应说“三个海盗”，不能说“三个海盗们”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '94607403-b557-4704-997b-e13101ad41c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
