INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87353, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "到底是问到最后，想知道真正的样子。", "primary_collocate": null, "pronunciation": "dào dǐ", "ipa": "tɑʊ˥˩ ti˨˩˦", "syllable_count": 2, "sentences": [{"text": "这到底是什么意思？", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你到底喜欢哪一个？", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到底几岁了？", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到底谁才是你的朋友？", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你昨天到底去哪儿了？", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题到底该怎么办？", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们到底在吵什么？", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "到底是红的好，还是蓝的好？", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他到底要不要来参加？", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服到底多少钱？", "target_word": "到底", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "到底：追问到最后，想知道真实情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02e6c952-5557-4423-80e1-8c7df400d0c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87353, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "到底", "is_correct": true, "explanation": "到底：副词，表示追问到最后、想知道真实情况，是本题的正确答案。"}, {"text": "倒地", "is_correct": false, "explanation": "dǎo dì（第三、第四声）与 dào dǐ 声调不同，意思是“摔倒在地”。"}, {"text": "到顶", "is_correct": false, "explanation": "dǐng 比 dǐ 多一个 ng 韵尾，意思是“到达顶点”。"}, {"text": "道地", "is_correct": false, "explanation": "dì（第四声）与 dǐ（第三声）声调不同，意思是“地道、纯正”。"}], "explanations": {"到底": "到底：副词，表示追问到最后、想知道真实情况，是本题的正确答案。", "倒地": "dǎo dì（第三、第四声）与 dào dǐ 声调不同，意思是“摔倒在地”。", "到顶": "dǐng 比 dǐ 多一个 ng 韵尾，意思是“到达顶点”。", "道地": "dì（第四声）与 dǐ（第三声）声调不同，意思是“地道、纯正”。"}, "sentence_index": null, "correct_answer": "到底"}, "level_3": {"options": [{"text": "到底", "is_correct": true, "explanation": "到底：表示追问到最后，与“是什么意思”的追问相合。"}, {"text": "已经", "is_correct": false, "explanation": "搭配：“已经”表示已经发生的事，不能用来修饰问“是什么意思”的疑问。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示故意与情理相反，与这里的追问不合。"}, {"text": "确实", "is_correct": false, "explanation": "语义：“确实”表示肯定某事真实，与句中追问的语气不符。"}], "explanations": {"到底": "到底：表示追问到最后，与“是什么意思”的追问相合。", "已经": "搭配：“已经”表示已经发生的事，不能用来修饰问“是什么意思”的疑问。", "偏偏": "语义：“偏偏”表示故意与情理相反，与这里的追问不合。", "确实": "语义：“确实”表示肯定某事真实，与句中追问的语气不符。"}, "sentence_index": 0, "correct_answer": "到底"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我到底有两个哥哥。", "explanation": "这里应该用〈只〉，表示数量有限；“到底”用于追问，不能用在这样的陈述句里。"}, {"text": "连老师到底不知道这件事。", "explanation": "这里应该用〈都〉，构成“连……都……”的强调；“到底”不能用在这个结构里。"}, {"text": "他的闹钟五点到底了。", "explanation": "这里应该用〈响〉，表示闹钟发出声音；“到底”表示追问或最终结果，不表示闹钟响起。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87353, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "到底", "is_correct": true, "explanation": "到底：表示追问究竟，与“在吵什么”的追问相合。"}, {"text": "明明", "is_correct": false, "explanation": "语义：“明明”强调与事实相反，与“在吵什么”的追问不合。"}, {"text": "也", "is_correct": false, "explanation": "搭配：“也”要与前文呼应，句中单独用“也”不成立。"}, {"text": "一定", "is_correct": false, "explanation": "语义：“一定”表示肯定的推断，与追问“在吵什么”的语气不符。"}], "explanations": {"到底": "到底：表示追问究竟，与“在吵什么”的追问相合。", "明明": "语义：“明明”强调与事实相反，与“在吵什么”的追问不合。", "也": "搭配：“也”要与前文呼应，句中单独用“也”不成立。", "一定": "语义：“一定”表示肯定的推断，与追问“在吵什么”的语气不符。"}, "sentence_index": 6, "correct_answer": "到底"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我吃了到底饭。", "explanation": "这里应该用〈吃完〉，表示动作完成；“到底”不能插在“了”和宾语之间。"}, {"text": "这口井很到底深。", "explanation": "“到底”不能插在“很”和“深”之间；这里应直接说〈这口井很深〉。"}, {"text": "他每天早上到底去跑步。", "explanation": "这里应该用〈都〉，表示每次如此；“到底”用于追问，不能表示习惯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87353, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这道题到底了对不对？", "corrected_sentence": "这道题到底对不对？", "error_description": "“了”不能加在“到底”后面，“到底了”语法不通，应说“这道题到底对不对”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87353, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个方案到底的行不行？", "corrected_sentence": "这个方案到底行不行？", "error_description": "“到底”是副词，后面不能加“的”；“到底的行不行”语法不对，应说“到底行不行”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
