INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87355, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "士兵是军队里的兵，要听命令去打仗或站岗。", "primary_collocate": null, "pronunciation": "shì bīng", "ipa": "ʂɻ̩˥˩ piŋ˥", "syllable_count": 2, "sentences": [{"text": "士兵要听命令，不能自己决定。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，士兵站在门口守着。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位士兵每天早上五点起床。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争开始了，士兵们拿着枪出发。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个士兵站了一夜，一动不动。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵向长官敬了一个礼。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雪了，门口的士兵还在站岗。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵们每天都要训练。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个士兵很勇敢，没有害怕过。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想当士兵，保护自己的国家。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一名士兵", "label": "量词"}, {"form": "一个士兵", "label": "量词"}, {"form": "士兵们", "label": "复数"}], "register": "中性", "sense_fingerprint": "军队里听命令、打仗或站岗的兵", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1493551b-beb8-436c-890d-5f7aa674fb8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87355, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "士兵", "is_correct": true, "explanation": "正确：“士兵”是军队里听命令的兵，填入后与“听命令、不能自己决定”的语境相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不能听命令，也谈不上“自己决定”。"}, {"text": "太阳", "is_correct": false, "explanation": "语义：太阳是天体，不会听命令，也没有“自己决定”的问题。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会听命令，也谈不上“自己决定”。"}], "explanations": {"士兵": "正确：“士兵”是军队里听命令的兵，填入后与“听命令、不能自己决定”的语境相符。", "石头": "语义：石头没有生命，不能听命令，也谈不上“自己决定”。", "太阳": "语义：太阳是天体，不会听命令，也没有“自己决定”的问题。", "桌子": "语义：桌子是家具，不会听命令，也谈不上“自己决定”。"}, "sentence_index": 0, "correct_answer": "士兵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他三十岁就当上了士兵，负责指挥整个连队。", "explanation": "这里应该用〈军官〉。指挥连队的是军官，士兵是普通战士，不负责指挥。"}, {"text": "他是一名士兵，负责带领几十名新兵训练。", "explanation": "这里应该用〈士官〉。带领新兵训练的是士官，士兵不负责带队。"}, {"text": "这位士兵每天在作战室里制定作战方案。", "explanation": "这里应该用〈军官〉。在作战室里制定作战方案的是军官，普通士兵不参与这类决策。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87355, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "士兵", "is_correct": true, "explanation": "正确：“士兵”是值岗站哨的兵，填入后与“还在站岗”的语境相符。"}, {"text": "行人", "is_correct": false, "explanation": "语义：行人只是路过，不在门口值岗，与“还在站岗”不合。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是来参观的，不承担站岗任务。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师负责做饭，不承担站岗任务，与“还在站岗”不合。"}], "explanations": {"士兵": "正确：“士兵”是值岗站哨的兵，填入后与“还在站岗”的语境相符。", "行人": "语义：行人只是路过，不在门口值岗，与“还在站岗”不合。", "游客": "语义：游客是来参观的，不承担站岗任务。", "厨师": "语义：厨师负责做饭，不承担站岗任务，与“还在站岗”不合。"}, "sentence_index": 6, "correct_answer": "士兵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想当一只士兵，保护自己的国家。", "explanation": "量词用错。指人的“士兵”应该用“名”或“个”，不能用“只”（“只”多用于动物或小件东西）。"}, {"text": "我弟弟去年当上了一条士兵。", "explanation": "量词用错。“条”用于细长的东西，指人的“士兵”应该用“名”。"}, {"text": "那张士兵在训练场上跑得很快。", "explanation": "量词用错。“张”用于平面的东西，指人的“士兵”应该用“名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87355, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一个士兵们很快就到了。", "corrected_sentence": "一个士兵很快就到了。", "error_description": "错误形式：“一个士兵们”；正确形式：“一个士兵”。“一个”表示单数，“们”表示复数，两者不能同时用于同一个名词。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87355, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月他终于当上了一棵士兵。", "corrected_sentence": "这个月他终于当上了士兵。", "error_description": "错误形式：“一棵士兵”；正确形式：“士兵”（或“一名士兵”）。“棵”用于树木，指人的“士兵”不能用它来计量。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
