INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87356, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87356, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "军队中的普通战士。", "primary_collocate": null, "pronunciation": "shì bīng", "ipa": "ʂɻ̩˥˩ piŋ˥", "syllable_count": 2, "sentences": [{"text": "他在军队里只是一名普通士兵。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位将军以前也是一个士兵。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从士兵到军官，他用了十年。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "军队里有军官，也有士兵。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他十八岁就成了一名士兵。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支军队有一万名士兵。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位年轻的士兵还不到二十岁。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "士兵的工资比军官的低一些。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的主人公是一位老士兵。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想当军官，只想当士兵。", "target_word": "士兵", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一名士兵", "label": "量词"}, {"form": "一个士兵", "label": "量词"}, {"form": "士兵们", "label": "复数"}], "register": "中性", "sense_fingerprint": "军队中不是军官的普通战士", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1493551b-beb8-436c-890d-5f7aa674fb8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87356, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "士兵", "is_correct": true, "explanation": "正确：“士兵”指军队中的普通战士，与“只是一名普通”的身份相符。"}, {"text": "将军", "is_correct": false, "explanation": "语义：将军是高级军官，与“只是一名普通”的身份矛盾。"}, {"text": "上校", "is_correct": false, "explanation": "语义：上校是军官军衔，与“只是一名普通”的说法矛盾。"}, {"text": "教授", "is_correct": false, "explanation": "语义：“教授”是学术职称，不是军队里普通战士的身份。"}], "explanations": {"士兵": "正确：“士兵”指军队中的普通战士，与“只是一名普通”的身份相符。", "将军": "语义：将军是高级军官，与“只是一名普通”的身份矛盾。", "上校": "语义：上校是军官军衔，与“只是一名普通”的说法矛盾。", "教授": "语义：“教授”是学术职称，不是军队里普通战士的身份。"}, "sentence_index": 0, "correct_answer": "士兵"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他毕业后成了一名士兵，负责指挥整个营。", "explanation": "这里应该用〈军官〉。指挥一个营的是军官，士兵只是普通战士，不负责指挥。"}, {"text": "他是一名士兵，负责带领全排执行任务。", "explanation": "这里应该用〈排长〉。带领全排执行任务的是排长，普通士兵不担任这一职务。"}, {"text": "这位士兵常常在指挥部里决定整场战役的进攻方向。", "explanation": "这里应该用〈将军〉。决定整场战役方向的是将军，普通士兵没有这样的决策权。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87356, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "士兵", "is_correct": true, "explanation": "正确：“士兵”是年轻的普通战士，与“还不到二十岁”的语境相符。"}, {"text": "老兵", "is_correct": false, "explanation": "搭配：“年轻的”与“老兵”搭配相悖，“老兵”指资历深的战士。"}, {"text": "老人", "is_correct": false, "explanation": "语义：“老人”年纪大，与“年轻的”矛盾。"}, {"text": "中年人", "is_correct": false, "explanation": "语义：“中年人”年龄已偏大，与“年轻的”和“还不到二十岁”矛盾。"}], "explanations": {"士兵": "正确：“士兵”是年轻的普通战士，与“还不到二十岁”的语境相符。", "老兵": "搭配：“年轻的”与“老兵”搭配相悖，“老兵”指资历深的战士。", "老人": "语义：“老人”年纪大，与“年轻的”矛盾。", "中年人": "语义：“中年人”年龄已偏大，与“年轻的”和“还不到二十岁”矛盾。"}, "sentence_index": 6, "correct_answer": "士兵"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一头士兵，在部队里认真训练。", "explanation": "量词用错。“头”用于牲畜，指人的“士兵”应该用“名”。"}, {"text": "我哥哥是一把士兵，每天在营区站岗。", "explanation": "量词用错。“把”用于有柄的东西，指人的“士兵”应该用“名”。"}, {"text": "那棵士兵在操场上排队。", "explanation": "量词用错。“棵”用于树木，指人的“士兵”应该用“名”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87356, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一名士兵们在门口站岗。", "corrected_sentence": "一名士兵在门口站岗。", "error_description": "错误形式：“一名士兵们”；正确形式：“一名士兵”。“一名”已表示单数，不能再加“们”表示复数。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87356, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他去年才当上了一条士兵。", "corrected_sentence": "他去年才当上了士兵。", "error_description": "错误形式：“一条士兵”；正确形式：“士兵”（或“一名士兵”）。“条”用于细长的东西，指人应该用“名”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87357, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "温和", "is_correct": true, "explanation": "温和指性情或动作不猛烈，与凶猛相对，是反义词。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白，与猛没有反义关系。"}, {"text": "遥远", "is_correct": false, "explanation": "遥远指距离很远，与猛没有反义关系。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮指光线充足，与猛没有反义关系。"}], "correct_answer": "温和", "explanations": {"温和": "温和指性情或动作不猛烈，与凶猛相对，是反义词。", "清楚": "清楚指明白，与猛没有反义关系。", "遥远": "遥远指距离很远，与猛没有反义关系。", "明亮": "明亮指光线充足，与猛没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87357, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "温顺", "is_correct": true, "explanation": "温顺指性情柔和、不凶暴，与凶猛相对，是反义词。"}, {"text": "甜美", "is_correct": false, "explanation": "甜美指味道甜、声音好听，与猛没有反义关系。"}, {"text": "厚实", "is_correct": false, "explanation": "厚实指厚度大、结实，与猛没有反义关系。"}, {"text": "陡峭", "is_correct": false, "explanation": "陡峭指坡度很大，与猛没有反义关系。"}], "correct_answer": "温顺", "explanations": {"温顺": "温顺指性情柔和、不凶暴，与凶猛相对，是反义词。", "甜美": "甜美指味道甜、声音好听，与猛没有反义关系。", "厚实": "厚实指厚度大、结实，与猛没有反义关系。", "陡峭": "陡峭指坡度很大，与猛没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87357, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "猛是很有力、很凶，一下子很快。", "primary_collocate": null, "pronunciation": "měng", "ipa": "mɤŋ˨˩", "syllable_count": 1, "sentences": [{"text": "他一拳打得又快又猛。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只老虎看起来很猛。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他踢球的力量很猛，球飞进了网里。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对手的攻势太猛了，我们挡不住。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个拳击手出拳又重又猛。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他跑得很猛，一下子冲到了最前面。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条大狗很猛，我不敢靠近。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喝水喝得太猛，一下子呛住了。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个球员打球很猛，经常把对手撞倒。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开车开得很猛，坐车的人都害怕。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "猛烈", "label": "复合"}, {"form": "凶猛", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容人或动物的动作、力量很大、很凶、很快，如出拳猛、踢得猛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d04d293-e650-4428-be70-164f690aefe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87357, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "蒙", "is_correct": false, "explanation": "méng（第二声）与 měng（第三声）声调不同，意思是遮盖、蒙住。"}, {"text": "猛", "is_correct": true, "explanation": "猛 měng：指力量大、很凶、很快，是正确答案。"}, {"text": "梦", "is_correct": false, "explanation": "mèng（第四声）与 měng（第三声）声调不同，意思是梦。"}, {"text": "蟒", "is_correct": false, "explanation": "mǎng 与 měng 声调相同，韵母不同（ang 与 eng），意思是蟒蛇。"}], "explanations": {"蒙": "méng（第二声）与 měng（第三声）声调不同，意思是遮盖、蒙住。", "猛": "猛 měng：指力量大、很凶、很快，是正确答案。", "梦": "mèng（第四声）与 měng（第三声）声调不同，意思是梦。", "蟒": "mǎng 与 měng 声调相同，韵母不同（ang 与 eng），意思是蟒蛇。"}, "sentence_index": null, "correct_answer": "猛"}, "level_3": {"options": [{"text": "慢", "is_correct": false, "explanation": "语义：“慢”与前面的“又快”矛盾，句子说不通。"}, {"text": "柔", "is_correct": false, "explanation": "搭配：“柔”指柔软，不能用来形容打拳的力度，搭配不自然。"}, {"text": "猛", "is_correct": true, "explanation": "正确：猛指力量大、来势快，与“又快又猛”描写打拳相符。"}, {"text": "绿", "is_correct": false, "explanation": "语义：“绿”是颜色，不能用来形容拳击的动作。"}], "explanations": {"慢": "语义：“慢”与前面的“又快”矛盾，句子说不通。", "柔": "搭配：“柔”指柔软，不能用来形容打拳的力度，搭配不自然。", "猛": "正确：猛指力量大、来势快，与“又快又猛”描写打拳相符。", "绿": "语义：“绿”是颜色，不能用来形容拳击的动作。"}, "sentence_index": 0, "correct_answer": "猛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他对这个问题的态度很猛。", "explanation": "这里应该用〈强烈〉。猛形容力量或动作的凶猛，态度和感情要用强烈。"}, {"text": "他的伤势很猛，需要马上住院。", "explanation": "这里应该用〈严重〉。猛不用来形容伤势，伤势的程度要用严重。"}, {"text": "这间教室很猛，同学们都很安静地读书。", "explanation": "这里应该用〈安静〉。猛表示很有力、很凶，不能形容教室的安静，要说安静。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87357, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "萌", "is_correct": false, "explanation": "méng（第二声）与 měng（第三声）声调不同，意思是萌芽、萌发。"}, {"text": "梦", "is_correct": false, "explanation": "mèng（第四声）与 měng（第三声）声调不同，意思是梦。"}, {"text": "猛", "is_correct": true, "explanation": "猛 měng：指力量大、很凶、很快，是正确答案。"}, {"text": "莽", "is_correct": false, "explanation": "mǎng 与 měng 声调相同，韵母不同（ang 与 eng），意思是鲁莽、粗野。"}], "explanations": {"萌": "méng（第二声）与 měng（第三声）声调不同，意思是萌芽、萌发。", "梦": "mèng（第四声）与 měng（第三声）声调不同，意思是梦。", "猛": "猛 měng：指力量大、很凶、很快，是正确答案。", "莽": "mǎng 与 měng 声调相同，韵母不同（ang 与 eng），意思是鲁莽、粗野。"}, "sentence_index": null, "correct_answer": "猛"}, "level_3": {"options": [{"text": "柔和", "is_correct": false, "explanation": "语义：“柔和”指温和不凶，与“我不敢靠近”的感受相矛盾。"}, {"text": "猛", "is_correct": true, "explanation": "正确：猛指凶悍，与“我不敢靠近”的感受相符。"}, {"text": "友好", "is_correct": false, "explanation": "语义：“友好”指亲切和善，与“我不敢靠近”的感受相矛盾。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”是味觉，不能用来形容狗，搭配不自然。"}], "explanations": {"柔和": "语义：“柔和”指温和不凶，与“我不敢靠近”的感受相矛盾。", "猛": "正确：猛指凶悍，与“我不敢靠近”的感受相符。", "友好": "语义：“友好”指亲切和善，与“我不敢靠近”的感受相矛盾。", "甜": "搭配：“甜”是味觉，不能用来形容狗，搭配不自然。"}, "sentence_index": 6, "correct_answer": "猛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他第一次上台，心里很猛。", "explanation": "这里应该用〈紧张〉。猛不用来形容心情，心里的紧张要说紧张。"}, {"text": "这盏灯很猛，屋里一下子就暗了。", "explanation": "这里应该用〈亮〉。猛不用来形容灯光的明暗，灯的亮度要说亮。"}, {"text": "他对这条路很猛，闭着眼睛都能走。", "explanation": "这里应该用〈熟悉〉。猛不表示对情况的熟悉程度，要说熟悉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87357, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个小伙子打篮球打很猛，经常一个人突破。", "corrected_sentence": "这个小伙子打篮球打得很猛，经常一个人突破。", "error_description": "错误：“打”和“很猛”之间漏掉了“得”。“猛”作补语说明“打”的程度，要说“打得很猛”，不能说“打很猛”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87357, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那只猎犬猛很，我们都不敢靠近。", "corrected_sentence": "那只猎犬很猛，我们都不敢靠近。", "error_description": "错误：“很”和“猛”的顺序颠倒。“很”是程度副词，要放在形容词“猛”前面，应说“很猛”，不能说“猛很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
