INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87358, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "力量大而凶；来势急速。", "primary_collocate": null, "pronunciation": "měng", "ipa": "mɤŋ˨˩", "syllable_count": 1, "sentences": [{"text": "今天的风很猛，帽子都吹跑了。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水来得很猛，一下子淹了路。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场雨下得又大又猛，街上没有人。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的火烧得很猛，大家都往外跑。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种药很猛，不要一次吃太多。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洪水又急又猛，村里的人都跑了。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的病来得很猛，医生也没想到。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那辆车冲过来，势头很猛。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海浪一个比一个猛，小船差点翻了。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几天寒潮来势很猛，气温一下子降了。", "target_word": "猛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "猛烈", "label": "复合"}, {"form": "凶猛", "label": "复合"}], "register": "中性", "sense_fingerprint": "形容风、水、火、病、药等力量大、来势急，如风很猛、来势很猛", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d04d293-e650-4428-be70-164f690aefe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87358, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "梦", "is_correct": false, "explanation": "mèng（第四声）与 měng（第三声）声调不同，意思是梦。"}, {"text": "猛", "is_correct": true, "explanation": "猛 měng：指风、水、火、病等力量大、来势急，是正确答案。"}, {"text": "萌", "is_correct": false, "explanation": "méng（第二声）与 měng（第三声）声调不同，意思是萌芽、萌发。"}, {"text": "莽", "is_correct": false, "explanation": "mǎng 与 měng 声调相同，韵母不同（ang 与 eng），意思是鲁莽、粗野。"}], "explanations": {"梦": "mèng（第四声）与 měng（第三声）声调不同，意思是梦。", "猛": "猛 měng：指风、水、火、病等力量大、来势急，是正确答案。", "萌": "méng（第二声）与 měng（第三声）声调不同，意思是萌芽、萌发。", "莽": "mǎng 与 měng 声调相同，韵母不同（ang 与 eng），意思是鲁莽、粗野。"}, "sentence_index": null, "correct_answer": "猛"}, "level_3": {"options": [{"text": "无力", "is_correct": false, "explanation": "语义：“无力”指力量弱，与“帽子都吹跑了”的强风相矛盾。"}, {"text": "猛", "is_correct": true, "explanation": "正确：猛指力量大、来势急，与“帽子都吹跑了”相符。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”是味觉，不能用来形容风，搭配不自然。"}, {"text": "红", "is_correct": false, "explanation": "语义：“红”是颜色，不能用来形容风的力量。"}], "explanations": {"无力": "语义：“无力”指力量弱，与“帽子都吹跑了”的强风相矛盾。", "猛": "正确：猛指力量大、来势急，与“帽子都吹跑了”相符。", "甜": "搭配：“甜”是味觉，不能用来形容风，搭配不自然。", "红": "语义：“红”是颜色，不能用来形容风的力量。"}, "sentence_index": 0, "correct_answer": "猛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次水灾造成的损失很猛，很多房子都倒了。", "explanation": "这里应该用〈严重〉。猛形容力量和来势，损失的程度要用严重。"}, {"text": "这张桌子很猛，适合放书。", "explanation": "这里应该用〈结实〉。猛表示力量大、来势急，形容桌子牢固要用结实。"}, {"text": "湖面很猛，孩子们在湖边玩耍。", "explanation": "这里应该用〈平静〉。猛形容力量大、来势急，湖面平静要用平静。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87358, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "梦", "is_correct": false, "explanation": "mèng（第四声）与 měng（第三声）声调不同，意思是梦。"}, {"text": "蒙", "is_correct": false, "explanation": "méng（第二声）与 měng（第三声）声调不同，意思是遮盖、蒙住。"}, {"text": "猛", "is_correct": true, "explanation": "猛 měng：指风、水、火、病等力量大、来势急，是正确答案。"}, {"text": "蟒", "is_correct": false, "explanation": "mǎng 与 měng 声调相同，韵母不同（ang 与 eng），意思是蟒蛇。"}], "explanations": {"梦": "mèng（第四声）与 měng（第三声）声调不同，意思是梦。", "蒙": "méng（第二声）与 měng（第三声）声调不同，意思是遮盖、蒙住。", "猛": "猛 měng：指风、水、火、病等力量大、来势急，是正确答案。", "蟒": "mǎng 与 měng 声调相同，韵母不同（ang 与 eng），意思是蟒蛇。"}, "sentence_index": null, "correct_answer": "猛"}, "level_3": {"options": [{"text": "亮", "is_correct": false, "explanation": "语义：“亮”指光线明亮，不能用来形容病来的情形。"}, {"text": "方便", "is_correct": false, "explanation": "搭配：“方便”不能用来形容病来的势头，搭配不自然。"}, {"text": "猛", "is_correct": true, "explanation": "正确：猛指来势急、力量大，与“病来得很猛，医生也没想到”相符。"}, {"text": "绿", "is_correct": false, "explanation": "语义：“绿”是颜色，不能用来形容病的情况。"}], "explanations": {"亮": "语义：“亮”指光线明亮，不能用来形容病来的情形。", "方便": "搭配：“方便”不能用来形容病来的势头，搭配不自然。", "猛": "正确：猛指来势急、力量大，与“病来得很猛，医生也没想到”相符。", "绿": "语义：“绿”是颜色，不能用来形容病的情况。"}, "sentence_index": 6, "correct_answer": "猛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块布很猛，适合做婴儿衣服。", "explanation": "这里应该用〈柔软〉。猛不能形容布料，布料的软硬要用柔软。"}, {"text": "他的笑容很猛，让人觉得很温暖。", "explanation": "这里应该用〈温和〉。猛表示力量大、来势急，形容笑容要用温和。"}, {"text": "这朵花很猛，院子里满是香味。", "explanation": "这里应该用〈香〉。猛不能形容花的气味，花香要用香。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87358, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场暴雨下得猛很，路上的车都停了。", "corrected_sentence": "这场暴雨下得很猛，路上的车都停了。", "error_description": "错误：“很”和“猛”的顺序颠倒。“很”要放在形容词“猛”前面，应说“很猛”，不能说“猛很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87358, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "寒潮来很猛，大家都穿上了厚衣服。", "corrected_sentence": "寒潮来得很猛，大家都穿上了厚衣服。", "error_description": "错误：“来”后面漏掉了“得”。“猛”作补语说明“来”的程度，要说“来得很猛”，不能说“来很猛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
