INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87359, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "名手是在一件事上做得特别好、很有名的人。", "primary_collocate": null, "pronunciation": "míng shǒu", "ipa": "miŋ˧˥ ʂou˨˩˦", "syllable_count": 2, "sentences": [{"text": "她是做饭的名手，朋友都爱吃。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是公司里修电脑的名手。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位名手做的蛋糕又好看又好吃。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想拜一位名手为师，学做木工。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是射箭名手，百发百中。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子里有一位编竹篮的名手。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "名手的作品，总是让人喜欢。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你想学拍照，应该去问问那位名手。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小学琴，现在已经是名手了。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在这个行业里，他可是一位名手。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "在一件事上做得特别好、很有名的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4cf27cd-43b5-427b-9ffd-1e148fc0d9bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87359, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名手", "is_correct": true, "explanation": "正确。名手指在某项技艺上很有名的能手，“做饭”正是一种技艺。"}, {"text": "名菜", "is_correct": false, "explanation": "语义：名菜是一道出名的菜，不能指人，“她是做饭的名菜”句子不通。"}, {"text": "名医", "is_correct": false, "explanation": "搭配：“名医”应与“看病”搭配，不能与“做饭”搭配。"}, {"text": "名著", "is_correct": false, "explanation": "语义：名著指有名的书籍作品，不指人，句子不通。"}], "explanations": {"名手": "正确。名手指在某项技艺上很有名的能手，“做饭”正是一种技艺。", "名菜": "语义：名菜是一道出名的菜，不能指人，“她是做饭的名菜”句子不通。", "名医": "搭配：“名医”应与“看病”搭配，不能与“做饭”搭配。", "名著": "语义：名著指有名的书籍作品，不指人，句子不通。"}, "sentence_index": 0, "correct_answer": "名手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事闹得全村都知道，他也成了村里的名手。", "explanation": "这里应该用〈名人〉。名人指因某事而出名的人，名手指在技艺上出色的人，这里是因事情闹大而出名，不能用名手。"}, {"text": "这种茶叶是名手，喝起来很香。", "explanation": "这里应该用〈名产〉。名产指某地有名的产品，名手只指在技艺上出色的人，不能用来形容商品。"}, {"text": "这件衣服是名手，价格很贵。", "explanation": "这里应该用〈名牌〉。名牌指有名的商品，名手只指人，不能用来说商品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87359, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名手", "is_correct": true, "explanation": "正确。名手指在某项技艺上很有名的能手，可以创作出受人喜欢的作品。"}, {"text": "名单", "is_correct": false, "explanation": "语义：名单指人员的名册，不能作为创作作品的人，句子不通。"}, {"text": "名声", "is_correct": false, "explanation": "搭配：“作品”需要由人创作，“名声”是声望，不能作为创作的主体，搭配不当。"}, {"text": "名胜", "is_correct": false, "explanation": "语义：名胜指著名的风景或古迹，不能创作作品，句子不通。"}], "explanations": {"名手": "正确。名手指在某项技艺上很有名的能手，可以创作出受人喜欢的作品。", "名单": "语义：名单指人员的名册，不能作为创作作品的人，句子不通。", "名声": "搭配：“作品”需要由人创作，“名声”是声望，不能作为创作的主体，搭配不当。", "名胜": "语义：名胜指著名的风景或古迹，不能创作作品，句子不通。"}, "sentence_index": 6, "correct_answer": "名手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆汽车是名手，开起来很舒服。", "explanation": "这里应该用〈名车〉。名车指有名的车，名手只指在技艺上出色的人，不能用来形容车辆。"}, {"text": "他的名手很长，很适合弹钢琴。", "explanation": "这个词不这么用。名手指人，不指手，不能用来形容手的样子。"}, {"text": "这首歌是名手，大家都很喜欢。", "explanation": "这里应该用〈名曲〉。名曲指有名的乐曲，名手只指在技艺上出色的人，不能用来形容作品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87359, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她是一只做饭的名手。", "corrected_sentence": "她是一位做饭的名手。", "error_description": "量词错误：“名手”指人，量词应用“位”，不能用“只”。应说“她是一位做饭的名手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87359, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位很名手做的蛋糕很好吃。", "corrected_sentence": "这位名手做的蛋糕很好吃。", "error_description": "错误在“很名手”：“很”不能直接修饰名词“名手”，应去掉“很”，说“这位名手做的蛋糕很好吃”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
