INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87360, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "大多是说大部分都是这样，只有少数不是。", "primary_collocate": null, "pronunciation": "dà duō", "ipa": "ta˥˩ tuɔ˥", "syllable_count": 2, "sentences": [{"text": "我的同学大多是北京人。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的菜大多很好吃。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末公园里的人大多是老人和孩子。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买的书大多是历史书。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班的同学大多喜欢踢足球。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的水果大多很新鲜。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来开会的人大多已经到了。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些衣服大多是妈妈给我买的。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天这里的游客大多是年轻人。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的朋友大多住在城里。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "大多：副词，大部分都是这样，只有少数例外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1493551b-beb8-436c-890d-5f7aa674fb8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87360, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大多", "is_correct": true, "explanation": "正确：“大多”表示大部分，填入后与“同学大多是北京人”的语境相符。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示少数情况，与“同学……是北京人”的整体判断矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示一向如此，多用于否定，不能说明“同学是北京人”的范围。"}, {"text": "极其", "is_correct": false, "explanation": "语义：“极其”是程度副词，不能说明“同学是哪里人”这类判断的范围。"}], "explanations": {"大多": "正确：“大多”表示大部分，填入后与“同学大多是北京人”的语境相符。", "偶尔": "语义：“偶尔”表示少数情况，与“同学……是北京人”的整体判断矛盾。", "从来": "语义：“从来”表示一向如此，多用于否定，不能说明“同学是北京人”的范围。", "极其": "语义：“极其”是程度副词，不能说明“同学是哪里人”这类判断的范围。"}, "sentence_index": 0, "correct_answer": "大多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试的学生大多只有一个及格了。", "explanation": "“大多”表示大部分，与“只有一个及格”自相矛盾。应去掉“大多”，说“这次考试的学生只有一个及格了”。"}, {"text": "我买的书大多一本都没看过。", "explanation": "这里应该用〈几乎〉。大多表示大部分，与“一本都没看过”矛盾；要表示几乎没看过，应说“几乎一本都没看过”。"}, {"text": "这些衣服大多没有一件是新的。", "explanation": "“大多”表示大部分，与“没有一件是新的”（全部）矛盾。应去掉“大多”，说“这些衣服没有一件是新的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87360, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大多", "is_correct": true, "explanation": "正确：“大多”表示大部分，与“已经到了”的语境相符。"}, {"text": "将要", "is_correct": false, "explanation": "搭配：“将要”表示将来，与“已经”表示的完成状态冲突。"}, {"text": "马上", "is_correct": false, "explanation": "搭配：“马上”表示即将发生，与“已经到了”的完成意义冲突。"}, {"text": "始终", "is_correct": false, "explanation": "语义：“始终”表示一直持续，与“已经到了”这一结果状态不合。"}], "explanations": {"大多": "正确：“大多”表示大部分，与“已经到了”的语境相符。", "将要": "搭配：“将要”表示将来，与“已经”表示的完成状态冲突。", "马上": "搭配：“马上”表示即将发生，与“已经到了”的完成意义冲突。", "始终": "语义：“始终”表示一直持续，与“已经到了”这一结果状态不合。"}, "sentence_index": 6, "correct_answer": "大多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末员工大多全都回家了。", "explanation": "这里应该用〈全部〉。大多表示大部分，与“全都”同用自相矛盾；表示全体要用“全部”，不能加“大多”。"}, {"text": "这次比赛我大多拿到了第一名。", "explanation": "“大多”说明多数人或物的情况，主语必须是复数；“我”只有一个人，不能用“大多”。应说“这次比赛我拿到了第一名”。"}, {"text": "他大多去过一次北京。", "explanation": "这里应该用〈只〉。大多表示大部分，“去过一次”是单次行为，不能说大部分；只去过一次应说“只去过一次北京”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87360, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班里的学生大多了很努力。", "corrected_sentence": "班里的学生大多很努力。", "error_description": "错误形式：“大多了很努力”；正确形式：“大多很努力”。“大多”是副词，后面不能直接加“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87360, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们公司的员工的大多很年轻。", "corrected_sentence": "他们公司的员工大多很年轻。", "error_description": "错误形式：“员工的大多”；正确形式：“员工大多”。“大多”是副词，不能用“的”接在名词后面作定语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
