INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87361, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在某项技艺上很有名的能手。", "primary_collocate": null, "pronunciation": "míng shǒu", "ipa": "miŋ˧˥ ʂou˨˩˦", "syllable_count": 2, "sentences": [{"text": "他是我们城市的棋艺名手。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位书法名手写的字很漂亮。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷年轻时是象棋名手。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的师傅是做面条的名手。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是游泳名手，拿过很多奖。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想学画画，就去请教那位名手吧。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位名手一出手，大家都安静了。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王是钓鱼名手，今天钓了十条鱼。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时，名手们都认真地看着棋盘。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位乒乓球名手教了我很多技术。", "target_word": "名手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}], "register": "中性", "sense_fingerprint": "在某项技艺上很有名的能手", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4cf27cd-43b5-427b-9ffd-1e148fc0d9bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87361, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "名手", "is_correct": true, "explanation": "正确。名手指在某项技艺上很有名的能手，与“棋艺”相符。"}, {"text": "名片", "is_correct": false, "explanation": "语义：名片是印有个人信息的卡片，不指人的技艺，句子不通。"}, {"text": "名胜", "is_correct": false, "explanation": "语义：名胜指著名的风景或古迹，不能指人，句子不通。"}, {"text": "书法", "is_correct": false, "explanation": "搭配：“棋艺”修饰的应是指人的能手，“书法”是技艺名称，不能用来指人。"}], "explanations": {"名手": "正确。名手指在某项技艺上很有名的能手，与“棋艺”相符。", "名片": "语义：名片是印有个人信息的卡片，不指人的技艺，句子不通。", "名胜": "语义：名胜指著名的风景或古迹，不能指人，句子不通。", "书法": "搭配：“棋艺”修饰的应是指人的能手，“书法”是技艺名称，不能用来指人。"}, "sentence_index": 0, "correct_answer": "名手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座山是名手，每年都有很多游客来。", "explanation": "这里应该用〈名胜〉。名胜指风景有名的地方，名手只指在技艺上出色的人，不能用来说地方。"}, {"text": "这个女孩是班里的美貌名手。", "explanation": "这个词不这么用。名手指在某项技艺上很出色的人，不能用来形容外貌，应说“美人”。"}, {"text": "这个牌子的手表是名手，很多人想买。", "explanation": "这里应该用〈名牌〉。名牌指有名的商品，名手只指在技艺上出色的人，不能用来形容商品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87361, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "名手", "is_correct": true, "explanation": "正确。名手指在某项技艺上很有名的能手，“一出手”正是说高超的技艺。"}, {"text": "名句", "is_correct": false, "explanation": "语义：名句指流传的好句子，不指能施展技艺的人，句子不通。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋是食物，不是人，不能用“这位”，也不能施展技艺。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是装书的袋子，不能施展技艺，句子不通。"}], "explanations": {"名手": "正确。名手指在某项技艺上很有名的能手，“一出手”正是说高超的技艺。", "名句": "语义：名句指流传的好句子，不指能施展技艺的人，句子不通。", "鸡蛋": "语义：鸡蛋是食物，不是人，不能用“这位”，也不能施展技艺。", "书包": "语义：书包是装书的袋子，不能施展技艺，句子不通。"}, "sentence_index": 6, "correct_answer": "名手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这间饭店是城里的名手，每天都有很多客人。", "explanation": "这个词不这么用。名手指在技艺上出色的人，不能用来形容饭店，应说“名店”。"}, {"text": "他的名手很漂亮。", "explanation": "这个词不这么用。名手指在技艺上出色的人，不指手，不能用来形容手的样子。"}, {"text": "这部电影是名手，票房很高。", "explanation": "这里应该用〈名作〉。名作指有名的作品，名手只指在技艺上出色的人，不能用来形容电影。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87361, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们班有三只名手。", "corrected_sentence": "我们班有三位名手。", "error_description": "量词错误：“名手”指人，应用“位”，不能用“只”。应说“我们班有三位名手”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87361, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很围棋名手，教了我很多技术。", "corrected_sentence": "他是围棋名手，教了我很多技术。", "error_description": "错误在“很围棋名手”：“很”不能直接修饰名词“名手”，应用“是”表示判断，说“他是围棋名手”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
