INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87362, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示大部分、多数。", "primary_collocate": null, "pronunciation": "dà duō", "ipa": "ta˥˩ tuɔ˥", "syllable_count": 2, "sentences": [{"text": "我家附近的商店大多关门了。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说的话大多是真的。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参加比赛的孩子大多不到十岁。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的房子大多很旧。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看过的电影大多是中国电影。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "星期天，商场里的人大多在买东西。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给的作业大多很简单。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的照片大多是在海边拍的。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的路大多很宽。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司的人大多会说英语。", "target_word": "大多", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "大多：副词，表示大部分、多数", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1493551b-beb8-436c-890d-5f7aa674fb8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87362, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "大多", "is_correct": true, "explanation": "正确：“大多”表示大部分，填入后与“商店大多关门了”的语境相符。"}, {"text": "绝不", "is_correct": false, "explanation": "搭配：“绝不”是否定语气，与“关门了”这一已然事实冲突。"}, {"text": "极其", "is_correct": false, "explanation": "语义：“极其”是程度副词，无法说明“关门”的范围。"}, {"text": "格外", "is_correct": false, "explanation": "语义：“格外”表示特别，与“关门了”这一判断搭配不当。"}], "explanations": {"大多": "正确：“大多”表示大部分，填入后与“商店大多关门了”的语境相符。", "绝不": "搭配：“绝不”是否定语气，与“关门了”这一已然事实冲突。", "极其": "语义：“极其”是程度副词，无法说明“关门”的范围。", "格外": "语义：“格外”表示特别，与“关门了”这一判断搭配不当。"}, "sentence_index": 0, "correct_answer": "大多"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个小区的住户大多只有一户是老人。", "explanation": "“大多”表示大部分，与“只有一户是老人”矛盾。应去掉“大多”，说“这个小区的住户只有一户是老人”。"}, {"text": "我们学校的学生大多一个都没住宿。", "explanation": "这里应该用〈几乎〉。大多表示大部分，与“一个都没住宿”矛盾；要表示几乎没人住宿，应说“几乎一个都没住宿”。"}, {"text": "这些书大多全都不是历史书。", "explanation": "“大多”表示大部分，与“全都”矛盾，两者不能同用。应去掉“大多”，说“这些书全都不是历史书”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87362, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大多", "is_correct": true, "explanation": "正确：“大多”表示大部分，与“作业大多很简单”的语境相符。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”与“很”同时出现属于程度副词叠用，不符合汉语语法。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”与“很”叠用，不符合汉语语法。"}, {"text": "仅", "is_correct": false, "explanation": "语义：“仅”表示限定，与“很简单”的程度描述不合。"}], "explanations": {"大多": "正确：“大多”表示大部分，与“作业大多很简单”的语境相符。", "太": "搭配：“太”与“很”同时出现属于程度副词叠用，不符合汉语语法。", "非常": "搭配：“非常”与“很”叠用，不符合汉语语法。", "仅": "语义：“仅”表示限定，与“很简单”的程度描述不合。"}, "sentence_index": 6, "correct_answer": "大多"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "期末前的学生大多全都在图书馆。", "explanation": "这里应该用〈全部〉。大多表示大部分，与“全都在图书馆”自相矛盾；表示全体要用“全部”，不能加“大多”。"}, {"text": "这次比赛大多获得了冠军。", "explanation": "“大多”说明多数人或物的情况，需要复数主语；冠军只有一个，不能用“大多”。应说“他在这次比赛中获得了冠军”。"}, {"text": "他大多去过一次北京。", "explanation": "这里应该用〈只〉。大多表示大部分，“去过一次”是单次行为，不能说大部分；只去过一次应说“只去过一次北京”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87362, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条街上的店铺的大多很整洁。", "corrected_sentence": "这条街上的店铺大多很整洁。", "error_description": "错误形式：“店铺的大多”；正确形式：“店铺大多”。“大多”是副词，不能用“的”接在名词后面作定语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87362, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们这里的人大多了很热情。", "corrected_sentence": "我们这里的人大多很热情。", "error_description": "错误形式：“大多了很热情”；正确形式：“大多很热情”。“大多”是副词，后面不能直接加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87363, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "闹翻", "is_correct": true, "explanation": "正确：闹翻指关系破裂、不再和睦，与和好的重归于好正相反。"}, {"text": "散步", "is_correct": false, "explanation": "散步是日常活动，与人际关系的好坏没有反义关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "唱歌与朋友之间的关系恢复无关，不是和好的反义词。"}, {"text": "写字", "is_correct": false, "explanation": "写字是一种动作，与和好所指的关系变化无关，不构成反义。"}], "correct_answer": "闹翻", "explanations": {"闹翻": "正确：闹翻指关系破裂、不再和睦，与和好的重归于好正相反。", "散步": "散步是日常活动，与人际关系的好坏没有反义关系。", "唱歌": "唱歌与朋友之间的关系恢复无关，不是和好的反义词。", "写字": "写字是一种动作，与和好所指的关系变化无关，不构成反义。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87363, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "闹翻", "is_correct": true, "explanation": "正确：闹翻指关系破裂，与她们重新和睦的状态相反。"}, {"text": "游泳", "is_correct": false, "explanation": "游泳是一种运动，与人际关系的好坏没有反义关系。"}, {"text": "跑步", "is_correct": false, "explanation": "跑步是一种运动，与和好的关系变化无关，不是反义词。"}, {"text": "看书", "is_correct": false, "explanation": "看书是一种活动，与人际关系的恢复无关，不构成反义。"}], "correct_answer": "闹翻", "explanations": {"闹翻": "正确：闹翻指关系破裂，与她们重新和睦的状态相反。", "游泳": "游泳是一种运动，与人际关系的好坏没有反义关系。", "跑步": "跑步是一种运动，与和好的关系变化无关，不是反义词。", "看书": "看书是一种活动，与人际关系的恢复无关，不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87363, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "和好是吵架以后，又做回好朋友。", "primary_collocate": null, "pronunciation": "hé hǎo", "ipa": "xɤ˧˥ xɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他们吵架以后，昨天和好了。", "target_word": "和好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想和她和好，可是不知道怎么说。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们两个别生气了，快和好吧。", "target_word": "和好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小明和小红吵架了，现在还没和好。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让姐姐和我和好。", "target_word": "和好", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们是好朋友，吵完架很快就和好。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我向他说了对不起，我们就和好了。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吵架以后，他们好几天没说话，后来才和好。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友吵架了，你可以帮他们和好。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她们和好以后，又一起去上学。", "target_word": "和好", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "和好了", "label": "体标"}, {"form": "和好如初", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：朋友吵架以后重新做回好朋友", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96df1d2b-98d4-4058-aa95-b548c2ba3b98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87363, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "和好", "is_correct": true, "explanation": "正确：和好指吵架以后又做回好朋友，符合“吵架以后，昨天……了”的句意。"}, {"text": "放假", "is_correct": false, "explanation": "语义：放假与吵架后的关系变化无关，“吵架以后，昨天放假了”读起来不通。"}, {"text": "出发", "is_correct": false, "explanation": "语义：出发是离开某地，与吵架后的人际关系无关，句意不通。"}, {"text": "毕业", "is_correct": false, "explanation": "语义：毕业与吵架后的关系变化无关，“吵架以后，昨天毕业了”句意不通。"}], "explanations": {"和好": "正确：和好指吵架以后又做回好朋友，符合“吵架以后，昨天……了”的句意。", "放假": "语义：放假与吵架后的关系变化无关，“吵架以后，昨天放假了”读起来不通。", "出发": "语义：出发是离开某地，与吵架后的人际关系无关，句意不通。", "毕业": "语义：毕业与吵架后的关系变化无关，“吵架以后，昨天毕业了”句意不通。"}, "sentence_index": 0, "correct_answer": "和好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台坏了很久的洗衣机，今天终于和好了。", "explanation": "这里应该用〈修好〉。和好只用于人与人之间闹别扭后重新友好，机器坏了要说修好。"}, {"text": "他的病情今天终于和好了。", "explanation": "这里应该用〈好转〉。和好只用于人与人之间闹别扭后重新友好，病情只能好转。"}, {"text": "这场比赛打到加时赛，最后终于和好了。", "explanation": "这里应该用〈结束〉。比赛只能结束，不能和好；和好表示双方不和睦后恢复友好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87363, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "和好", "is_correct": true, "explanation": "正确：和好指道歉后关系恢复，与句中的“对不起”前后呼应。"}, {"text": "绝交", "is_correct": false, "explanation": "语义：道歉之后关系应当缓和，说绝交与句意相反。"}, {"text": "翻脸", "is_correct": false, "explanation": "语义：翻脸是突然变脸，与道歉后的和解相反，句意不通。"}, {"text": "生病", "is_correct": false, "explanation": "语义：说了对不起与生病没有关系，句意不通。"}], "explanations": {"和好": "正确：和好指道歉后关系恢复，与句中的“对不起”前后呼应。", "绝交": "语义：道歉之后关系应当缓和，说绝交与句意相反。", "翻脸": "语义：翻脸是突然变脸，与道歉后的和解相反，句意不通。", "生病": "语义：说了对不起与生病没有关系，句意不通。"}, "sentence_index": 6, "correct_answer": "和好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份作业他终于和好了。", "explanation": "这里应该用〈完成〉。和好只用于人与人之间，不能用来说作业。"}, {"text": "他第一次见到新同学，就跟对方和好了。", "explanation": "这里应该用〈交朋友〉。和好要求双方之前有过矛盾，初次见面的人只能说交朋友。"}, {"text": "飞机平安和好了。", "explanation": "这里应该用〈降落〉。和好只用于人或人与人之间的关系，飞机不能和好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87363, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们吵架以后，很快和好了了。", "corrected_sentence": "他们吵架以后，很快和好了。", "error_description": "错误：“了”多加了一个；正确：“很快和好了”，“了”只用一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87363, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两个人吵了一架，过了几天就和好着了。", "corrected_sentence": "两个人吵了一架，过了几天就和好了。", "error_description": "错误：“和好着了”；正确：“和好了”。“和好”表示动作已经完成，要用“了”，不能用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
