INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87364, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "结束不和睦的状态，恢复友好。", "primary_collocate": null, "pronunciation": "hé hǎo", "ipa": "xɤ˧˥ xɑʊ˨˩˦", "syllable_count": 2, "sentences": [{"text": "两个朋友因误会闹翻，很久以后终于和好了。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居们为了小事不说话，最后和好了。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对夫妻吵了很久，现在和好了。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家人多年不来往，今天终于和好。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两年没说话，现在想和好。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过大家的帮助，两个同学和好了。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如果你先道歉，他就会和你和好。", "target_word": "和好", "complexity_tier": "T4", "sentence_source": "generated"}, {"text": "爸爸和叔叔吵架后很久才和好。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两位邻居因为停车的事闹过矛盾，后来终于和好了。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们和好以后，关系比以前更好。", "target_word": "和好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "和好了", "label": "体标"}, {"form": "和好如初", "label": "复合"}], "register": "中性", "sense_fingerprint": "动词：双方结束不和睦，恢复友好关系", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '96df1d2b-98d4-4058-aa95-b548c2ba3b98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87364, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "和好", "is_correct": true, "explanation": "正确：和好指闹翻后重新友好，与“很久以后终于”的语境相符。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：下雨是天气现象，不能用“两个朋友”作主语，句意不通。"}, {"text": "出发", "is_correct": false, "explanation": "语义：出发是离开某地，与朋友闹翻后的和解不符。"}, {"text": "闹翻", "is_correct": false, "explanation": "语义：句中已有“闹翻”，再说闹翻与“终于”后的重归于好矛盾。"}], "explanations": {"和好": "正确：和好指闹翻后重新友好，与“很久以后终于”的语境相符。", "下雨": "语义：下雨是天气现象，不能用“两个朋友”作主语，句意不通。", "出发": "语义：出发是离开某地，与朋友闹翻后的和解不符。", "闹翻": "语义：句中已有“闹翻”，再说闹翻与“终于”后的重归于好矛盾。"}, "sentence_index": 0, "correct_answer": "和好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台旧电视机，今天终于和好了。", "explanation": "这里应该用〈修好〉。和好只用于人与人之间的关系，不能用于电视机。"}, {"text": "我的数学成绩终于和好了。", "explanation": "这里应该用〈提高〉。和好只用于人与人之间闹别扭后重新友好，成绩只能提高。"}, {"text": "这场雨下了三天，今天终于和好了。", "explanation": "这里应该用〈停〉。和好指人与人之间重归于好，不能用于雨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87364, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "和好", "is_correct": true, "explanation": "正确：和好指双方恢复友好，与条件句“先道歉”的结果相符。"}, {"text": "绝交", "is_correct": false, "explanation": "语义：先道歉之后，绝交与条件句的结果相反。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：先道歉之后不会再吵架，与条件句的结果相反。"}, {"text": "翻脸", "is_correct": false, "explanation": "语义：翻脸是突然变脸，与先道歉这一前提不符。"}], "explanations": {"和好": "正确：和好指双方恢复友好，与条件句“先道歉”的结果相符。", "绝交": "语义：先道歉之后，绝交与条件句的结果相反。", "吵架": "语义：先道歉之后不会再吵架，与条件句的结果相反。", "翻脸": "语义：翻脸是突然变脸，与先道歉这一前提不符。"}, "sentence_index": 6, "correct_answer": "和好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份报告他终于和好了。", "explanation": "这里应该用〈完成〉。和好只用于人与人之间，不能用来说报告。"}, {"text": "我们刚认识，他就跟我和好了。", "explanation": "这里应该用〈交朋友〉。和好要求双方之前有过矛盾，没有矛盾的人只能说交朋友。"}, {"text": "飞机平安和好了。", "explanation": "这里应该用〈降落〉。和好只用于人或人与人之间的关系，飞机不能和好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87364, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们闹了矛盾，后来很快和好了了。", "corrected_sentence": "他们闹了矛盾，后来很快和好了。", "error_description": "错误：“了”多加了一个；正确：“很快和好了”，“了”只用一个。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87364, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "两位老同学因为一件小事闹别扭，后来又和好着了。", "corrected_sentence": "两位老同学因为一件小事闹别扭，后来又和好了。", "error_description": "错误：“和好着了”；正确：“和好了”。“和好”表示动作已经完成，要用“了”，不能用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4bde90eb-7d60-4472-9330-89734b4b836e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87365, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "果断", "is_correct": true, "explanation": "果断：遇事不迟疑，立即拿定主意，与“犹豫”意思相反。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹形容场面或气氛活跃，与“犹豫”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐指排列有序或样子规整，与“犹豫”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、不模糊，与“犹豫”没有反义关系。"}], "correct_answer": "果断", "explanations": {"果断": "果断：遇事不迟疑，立即拿定主意，与“犹豫”意思相反。", "热闹": "热闹形容场面或气氛活跃，与“犹豫”没有反义关系。", "整齐": "整齐指排列有序或样子规整，与“犹豫”没有反义关系。", "清楚": "清楚指明白、不模糊，与“犹豫”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87365, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "果断", "is_correct": true, "explanation": "果断：遇事不迟疑，立即拿定主意，与“犹豫”意思相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮形容外表好看，与“犹豫”没有反义关系。"}, {"text": "繁忙", "is_correct": false, "explanation": "繁忙形容事情多、非常忙，与“犹豫”没有反义关系。"}, {"text": "严肃", "is_correct": false, "explanation": "严肃形容态度认真或神情庄重，与“犹豫”没有反义关系。"}], "correct_answer": "果断", "explanations": {"果断": "果断：遇事不迟疑，立即拿定主意，与“犹豫”意思相反。", "漂亮": "漂亮形容外表好看，与“犹豫”没有反义关系。", "繁忙": "繁忙形容事情多、非常忙，与“犹豫”没有反义关系。", "严肃": "严肃形容态度认真或神情庄重，与“犹豫”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87365, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "犹豫是不知道该怎么选，想来想去。", "primary_collocate": null, "pronunciation": "yóu yù", "ipa": "jou̯˧˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "菜单上的菜太多，我不知道选什么，一直犹豫。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在两件衣服前犹豫了半天。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选哪个大学，他犹豫了很长时间。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个都好看，别犹豫，买哪个都行。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我犹豫着是坐火车还是坐飞机。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在路口犹豫，不知道往哪边走。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要不要换手机，我犹豫了好几天。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟犹豫过学画画还是学唱歌。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看着两条路，她犹豫起来。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想来想去，犹豫得睡不着觉。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "犹豫了", "label": "体标"}, {"form": "犹豫着", "label": "体标"}, {"form": "犹豫过", "label": "体标"}, {"form": "犹犹豫豫", "label": "重叠"}, {"form": "犹豫不决", "label": "复合"}], "register": "中性", "sense_fingerprint": "面对选择，想来想去不知选哪个", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f88939-d718-4d2d-bc4c-ca9e6f6115ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87365, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "犹豫", "is_correct": true, "explanation": "正确答案：犹豫（yóu yù），指面对选择想来想去。"}, {"text": "忧郁", "is_correct": false, "explanation": "yōu（第一声）与 yóu（第二声）声调不同，意思是心情低落，与选择无关。"}, {"text": "由于", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是因为，是连词。"}, {"text": "鱿鱼", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是鱿鱼，一种海洋动物。"}, {"text": "优于", "is_correct": false, "explanation": "yōu（第一声）与 yóu（第二声），yú（第二声）与 yù（第四声），声调都不同，意思是比……更好。"}], "explanations": {"犹豫": "正确答案：犹豫（yóu yù），指面对选择想来想去。", "忧郁": "yōu（第一声）与 yóu（第二声）声调不同，意思是心情低落，与选择无关。", "由于": "yú（第二声）与 yù（第四声）声调不同，意思是因为，是连词。", "鱿鱼": "yú（第二声）与 yù（第四声）声调不同，意思是鱿鱼，一种海洋动物。", "优于": "yōu（第一声）与 yóu（第二声），yú（第二声）与 yù（第四声），声调都不同，意思是比……更好。"}, "sentence_index": null, "correct_answer": "犹豫"}, "level_3": {"options": [{"text": "犹豫", "is_correct": true, "explanation": "正确：“一直犹豫”表示在菜单前来回拿不定主意，与语境相符。"}, {"text": "决定", "is_correct": false, "explanation": "搭配：“决定”是一次性的结果，不能说“一直决定”。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”与“不知道选什么”的情境无关，句子意思不通。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”与选菜的情境不合，句子意思不通。"}], "explanations": {"犹豫": "正确：“一直犹豫”表示在菜单前来回拿不定主意，与语境相符。", "决定": "搭配：“决定”是一次性的结果，不能说“一直决定”。", "吃": "语义：“吃”与“不知道选什么”的情境无关，句子意思不通。", "洗": "语义：“洗”与选菜的情境不合，句子意思不通。"}, "sentence_index": 0, "correct_answer": "犹豫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我犹豫得很干脆，一下子就买了那台电视。", "explanation": "这里应该用〈果断〉。“犹豫”表示拿不定主意，与“干脆”做事利落的意思相反，不能说“犹豫得很干脆”；迅速决定要用“果断”。"}, {"text": "听到考上大学的好消息，他犹豫得跳了起来。", "explanation": "这里应该用〈兴奋〉。“犹豫”表示拿不定主意，不能形容高兴激动的样子；听到好消息高兴得跳起来要说“兴奋得跳了起来”。"}, {"text": "我犹豫好了，就买那本书吧。", "explanation": "这里应该用〈决定〉。“犹豫”表示还没拿定主意，不能说“犹豫好了”；已经选定要说“决定好了”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87365, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "犹豫", "is_correct": true, "explanation": "正确：“我犹豫了好几天”表示换不换手机拿不定主意，与句子语境相符。"}, {"text": "宣布", "is_correct": false, "explanation": "搭配：“宣布”是一次性的正式动作，不能说“宣布了好几天”。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”与“要不要换手机”的语境无关，句子意思不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与换手机的问题无关，句子意思不通。"}], "explanations": {"犹豫": "正确：“我犹豫了好几天”表示换不换手机拿不定主意，与句子语境相符。", "宣布": "搭配：“宣布”是一次性的正式动作，不能说“宣布了好几天”。", "生病": "语义：“生病”与“要不要换手机”的语境无关，句子意思不通。", "游泳": "语义：“游泳”与换手机的问题无关，句子意思不通。"}, "sentence_index": 6, "correct_answer": "犹豫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想来想去，终于犹豫了主意，睡得很香。", "explanation": "这里应该用〈拿定〉。“犹豫”不能带“主意”做宾语，也表示还没决定；最后决定了要说“拿定了主意”。"}, {"text": "他想来想去，很快就犹豫好了，睡得很香。", "explanation": "这里应该用〈想好〉。“犹豫”表示还没拿定主意，不能用“好”表示已经想清楚；想清楚要说“想好了”。"}, {"text": "他想来想去，犹豫得很认真，把两个方案都仔细看了一遍。", "explanation": "这里应该用〈比较〉。“犹豫”表示拿不定主意，不能用来形容认真对比的做法；对两个方案认真对比要说“比较”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87365, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她犹豫地连饭都吃不下。", "corrected_sentence": "她犹豫得连饭都吃不下。", "error_description": "“得”和“地”混用：“犹豫得……”表示程度，要用补语“得”，不能用状语“地”，应说“犹豫得连饭都吃不下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87365, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我犹豫了过要不要换手机，最后没有换。", "corrected_sentence": "我犹豫过要不要换手机，最后没有换。", "error_description": "时态标记叠加错误：“过”已表示曾经有过这种经历，不能再与“了”同用，应说“犹豫过”，不能说“犹豫了过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87366, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "果断", "is_correct": true, "explanation": "果断：遇事不迟疑，立即拿定主意，与“犹豫”意思相反。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹形容场面或气氛活跃，与“犹豫”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "整齐指排列有序或样子规整，与“犹豫”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚指明白、不模糊，与“犹豫”没有反义关系。"}], "correct_answer": "果断", "explanations": {"果断": "果断：遇事不迟疑，立即拿定主意，与“犹豫”意思相反。", "热闹": "热闹形容场面或气氛活跃，与“犹豫”没有反义关系。", "整齐": "整齐指排列有序或样子规整，与“犹豫”没有反义关系。", "清楚": "清楚指明白、不模糊，与“犹豫”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87366, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "果断", "is_correct": true, "explanation": "果断：遇事不迟疑，立即拿定主意，与“犹豫”意思相反。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮形容外表好看，与“犹豫”没有反义关系。"}, {"text": "繁忙", "is_correct": false, "explanation": "繁忙形容事情多、非常忙，与“犹豫”没有反义关系。"}, {"text": "严肃", "is_correct": false, "explanation": "严肃形容态度认真或神情庄重，与“犹豫”没有反义关系。"}], "correct_answer": "果断", "explanations": {"果断": "果断：遇事不迟疑，立即拿定主意，与“犹豫”意思相反。", "漂亮": "漂亮形容外表好看，与“犹豫”没有反义关系。", "繁忙": "繁忙形容事情多、非常忙，与“犹豫”没有反义关系。", "严肃": "严肃形容态度认真或神情庄重，与“犹豫”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87366, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "拿不定主意，迟疑不决。", "primary_collocate": null, "pronunciation": "yóu yù", "ipa": "jou̯˧˥ y˥˩", "syllable_count": 2, "sentences": [{"text": "他犹豫了很久，还是没有买。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你别犹豫了，快点决定吧。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她犹豫着要不要告诉妈妈。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有犹豫，马上就答应了。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对两份工作，他很犹豫。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他犹豫了一下，才打开门。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问她想不想参加比赛，她有点犹豫。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么还在犹豫？", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他犹豫了半天，最后还是去了。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我犹豫过要不要搬家，最后决定留下。", "target_word": "犹豫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "犹豫了", "label": "体标"}, {"form": "犹豫着", "label": "体标"}, {"form": "犹豫过", "label": "体标"}, {"form": "犹犹豫豫", "label": "重叠"}, {"form": "犹豫不决", "label": "复合"}], "register": "中性", "sense_fingerprint": "拿不定主意，迟疑不决", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f88939-d718-4d2d-bc4c-ca9e6f6115ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87366, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "犹豫", "is_correct": true, "explanation": "正确答案：犹豫（yóu yù），指拿不定主意。"}, {"text": "忧郁", "is_correct": false, "explanation": "yōu（第一声）与 yóu（第二声）声调不同，意思是心情低落，不是拿不定主意。"}, {"text": "由于", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是因为，是连词。"}, {"text": "鱿鱼", "is_correct": false, "explanation": "yú（第二声）与 yù（第四声）声调不同，意思是鱿鱼，一种海洋动物。"}, {"text": "优于", "is_correct": false, "explanation": "yōu（第一声）与 yóu（第二声），yú（第二声）与 yù（第四声），声调都不同，意思是比……更好。"}], "explanations": {"犹豫": "正确答案：犹豫（yóu yù），指拿不定主意。", "忧郁": "yōu（第一声）与 yóu（第二声）声调不同，意思是心情低落，不是拿不定主意。", "由于": "yú（第二声）与 yù（第四声）声调不同，意思是因为，是连词。", "鱿鱼": "yú（第二声）与 yù（第四声）声调不同，意思是鱿鱼，一种海洋动物。", "优于": "yōu（第一声）与 yóu（第二声），yú（第二声）与 yù（第四声），声调都不同，意思是比……更好。"}, "sentence_index": null, "correct_answer": "犹豫"}, "level_3": {"options": [{"text": "犹豫", "is_correct": true, "explanation": "正确：“犹豫”指拿不定主意，与“很久”和“还是没有买”的语境相符。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与买东西的情境无关，句子意思不通。"}, {"text": "迟到", "is_correct": false, "explanation": "语义：“迟到”与“买”的语境对不上，句子意思不通。"}, {"text": "流泪", "is_correct": false, "explanation": "语义：“流泪”不能表示买不买的迟疑，句子意思不通。"}], "explanations": {"犹豫": "正确：“犹豫”指拿不定主意，与“很久”和“还是没有买”的语境相符。", "睡觉": "语义：“睡觉”与买东西的情境无关，句子意思不通。", "迟到": "语义：“迟到”与“买”的语境对不上，句子意思不通。", "流泪": "语义：“流泪”不能表示买不买的迟疑，句子意思不通。"}, "sentence_index": 0, "correct_answer": "犹豫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他犹豫得很仔细，把每个细节都看了一遍。", "explanation": "这里应该用〈考虑〉。“仔细”形容认真地想清楚，犹豫是拿不定主意的状态，二者不能这样搭配，不能说“犹豫得很仔细”。"}, {"text": "他犹豫了一下午那道数学题，终于做出来了。", "explanation": "这里应该用〈研究〉。“犹豫”是不及物动词，表示拿不定主意，不能带“数学题”做宾语；花时间认真想题目要说“研究”。"}, {"text": "他犹豫得很痛快，几句话就把事情定下来了。", "explanation": "这里应该用〈果断〉。“痛快”形容做事干脆利落，与“犹豫”拿不定主意的意思相反；表示迅速决定要说“果断”，不能说“犹豫得很痛快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87366, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "犹豫", "is_correct": true, "explanation": "正确：“有点犹豫”说明她拿不定主意，与“老师问她想不想参加比赛”相符。"}, {"text": "宣布", "is_correct": false, "explanation": "搭配：“宣布”是一次性的正式动作，不能与“有点”搭配。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”与老师问她是否参赛的语境不合，句子意思不通。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”与“参加比赛”的问题无关，句子意思不通。"}], "explanations": {"犹豫": "正确：“有点犹豫”说明她拿不定主意，与“老师问她想不想参加比赛”相符。", "宣布": "搭配：“宣布”是一次性的正式动作，不能与“有点”搭配。", "睡觉": "语义：“睡觉”与老师问她是否参赛的语境不合，句子意思不通。", "游泳": "语义：“游泳”与“参加比赛”的问题无关，句子意思不通。"}, "sentence_index": 6, "correct_answer": "犹豫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我很快就犹豫好了，马上答应了。", "explanation": "这里应该用〈考虑〉。“犹豫”表示还没拿定主意，不能用“好”表示已经想清楚，想清楚要说“考虑好了”。"}, {"text": "他买东西时犹豫得很利索，一下子就付了钱。", "explanation": "这里应该用〈干脆〉。“犹豫”表示拿不定主意，与“利索”做事迅速、不拖泥带水的意思相反，不能说“犹豫得很利索”；迅速决定要说“干脆”。"}, {"text": "他犹豫地把好消息告诉了大家，笑得合不拢嘴。", "explanation": "这里应该用〈高兴〉。“犹豫”表示拿不定主意，与“笑得合不拢嘴”矛盾；开心地告诉大家要说“高兴地”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87366, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他犹豫了着很久，才开口说话。", "corrected_sentence": "他犹豫了很久，才开口说话。", "error_description": "体标错误：“了”与“着”不能同用；“犹豫”后只用“了”，应去掉“着”，说“他犹豫了很久，才开口说话”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87366, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这件事犹豫了很久，最后决定不去。", "corrected_sentence": "他犹豫了很久，最后决定不去。", "error_description": "“把”字句错误：“犹豫”是不及物动词，不能用“把”带事情做宾语，应说“他犹豫了很久”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
