INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87367, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "喜悦是心里很高兴的样子。", "primary_collocate": null, "pronunciation": "xǐ yuè", "ipa": "ɕi˨˩˦ ɥe˥˩", "syllable_count": 2, "sentences": [{"text": "她心里很喜悦。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到好消息，大家都很喜悦。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脸上带着喜悦的笑。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们喜悦地跑进教室。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到妈妈回来，我非常喜悦。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她喜悦的样子让人也高兴起来。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试通过了，他喜悦极了。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人收到信，心里十分喜悦。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家喜悦地唱起歌来。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天她看上去特别喜悦。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "喜悦地", "label": "状语形式"}], "register": "书面", "sense_fingerprint": "形容词：心里很高兴的样子，可作谓语或定语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5557fc-539b-4cb6-b9b1-8d2660c41b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87367, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "喜悦", "is_correct": true, "explanation": "正确。喜悦读 xǐ yuè，意思是心里很高兴的样子。"}, {"text": "喜雨", "is_correct": false, "explanation": "第二音节 yǔ（第三声）与 yuè（第四声）韵母不同、声调也不同，意思是及时雨。"}, {"text": "喜鹊", "is_correct": false, "explanation": "第二音节 què 与 yuè 声母不同（q 与零声母），是一种鸟。"}, {"text": "几月", "is_correct": false, "explanation": "第一音节 jǐ 与 xǐ 声母不同（j 与 x），意思是问月份。"}], "explanations": {"喜悦": "正确。喜悦读 xǐ yuè，意思是心里很高兴的样子。", "喜雨": "第二音节 yǔ（第三声）与 yuè（第四声）韵母不同、声调也不同，意思是及时雨。", "喜鹊": "第二音节 què 与 yuè 声母不同（q 与零声母），是一种鸟。", "几月": "第一音节 jǐ 与 xǐ 声母不同（j 与 x），意思是问月份。"}, "sentence_index": null, "correct_answer": "喜悦"}, "level_3": {"options": [{"text": "喜悦", "is_correct": true, "explanation": "正确。“心里很喜悦”描述高兴的心情。"}, {"text": "喜庆", "is_correct": false, "explanation": "搭配：喜庆多形容场面或节日气氛，不用来说人的心里。"}, {"text": "可爱", "is_correct": false, "explanation": "语义：可爱指令人喜爱的样子，不能描述心里的感受。"}, {"text": "健壮", "is_correct": false, "explanation": "体貌：健壮描写身体状况，不能用于心里。"}], "explanations": {"喜悦": "正确。“心里很喜悦”描述高兴的心情。", "喜庆": "搭配：喜庆多形容场面或节日气氛，不用来说人的心里。", "可爱": "语义：可爱指令人喜爱的样子，不能描述心里的感受。", "健壮": "体貌：健壮描写身体状况，不能用于心里。"}, "sentence_index": 0, "correct_answer": "喜悦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我非常喜悦这份礼物。", "explanation": "这里应该用〈喜欢〉。喜悦是形容词，只说心情，不能带宾语“这份礼物”。"}, {"text": "我很喜悦你的帮助。", "explanation": "这里应该用〈感谢〉。喜悦是形容词，不能带宾语“你的帮助”。"}, {"text": "我们喜悦新同学。", "explanation": "这里应该用〈欢迎〉。喜悦是形容词，不能带宾语“新同学”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87367, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喜悦", "is_correct": true, "explanation": "正确。“喜悦极了”表示高兴到极点，与“考试通过了”呼应。"}, {"text": "悲痛", "is_correct": false, "explanation": "语义：悲痛表示极度伤心，与“考试通过了”的结果矛盾。"}, {"text": "漠然", "is_correct": false, "explanation": "语义：漠然指不在意，与“考试通过了”后的激动不合。"}, {"text": "苍白", "is_correct": false, "explanation": "体貌：苍白描写脸色，不用来说整体的心情。"}], "explanations": {"喜悦": "正确。“喜悦极了”表示高兴到极点，与“考试通过了”呼应。", "悲痛": "语义：悲痛表示极度伤心，与“考试通过了”的结果矛盾。", "漠然": "语义：漠然指不在意，与“考试通过了”后的激动不合。", "苍白": "体貌：苍白描写脸色，不用来说整体的心情。"}, "sentence_index": 6, "correct_answer": "喜悦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想喜悦一下。", "explanation": "这里应该用“开心”。喜悦是形容词，表示心情，不能带“一下”表示动作。"}, {"text": "你先喜悦一下，再工作吧。", "explanation": "这里应该用〈放松〉。喜悦不作动词，不能带“一下”。"}, {"text": "他听完后喜悦我一阵。", "explanation": "喜悦是形容词，不能直接带宾语“我”；要表达使人高兴，应说“让我高兴了一阵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87367, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她喜悦的接过了信。", "corrected_sentence": "她喜悦地接过了信。", "error_description": "修饰动词“接过”的状语要用“地”，写成“的”不通；正确为“喜悦地接过了信”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87367, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "听到好消息，她慢慢喜悦下来了。", "corrected_sentence": "听到好消息，她慢慢喜悦起来了。", "error_description": "表示情绪逐渐变化要用趋向补语“起来”，写成“下来”不通；正确为“慢慢喜悦起来了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
