INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87368, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "愉快，高兴的心情。", "primary_collocate": null, "pronunciation": "xǐ yuè", "ipa": "ɕi˨˩˦ ɥe˥˩", "syllable_count": 2, "sentences": [{"text": "他心中充满了喜悦。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想和你分享这份喜悦。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "喜悦写在她的脸上。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "收到礼物，孩子藏不住喜悦。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成功的喜悦让他忘了累。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把喜悦告诉了妈妈。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "回家的路上，我们都沉浸在喜悦中。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的喜悦很快传给了大家。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年的喜悦到处都是。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到女儿毕业，父亲有说不出的喜悦。", "target_word": "喜悦", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "名词：愉快、高兴的心情，可充满、分享、藏不住", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5557fc-539b-4cb6-b9b1-8d2660c41b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87368, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "喜悦", "is_correct": true, "explanation": "正确。喜悦读 xǐ yuè，指愉快、高兴的心情。"}, {"text": "喜雨", "is_correct": false, "explanation": "第二音节 yǔ（第三声）与 yuè（第四声）韵母不同、声调也不同，意思是及时雨。"}, {"text": "喜鹊", "is_correct": false, "explanation": "第二音节 què 与 yuè 声母不同（q 与零声母），是一种鸟。"}, {"text": "几月", "is_correct": false, "explanation": "第一音节 jǐ 与 xǐ 声母不同（j 与 x），意思是问月份。"}], "explanations": {"喜悦": "正确。喜悦读 xǐ yuè，指愉快、高兴的心情。", "喜雨": "第二音节 yǔ（第三声）与 yuè（第四声）韵母不同、声调也不同，意思是及时雨。", "喜鹊": "第二音节 què 与 yuè 声母不同（q 与零声母），是一种鸟。", "几月": "第一音节 jǐ 与 xǐ 声母不同（j 与 x），意思是问月份。"}, "sentence_index": null, "correct_answer": "喜悦"}, "level_3": {"options": [{"text": "喜悦", "is_correct": true, "explanation": "正确。“充满了喜悦”指心中装满高兴的心情。"}, {"text": "尘土", "is_correct": false, "explanation": "语义：尘土是灰尘，不是可以充满心中的情感。"}, {"text": "债务", "is_correct": false, "explanation": "语义：债务指欠的钱，与“心中”的情感不合。"}, {"text": "面貌", "is_correct": false, "explanation": "体貌：面貌指外表容貌，不能用于心中。"}], "explanations": {"喜悦": "正确。“充满了喜悦”指心中装满高兴的心情。", "尘土": "语义：尘土是灰尘，不是可以充满心中的情感。", "债务": "语义：债务指欠的钱，与“心中”的情感不合。", "面貌": "体貌：面貌指外表容貌，不能用于心中。"}, "sentence_index": 0, "correct_answer": "喜悦"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很喜悦我。", "explanation": "这里应该用〈喜欢〉。喜悦表示高兴的心情，不表示对人有好感，也不能带人作宾语。"}, {"text": "他感到一个喜悦。", "explanation": "这里的量词“个”不适合抽象名词“喜悦”，应用“一股”“一阵”。"}, {"text": "他终于克服了喜悦。", "explanation": "这里应该用〈困难〉。“克服”用于困难、缺点等负面事物，喜悦是积极情绪，不能说“克服喜悦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87368, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "喜悦", "is_correct": true, "explanation": "正确。“沉浸在……中”后接表示情绪或氛围的名词，与“回家的路上”相合。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾是废弃物，不是可以沉浸其中的情境。"}, {"text": "石块", "is_correct": false, "explanation": "搭配：石块是具体的硬物，不能作为可以沉浸其中的对象。"}, {"text": "体积", "is_correct": false, "explanation": "语义：体积指物体的大小，不能用来表示可以沉浸的对象。"}], "explanations": {"喜悦": "正确。“沉浸在……中”后接表示情绪或氛围的名词，与“回家的路上”相合。", "垃圾": "语义：垃圾是废弃物，不是可以沉浸其中的情境。", "石块": "搭配：石块是具体的硬物，不能作为可以沉浸其中的对象。", "体积": "语义：体积指物体的大小，不能用来表示可以沉浸的对象。"}, "sentence_index": 6, "correct_answer": "喜悦"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生把他的喜悦治好了。", "explanation": "这里应该用〈病〉。“治好”只用于疾病，喜悦是高兴的心情，不能被“治好”。"}, {"text": "他想消除喜悦。", "explanation": "这里应该用〈疲惫〉。消除用于去掉负面状态，喜悦不能被“消除”。"}, {"text": "他终于摆脱了喜悦。", "explanation": "这里应该用〈疾病〉。摆脱多用于去掉负面的事物，喜悦是积极情绪，不能说“摆脱喜悦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87368, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她心里涌起一个喜悦。", "corrected_sentence": "她心里涌起一阵喜悦。", "error_description": "抽象名词“喜悦”前的量词应用“阵”（或“股”），用“个”不妥；正确为“涌起一阵喜悦”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87368, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们沉浸喜悦之中。", "corrected_sentence": "孩子们沉浸在喜悦之中。", "error_description": "“沉浸”后要用介词“在”引出所沉浸的内容，漏掉“在”不通；正确为“沉浸在喜悦之中”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
