INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87369, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "奇怪是和平常不一样，让人觉得不明白。", "primary_collocate": null, "pronunciation": "qí guài", "ipa": "tɕʰi˧˥ kuai˥˩", "syllable_count": 2, "sentences": [{"text": "这个人说话很奇怪。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天路上一个人也没有，真奇怪。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我听到一个奇怪的声音。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今天穿得很奇怪。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道菜的味道有点奇怪。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他怎么还没来？真奇怪。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，房间里有奇怪的响声。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得这件事很奇怪。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫的叫声很奇怪。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门开着，里面没有人，太奇怪了。", "target_word": "奇怪", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "奇奇怪怪", "label": "重叠"}], "register": "中性", "sense_fingerprint": "形容词；和平常不一样；让人觉得不明白", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e50ef452-9f17-49b2-bfd5-efaaf3235ce1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87369, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高大", "is_correct": false, "explanation": "体貌：高大形容身材或体型，不能修饰说话。"}, {"text": "饱", "is_correct": false, "explanation": "搭配：饱形容吃得满足，不能修饰说话。"}, {"text": "远", "is_correct": false, "explanation": "语义：远指距离，与说话的方式无关。"}, {"text": "奇怪", "is_correct": true, "explanation": "正确。奇怪指和平常不一样、让人觉得不明白，可以修饰说话的样子。"}], "explanations": {"高大": "体貌：高大形容身材或体型，不能修饰说话。", "饱": "搭配：饱形容吃得满足，不能修饰说话。", "远": "语义：远指距离，与说话的方式无关。", "奇怪": "正确。奇怪指和平常不一样、让人觉得不明白，可以修饰说话的样子。"}, "sentence_index": 0, "correct_answer": "奇怪"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片森林在月光下很奇怪，美得让人忘记了时间。", "explanation": "这里应该用〈奇妙〉。奇怪指不寻常、让人疑惑，形容令人赞叹的景色要用奇妙。"}, {"text": "这家餐厅的服务很奇怪，服务员都很热情体贴。", "explanation": "这里应该用〈周到〉。奇怪指不寻常、让人疑惑，形容服务细致体贴要用周到。"}, {"text": "他的朗读很奇怪，老师称赞他读得非常好。", "explanation": "这里应该用〈标准〉。奇怪指不寻常、令人疑惑，形容朗读发音准确要用标准。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21502048-c903-47f7-9ff1-2e6422ff8ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87369, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "安静", "is_correct": false, "explanation": "语义：安静指没有声音，与“响声”意思矛盾。"}, {"text": "好看", "is_correct": false, "explanation": "搭配：好看形容外观，不能修饰声音。"}, {"text": "光滑", "is_correct": false, "explanation": "搭配：光滑形容表面的触感，不能修饰声音。"}, {"text": "奇怪", "is_correct": true, "explanation": "正确。奇怪指与平常不同、让人疑惑，可以修饰响声。"}], "explanations": {"安静": "语义：安静指没有声音，与“响声”意思矛盾。", "好看": "搭配：好看形容外观，不能修饰声音。", "光滑": "搭配：光滑形容表面的触感，不能修饰声音。", "奇怪": "正确。奇怪指与平常不同、让人疑惑，可以修饰响声。"}, "sentence_index": 6, "correct_answer": "奇怪"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的字很奇怪，老师看了都夸他写得很漂亮。", "explanation": "这里应该用〈工整〉。奇怪指不寻常、让人疑惑，形容字写得整齐好看要用工整。"}, {"text": "我每天认真复习，这次考试成绩很奇怪，考了全班第一，妈妈很满意。", "explanation": "这里应该用〈好〉。奇怪指不寻常、令人疑惑，认真复习后考得好是意料之中，应说成绩很好。"}, {"text": "这间书房的布置很奇怪，每本书都摆得很整齐。", "explanation": "这里应该用〈整齐〉。奇怪指不寻常、令人疑惑，形容书房摆放有序要用整齐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21502048-c903-47f7-9ff1-2e6422ff8ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87369, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他最近说话很的奇怪。", "corrected_sentence": "他最近说话很奇怪。", "error_description": "助词错误：“很”和“奇怪”之间不能加“的”。程度副词修饰形容词时直接相连，应说“很奇怪”，不能说“很的奇怪”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21502048-c903-47f7-9ff1-2e6422ff8ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87369, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他奇怪地地笑了一下。", "corrected_sentence": "他奇怪地笑了一下。", "error_description": "助词重复：“地”不能连用两次。“奇怪”修饰动词“笑”时只用一个“地”，应说“奇怪地笑了一下”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '21502048-c903-47f7-9ff1-2e6422ff8ec6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
