INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87374, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不经烹煮而直接吃。", "primary_collocate": null, "pronunciation": "shēng chī", "ipa": "ʂɤŋ˥ ʈʂʰɻ̩˥", "syllable_count": 2, "sentences": [{"text": "洗干净的黄瓜可以直接生吃。", "target_word": "生吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河里的螃蟹不要生吃，有虫子。", "target_word": "生吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你敢生吃大蒜吗？", "target_word": "生吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种蘑菇有毒，千万别生吃。", "target_word": "生吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说，生吃红薯对身体不好。", "target_word": "生吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她第一次生吃牡蛎，觉得很特别。", "target_word": "生吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玉米煮着吃很甜，生吃也很好吃。", "target_word": "生吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个菜是生吃的，不用加热。", "target_word": "生吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了健康，我不再生吃肉了。", "target_word": "生吃", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在海边生吃着刚打上来的鱼。", "target_word": "生吃", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生吃过", "label": "经验体"}, {"form": "生吃着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "不经过烹煮，直接把食物吃下去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d04d293-e650-4428-be70-164f690aefe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87374, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "弄脏", "is_correct": false, "explanation": "语义：「洗干净」与「弄脏」矛盾，不能说洗干净的黄瓜可以直接弄脏"}, {"text": "生吃", "is_correct": true, "explanation": "正确：生吃即不煮不炒直接吃，与「直接」相符"}, {"text": "喝", "is_correct": false, "explanation": "搭配：「喝」用于液体，黄瓜是固体，不能说直接喝"}, {"text": "送给", "is_correct": false, "explanation": "配价：「送给」要说明送给谁，句中没有接受者，不成立"}], "explanations": {"弄脏": "语义：「洗干净」与「弄脏」矛盾，不能说洗干净的黄瓜可以直接弄脏", "生吃": "正确：生吃即不煮不炒直接吃，与「直接」相符", "喝": "搭配：「喝」用于液体，黄瓜是固体，不能说直接喝", "送给": "配价：「送给」要说明送给谁，句中没有接受者，不成立"}, "sentence_index": 0, "correct_answer": "生吃"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把煮熟的玉米生吃了，觉得很甜。", "explanation": "这里误用了〈生吃〉：它指没煮过就吃，玉米已经煮熟，应直接说〈吃〉。"}, {"text": "这些饺子已经煮好了，我们可以直接生吃。", "explanation": "这里误用了〈生吃〉：它指没煮过就吃，饺子已经煮好，应直接说〈吃〉。"}, {"text": "他考试前生吃了三本书，成绩很好。", "explanation": "「生吃」指不煮就吃食物，不能表示死记硬背，这里意思不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87374, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扔掉", "is_correct": false, "explanation": "语义：扔掉的东西不能说好吃，与「也很好吃」矛盾"}, {"text": "生吃", "is_correct": true, "explanation": "正确：生吃指不煮就吃，与前半句「煮着吃」形成对比"}, {"text": "拍照", "is_correct": false, "explanation": "搭配：「拍照」与「好吃」不搭，句子谈的是吃的感受"}, {"text": "交给", "is_correct": false, "explanation": "配价：「交给」要说明交给谁，句中没有接受者，不成立"}], "explanations": {"扔掉": "语义：扔掉的东西不能说好吃，与「也很好吃」矛盾", "生吃": "正确：生吃指不煮就吃，与前半句「煮着吃」形成对比", "拍照": "搭配：「拍照」与「好吃」不搭，句子谈的是吃的感受", "交给": "配价：「交给」要说明交给谁，句中没有接受者，不成立"}, "sentence_index": 6, "correct_answer": "生吃"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们在海边生吃着刚打上来的石头。", "explanation": "这里误用了〈生吃〉：它只用于可以吃的食物，石头不是食物，不能说生吃石头。"}, {"text": "这孩子又在生吃着彩色的蜡笔。", "explanation": "这里误用了〈生吃〉：它只用于可以吃的食物，蜡笔不是食物，不能说生吃蜡笔。"}, {"text": "他生吃着老师的答案，一个字也不改。", "explanation": "「生吃」指不煮就吃食物，不能表示照搬答案，这里意思不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87374, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些小番茄可以直接生生吃。", "corrected_sentence": "这些小番茄可以直接生吃。", "error_description": "错误：「生」多重复了一次。「生吃」是固定的动词复合，「生」不能重复，应为「直接生吃」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87374, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他很快就生吃了完那盘鱼片。", "corrected_sentence": "他很快就生吃完了那盘鱼片。", "error_description": "补语位置错误。结果补语「完」应紧接动词，应为「生吃完了」，不能说「生吃了完」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
