INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87375, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "国内线是只在自己国家里飞的飞机路线。", "primary_collocate": null, "pronunciation": "guó nèi xiàn", "ipa": "kwo˧˥ nei˥˩ ɕjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "国内线只在中国国内飞。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去海南玩，我选了国内线。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内线不用出国，所以很方便。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内线的飞机比国际线小一些。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每周坐国内线去出差。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小机场只有国内线。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从广州到西安，要坐国内线。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内线的航站楼在左边。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次坐国内线，心里有点紧张。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们开通了一条新的国内线。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "國內線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "只在自己国家里飞的飞机路线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4cf27cd-43b5-427b-9ffd-1e148fc0d9bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87375, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国内线", "is_correct": true, "explanation": "国内线只在本国境内飞，与“只在中国国内飞”相符。"}, {"text": "国际线", "is_correct": false, "explanation": "语义：国际线是飞往境外的航线，与“只在中国国内飞”的限定相反。"}, {"text": "高铁", "is_correct": false, "explanation": "搭配：“飞”只用于飞机、航班，高铁不会飞。"}, {"text": "北京", "is_correct": false, "explanation": "语义：北京是城市名，不是航线，不能“只在中国国内飞”。"}], "explanations": {"国内线": "国内线只在本国境内飞，与“只在中国国内飞”相符。", "国际线": "语义：国际线是飞往境外的航线，与“只在中国国内飞”的限定相反。", "高铁": "搭配：“飞”只用于飞机、航班，高铁不会飞。", "北京": "语义：北京是城市名，不是航线，不能“只在中国国内飞”。"}, "sentence_index": 0, "correct_answer": "国内线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条国内线的终点是伦敦。", "explanation": "这里应该用〈国际线〉。国内线只在本国境内飞，终点不能是伦敦这样的境外城市。"}, {"text": "我们今天坐的是一架国内线。", "explanation": "这里应该用〈条〉。“架”用于飞机，国内线指航线，要用“条”。"}, {"text": "我们在码头登上国内线。", "explanation": "国内线是飞机的航线，要在机场乘坐，不能在码头登上。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87375, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国内线", "is_correct": true, "explanation": "国内线是飞机航线，乘坐它从广州到西安，符合“要坐”的语境。"}, {"text": "电梯", "is_correct": false, "explanation": "语义：电梯只在楼层之间运行，不能从广州到西安。"}, {"text": "公交", "is_correct": false, "explanation": "语义：公交是市内公共汽车，不能跨城市从广州到西安。"}, {"text": "地下室", "is_correct": false, "explanation": "搭配：“坐”搭配交通工具，“地下室”不是可以乘坐的东西，搭配不当。"}], "explanations": {"国内线": "国内线是飞机航线，乘坐它从广州到西安，符合“要坐”的语境。", "电梯": "语义：电梯只在楼层之间运行，不能从广州到西安。", "公交": "语义：公交是市内公共汽车，不能跨城市从广州到西安。", "地下室": "搭配：“坐”搭配交通工具，“地下室”不是可以乘坐的东西，搭配不当。"}, "sentence_index": 6, "correct_answer": "国内线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的国内线是一位老师。", "explanation": "这里把国内线当成了人。国内线是航线，不能指人，不能说“是一位老师”。"}, {"text": "国内线的比赛下午开始。", "explanation": "国内线是航线，不是比赛或活动，这里误把它当成了事件。"}, {"text": "我把行李装进了国内线里。", "explanation": "国内线是航线，不是可以装东西的容器或场所，不能说“装进国内线里”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87375, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个机场又多了一张国内线。", "corrected_sentence": "这个机场又多了一条国内线。", "error_description": "量词错误：“张”用于纸、票等，“国内线”指航线，要用“条”，应说“一条国内线”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87375, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几条国内线们今天都满座了。", "corrected_sentence": "这几条国内线今天都满座了。", "error_description": "错误在“国内线”后加了“们”。国内线指航线，不指人，不能加“们”，应说“这几条国内线”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
