INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87376, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在本国境内各地之间运营的航线。", "primary_collocate": null, "pronunciation": "guó nèi xiàn", "ipa": "kwo˧˥ nei˥˩ ɕjɛn˥˩", "syllable_count": 3, "sentences": [{"text": "这条国内线每天有三个航班。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我坐国内线去成都，不用带护照。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内线的机票比去年便宜了。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机场的国内线很多。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天的国内线航班因为大雪取消了。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内线的飞机上不提供热饭。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在航空公司负责国内线的工作。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司新开了一条国内线。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北京到上海是很忙的国内线。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国内线起飞前一小时要到机场。", "target_word": "国内线", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "國內線", "label": "繁体"}], "register": "中性", "sense_fingerprint": "在本国境内各地之间运营的航线", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a4cf27cd-43b5-427b-9ffd-1e148fc0d9bc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87376, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "国内线", "is_correct": true, "explanation": "国内线指在本国境内各地之间运营的航线，与“每天有三个航班”相符。"}, {"text": "铁路", "is_correct": false, "explanation": "搭配：“航班”只在航线上运营，“铁路”不能与“航班”搭配。"}, {"text": "公路", "is_correct": false, "explanation": "语义：公路是供车辆通行的陆路，不运营航班。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是自然水道，不会有航班。"}], "explanations": {"国内线": "国内线指在本国境内各地之间运营的航线，与“每天有三个航班”相符。", "铁路": "搭配：“航班”只在航线上运营，“铁路”不能与“航班”搭配。", "公路": "语义：公路是供车辆通行的陆路，不运营航班。", "河流": "语义：河流是自然水道，不会有航班。"}, "sentence_index": 0, "correct_answer": "国内线"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条国内线飞往伦敦。", "explanation": "这里应该用〈国际线〉。国内线只在本国境内各地之间运营，不能飞往伦敦这样的境外城市。"}, {"text": "我们公司新开了一架国内线。", "explanation": "这里应该用〈条〉。“架”用于飞机，国内线指航线，要用“条”。"}, {"text": "我们去火车站坐国内线。", "explanation": "国内线是航空线路，只能在机场乘坐，不能在火车站乘坐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87376, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "国内线", "is_correct": true, "explanation": "国内线是航空线路，“负责国内线的工作”符合“在航空公司负责……的工作”的语境。"}, {"text": "中药", "is_correct": false, "explanation": "语义：中药是药品，与航空公司的工作无关。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋是自然地理对象，不是航空公司负责的工作内容。"}, {"text": "脾气", "is_correct": false, "explanation": "搭配：“负责”一般搭配具体事务，“脾气”不能被负责，搭配不当。"}], "explanations": {"国内线": "国内线是航空线路，“负责国内线的工作”符合“在航空公司负责……的工作”的语境。", "中药": "语义：中药是药品，与航空公司的工作无关。", "海洋": "语义：海洋是自然地理对象，不是航空公司负责的工作内容。", "脾气": "搭配：“负责”一般搭配具体事务，“脾气”不能被负责，搭配不当。"}, "sentence_index": 6, "correct_answer": "国内线"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家餐厅新开了一条国内线。", "explanation": "国内线是航线，不是餐厅或其他场所，这里把它用在了餐厅上。"}, {"text": "我把行李装进了国内线里。", "explanation": "国内线是航线，不是可以装东西的容器或场所，不能说“装进国内线里”。"}, {"text": "这条国内线的司机很热情。", "explanation": "国内线是航线，不是有司机的交通工具，这里误把它当成了人或车辆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87376, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这架国内线昨天开始停运了。", "corrected_sentence": "这条国内线昨天开始停运了。", "error_description": "错误在量词：“架”用于飞机，“国内线”指航线，应说“这条国内线”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87376, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些国内线们都很忙。", "corrected_sentence": "这些国内线都很忙。", "error_description": "错误在“国内线”后加了“们”。国内线指航线，不指人，不能加“们”，应说“这些国内线”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7553a4a7-0986-4a7d-a848-bd4df466845b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
