INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87377, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "function", "definition": "表示样子差不多，如同某物一样。", "primary_collocate": null, "pronunciation": "hǎo xiàng", "ipa": "xɑʊ˨˩ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "她笑起来好像一朵花。", "target_word": "好像", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "天上的云好像一只大白兔。", "target_word": "好像", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小河里的水好像镜子一样干净。", "target_word": "好像", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们两个人长得好像双胞胎。", "target_word": "好像", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雪白的月亮好像一个大盘子挂在天上。", "target_word": "好像", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子的小手好像一片小小的叶子。", "target_word": "好像", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "远处的山好像一条长长的龙。", "target_word": "好像", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他高兴得好像一个小孩子。", "target_word": "好像", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "今天的天气热得好像夏天一样。", "target_word": "好像", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这只小狗的耳朵好像两片大叶子，很可爱。", "target_word": "好像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "好象", "label": "异体"}], "register": "中性", "sense_fingerprint": "好像·比喻·样子相似", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 9 above tier T1: 3 words above tier T1 (max 2): 小狗 (Zipf 3.89), 两片 (Zipf 3.31), 叶子 (Zipf 3.84)']::text[], '02e6c952-5557-4423-80e1-8c7df400d0c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87377, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好像", "is_correct": true, "explanation": "好像（xiàng 第四声）：表示两者样子相似，符合句意。"}, {"text": "好想", "is_correct": false, "explanation": "好想（xiǎng 第三声）与好像的第二音节声调不同，意思是“很想”。"}, {"text": "好香", "is_correct": false, "explanation": "好香（xiāng 第一声）与好像的第二音节声调不同，意思是“很香”。"}, {"text": "好响", "is_correct": false, "explanation": "好响（xiǎng 第三声）与好像的第二音节声调不同，意思是“声音很大”。"}], "explanations": {"好像": "好像（xiàng 第四声）：表示两者样子相似，符合句意。", "好想": "好想（xiǎng 第三声）与好像的第二音节声调不同，意思是“很想”。", "好香": "好香（xiāng 第一声）与好像的第二音节声调不同，意思是“很香”。", "好响": "好响（xiǎng 第三声）与好像的第二音节声调不同，意思是“声音很大”。"}, "sentence_index": null, "correct_answer": "好像"}, "level_3": {"options": [{"text": "好像", "is_correct": true, "explanation": "好像：表示“像”的比喻，“她笑起来好像一朵花”符合句意。"}, {"text": "就", "is_correct": false, "explanation": "语义：“就”表示“只是、就是”，与“笑起来像一朵花”的比喻意思不合。"}, {"text": "仅", "is_correct": false, "explanation": "语义：“仅”表示只有、限于，与“笑起来像一朵花”的比喻意思不合。"}, {"text": "只", "is_correct": false, "explanation": "语义：“只”表示限定，与“笑起来”的比喻不合。"}], "explanations": {"好像": "好像：表示“像”的比喻，“她笑起来好像一朵花”符合句意。", "就": "语义：“就”表示“只是、就是”，与“笑起来像一朵花”的比喻意思不合。", "仅": "语义：“仅”表示只有、限于，与“笑起来像一朵花”的比喻意思不合。", "只": "语义：“只”表示限定，与“笑起来”的比喻不合。"}, "sentence_index": 0, "correct_answer": "好像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她笑起来好像，很可爱。", "explanation": "比喻句中的“好像”后面必须有被比作的事物，此处缺少比较对象，应补出如“一朵花”。"}, {"text": "这张桌子好像星期五一样。", "explanation": "用“好像”打比方，两者要有看得出的相似之处；桌子和星期五毫无共同点，无法用“好像”作比。"}, {"text": "她是好像一朵花。", "explanation": "“是”表示判断，“好像”表示相似，两者不能并列；打比方时应说“好像一朵花”或“像一朵花”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87377, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好像", "is_correct": true, "explanation": "好像：表示“像”的比喻，“远处的山好像一条长长的龙”符合句意。"}, {"text": "足足", "is_correct": false, "explanation": "语义：“足足”表示数量充足，与“像一条长龙”的比喻不合。"}, {"text": "才", "is_correct": false, "explanation": "配价：“才”后接数量短语表示“仅有”，不能用来说山像龙。"}, {"text": "整整", "is_correct": false, "explanation": "语义：“整整”表示数量完整，不能表示比喻关系。"}], "explanations": {"好像": "好像：表示“像”的比喻，“远处的山好像一条长长的龙”符合句意。", "足足": "语义：“足足”表示数量充足，与“像一条长龙”的比喻不合。", "才": "配价：“才”后接数量短语表示“仅有”，不能用来说山像龙。", "整整": "语义：“整整”表示数量完整，不能表示比喻关系。"}, "sentence_index": 6, "correct_answer": "好像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那只猫的尾巴好像，很长。", "explanation": "比喻句中的“好像”后面必须有被比作的事物，此处缺少比较对象，应补出如“一条长绳”。"}, {"text": "这只小狗的耳朵好像星期一一样。", "explanation": "用“好像”打比方，两者要有看得出的相似之处；耳朵和星期一毫无共同点，无法用“好像”作比。"}, {"text": "这只小狗的耳朵是好像两片大叶子。", "explanation": "“是”表示判断，“好像”表示相似，两者不能并列；打比方时应说“好像两片大叶子”或“像两片大叶子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87377, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的眼睛好像的两颗黑葡萄。", "corrected_sentence": "他的眼睛好像两颗黑葡萄。", "error_description": "错误：“好像”后面多加了“的”。“好像”后直接接比较对象，中间不能加“的”，应说“好像两颗黑葡萄”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87377, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋里的灯亮得好像了白天一样。", "corrected_sentence": "屋里的灯亮得好像白天一样。", "error_description": "错误：“好像”后面多加了“了”。“好像”表示比喻，后面不能加“了”，应说“好像白天一样”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
