INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87378, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "表示不很确定的推测，相当于“似乎”。", "primary_collocate": null, "pronunciation": "hǎo xiàng", "ipa": "xɑʊ˨˩ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他好像不在家。", "target_word": "好像", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她好像不太高兴。", "target_word": "好像", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师好像还没有来。", "target_word": "好像", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我好像在哪儿见过你。", "target_word": "好像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他好像忘了带手机。", "target_word": "好像", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个问题好像很难，我不会做。", "target_word": "好像", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "楼上好像有人在跳舞，声音很大。", "target_word": "好像", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的钥匙好像放在桌子上了。", "target_word": "好像", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们好像都不知道明天开会的时间。", "target_word": "好像", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天黑了，路上好像一个人也没有。", "target_word": "好像", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "好象", "label": "异体"}], "register": "口语", "sense_fingerprint": "好像·似乎·揣测", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02e6c952-5557-4423-80e1-8c7df400d0c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87378, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "好像", "is_correct": true, "explanation": "好像（hǎo xiàng）：表示似乎、大概的揣测，符合句意。"}, {"text": "好想", "is_correct": false, "explanation": "好想（xiǎng 第三声）与好像的第二音节声调不同，意思是“很想”。"}, {"text": "好香", "is_correct": false, "explanation": "好香（xiāng 第一声）与好像的第二音节声调不同，意思是“很香”。"}, {"text": "好响", "is_correct": false, "explanation": "好响（xiǎng 第三声）与好像的第二音节声调不同，意思是“声音很大”。"}], "explanations": {"好像": "好像（hǎo xiàng）：表示似乎、大概的揣测，符合句意。", "好想": "好想（xiǎng 第三声）与好像的第二音节声调不同，意思是“很想”。", "好香": "好香（xiāng 第一声）与好像的第二音节声调不同，意思是“很香”。", "好响": "好响（xiǎng 第三声）与好像的第二音节声调不同，意思是“声音很大”。"}, "sentence_index": null, "correct_answer": "好像"}, "level_3": {"options": [{"text": "好像", "is_correct": true, "explanation": "好像：表示揣测，“他好像不在家”符合句意。"}, {"text": "很", "is_correct": false, "explanation": "搭配：“很”修饰形容词和心理动词，不能用于“不在家”这类动词性否定短语。"}, {"text": "更", "is_correct": false, "explanation": "语义：“更”表示程度加深，与“他不在家”的推测不合。"}, {"text": "最", "is_correct": false, "explanation": "搭配：“最”表示程度最高，不能修饰“不在家”。"}], "explanations": {"好像": "好像：表示揣测，“他好像不在家”符合句意。", "很": "搭配：“很”修饰形容词和心理动词，不能用于“不在家”这类动词性否定短语。", "更": "语义：“更”表示程度加深，与“他不在家”的推测不合。", "最": "搭配：“最”表示程度最高，不能修饰“不在家”。"}, "sentence_index": 0, "correct_answer": "好像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他好像一定是昨天走的，我亲眼看见了。", "explanation": "“好像”表示不太确定，与“一定是昨天走的”和“亲眼看见”的确定语气矛盾，应改用表示确定的副词，如〈确实〉。"}, {"text": "这盒子里好像装着十个苹果，我数了，正好十个。", "explanation": "“好像”表示不太确定，与“我数了，正好十个”的确切结果矛盾；应去掉“好像”，直接说“这盒子里装着十个苹果”。"}, {"text": "这台电脑好像一定能开机，我昨天修好了。", "explanation": "这里应该用〈确实〉。“好像”表示不太确定，与“一定能开机”和“修好了”的确定语气矛盾；说确定能开机要用〈确实〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87378, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "好像", "is_correct": true, "explanation": "好像：表示揣测，“楼上好像有人在跳舞”符合句意。"}, {"text": "太", "is_correct": false, "explanation": "搭配：“太”修饰形容词，不能用在“有人”前面。"}, {"text": "格外", "is_correct": false, "explanation": "语义：“格外”表示特别，与“楼上有人跳舞”的推测不合。"}, {"text": "十分", "is_correct": false, "explanation": "搭配：“十分”修饰形容词，不能用在“有人”前面。"}], "explanations": {"好像": "好像：表示揣测，“楼上好像有人在跳舞”符合句意。", "太": "搭配：“太”修饰形容词，不能用在“有人”前面。", "格外": "语义：“格外”表示特别，与“楼上有人跳舞”的推测不合。", "十分": "搭配：“十分”修饰形容词，不能用在“有人”前面。"}, "sentence_index": 6, "correct_answer": "好像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "屋里好像一定没有人，可我刚才亲耳听见有人说话。", "explanation": "“好像”表示不太确定，与“一定没有人”的确定语气矛盾，应改用〈明明〉之类表示确定的副词。"}, {"text": "这块石头好像一定重二十公斤，我称过了。", "explanation": "“好像”表示不太确定，与“我称过了”的确切结果矛盾；应去掉“好像一定”，说“这块石头重二十公斤”，或改用〈确实〉。"}, {"text": "这份报告好像百分之百已经交给老板了，他昨天亲手签收的。", "explanation": "“好像”表示不太确定，与“百分之百”和“亲手签收”的确定事实矛盾，应改用〈确实〉之类表示确定的副词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87378, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老板好像了不在办公室。", "corrected_sentence": "老板好像不在办公室。", "error_description": "错误：“好像”后面多加了“了”。“好像”表示揣测，后面直接接陈述，不能加“了”，应说“好像不在办公室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87378, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "屋里好像的有人在说话，声音很低。", "corrected_sentence": "屋里好像有人在说话，声音很低。", "error_description": "错误：“好像”后面多加了“的”。“好像”是副词，后面直接接陈述，不加“的”，应说“好像有人在说话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
