INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87379, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "当晚是事情发生的那天晚上。", "primary_collocate": null, "pronunciation": "dàng wǎn", "ipa": "taŋ˥˩ wan˨˩˦", "syllable_count": 2, "sentences": [{"text": "演唱会当晚，很多人去了体育馆。", "target_word": "当晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他下了飞机，当晚就开始工作。", "target_word": "当晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我买了票，当晚就坐火车走了。", "target_word": "当晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "婚礼当晚，朋友们唱了很多歌。", "target_word": "当晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出事当晚，他一个人在公司。", "target_word": "当晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她收到信，当晚就给妈妈回了电话。", "target_word": "当晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试结果出来，当晚我睡不着。", "target_word": "当晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "当晚下着雪，路上没有车。", "target_word": "当晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当晚喝了很多酒，第二天头疼。", "target_word": "当晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们早上到，当晚参加了晚会。", "target_word": "当晚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "某件事发生的那天夜晚", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d04d293-e650-4428-be70-164f690aefe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87379, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "赛后", "is_correct": false, "explanation": "搭配：「赛后」是体育比赛用语，演唱会不说赛后"}, {"text": "当晚", "is_correct": true, "explanation": "正确：当晚指演唱会举行当天的晚上，与「去了体育馆」相符"}, {"text": "体育场", "is_correct": false, "explanation": "语义：体育场是地点不是时间，不能放在这个时间位置"}, {"text": "开赛时", "is_correct": false, "explanation": "搭配：「开赛时」是体育比赛用语，演唱会不说开赛"}], "explanations": {"赛后": "搭配：「赛后」是体育比赛用语，演唱会不说赛后", "当晚": "正确：当晚指演唱会举行当天的晚上，与「去了体育馆」相符", "体育场": "语义：体育场是地点不是时间，不能放在这个时间位置", "开赛时": "搭配：「开赛时」是体育比赛用语，演唱会不说开赛"}, "sentence_index": 0, "correct_answer": "当晚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "婚礼当晚中午，朋友们唱了很多歌。", "explanation": "这里应该用〈当天〉。「当晚」指晚上，与「中午」矛盾，表示整天要用「当天」。"}, {"text": "我每天加班，当晚都很累。", "explanation": "这里误用了〈当晚〉：它只指某件事发生的那天晚上，不能用于每天的情况，应说〈晚上〉。"}, {"text": "婚礼当晚早上，朋友们才来到。", "explanation": "这里应该用〈次日〉。「当晚」指晚上，与「早上」矛盾，应说「次日早上」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87379, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "交卷前", "is_correct": false, "explanation": "语义：结果出来时已经交卷，「交卷前」与句意矛盾"}, {"text": "当晚", "is_correct": true, "explanation": "正确：当晚指考试结果出来当天的晚上，与「结果出来」相呼应"}, {"text": "上周", "is_correct": false, "explanation": "语义：结果刚出来，却说上周睡不着，时间上对不上"}, {"text": "当场", "is_correct": false, "explanation": "搭配：「当场」指立即在现场，不能修饰「睡不着」这种持续状态"}], "explanations": {"交卷前": "语义：结果出来时已经交卷，「交卷前」与句意矛盾", "当晚": "正确：当晚指考试结果出来当天的晚上，与「结果出来」相呼应", "上周": "语义：结果刚出来，却说上周睡不着，时间上对不上", "当场": "搭配：「当场」指立即在现场，不能修饰「睡不着」这种持续状态"}, "sentence_index": 6, "correct_answer": "当晚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们早上到，当晚中午参加了晚会。", "explanation": "这里应该用〈当天〉。「当晚」指晚上，与「中午」矛盾，应说「当天中午」。"}, {"text": "我们早上到，当晚的早饭吃得很饱。", "explanation": "「当晚」指晚上，与「早饭」矛盾，早上要说「当天早上」。"}, {"text": "我们早上到，当晚的午饭很丰盛。", "explanation": "「当晚」指晚上，与「午饭」矛盾，中午要说「当天中午」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87379, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "婚礼当晚的，朋友们很开心。", "corrected_sentence": "婚礼当晚，朋友们很开心。", "error_description": "错误：“当晚”后面多加了“的”。时间词作状语时后面不能直接加“的”，正确形式是“婚礼当晚，朋友们很开心”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87379, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "搬家当晚上，我们很早就睡了。", "corrected_sentence": "搬家当晚，我们很早就睡了。", "error_description": "错误：「当晚」后面多加了「上」。「当晚」本身已经指那天晚上，不能再说「当晚上」，正确形式是「搬家当晚，我们很早就睡了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
