INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87381, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "带领旅游团、合唱团等团体的人。", "primary_collocate": null, "pronunciation": "tuán zhǎng", "ipa": "tʰwan˧˥ ʈʂaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "这次旅行的团长是李老师。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团长带着大家参观博物馆。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团长说八点在门口见面。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团长给每个人发了一张地图。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都听团长的安排。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团长数了数人，一共二十个。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，团长让大家先回酒店。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是我们合唱团的团长。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团长请大家坐上了大巴。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团长每天都要检查人数。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位团长", "label": "量词"}, {"form": "副团长", "label": "复合"}], "register": "中性", "sense_fingerprint": "旅游团、合唱团等团体的带队人或负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dee2df57-fb87-4f86-b7e0-dc23161c9f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87381, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行李", "is_correct": false, "explanation": "语义：“行李”是随身物品，不能指人，与“是李老师”不符。"}, {"text": "团长", "is_correct": true, "explanation": "“团长”指带领旅游团的人，与“这次旅行”的语境相符，且可以是李老师。"}, {"text": "地图", "is_correct": false, "explanation": "语义：“地图”是物品，不能指人。"}, {"text": "乐队", "is_correct": false, "explanation": "语义：“乐队”指一群演奏的人组成的团体，不能指一个带队的人，与“是李老师”不符。"}], "explanations": {"行李": "语义：“行李”是随身物品，不能指人，与“是李老师”不符。", "团长": "“团长”指带领旅游团的人，与“这次旅行”的语境相符，且可以是李老师。", "地图": "语义：“地图”是物品，不能指人。", "乐队": "语义：“乐队”指一群演奏的人组成的团体，不能指一个带队的人，与“是李老师”不符。"}, "sentence_index": 0, "correct_answer": "团长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们医院的团长今天来看病人了。", "explanation": "这里应该用〈院长〉。“团长”指带领旅游团、合唱团等团体的人，医院的负责人叫院长。"}, {"text": "我们厂的团长在会上讲了话。", "explanation": "这里应该用〈厂长〉。“团长”指带领一个团的人，工厂的负责人叫厂长。"}, {"text": "我们小组的团长很热情。", "explanation": "这里应该用〈组长〉。“团长”指带领一个团的人，小组的负责人叫组长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87381, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雨伞", "is_correct": false, "explanation": "语义：“雨伞”是物品，不能指使大家做事。"}, {"text": "团长", "is_correct": true, "explanation": "“团长”是能带领大家行动的人，符合“让大家先回酒店”的语境。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：“窗户”不能有意地让人行动，与句意不符。"}, {"text": "纸巾", "is_correct": false, "explanation": "配价：“让”要求主语是能指使他人的人，“纸巾”不能充当。"}], "explanations": {"雨伞": "语义：“雨伞”是物品，不能指使大家做事。", "团长": "“团长”是能带领大家行动的人，符合“让大家先回酒店”的语境。", "窗户": "语义：“窗户”不能有意地让人行动，与句意不符。", "纸巾": "配价：“让”要求主语是能指使他人的人，“纸巾”不能充当。"}, "sentence_index": 6, "correct_answer": "团长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们的团长有二十个人。", "explanation": "这里应该用〈团〉。“团长”指带队的人，指整个团体要说〈团〉。"}, {"text": "我们科室的团长每天都要检查人数。", "explanation": "这里应该用〈主任〉。“团长”指带领一个团的人，科室的负责人叫主任。"}, {"text": "我们班的团长每天都要检查人数。", "explanation": "这里应该用〈班长〉。“团长”指带领旅游团、合唱团等团体的人，班级的负责人叫班长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87381, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只团长带我们去了博物馆。", "corrected_sentence": "一位团长带我们去了博物馆。", "error_description": "量词用错。“团长”指人，应用量词“位”，不能用“只”。正确应为“一位团长带我们去了博物馆”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87381, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "一台团长在车上讲话。", "corrected_sentence": "一位团长在车上讲话。", "error_description": "量词用错。“台”用于机器，指人应用“位”。正确应为“一位团长在车上讲话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
