INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87382, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "团的主要负责人，指军队中的团级指挥官。", "primary_collocate": null, "pronunciation": "tuán zhǎng", "ipa": "tʰwan˧˥ ʈʂaŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他在部队当了十年团长。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团长命令战士们马上出发。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位团长很年轻，只有三十岁。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团长在会上讲了训练计划。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们都很尊敬他们的团长。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团长坐着车去看望受伤的战士。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文工团的团长是一位老演员。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团长把任务交给了一营。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的团长今天见了全团的战士。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "团长要求大家每天早上跑步。", "target_word": "团长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位团长", "label": "量词"}, {"form": "副团长", "label": "复合"}], "register": "中性", "sense_fingerprint": "军队中的团级指挥官，或文工团等军队团体的主要负责人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dee2df57-fb87-4f86-b7e0-dc23161c9f7f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87382, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "学生", "is_correct": false, "explanation": "语义：“学生”指在校读书的人，与“在部队当了十年”不符。"}, {"text": "团长", "is_correct": true, "explanation": "“团长”是部队团级指挥官，与“在部队当了十年”的语境相符。"}, {"text": "行李", "is_correct": false, "explanation": "语义：“行李”是物品，不能用“当”指人。"}, {"text": "乐队", "is_correct": false, "explanation": "搭配：“当了十年”后接职务或职业，“乐队”是团体名称，不能这样搭配。"}], "explanations": {"学生": "语义：“学生”指在校读书的人，与“在部队当了十年”不符。", "团长": "“团长”是部队团级指挥官，与“在部队当了十年”的语境相符。", "行李": "语义：“行李”是物品，不能用“当”指人。", "乐队": "搭配：“当了十年”后接职务或职业，“乐队”是团体名称，不能这样搭配。"}, "sentence_index": 0, "correct_answer": "团长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的团长在会上讲了训练计划。", "explanation": "这里应该用〈董事长〉。“团长”用于军队或团体的带队人，公司的负责人叫董事长。"}, {"text": "这所医院的团长在会上讲了训练计划。", "explanation": "这里应该用〈院长〉。“团长”指团的主要负责人，医院的负责人叫院长。"}, {"text": "我们饭店的团长在会上讲了训练计划。", "explanation": "这里应该用〈经理〉。“团长”指团的主要负责人，饭店的负责人叫经理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87382, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "舞台", "is_correct": false, "explanation": "语义：“舞台”是表演的场所，不能是人，与“是一位老演员”不符。"}, {"text": "团长", "is_correct": true, "explanation": "“团长”是文工团的负责人，可以是一位老演员，符合句意。"}, {"text": "节目", "is_correct": false, "explanation": "语义：“节目”是表演内容，不能指人。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”是钱，不能与“是一位老演员”搭配指人。"}], "explanations": {"舞台": "语义：“舞台”是表演的场所，不能是人，与“是一位老演员”不符。", "团长": "“团长”是文工团的负责人，可以是一位老演员，符合句意。", "节目": "语义：“节目”是表演内容，不能指人。", "工资": "搭配：“工资”是钱，不能与“是一位老演员”搭配指人。"}, "sentence_index": 6, "correct_answer": "团长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们工厂的团长要求大家每天早上跑步。", "explanation": "这里应该用〈厂长〉。“团长”指团的主要负责人，工厂的负责人叫厂长。"}, {"text": "我们学校的团长要求大家每天早上跑步。", "explanation": "这里应该用〈校长〉。“团长”指团的主要负责人，学校的负责人叫校长。"}, {"text": "我们团长一共三十个人。", "explanation": "这里应该用〈团〉。“团长”指带队的人，指整个团体要说〈团〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87382, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新来团长很年轻。", "corrected_sentence": "新来的团长很年轻。", "error_description": "错误在于“新来”修饰“团长”时漏掉了“的”。正确应为“新来的团长很年轻”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87382, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那位团长们今天很忙。", "corrected_sentence": "那位团长今天很忙。", "error_description": "错误在于“那位”与复数“们”同用。数量词已表明单个人，不能再加“们”。正确应为“那位团长今天很忙”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a98ea9d3-b4df-4039-8afd-0d8e4106367f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
