INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87384, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "双方在地位、权利或身份上相等，彼此对应。", "primary_collocate": null, "pronunciation": "duì děng", "ipa": "twei˥˩ təŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "两国代表团的地位对等，谈判才能顺利进行。", "target_word": "对等", "complexity_tier": "T3", "furigana": "liǎng guó dài biǎo tuán de dì wèi duì děng, tán pàn cái néng shùn lì jìn xíng.", "sentence_source": "generated"}, {"text": "两国在对等的基础上谈判。", "target_word": "对等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板和员工不是对等的关系。", "target_word": "对等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要在对等的地位上交流。", "target_word": "对等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方的权利是对等的。", "target_word": "对等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他希望和老板以对等的身份对话。", "target_word": "对等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两家公司以对等的身份合作。", "target_word": "对等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友之间的关系应该是对等的。", "target_word": "对等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在会上得到了对等的待遇。", "target_word": "对等", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两个人的地位对等，交流起来才更自在。", "target_word": "对等", "complexity_tier": "T3", "furigana": "liǎng gè rén de dì wèi duì děng, jiāo liú qǐ lái cái gèng zì zài.", "sentence_source": "generated"}], "morphological_forms": [{"form": "不对等", "label": "否定形式"}, {"form": "對等", "label": "繁体"}], "register": "书面", "sense_fingerprint": "对等：地位、权利或身份相等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02e6c952-5557-4423-80e1-8c7df400d0c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87384, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对等", "is_correct": true, "explanation": "对等：两国代表团的地位相当，谈判才能顺利进行，符合句意。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，不能用来说“地位”。"}, {"text": "陌生", "is_correct": false, "explanation": "搭配：“陌生”指不熟悉，不能修饰“地位”。"}, {"text": "高兴", "is_correct": false, "explanation": "语义：“高兴”表示人的心情，用在“地位”上句意不通。"}], "explanations": {"对等": "对等：两国代表团的地位相当，谈判才能顺利进行，符合句意。", "漂亮": "体貌：“漂亮”形容外貌，不能用来说“地位”。", "陌生": "搭配：“陌生”指不熟悉，不能修饰“地位”。", "高兴": "语义：“高兴”表示人的心情，用在“地位”上句意不通。"}, "sentence_index": 0, "correct_answer": "对等"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "在法律面前，我们人人对等。", "explanation": "这里应该用〈平等〉。对等指双方地位、权利相当，要有两方相互对应；说每个人都享有相同权利时用平等。"}, {"text": "他是一位很对等的裁判。", "explanation": "这里应该用〈公正〉。对等说双方地位、实力相当，形容裁判的为人要用公正。"}, {"text": "他一个人的地位对等。", "explanation": "这里应该用〈显赫〉。对等表示双方地位相当，要有两方相互对应，只描述一个人的地位时不能用对等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87384, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对等", "is_correct": true, "explanation": "对等：两家公司以地位相当的身份合作，符合句意。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容性情，不能用来说“身份”。"}, {"text": "轻松", "is_correct": false, "explanation": "搭配：“轻松”形容心情或工作，不能修饰“身份”。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“聪明”形容人的智力，不能修饰“身份”。"}], "explanations": {"对等": "对等：两家公司以地位相当的身份合作，符合句意。", "温柔": "语义：“温柔”形容性情，不能用来说“身份”。", "轻松": "搭配：“轻松”形容心情或工作，不能修饰“身份”。", "聪明": "搭配：“聪明”形容人的智力，不能修饰“身份”。"}, "sentence_index": 6, "correct_answer": "对等"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我家离车站很对等。", "explanation": "这里应该用〈近〉。对等指双方相当，形容距离远近要用近。"}, {"text": "这支舞团的动作很对等。", "explanation": "这里应该用〈同步〉。对等说地位、实力、数量相当，形容动作一起进行要用同步。"}, {"text": "我和朋友的看法很对等。", "explanation": "这里应该用〈一致〉。对等不用于形容看法，看法相同要说一致。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87384, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两家公司的地位对等地，合作才能长久。", "corrected_sentence": "两家公司的地位对等，合作才能长久。", "error_description": "错误：“对等”后面多加了“地”。“对等”作谓语时直接说“地位对等”，不加“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87384, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "双方的权利对等着，合作才算公平。", "corrected_sentence": "双方的权利对等，合作才算公平。", "error_description": "错误：“对等”后面多加了“着”。“对等”是形容词，表示状态相当，不能加“着”，应说“权利对等”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87385, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不幸", "is_correct": true, "explanation": "反义：“不幸”是“幸运”的反义词，指遭遇坏事、运气差。"}, {"text": "懒惰", "is_correct": false, "explanation": "与“幸运”不构成反义关系：“懒惰”说的是性格和做事态度，与运气无关。"}, {"text": "聪明", "is_correct": false, "explanation": "与“幸运”不构成反义关系：“聪明”说的是智力，不是运气的好坏。"}, {"text": "富有", "is_correct": false, "explanation": "与“幸运”不构成反义关系：“富有”说的是钱财多，与运气无关。"}], "correct_answer": "不幸", "explanations": {"不幸": "反义：“不幸”是“幸运”的反义词，指遭遇坏事、运气差。", "懒惰": "与“幸运”不构成反义关系：“懒惰”说的是性格和做事态度，与运气无关。", "聪明": "与“幸运”不构成反义关系：“聪明”说的是智力，不是运气的好坏。", "富有": "与“幸运”不构成反义关系：“富有”说的是钱财多，与运气无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87385, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不幸", "is_correct": true, "explanation": "反义：“不幸”是“幸运”的反义词，指遭遇坏事、运气差。"}, {"text": "笨拙", "is_correct": false, "explanation": "与“幸运”不构成反义关系：“笨拙”说动作不灵活，与运气无关。"}, {"text": "勤奋", "is_correct": false, "explanation": "与“幸运”不构成反义关系：“勤奋”说的是自己用功，不是运气好坏。"}, {"text": "平静", "is_correct": false, "explanation": "与“幸运”不构成反义关系：“平静”说心情或环境安稳，与运气无关。"}], "correct_answer": "不幸", "explanations": {"不幸": "反义：“不幸”是“幸运”的反义词，指遭遇坏事、运气差。", "笨拙": "与“幸运”不构成反义关系：“笨拙”说动作不灵活，与运气无关。", "勤奋": "与“幸运”不构成反义关系：“勤奋”说的是自己用功，不是运气好坏。", "平静": "与“幸运”不构成反义关系：“平静”说心情或环境安稳，与运气无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87385, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "幸运是遇到好事，而且不是自己想办法得来的。", "primary_collocate": null, "pronunciation": "xìng yùn", "ipa": "ɕiŋ˥˩ yn˥˩", "syllable_count": 2, "sentences": [{"text": "我今天很幸运，在路上捡到了一百块钱。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他真幸运，刚到车站就上车了。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能遇到这么好的老师，我很幸运。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你真幸运，今天的票还没卖完。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下大雨的时候，她很幸运，正好在家。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天我很幸运，一出门就有出租车。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很幸运，丢了的手机又找到了。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们很幸运，旅行的时候天天都是好天气。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试题目刚好都是我会的，真幸运。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛时他很幸运，第一次就赢了。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "幸运儿", "label": "复合"}, {"form": "幸運", "label": "繁体"}], "register": "中性", "sense_fingerprint": "幸运：形容词，遇到好事且并非自己争取而来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1493551b-beb8-436c-890d-5f7aa674fb8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87385, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "幸运", "is_correct": true, "explanation": "幸运：遇到好事，且不是自己争取而来的。"}, {"text": "命运", "is_correct": false, "explanation": "mìng（第四声）与 xìng（第四声）声母不同（m 与 x），意思是人生的安排。"}, {"text": "星云", "is_correct": false, "explanation": "xīng（第一声）与 xìng（第四声）声调不同，yún（第二声）与 yùn（第四声）声调也不同，意思是星云。"}, {"text": "行云", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，yún（第二声）与 yùn（第四声）声调也不同，意思是飘动的云。"}], "explanations": {"幸运": "幸运：遇到好事，且不是自己争取而来的。", "命运": "mìng（第四声）与 xìng（第四声）声母不同（m 与 x），意思是人生的安排。", "星云": "xīng（第一声）与 xìng（第四声）声调不同，yún（第二声）与 yùn（第四声）声调也不同，意思是星云。", "行云": "xíng（第二声）与 xìng（第四声）声调不同，yún（第二声）与 yùn（第四声）声调也不同，意思是飘动的云。"}, "sentence_index": null, "correct_answer": "幸运"}, "level_3": {"options": [{"text": "幸运", "is_correct": true, "explanation": "幸运：遇到好事，且不是自己争取来的，正合“捡到一百块钱”。"}, {"text": "倒霉", "is_correct": false, "explanation": "语义：“倒霉”指运气差，与“捡到一百块钱”这一好事相反。"}, {"text": "方便", "is_correct": false, "explanation": "搭配：“方便”说事情或条件便利，不用来形容人当天的状态。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，与运气无关。"}], "explanations": {"幸运": "幸运：遇到好事，且不是自己争取来的，正合“捡到一百块钱”。", "倒霉": "语义：“倒霉”指运气差，与“捡到一百块钱”这一好事相反。", "方便": "搭配：“方便”说事情或条件便利，不用来形容人当天的状态。", "高大": "体貌：“高大”形容身材，与运气无关。"}, "sentence_index": 0, "correct_answer": "幸运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇文章的语法很幸运，没有一个错误。", "explanation": "这里应该用〈正确〉。幸运说的是运气好、遇到好事，不能用来评价文章的对错；这里要用正确。"}, {"text": "他的头脑很幸运，每道题都能很快做出来。", "explanation": "这里应该用〈聪明〉。幸运说的是运气，不能用来说人的能力；能力和才智要用聪明。"}, {"text": "这本书的价格很幸运，只要十块钱。", "explanation": "这里应该用〈便宜〉。幸运说的是运气好，不能用来说价格的高低；价格低要用便宜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87385, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幸运", "is_correct": true, "explanation": "幸运：丢了的手机又找到了，是遇到好事。"}, {"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外貌，与丢手机又找到了无关。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容身高，与这件事毫无关系。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”指价格低，用来形容人会显得很不恰当。"}], "explanations": {"幸运": "幸运：丢了的手机又找到了，是遇到好事。", "漂亮": "体貌：“漂亮”形容外貌，与丢手机又找到了无关。", "矮": "体貌：“矮”形容身高，与这件事毫无关系。", "便宜": "搭配：“便宜”指价格低，用来形容人会显得很不恰当。"}, "sentence_index": 6, "correct_answer": "幸运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤很幸运，特别鲜。", "explanation": "这里应该用〈好喝〉。幸运说的是运气好，不能用来评价汤的味道；品尝后的评价要用好喝。"}, {"text": "他长得很幸运，眼睛很大。", "explanation": "这里应该用〈好看〉。幸运说的是运气，不能用来形容外貌；形容外貌要用好看。"}, {"text": "他的性格很幸运，待人很热情。", "explanation": "这里应该用〈开朗〉。幸运说的是运气好，不能用来描述性格；性格的特点要用开朗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87385, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天我遇到了一个幸运人，她买到了最后一张票。", "corrected_sentence": "今天我遇到了一个幸运的人，她买到了最后一张票。", "error_description": "“幸运”修饰名词时要加“的”：应说“幸运的人”，不能说“幸运人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87385, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天他幸运的抽中了一张票。", "corrected_sentence": "昨天他幸运地抽中了一张票。", "error_description": "“幸运”修饰后面的动词时要用“地”，不能用“的”：应说“幸运地抽中”，“幸运的抽中”误用了定语的“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87386, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不幸", "is_correct": true, "explanation": "反义：“不幸”是“幸运”的反义词，指遭遇坏事、运气差。"}, {"text": "富裕", "is_correct": false, "explanation": "与“幸运”不构成反义关系：“富裕”说的是家境殷实，与运气无关。"}, {"text": "文静", "is_correct": false, "explanation": "与“幸运”不构成反义关系：“文静”说的是性格举止，与运气无关。"}, {"text": "粗鲁", "is_correct": false, "explanation": "与“幸运”不构成反义关系：“粗鲁”说的是言行举止，与运气无关。"}], "correct_answer": "不幸", "explanations": {"不幸": "反义：“不幸”是“幸运”的反义词，指遭遇坏事、运气差。", "富裕": "与“幸运”不构成反义关系：“富裕”说的是家境殷实，与运气无关。", "文静": "与“幸运”不构成反义关系：“文静”说的是性格举止，与运气无关。", "粗鲁": "与“幸运”不构成反义关系：“粗鲁”说的是言行举止，与运气无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87386, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "不幸", "is_correct": true, "explanation": "反义：“不幸”是“幸运”的反义词，指遭遇坏事、运气差。"}, {"text": "愚笨", "is_correct": false, "explanation": "与“幸运”不构成反义关系：“愚笨”说的是智力，与运气无关。"}, {"text": "认真", "is_correct": false, "explanation": "与“幸运”不构成反义关系：“认真”说的是做事态度，与运气无关。"}, {"text": "整洁", "is_correct": false, "explanation": "与“幸运”不构成反义关系：“整洁”说的是干净整齐，与运气无关。"}], "correct_answer": "不幸", "explanations": {"不幸": "反义：“不幸”是“幸运”的反义词，指遭遇坏事、运气差。", "愚笨": "与“幸运”不构成反义关系：“愚笨”说的是智力，与运气无关。", "认真": "与“幸运”不构成反义关系：“认真”说的是做事态度，与运气无关。", "整洁": "与“幸运”不构成反义关系：“整洁”说的是干净整齐，与运气无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87386, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "形容运气好，遇到好的机会或结果。", "primary_collocate": null, "pronunciation": "xìng yùn", "ipa": "ɕiŋ˥˩ yn˥˩", "syllable_count": 2, "sentences": [{"text": "她很幸运，得到了一个好工作。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个幸运的孩子找到了自己的家人。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我觉得自己是个幸运的人。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直很幸运，做什么事都很顺利。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "能和你做朋友，我觉得非常幸运。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "幸运的是，飞机没有晚点。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很幸运，第一次面试就成功了。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我特别幸运，抽到了一张电影票。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别人都说我很幸运，可是我也很努力。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛，她没有那么幸运。", "target_word": "幸运", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "幸运儿", "label": "复合"}, {"form": "幸運", "label": "繁体"}], "register": "中性", "sense_fingerprint": "幸运：形容词，运气好，遇到好机会或好结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1493551b-beb8-436c-890d-5f7aa674fb8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87386, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "幸运", "is_correct": true, "explanation": "幸运：运气好，遇到好的机会或结果。"}, {"text": "命运", "is_correct": false, "explanation": "mìng（第四声）与 xìng（第四声）声母不同（m 与 x），意思是人生的安排。"}, {"text": "星云", "is_correct": false, "explanation": "xīng（第一声）与 xìng（第四声）声调不同，yún（第二声）与 yùn（第四声）声调也不同，意思是星云。"}, {"text": "行云", "is_correct": false, "explanation": "xíng（第二声）与 xìng（第四声）声调不同，yún（第二声）与 yùn（第四声）声调也不同，意思是飘动的云。"}], "explanations": {"幸运": "幸运：运气好，遇到好的机会或结果。", "命运": "mìng（第四声）与 xìng（第四声）声母不同（m 与 x），意思是人生的安排。", "星云": "xīng（第一声）与 xìng（第四声）声调不同，yún（第二声）与 yùn（第四声）声调也不同，意思是星云。", "行云": "xíng（第二声）与 xìng（第四声）声调不同，yún（第二声）与 yùn（第四声）声调也不同，意思是飘动的云。"}, "sentence_index": null, "correct_answer": "幸运"}, "level_3": {"options": [{"text": "幸运", "is_correct": true, "explanation": "幸运：运气好，遇到好的工作机会，正合“得到了一个好工作”。"}, {"text": "倒霉", "is_correct": false, "explanation": "语义：“倒霉”指运气差，与“得到了一个好工作”这一好结果相反。"}, {"text": "便宜", "is_correct": false, "explanation": "搭配：“便宜”指价格低，用来形容人会显得很不恰当。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：“矮”形容身高，与找工作无关。"}], "explanations": {"幸运": "幸运：运气好，遇到好的工作机会，正合“得到了一个好工作”。", "倒霉": "语义：“倒霉”指运气差，与“得到了一个好工作”这一好结果相反。", "便宜": "搭配：“便宜”指价格低，用来形容人会显得很不恰当。", "矮": "体貌：“矮”形容身高，与找工作无关。"}, "sentence_index": 0, "correct_answer": "幸运"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这篇作文的错别字很幸运，一个都没有。", "explanation": "这里应该用〈少〉。幸运说的是运气好，不能用来说错别字的多少，描述数量要用少。"}, {"text": "她的头脑很幸运，一看题目就知道答案。", "explanation": "这里应该用〈聪明〉。幸运说的是运气，不能用来说人理解问题快；这种能力要用聪明。"}, {"text": "这件衣服的价格很幸运，只要五十块。", "explanation": "这里应该用〈便宜〉。幸运说的是运气好，不能用来说价格；价格低要用便宜。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87386, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "幸运", "is_correct": true, "explanation": "幸运：运气好，第一次面试就成功，正合句意。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”形容身材，与面试成功无关。"}, {"text": "方便", "is_correct": false, "explanation": "搭配：“方便”说事情或条件便利，不用来形容人的状态。"}, {"text": "失落", "is_correct": false, "explanation": "语义：“失落”说心情低落，与“第一次面试就成功了”相矛盾。"}], "explanations": {"幸运": "幸运：运气好，第一次面试就成功，正合句意。", "高大": "体貌：“高大”形容身材，与面试成功无关。", "方便": "搭配：“方便”说事情或条件便利，不用来形容人的状态。", "失落": "语义：“失落”说心情低落，与“第一次面试就成功了”相矛盾。"}, "sentence_index": 6, "correct_answer": "幸运"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗面很幸运，味道特别鲜。", "explanation": "这里应该用〈好吃〉。幸运说的是运气，不能用来评价面的味道；品尝后的评价要用好吃。"}, {"text": "她的长相很幸运，眉眼很漂亮。", "explanation": "这里应该用〈好看〉。幸运说的是运气，不能用来形容外貌；形容外貌要用好看。"}, {"text": "她的性格很幸运，待人很热情。", "explanation": "这里应该用〈开朗〉。幸运说的是运气好，不能用来描述性格；性格的特点要用开朗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87386, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次比赛，她是一个幸运人，最后获得了第一名。", "corrected_sentence": "这次比赛，她是一个幸运的人，最后获得了第一名。", "error_description": "“幸运”修饰名词时要加“的”：应说“幸运的人”，不能说“幸运人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87386, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她幸运的在路上遇到了老同学。", "corrected_sentence": "她幸运地在路上遇到了老同学。", "error_description": "“幸运”修饰后面的动词时要用“地”，不能用“的”：应说“幸运地遇到”，“幸运的遇到”误用了定语的“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
