INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87387, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "发回是把东西或消息送回来。", "primary_collocate": null, "pronunciation": "fā huí", "ipa": "fa˥ xweɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他从火车站发回一条短信。", "target_word": "发回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把作业发回给同学们。", "target_word": "发回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批衣服太小，商店要发回工厂。", "target_word": "发回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者在现场发回了最新消息。", "target_word": "发回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你把表格发回我的邮箱。", "target_word": "发回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王去了南方，常常发回家乡的照片。", "target_word": "发回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器坏了，我们把它发回厂里修。", "target_word": "发回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她拍好视频，马上发回了家。", "target_word": "发回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈收到哥哥发回的钱了。", "target_word": "发回", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的人发回消息说，大家都很平安。", "target_word": "发回", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "发回了", "label": "完成体"}, {"form": "发回来", "label": "复合"}], "register": "中性", "sense_fingerprint": "把物品或消息寄送、传送回到原处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d04d293-e650-4428-be70-164f690aefe7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87387, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "发回", "is_correct": true, "explanation": "正确。“发回”表示把短信从外地送回来源处，与“从火车站”的语境吻合。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能用于短信。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能以“短信”作宾语。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修”通常用于东西的修理，不能与“短信”搭配。"}], "explanations": {"发回": "正确。“发回”表示把短信从外地送回来源处，与“从火车站”的语境吻合。", "吃": "语义：“吃”指进食，不能用于短信。", "唱": "搭配：“唱”不能以“短信”作宾语。", "修": "搭配：“修”通常用于东西的修理，不能与“短信”搭配。"}, "sentence_index": 0, "correct_answer": "发回"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天上班都发回一个包。", "explanation": "这里应该用〈带〉。“发回”指东西送回来源处；上班时随身带包不是送回，应说“带”。"}, {"text": "图书馆给每位读者发回了一张借书证。", "explanation": "这里应该用〈发放〉。“发回”指东西送回来源处；图书馆把借书证发给读者是“发放”，不是送回，此处不能用“发回”。"}, {"text": "我周末去机场发回了朋友。", "explanation": "这里应该用〈送〉。“发回”的对象是东西或消息，不能指人；去机场送朋友要用“送”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87387, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "发回", "is_correct": true, "explanation": "正确。“发回”表示把机器送回厂里，与“机器坏了”“厂里修”的语境吻合。"}, {"text": "买", "is_correct": false, "explanation": "语义：“买”是购买，与把机器送去厂里修理无关。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”的对象是文字，不能用于机器。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是丢弃，与送去修理的语境正好相反。"}], "explanations": {"发回": "正确。“发回”表示把机器送回厂里，与“机器坏了”“厂里修”的语境吻合。", "买": "语义：“买”是购买，与把机器送去厂里修理无关。", "写": "搭配：“写”的对象是文字，不能用于机器。", "扔": "语义：“扔”是丢弃，与送去修理的语境正好相反。"}, "sentence_index": 6, "correct_answer": "发回"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我大学毕业后发回了老家。", "explanation": "这里应该用〈搬〉。“发回”的对象只能是东西或消息，人搬回老家要用“搬”。"}, {"text": "我昨天在河边发回了几块石头。", "explanation": "这里应该用〈捡〉。“发回”表示东西从别处送回来源处；在河边拾石头不是送回，应说“捡”。"}, {"text": "我在院子里发回了几个桃子。", "explanation": "这里应该用〈摘〉。“发回”表示东西从别处送回来源处，不表示采摘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87387, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从北京发回着一份报告。", "corrected_sentence": "他从北京发回了一份报告。", "error_description": "错误：「发回」后面用了「着」。「发回」表示一次完成的寄送动作，不能用表示持续的「着」，应该用「了」，正确形式是「他从北京发回了一份报告」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87387, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把那台相机发回在老家。", "corrected_sentence": "她把那台相机发回了老家。", "error_description": "错误：“发回”后面直接接处所，不加“在”，完成体“了”也不能换成“在”。正确形式是“她把那台相机发回了老家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '026276c4-3161-4fb2-a829-030c62e7a89f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
