INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87389, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在教是信一种宗教，是那个教的人。", "primary_collocate": null, "pronunciation": "zài jiào", "ipa": "t͡sai̯˥˩ t͡ɕjɑu̯˥˩", "syllable_count": 2, "sentences": [{"text": "我们村里在教的人不多。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在教的人和不在教的人都来了。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的老板是在教的。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们公司在教的同事有五个。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在教的朋友每天都要祈祷。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她家里在教的比不在教的多。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小区里在教的老人经常一起聚会。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在教的人有自己的节日。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我认识几个在教的，他们都很友好。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班上在教的同学可以请假去过节。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "指信奉某种宗教、属于某个教的人，常说“在教的”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f650a73-b56c-4b35-a5aa-fa33d63c4ebd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87389, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "在教", "is_correct": true, "explanation": "在教指信奉某种宗教、属于某个教的人，即本词的读音和意思。"}, {"text": "在校", "is_correct": false, "explanation": "zài 相同，jiào 与 xiào 声母不同（j 与 x），在校指在学校，意思不同。"}, {"text": "在笑", "is_correct": false, "explanation": "zài 相同，jiào 与 xiào 声母不同（j 与 x），在笑指正在笑，意思不同。"}, {"text": "再笑", "is_correct": false, "explanation": "zài 相同，jiào 与 xiào 声母不同（j 与 x），再笑指又笑一次，意思不同。"}], "explanations": {"在教": "在教指信奉某种宗教、属于某个教的人，即本词的读音和意思。", "在校": "zài 相同，jiào 与 xiào 声母不同（j 与 x），在校指在学校，意思不同。", "在笑": "zài 相同，jiào 与 xiào 声母不同（j 与 x），在笑指正在笑，意思不同。", "再笑": "zài 相同，jiào 与 xiào 声母不同（j 与 x），再笑指又笑一次，意思不同。"}, "sentence_index": null, "correct_answer": "在教"}, "level_3": {"options": [{"text": "在教", "is_correct": true, "explanation": "正确答案。“在教的人”指信教的人，放在“我们村里”之后语义通顺。"}, {"text": "在建", "is_correct": false, "explanation": "语义：在建指正在施工，“村里在建的人”说不通。"}, {"text": "在用", "is_correct": false, "explanation": "语义：在用指正在使用，多指物品，“村里在用的人”说不通。"}, {"text": "在售", "is_correct": false, "explanation": "语义：在售指在市场出售，只用于商品，“村里在售的人”说不通。"}], "explanations": {"在教": "正确答案。“在教的人”指信教的人，放在“我们村里”之后语义通顺。", "在建": "语义：在建指正在施工，“村里在建的人”说不通。", "在用": "语义：在用指正在使用，多指物品，“村里在用的人”说不通。", "在售": "语义：在售指在市场出售，只用于商品，“村里在售的人”说不通。"}, "sentence_index": 0, "correct_answer": "在教"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的在教很深。", "explanation": "这里应该用〈信仰〉。“在教”指信教的人，是人，不能用“很深”来形容信仰的程度。"}, {"text": "他家的在教很咸。", "explanation": "这里应该用〈信徒〉。“咸”形容味道，“在教”指信教的人，不能用味觉来形容。"}, {"text": "他们公司的在教很厚。", "explanation": "这里应该用〈经书〉。“厚”说的是书本的厚薄，不能用来形容信教的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87389, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在教", "is_correct": true, "explanation": "正确答案。“在教的老人”指信教的老人，与“经常一起聚会”语义相符。"}, {"text": "在线", "is_correct": false, "explanation": "语义：在线指接入网络或在网上，不能用来形容“老人”，句意说不通。"}, {"text": "在职", "is_correct": false, "explanation": "语义：在职指正在工作岗位上，与“老人经常一起聚会”不搭配。"}, {"text": "在岗", "is_correct": false, "explanation": "语义：在岗指正在工作岗位上值守，“在岗的老人”说不通。"}], "explanations": {"在教": "正确答案。“在教的老人”指信教的老人，与“经常一起聚会”语义相符。", "在线": "语义：在线指接入网络或在网上，不能用来形容“老人”，句意说不通。", "在职": "语义：在职指正在工作岗位上，与“老人经常一起聚会”不搭配。", "在岗": "语义：在岗指正在工作岗位上值守，“在岗的老人”说不通。"}, "sentence_index": 6, "correct_answer": "在教"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "班上的在教很便宜。", "explanation": "“便宜”形容价钱，“在教”指信教的人，不能用价格来形容这种人。"}, {"text": "班上的在教很甜。", "explanation": "“甜”形容味道，“在教”指信教的人，不能用味觉来形容。"}, {"text": "班上的在教很酸。", "explanation": "“酸”形容味道，“在教”指信教的人，不能用味觉来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87389, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们村里在教老人不多。", "corrected_sentence": "我们村里在教的老人不多。", "error_description": "“在教”修饰名词“老人”时要加“的”，说“在教的老人”；“在教老人”会被理解成“正在教老人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87389, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班上在教同学平时很用功。", "corrected_sentence": "班上在教的同学平时很用功。", "error_description": "“在教”修饰“同学”时要加“的”；“在教同学”会被理解成“正在教同学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
