INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87390, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "property", "definition": "属于某种宗教，信奉某种宗教。", "primary_collocate": null, "pronunciation": "zài jiào", "ipa": "t͡sai̯˥˩ t͡ɕjɑu̯˥˩", "syllable_count": 2, "sentences": [{"text": "他在教，所以不吃猪肉。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我奶奶在教，每个星期日都去教堂。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你家人都在教吗？", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就在教，现在还每天祈祷。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不在教，但是很尊重别人的信仰。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友在教，喝酒的聚会他不去。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说那位邻居在教，常常去寺庙。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们全家都在教，家里有一本经书。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我丈夫以前不在教，后来才信了佛。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我同学也在教，周末常去教堂。", "target_word": "在教", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "动词，表示某人属于、信奉某个宗教", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5f650a73-b56c-4b35-a5aa-fa33d63c4ebd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87390, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "在教", "is_correct": true, "explanation": "在教指信奉某种宗教、属于某个教，即本词的读音和意思。"}, {"text": "在校", "is_correct": false, "explanation": "zài 相同，jiào 与 xiào 声母不同（j 与 x），在校指在学校，意思不同。"}, {"text": "在笑", "is_correct": false, "explanation": "zài 相同，jiào 与 xiào 声母不同（j 与 x），在笑指正在笑，意思不同。"}, {"text": "再笑", "is_correct": false, "explanation": "zài 相同，jiào 与 xiào 声母不同（j 与 x），再笑指又笑一次，意思不同。"}], "explanations": {"在教": "在教指信奉某种宗教、属于某个教，即本词的读音和意思。", "在校": "zài 相同，jiào 与 xiào 声母不同（j 与 x），在校指在学校，意思不同。", "在笑": "zài 相同，jiào 与 xiào 声母不同（j 与 x），在笑指正在笑，意思不同。", "再笑": "zài 相同，jiào 与 xiào 声母不同（j 与 x），再笑指又笑一次，意思不同。"}, "sentence_index": null, "correct_answer": "在教"}, "level_3": {"options": [{"text": "在教", "is_correct": true, "explanation": "正确答案。“他在教，所以不吃猪肉”表示他信教，因此有饮食禁忌。"}, {"text": "在家", "is_correct": false, "explanation": "语义：在家是位置，与“不吃猪肉”没有因果关系，句意不通。"}, {"text": "在线", "is_correct": false, "explanation": "语义：在线指联网，与饮食规定没有关系，句意不通。"}, {"text": "在职", "is_correct": false, "explanation": "语义：在职指有工作岗位，与“所以不吃猪肉”的因果关系不符。"}], "explanations": {"在教": "正确答案。“他在教，所以不吃猪肉”表示他信教，因此有饮食禁忌。", "在家": "语义：在家是位置，与“不吃猪肉”没有因果关系，句意不通。", "在线": "语义：在线指联网，与饮食规定没有关系，句意不通。", "在职": "语义：在职指有工作岗位，与“所以不吃猪肉”的因果关系不符。"}, "sentence_index": 0, "correct_answer": "在教"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在教五个人，每天都祈祷。", "explanation": "此处“在教”是“教导”义，不是“信教”义；句中“祈祷”说的是信教。"}, {"text": "她家在教五个，每天都祈祷。", "explanation": "此处“在教”是“教导”义，不是信教义；应说“她家有五个信徒”。"}, {"text": "她的在教很深。", "explanation": "这里应该用〈信仰〉。“在教”是动词，不能直接作“的”字结构的中心语，应说“她的信仰很深”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87390, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "在教", "is_correct": true, "explanation": "正确答案。“听说那位邻居在教，常常去寺庙”表示邻居信教。"}, {"text": "在建", "is_correct": false, "explanation": "语义：在建指正在施工，“那位邻居在建”说不通。"}, {"text": "在售", "is_correct": false, "explanation": "语义：在售指在市场出售，“那位邻居在售”说不通。"}, {"text": "在用", "is_correct": false, "explanation": "语义：在用指正在使用，“那位邻居在用”说不通。"}], "explanations": {"在教": "正确答案。“听说那位邻居在教，常常去寺庙”表示邻居信教。", "在建": "语义：在建指正在施工，“那位邻居在建”说不通。", "在售": "语义：在售指在市场出售，“那位邻居在售”说不通。", "在用": "语义：在用指正在使用，“那位邻居在用”说不通。"}, "sentence_index": 6, "correct_answer": "在教"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我同学也在教五个人，周末常去教堂。", "explanation": "此处“在教”是“教导”义，不是信教义；句中说的是教人。"}, {"text": "我同学是五个在教，周末常去教堂。", "explanation": "这里应该用〈信徒〉。“在教”是动词，不能加数量词作名词用。"}, {"text": "我同学也在了教，周末常去教堂。", "explanation": "“了”插在“在教”中间，词形错误，应为“在教”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87390, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很在教，所以从来不喝酒。", "corrected_sentence": "他在教，所以从来不喝酒。", "error_description": "“在教”表示属于某个宗教，是或不是，没有程度之分，不能加“很”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5c912a95-669d-44e6-a421-6c480014ffc1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
