INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87391, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "盲目是没想清楚，就乱做。", "primary_collocate": null, "pronunciation": "máng mù", "ipa": "maŋ˧˥ mu˥˩", "syllable_count": 2, "sentences": [{"text": "做事前先想一想，别盲目行动。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没想清楚就盲目做了决定。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盲目买东西会浪费钱。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样做太盲目了。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子盲目地模仿大人说话。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不要盲目地比较成绩。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盲目学习，不一定有好结果。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他盲目地答应了朋友的要求。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她盲目地花钱，最后没钱吃饭。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有计划，盲目地工作很累。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "盲目地", "label": "状语形式"}], "register": "书面", "sense_fingerprint": "形容词：没想清楚就乱做", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5557fc-539b-4cb6-b9b1-8d2660c41b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87391, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "盲目", "is_correct": true, "explanation": "正确答案：盲目，意思是没想清楚就乱做。"}, {"text": "忙碌", "is_correct": false, "explanation": "máng 与 máng 声调和音节都相同，只有 mù 与 lù 声母不同（m 与 l），意思是忙个不停。"}, {"text": "名目", "is_correct": false, "explanation": "míng 与 máng 声调相同，韵母不同（ing 与 ang），意思是名义上的项目。"}, {"text": "明目", "is_correct": false, "explanation": "míng 与 máng 声调相同，韵母不同（ing 与 ang），意思是使眼睛明亮。"}], "explanations": {"盲目": "正确答案：盲目，意思是没想清楚就乱做。", "忙碌": "máng 与 máng 声调和音节都相同，只有 mù 与 lù 声母不同（m 与 l），意思是忙个不停。", "名目": "míng 与 máng 声调相同，韵母不同（ing 与 ang），意思是名义上的项目。", "明目": "míng 与 máng 声调相同，韵母不同（ing 与 ang），意思是使眼睛明亮。"}, "sentence_index": null, "correct_answer": "盲目"}, "level_3": {"options": [{"text": "盲目", "is_correct": true, "explanation": "盲目：没想清楚就行动，与“做事前先想一想”的提醒相呼应。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容排列或外貌，不修饰“行动”，句意不通。"}, {"text": "热情", "is_correct": false, "explanation": "搭配：“热情”形容人的态度，不修饰“行动”。"}, {"text": "快乐", "is_correct": false, "explanation": "语义：“快乐”形容心情，不能修饰“行动”，与“做事前先想一想”的要求无关。"}], "explanations": {"盲目": "盲目：没想清楚就行动，与“做事前先想一想”的提醒相呼应。", "整齐": "搭配：“整齐”形容排列或外貌，不修饰“行动”，句意不通。", "热情": "搭配：“热情”形容人的态度，不修饰“行动”。", "快乐": "语义：“快乐”形容心情，不能修饰“行动”，与“做事前先想一想”的要求无关。"}, "sentence_index": 0, "correct_answer": "盲目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他经过反复比较，盲目地选择了这家公司。", "explanation": "这里应该用〈果断〉。盲目指没想清楚就乱做，与“经过反复比较”矛盾；经过比较后再拿定主意，应说果断。"}, {"text": "老人的双眼已经盲目，看不清路。", "explanation": "这里应该用〈失明〉。盲目指没想清楚就乱做，不指眼睛看不见。"}, {"text": "他做这道题很盲目，每一步都验算过。", "explanation": "这里应该用〈慎重〉。盲目指没想清楚就乱做，与“每一步都验算过”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87391, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "盲目", "is_correct": true, "explanation": "盲目：不做计划就学习，正是句中所说的“不一定有好结果”的原因。"}, {"text": "精确", "is_correct": false, "explanation": "搭配：“精确”多修饰计算、测量，不说“精确学习”。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容排列或外貌，不修饰学习方式。"}, {"text": "精密", "is_correct": false, "explanation": "搭配：“精密”形容仪器或工艺的精确，不修饰学习。"}], "explanations": {"盲目": "盲目：不做计划就学习，正是句中所说的“不一定有好结果”的原因。", "精确": "搭配：“精确”多修饰计算、测量，不说“精确学习”。", "整齐": "搭配：“整齐”形容排列或外貌，不修饰学习方式。", "精密": "搭配：“精密”形容仪器或工艺的精确，不修饰学习。"}, "sentence_index": 6, "correct_answer": "盲目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脾气很盲目，动不动就发火。", "explanation": "这里应该用〈暴躁〉。盲目指没想清楚就乱做，不用来形容脾气。"}, {"text": "他写字很盲目，我看不清。", "explanation": "这里应该用〈潦草〉。盲目指做事没想清楚，不用来形容字迹。"}, {"text": "他很盲目，不敢一个人过马路。", "explanation": "这里应该用〈胆小〉。盲目指没想清楚就乱做，不用来形容胆量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87391, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他没想清楚，就盲目的辞了职。", "corrected_sentence": "他没想清楚，就盲目地辞了职。", "error_description": "“盲目”修饰动词“辞职”时要用“地”，应说“盲目地辞了职”，不能说“盲目的辞了职”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
