INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87392, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有明确目标或不了解情况而行动的。", "primary_collocate": null, "pronunciation": "máng mù", "ipa": "maŋ˧˥ mu˥˩", "syllable_count": 2, "sentences": [{"text": "不了解情况，不要盲目投资。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他盲目地跟着别人走。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有目标，盲目努力没有用。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买东西前先看价格，不要盲目购买。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对市场不了解，却盲目扩大了生意。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "盲目跟风常常会失败。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她盲目地去了一个陌生的城市。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没有计划就盲目开始，很容易出错。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能盲目相信网上的消息。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的选择太盲目了。", "target_word": "盲目", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "盲目地", "label": "状语形式"}], "register": "书面", "sense_fingerprint": "形容词：没有目标或不了解情况就行动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5557fc-539b-4cb6-b9b1-8d2660c41b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validati