INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87392, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "盲目", "is_correct": true, "explanation": "正确答案：盲目，意思是没有明确目标或不了解情况而行动。"}, {"text": "忙碌", "is_correct": false, "explanation": "máng 与 máng 声调和音节都相同，只有 mù 与 lù 声母不同（m 与 l），意思是忙个不停。"}, {"text": "名目", "is_correct": false, "explanation": "míng 与 máng 声调相同，韵母不同（ing 与 ang），意思是名义上的项目。"}, {"text": "明目", "is_correct": false, "explanation": "míng 与 máng 声调相同，韵母不同（ing 与 ang），意思是使眼睛明亮。"}], "explanations": {"盲目": "正确答案：盲目，意思是没有明确目标或不了解情况而行动。", "忙碌": "máng 与 máng 声调和音节都相同，只有 mù 与 lù 声母不同（m 与 l），意思是忙个不停。", "名目": "míng 与 máng 声调相同，韵母不同（ing 与 ang），意思是名义上的项目。", "明目": "míng 与 máng 声调相同，韵母不同（ing 与 ang），意思是使眼睛明亮。"}, "sentence_index": null, "correct_answer": "盲目"}, "level_3": {"options": [{"text": "盲目", "is_correct": true, "explanation": "盲目：没有了解情况就投资，正符合句中“不了解情况”的语境。"}, {"text": "精明", "is_correct": false, "explanation": "语义：“精明”指头脑敏锐、善于算计，需要了解情况，与“不了解情况”矛盾。"}, {"text": "熟练", "is_correct": false, "explanation": "搭配：“熟练”多修饰技能或操作，不说“熟练投资”。"}, {"text": "理智", "is_correct": false, "explanation": "语义：“理智”指冷静、依据事理判断，句中说不了解情况，二者不合。"}], "explanations": {"盲目": "盲目：没有了解情况就投资，正符合句中“不了解情况”的语境。", "精明": "语义：“精明”指头脑敏锐、善于算计，需要了解情况，与“不了解情况”矛盾。", "熟练": "搭配：“熟练”多修饰技能或操作，不说“熟练投资”。", "理智": "语义：“理智”指冷静、依据事理判断，句中说不了解情况，二者不合。"}, "sentence_index": 0, "correct_answer": "盲目"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他仔细调查了市场，盲目地决定投资。", "explanation": "这里应该用〈谨慎〉。盲目指不了解情况就行动，与“仔细调查了市场”矛盾。"}, {"text": "他是一个盲目的人，走路要拄拐杖。", "explanation": "这里应该用〈盲人〉。盲目指行动缺乏目标或依据，不指眼睛看不见。"}, {"text": "我昨天很盲目，忘了关煤气。", "explanation": "这里应该用〈糊涂〉。盲目侧重行动缺乏目标，不用来描述一时健忘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87392, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "盲目", "is_correct": true, "explanation": "盲目：没有目标地去一个陌生的城市，符合句意。"}, {"text": "熟练", "is_correct": false, "explanation": "语义：“熟练”指对操作或技能很熟悉，与“陌生的城市”矛盾。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”形容排列或外貌，不修饰“去”，句意不通。"}, {"text": "熟悉", "is_correct": false, "explanation": "语义：“熟悉”与“陌生的城市”直接对立，句意不通。"}], "explanations": {"盲目": "盲目：没有目标地去一个陌生的城市，符合句意。", "熟练": "语义：“熟练”指对操作或技能很熟悉，与“陌生的城市”矛盾。", "整齐": "搭配：“整齐”形容排列或外貌，不修饰“去”，句意不通。", "熟悉": "语义：“熟悉”与“陌生的城市”直接对立，句意不通。"}, "sentence_index": 6, "correct_answer": "盲目"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的脾气很盲目，动不动就发火。", "explanation": "这里应该用〈暴躁〉。盲目指行动缺乏目标或依据，不用来形容脾气。"}, {"text": "这个孩子很盲目，一句话就哭了。", "explanation": "这里应该用〈敏感〉。盲目不用来形容孩子的性格或反应的强弱。"}, {"text": "他很盲目，不敢一个人过马路。", "explanation": "这里应该用〈胆小〉。盲目指不了解情况就行动，不用来形容胆量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87392, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他盲目的买了很多没用的东西。", "corrected_sentence": "他盲目地买了很多没用的东西。", "error_description": "“盲目”修饰动词“买”时要用“地”，应说“盲目地买”，不能说“盲目的买”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87392, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他盲目的相信了网上的消息。", "corrected_sentence": "他盲目地相信了网上的消息。", "error_description": "“盲目”修饰动词“相信”时要用“地”，应说“盲目地相信”，不能说“盲目的相信”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
