INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87393, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "报分是把得了多少分大声说出来。", "primary_collocate": null, "pronunciation": "bào fēn", "ipa": "pɑʊ˥˩ fən˥", "syllable_count": 2, "sentences": [{"text": "比赛结束后，裁判大声报分。", "target_word": "报分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体操比赛里，裁判一个一个地报分。", "target_word": "报分", "complexity_tier": "T3", "furigana": "tǐ cāo bǐ sài lǐ, cái pàn yí gè yí gè de bào fēn.", "sentence_source": "generated"}, {"text": "篮球比赛结束了，裁判开始报分。", "target_word": "报分", "complexity_tier": "T3", "furigana": "lán qiú bǐ sài jié shù le, cái pàn kāi shǐ bào fēn.", "sentence_source": "generated"}, {"text": "他跳完以后，裁判马上报分了。", "target_word": "报分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你慢一点儿报分，我要写下来。", "target_word": "报分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体操比赛时，裁判要当场报分。", "target_word": "报分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明负责报分，大家都听着他的声音。", "target_word": "报分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判报分以后，观众鼓掌了。", "target_word": "报分", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体育馆里，裁判不停地报分，观众都很兴奋。", "target_word": "报分", "complexity_tier": "T3", "furigana": "tǐ yù guǎn lǐ, cái pàn bù tíng de bào fēn, guān zhòng dōu hěn xīng fèn.", "sentence_source": "generated"}, {"text": "今天下午有比赛，裁判要报分，我有点儿紧张。", "target_word": "报分", "complexity_tier": "T3", "furigana": "jīn tiān xià wǔ yǒu bǐ sài, cái pàn yào bào fēn, wǒ yǒu diǎnr jǐn zhāng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "报分员", "label": "复合"}, {"form": "報分", "label": "繁体"}], "register": "口语", "sense_fingerprint": "把得分大声说出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f17cd111-484e-48a1-bddc-52f40a3ae15b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87393, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "报分", "is_correct": true, "explanation": "正确：“报分”指把得分大声说出来，与“比赛结束后”“大声”的语境相符。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能用来表示大声宣布得分，句子意思不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“睡”与“大声”“得分”无关，裁判不会在这里“睡”。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要带“送给谁＋送什么”两个成分，这里缺少，句子不完整。"}], "explanations": {"报分": "正确：“报分”指把得分大声说出来，与“比赛结束后”“大声”的语境相符。", "吃": "语义：“吃”不能用来表示大声宣布得分，句子意思不通。", "睡": "语义：“睡”与“大声”“得分”无关，裁判不会在这里“睡”。", "送": "配价：“送”需要带“送给谁＋送什么”两个成分，这里缺少，句子不完整。"}, "sentence_index": 0, "correct_answer": "报分"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天他的钱包被偷了，今天一早他去派出所报分。", "explanation": "这里应该用〈报案〉。“报分”指报出得分，不能指向警察报告案件。"}, {"text": "他很想参加足球比赛，今天去学校报分了。", "explanation": "这里应该用〈报名〉。“报分”指报出得分，不能指报名参加比赛。"}, {"text": "卖菜的老板向我报分了。", "explanation": "这里应该用〈报价〉。“报分”指报出得分，不能指报出价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87393, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报分", "is_correct": true, "explanation": "正确：“负责报分”指负责把得分大声说出来，与“大家都听着他的声音”相符。"}, {"text": "发烧", "is_correct": false, "explanation": "语义：“发烧”是身体状况，不能被“负责”，句子意思不通。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：“咳嗽”不是可以负责的事，与“大家都听着他的声音”也无关。"}, {"text": "借", "is_correct": false, "explanation": "配价：“借”要带宾语（借什么），这里缺少宾语，句子不完整。"}], "explanations": {"报分": "正确：“负责报分”指负责把得分大声说出来，与“大家都听着他的声音”相符。", "发烧": "语义：“发烧”是身体状况，不能被“负责”，句子意思不通。", "咳嗽": "语义：“咳嗽”不是可以负责的事，与“大家都听着他的声音”也无关。", "借": "配价：“借”要带宾语（借什么），这里缺少宾语，句子不完整。"}, "sentence_index": 6, "correct_answer": "报分"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他去派出所报分了。", "explanation": "这里应该用〈报案〉。“报分”指报出得分，不能指向警察报告案件。"}, {"text": "学校门口，新生们正在报分。", "explanation": "这里应该用〈报到〉。“报分”指报出得分，不能指到校登记。"}, {"text": "我下午要去税务局报分。", "explanation": "这里应该用〈报税〉。“报分”指报出得分，不能指申报税款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87393, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "裁判大声报分完，比赛就结束了。", "corrected_sentence": "裁判大声报完分，比赛就结束了。", "error_description": "错误：“报分完”；正确：“报完分”。“完”是结果补语，应紧跟动词“报”，放在宾语“分”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87393, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比赛结束后，裁判报分完了。", "corrected_sentence": "比赛结束后，裁判报完分了。", "error_description": "错误：“报分完”；正确：“报完分”。“完”是结果补语，应紧跟动词“报”，放在宾语“分”之前。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8047eb7b-a39d-4111-9afe-36c29f2fb580') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87395, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "免费", "is_correct": true, "explanation": "免费：不收费用，与“收费”构成反义，是这一义项的对立面，与句中“网络收费吗”的问法相反。"}, {"text": "赔偿", "is_correct": false, "explanation": "无反义关系：“赔偿”指弥补损失，与“收费”的收钱之义没有对立关系。"}, {"text": "散步", "is_correct": false, "explanation": "无反义关系：“散步”指随意走动，与“收费”没有对立关系。"}, {"text": "打扫", "is_correct": false, "explanation": "无反义关系：“打扫”指清理卫生，与“收费”的收钱之义没有对立关系。"}], "correct_answer": "免费", "explanations": {"免费": "免费：不收费用，与“收费”构成反义，是这一义项的对立面，与句中“网络收费吗”的问法相反。", "赔偿": "无反义关系：“赔偿”指弥补损失，与“收费”的收钱之义没有对立关系。", "散步": "无反义关系：“散步”指随意走动，与“收费”没有对立关系。", "打扫": "无反义关系：“打扫”指清理卫生，与“收费”的收钱之义没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87395, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "免费", "is_correct": true, "explanation": "免费：不收费用，与“收费”构成反义，是这一义项的对立面，与句中“不收费”的说法相呼应。"}, {"text": "出发", "is_correct": false, "explanation": "无反义关系：“出发”指动身前往，与“收费”没有对立关系。"}, {"text": "批评", "is_correct": false, "explanation": "无反义关系：“批评”指指出缺点，与“收费”没有对立关系。"}, {"text": "唱歌", "is_correct": false, "explanation": "无反义关系：“唱歌”指发出歌声，与“收费”没有对立关系。"}], "correct_answer": "免费", "explanations": {"免费": "免费：不收费用，与“收费”构成反义，是这一义项的对立面，与句中“不收费”的说法相呼应。", "出发": "无反义关系：“出发”指动身前往，与“收费”没有对立关系。", "批评": "无反义关系：“批评”指指出缺点，与“收费”没有对立关系。", "唱歌": "无反义关系：“唱歌”指发出歌声，与“收费”没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87395, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "收费是别人用了东西，就要给钱。", "primary_collocate": null, "pronunciation": "shōu fèi", "ipa": "ʂoʊ˥ feɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这个公园的停车场要收费。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路不收费，你可以放心开。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公共厕所以前收费，现在免费了。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的网络收费吗？", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用这台机器要收费，一次五块钱。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "图书馆借书不收费。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个游泳池一小时收费二十块。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上厕所收费的地方很少。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里的停车位也收费。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个软件试用时不收费。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收费站", "label": "复合"}, {"form": "收费标准", "label": "复合"}], "register": "中性", "sense_fingerprint": "使用某地方、设备或东西时需要付钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf41015-8ec0-4664-ad3d-be3fa4f8add0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87395, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收费", "is_correct": true, "explanation": "收费：动词，表示停车场要求使用者付钱，与“要”和“停车场”搭配，句意完整。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”指去看展览或地方，停车场不能“要参观”，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”是人的动作，停车场不能睡觉，“要睡觉”句意不通。"}, {"text": "打印", "is_correct": false, "explanation": "搭配：“打印”的对象是文件或照片，停车场不能被“打印”，与句中的“停车场”搭配不当。"}], "explanations": {"收费": "收费：动词，表示停车场要求使用者付钱，与“要”和“停车场”搭配，句意完整。", "参观": "语义：“参观”指去看展览或地方，停车场不能“要参观”，句意不通。", "睡觉": "语义：“睡觉”是人的动作，停车场不能睡觉，“要睡觉”句意不通。", "打印": "搭配：“打印”的对象是文件或照片，停车场不能被“打印”，与句中的“停车场”搭配不当。"}, "sentence_index": 0, "correct_answer": "收费"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "进馆以后，游客向馆方收费。", "explanation": "这里应该用〈付费〉。游客是付钱的一方，应说“付费”；“向馆方收费”把收付双方颠倒了，收费是提供服务的一方向对方收钱。"}, {"text": "乱扔垃圾的人要收费。", "explanation": "这里应该用〈罚款〉。收费针对服务或设施，违规的惩罚要说“罚款”，不能说“收费”。"}, {"text": "孩子打碎了玻璃，要收费。", "explanation": "这里应该用〈赔偿〉。收费是为服务或设施收钱，打碎别人的东西要说“赔偿”，不能说“收费”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87395, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收费", "is_correct": true, "explanation": "收费：动词，表示游泳池按时间向使用者收钱，与“一小时”和“二十块”搭配，句意完整。"}, {"text": "开放", "is_correct": false, "explanation": "语义：“开放”指允许进入，不能说“开放二十块”，句意不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”是人的动作，游泳池不能“唱歌”，“唱歌二十块”句意不通。"}, {"text": "找零", "is_correct": false, "explanation": "搭配：“找零”指找还的钱，不能和“一小时”搭配，“一小时找零二十块”不成搭配。"}], "explanations": {"收费": "收费：动词，表示游泳池按时间向使用者收钱，与“一小时”和“二十块”搭配，句意完整。", "开放": "语义：“开放”指允许进入，不能说“开放二十块”，句意不通。", "唱歌": "语义：“唱歌”是人的动作，游泳池不能“唱歌”，“唱歌二十块”句意不通。", "找零": "搭配：“找零”指找还的钱，不能和“一小时”搭配，“一小时找零二十块”不成搭配。"}, "sentence_index": 6, "correct_answer": "收费"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大家可以收费帮助他。", "explanation": "这里应该用〈捐款〉。收费是为服务收钱，帮助他人要说“捐款”，不能说“收费”。"}, {"text": "这件衣服收费一百元。", "explanation": "这里应该用〈卖〉。收费针对服务或设施，商品买卖要说“卖”，衣服是商品，不能说“收费”。"}, {"text": "过生日时，我收费了朋友一个礼物。", "explanation": "这里应该用〈收到〉。收费是为服务或设施向对方收钱，得到别人送的礼物要说“收到”，不能说“收费”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87395, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个停车场要收费钱。", "corrected_sentence": "这个停车场要收费。", "error_description": "“收费”本身已经表示收钱，后面不能再加“钱”。错误形式是“收费钱”，正确形式是“收费”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87395, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "游泳池收费游客十块钱。", "corrected_sentence": "游泳池收游客十块钱。", "error_description": "“收费”不能直接带表示人的宾语和钱数，要说“收＋人＋钱数”。错误形式是“收费游客十块钱”，正确形式是“收游客十块钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
