INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87396, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "收取费用。", "primary_collocate": null, "pronunciation": "shōu fèi", "ipa": "ʂoʊ˥ feɪ˥˩", "syllable_count": 2, "sentences": [{"text": "银行对转账收费，每次两块钱。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们按小时收费。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家酒店对客人的早饭另外收费。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校不能乱收费。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说这个活动不收费。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出租车公司按路程收费。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "景区对外国游客也收费。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "律师按时间向客户收费。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家商店送货要另外收费。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为这项服务收费一百元。", "target_word": "收费", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "收费站", "label": "复合"}, {"form": "收费标准", "label": "复合"}], "register": "中性", "sense_fingerprint": "提供服务或商品的一方向对方收取钱款", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf41015-8ec0-4664-ad3d-be3fa4f8add0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87396, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收费", "is_correct": true, "explanation": "收费：动词，表示银行对转账收取费用，与后面的“每次两块钱”呼应，句意完整。"}, {"text": "演出", "is_correct": false, "explanation": "语义：“演出”指表演，银行不能对转账“演出”，句意不通。"}, {"text": "免费", "is_correct": false, "explanation": "语义：“免费”与后面的“每次两块钱”矛盾，句子自相矛盾。"}, {"text": "开门", "is_correct": false, "explanation": "搭配：“开门”的对象是门或房间，转账不能“开门”，与“银行对转账”搭配不当。"}], "explanations": {"收费": "收费：动词，表示银行对转账收取费用，与后面的“每次两块钱”呼应，句意完整。", "演出": "语义：“演出”指表演，银行不能对转账“演出”，句意不通。", "免费": "语义：“免费”与后面的“每次两块钱”矛盾，句子自相矛盾。", "开门": "搭配：“开门”的对象是门或房间，转账不能“开门”，与“银行对转账”搭配不当。"}, "sentence_index": 0, "correct_answer": "收费"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家向灾区收费。", "explanation": "这里应该用〈捐款〉。收费是为服务收钱，向灾区给钱帮助他人要说“捐款”，不能说“收费”。"}, {"text": "违规的司机要收费。", "explanation": "这里应该用〈罚款〉。收费针对服务或设施，违规的惩罚要说“罚款”，不能说“收费”。"}, {"text": "老板向员工收费一百元的奖金。", "explanation": "这里应该用〈发〉。奖金是老板付给员工的，应说“发奖金”；“向员工收费”颠倒了收付双方，不能说“收费”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87396, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收费", "is_correct": true, "explanation": "收费：动词，表示景区对外国游客收取费用，与“也”和句意呼应，句意完整。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”是人的动作，景区不能对游客“唱歌”，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”是人的动作，景区不能对游客“睡觉”，句意不通。"}, {"text": "学习", "is_correct": false, "explanation": "搭配：“学习”的对象是知识，景区对游客不能说“学习”，与“对外国游客”搭配不当。"}], "explanations": {"收费": "收费：动词，表示景区对外国游客收取费用，与“也”和句意呼应，句意完整。", "唱歌": "语义：“唱歌”是人的动作，景区不能对游客“唱歌”，句意不通。", "睡觉": "语义：“睡觉”是人的动作，景区不能对游客“睡觉”，句意不通。", "学习": "搭配：“学习”的对象是知识，景区对游客不能说“学习”，与“对外国游客”搭配不当。"}, "sentence_index": 6, "correct_answer": "收费"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "客户为这项服务收费一百元。", "explanation": "这里应该用〈付费〉。收费是提供服务的一方收钱，客户是使用服务的一方，应该说“付费”。"}, {"text": "他撞坏了别人的车，应该收费。", "explanation": "这里应该用〈赔偿〉。收费是为服务收钱，撞坏别人的东西要说“赔偿”，不能说“收费”。"}, {"text": "老师给表现好的学生收费。", "explanation": "这里应该用〈奖励〉。收费是向使用者收钱，奖励学生要说“奖励”，两者方向相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87396, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校乱收费钱，学生很不满意。", "corrected_sentence": "学校乱收费，学生很不满意。", "error_description": "“收费”本身已经表示收钱，后面不能再加“钱”。错误形式是“收费钱”，正确形式是“收费”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87396, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "景区收费外国游客五十块钱。", "corrected_sentence": "景区收外国游客五十块钱。", "error_description": "“收费”不能直接带表示人的宾语和钱数，要说“收＋人＋钱数”。错误形式是“收费外国游客五十块钱”，正确形式是“收外国游客五十块钱”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
