INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87397, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "省长是管一个省的大官。", "primary_collocate": null, "pronunciation": "shěng zhǎng", "ipa": "ʂɤŋ˨˩˦ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "省长今天要来我们学校。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位省长很受大家喜欢。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的爸爸是一位省长。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省长在会上说了很多话。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在电视上看到了省长。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的省长很年轻。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省长带着很多人去看农村。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想长大以后当省长。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省长的车停在大楼前面。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个省的省长换人了。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位省长", "label": "量词"}, {"form": "副省长", "label": "复合"}, {"form": "省長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "管理一个省的大官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f88939-d718-4d2d-bc4c-ca9e6f6115ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87397, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "省长", "is_correct": true, "explanation": "正确答案：省长（shěng zhǎng），指管理一个省的大官。"}, {"text": "生长", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是生长，指植物或人长大。"}, {"text": "胜仗", "is_correct": false, "explanation": "shèng（第四声）与 shěng（第三声）、zhàng（第四声）与 zhǎng（第三声）声调不同，意思是打赢的仗。"}, {"text": "声张", "is_correct": false, "explanation": "shěng 与 shēng 声调不同，zhǎng 与 zhāng 声调也不同，意思是公开宣扬。"}], "explanations": {"省长": "正确答案：省长（shěng zhǎng），指管理一个省的大官。", "生长": "shěng（第三声）与 shēng（第一声）声调不同，意思是生长，指植物或人长大。", "胜仗": "shèng（第四声）与 shěng（第三声）、zhàng（第四声）与 zhǎng（第三声）声调不同，意思是打赢的仗。", "声张": "shěng 与 shēng 声调不同，zhǎng 与 zhāng 声调也不同，意思是公开宣扬。"}, "sentence_index": null, "correct_answer": "省长"}, "level_3": {"options": [{"text": "省长", "is_correct": true, "explanation": "正确：“省长”是管理一个省的大官，与“今天要来我们学校”相符。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是物品，不会来学校，句子意思不通。"}, {"text": "省会", "is_correct": false, "explanation": "语义：省会是城市，不能来学校，句子意思不通。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果不会来学校，句子意思不通。"}], "explanations": {"省长": "正确：“省长”是管理一个省的大官，与“今天要来我们学校”相符。", "冰箱": "语义：冰箱是物品，不会来学校，句子意思不通。", "省会": "语义：省会是城市，不能来学校，句子意思不通。", "水果": "语义：水果不会来学校，句子意思不通。"}, "sentence_index": 0, "correct_answer": "省长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班的省长很热心，经常帮同学补课。", "explanation": "这里应该用〈班长〉。省长是管一个省的大官，班里的负责人要说班长，不能用“省长”。"}, {"text": "他是一家医院的省长，治好了很多病人。", "explanation": "这里应该用〈医生〉。省长是管一个省的官员，治病救人的人要说医生，不能用“省长”。"}, {"text": "这家饭店的省长很热情，每次都给我们多加一个菜。", "explanation": "这里应该用〈服务员〉。省长是管一个省的大官，饭店里招待客人的人要说服务员，不能用“省长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87397, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省长", "is_correct": true, "explanation": "正确：“省长”是管理一个省的大官，能够带人去农村考察。"}, {"text": "机器", "is_correct": false, "explanation": "语义：机器是物品，不能带着很多人去看农村，句子意思不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有生命，不能带人去看农村，句子意思不通。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶不是人，不能带着很多人去看农村，句子意思不通。"}], "explanations": {"省长": "正确：“省长”是管理一个省的大官，能够带人去农村考察。", "机器": "语义：机器是物品，不能带着很多人去看农村，句子意思不通。", "石头": "语义：石头没有生命，不能带人去看农村，句子意思不通。", "牛奶": "语义：牛奶不是人，不能带着很多人去看农村，句子意思不通。"}, "sentence_index": 6, "correct_answer": "省长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那位省长手艺很好，每位客人都很满意。", "explanation": "这里应该用〈理发师〉。省长是管一个省的官员，给客人理发的人要说理发师，不能说“省长”。"}, {"text": "那位省长做了一上午饭，很辛苦。", "explanation": "这里应该用〈厨师〉。省长是管一个省的官员，在厨房做饭的人要说厨师，不能说“省长”。"}, {"text": "那位省长每天开车接送乘客。", "explanation": "这里应该用〈司机〉。省长是管一个省的官员，专门开车接送乘客的人要说司机，不能说“省长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87397, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只省长很认真。", "corrected_sentence": "这位省长很认真。", "error_description": "量词错误：指人的“省长”要用量词“位”，不能用“只”，应说“这位省长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87397, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在电视上看到了一条省长。", "corrected_sentence": "我在电视上看到了一位省长。", "error_description": "量词错误：指人的“省长”要用量词“位”或“个”，不能用“条”，应说“一位省长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
