INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87398, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个省的政府首长。", "primary_collocate": null, "pronunciation": "shěng zhǎng", "ipa": "ʂɤŋ˨˩˦ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "省长是省政府的最高领导。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省长由省人大选举产生。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省长向记者介绍了今年的工作计划。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省长和市长一起开了会。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省长签署文件，决定修一条新路。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年，省长去过很多城市看教育情况。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者采访了这个省的省长。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省长在政府会议上讲了经济问题。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位省长已经工作了三十年。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "省长要求各个部门认真检查安全。", "target_word": "省长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位省长", "label": "量词"}, {"form": "副省长", "label": "复合"}, {"form": "省長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "省政府的首长，行政职务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f88939-d718-4d2d-bc4c-ca9e6f6115ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87398, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "省长", "is_correct": true, "explanation": "正确答案：省长（shěng zhǎng），指省政府的首长。"}, {"text": "生长", "is_correct": false, "explanation": "shěng（第三声）与 shēng（第一声）声调不同，意思是生长，指植物或人长大。"}, {"text": "胜仗", "is_correct": false, "explanation": "shèng（第四声）与 shěng（第三声）、zhàng（第四声）与 zhǎng（第三声）声调不同，意思是打赢的仗。"}, {"text": "声张", "is_correct": false, "explanation": "shěng 与 shēng 声调不同，zhǎng 与 zhāng 声调也不同，意思是公开宣扬。"}], "explanations": {"省长": "正确答案：省长（shěng zhǎng），指省政府的首长。", "生长": "shěng（第三声）与 shēng（第一声）声调不同，意思是生长，指植物或人长大。", "胜仗": "shèng（第四声）与 shěng（第三声）、zhàng（第四声）与 zhǎng（第三声）声调不同，意思是打赢的仗。", "声张": "shěng 与 shēng 声调不同，zhǎng 与 zhāng 声调也不同，意思是公开宣扬。"}, "sentence_index": null, "correct_answer": "省长"}, "level_3": {"options": [{"text": "省长", "is_correct": true, "explanation": "正确：“省长”是省政府的最高领导，与句子的定义相符。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是地方，不是政府领导，句子意思不通。"}, {"text": "省会", "is_correct": false, "explanation": "语义：省会是城市，不能是省政府的最高领导。"}, {"text": "首相", "is_correct": false, "explanation": "语域：“首相”是外国政府首脑的称呼，在中国省级政府的语境中不用。"}], "explanations": {"省长": "正确：“省长”是省政府的最高领导，与句子的定义相符。", "厨房": "语义：厨房是地方，不是政府领导，句子意思不通。", "省会": "语义：省会是城市，不能是省政府的最高领导。", "首相": "语域：“首相”是外国政府首脑的称呼，在中国省级政府的语境中不用。"}, "sentence_index": 0, "correct_answer": "省长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们小区的省长很负责，每天晚上都巡逻。", "explanation": "这里应该用〈保安〉。省长是管一个省的大官，负责小区巡逻的人要说保安，不能说“省长”。"}, {"text": "他在工厂里做了三年省长，现在退休了。", "explanation": "这里应该用〈工人〉。省长是管一个省的官员，在工厂里干活的人要说工人，不能用“省长”。"}, {"text": "这个省长很认真，每天都在病房里忙。", "explanation": "这里应该用〈护士〉。省长是管一个省的大官，在病房里照顾病人的人要说护士，不能说“省长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87398, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省长", "is_correct": true, "explanation": "正确：“记者采访了这个省的省长”，采访的对象是人，与“省长”相符。"}, {"text": "字典", "is_correct": false, "explanation": "搭配：采访的对象应是人或机构，“字典”不能被采访。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空不是人，不能被记者采访，句子意思不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是物品，不能被记者采访，句子意思不通。"}], "explanations": {"省长": "正确：“记者采访了这个省的省长”，采访的对象是人，与“省长”相符。", "字典": "搭配：采访的对象应是人或机构，“字典”不能被采访。", "天空": "语义：天空不是人，不能被记者采访，句子意思不通。", "冰箱": "语义：冰箱是物品，不能被记者采访，句子意思不通。"}, "sentence_index": 6, "correct_answer": "省长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们学校的省长很严格，每天都让我们练跑步。", "explanation": "这里应该用〈教练〉。省长是管一个省的官员，带学生锻炼的人要说教练，不能说“省长”。"}, {"text": "这位省长剪了一上午树，很辛苦。", "explanation": "这里应该用〈园丁〉。省长是管一个省的官员，在园子里修剪树木的人要说园丁，不能说“省长”。"}, {"text": "这家面包店的省长每天凌晨起来烤面包。", "explanation": "这里应该用〈面包师〉。省长是管一个省的官员，在面包店里烤面包的人要说面包师，不能说“省长”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87398, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只省长昨天去了农村。", "corrected_sentence": "这位省长昨天去了农村。", "error_description": "量词错误：指人的“省长”要用“位”，不能用“只”，应说“这位省长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87398, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "记者采访了这个省的一条省长。", "corrected_sentence": "记者采访了这个省的一位省长。", "error_description": "量词错误：指人的“省长”要用量词“位”，不能用“条”，应说“一位省长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
