INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87399, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "段是数一长条东西被分开后的一块，或一小段时间。", "primary_collocate": null, "pronunciation": "duàn", "ipa": "twan˥˩", "syllable_count": 1, "sentences": [{"text": "他把绳子剪成了三段。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段木头太短，不能做桌子。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把长长的面包切成两段。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我一段短绳子。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边有一段很旧的铁路。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路分成三段，每段都不长。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们只走了一段路，就累了。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着一段竹子。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了一段时间，雪就化了。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把电线剪成了好几段。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片段", "label": "复合"}, {"form": "段落", "label": "复合"}], "register": "中性", "sense_fingerprint": "量词，长条形东西分开后的一截，也可指一小段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae51d7e-db40-49f3-b67b-d653c6a88f9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87399, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "段", "is_correct": true, "explanation": "段（duàn）：量词，用于分开的长条形东西的一截。"}, {"text": "短", "is_correct": false, "explanation": "短（duǎn）与段（duàn）声调不同（第三声），意思是长度小。"}, {"text": "端", "is_correct": false, "explanation": "端（duān）与段（duàn）声调不同（第一声），意思是一头、末梢。"}, {"text": "顿", "is_correct": false, "explanation": "顿（dùn）与段（duàn）只差韵腹 a，声调相同，意思是一餐（如“一顿饭”）。"}, {"text": "但", "is_correct": false, "explanation": "但（dàn）与段（duàn）韵母不同（少了介音 u），意思是但是。"}], "explanations": {"段": "段（duàn）：量词，用于分开的长条形东西的一截。", "短": "短（duǎn）与段（duàn）声调不同（第三声），意思是长度小。", "端": "端（duān）与段（duàn）声调不同（第一声），意思是一头、末梢。", "顿": "顿（dùn）与段（duàn）只差韵腹 a，声调相同，意思是一餐（如“一顿饭”）。", "但": "但（dàn）与段（duàn）韵母不同（少了介音 u），意思是但是。"}, "sentence_index": null, "correct_answer": "段"}, "level_3": {"options": [{"text": "段", "is_correct": true, "explanation": "段：量词，用于剪开的长条形东西的一截。"}, {"text": "只", "is_correct": false, "explanation": "搭配：「只」用于动物或成对物体中的一个，绳子不能用“只”计数。"}, {"text": "位", "is_correct": false, "explanation": "语义：「位」用于人，绳子不是人，不能用“位”计数。"}, {"text": "张", "is_correct": false, "explanation": "搭配：「张」用于平面的东西，绳子不是平面的，不能用“张”计数。"}], "explanations": {"段": "段：量词，用于剪开的长条形东西的一截。", "只": "搭配：「只」用于动物或成对物体中的一个，绳子不能用“只”计数。", "位": "语义：「位」用于人，绳子不是人，不能用“位”计数。", "张": "搭配：「张」用于平面的东西，绳子不是平面的，不能用“张”计数。"}, "sentence_index": 0, "correct_answer": "段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌子上有一段苹果。", "explanation": "这里应该用〈个〉。段用于长条形东西分开后的一截，或一段时间、路程；苹果要用〈个〉。"}, {"text": "我养了一段狗。", "explanation": "这里应该用〈只〉。段用于长条形的东西，养的动物要用〈只〉。"}, {"text": "我借了一段书。", "explanation": "这里应该用〈本〉。书要用〈本〉，段不能用于书。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87399, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "段", "is_correct": true, "explanation": "段（duàn）：量词，用于分开的长条形东西的一截。"}, {"text": "乱", "is_correct": false, "explanation": "乱（luàn）与段（duàn）声母不同（l 与 d），意思是混乱。"}, {"text": "端", "is_correct": false, "explanation": "端（duān）与段（duàn）声母韵母相同，只是声调不同（第一声），意思是一头、末梢。"}, {"text": "蛋", "is_correct": false, "explanation": "蛋（dàn）与段（duàn）只差介音 u，声调相同，意思是鸡蛋。"}], "explanations": {"段": "段（duàn）：量词，用于分开的长条形东西的一截。", "乱": "乱（luàn）与段（duàn）声母不同（l 与 d），意思是混乱。", "端": "端（duān）与段（duàn）声母韵母相同，只是声调不同（第一声），意思是一头、末梢。", "蛋": "蛋（dàn）与段（duàn）只差介音 u，声调相同，意思是鸡蛋。"}, "sentence_index": null, "correct_answer": "段"}, "level_3": {"options": [{"text": "段", "is_correct": true, "explanation": "段：量词，用于一段路。"}, {"text": "座", "is_correct": false, "explanation": "搭配：「座」用于山、桥等大型固定的东西，路不能用“座”计数。"}, {"text": "名", "is_correct": false, "explanation": "语义：「名」用于人，路不是人，不能用“名”计数。"}, {"text": "所", "is_correct": false, "explanation": "搭配：「所」用于房屋、学校等建筑，路不能用“所”计数。"}], "explanations": {"段": "段：量词，用于一段路。", "座": "搭配：「座」用于山、桥等大型固定的东西，路不能用“座”计数。", "名": "语义：「名」用于人，路不是人，不能用“名”计数。", "所": "搭配：「所」用于房屋、学校等建筑，路不能用“所”计数。"}, "sentence_index": 6, "correct_answer": "段"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他买了一段衣服。", "explanation": "这里应该用〈件〉。段用于长条形东西或一段时间、路程，衣服要用〈件〉。"}, {"text": "他认识了一段朋友。", "explanation": "这里应该用〈个〉。段不能用于人，朋友要用〈个〉。"}, {"text": "他喝了一段水。", "explanation": "这里应该用〈口〉。喝水的量要用〈口〉，段不能用于液体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87399, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把木板锯成了两个段。", "corrected_sentence": "他把木板锯成了两段。", "error_description": "量词误用：“段”本身就是量词，不能再与“个”搭配。应说“两段”，即“他把木板锯成了两段”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87399, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们走了一个段很长的路。", "corrected_sentence": "我们走了一段很长的路。", "error_description": "量词叠用：“段”本身是量词，前面不能再加“个”，应说“一段很长的路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
