INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87400, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "量词，用于分成几部分的东西，或一段时间、距离。", "primary_collocate": null, "pronunciation": "duàn", "ipa": "twan˥˩", "syllable_count": 1, "sentences": [{"text": "我在北京住过一段时间。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师读了一段短文。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从家到学校有一段路。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们有过一段快乐的日子。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段话我听不懂。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱了一段京剧。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面这段路很难走。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个故事分成三段。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请你再说一段你的经历。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段音乐让我想起家乡。", "target_word": "段", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "片段", "label": "复合"}, {"form": "段落", "label": "复合"}], "register": "中性", "sense_fingerprint": "量词，用于时间、距离、话语、乐曲、故事等分出来的一部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eae51d7e-db40-49f3-b67b-d653c6a88f9a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87400, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "段", "is_correct": true, "explanation": "段（duàn）：量词，用于时间、路程、话语等分出来的一部分。"}, {"text": "短", "is_correct": false, "explanation": "短（duǎn）与段（duàn）声调不同（第三声），意思是长度小、时间短。"}, {"text": "端", "is_correct": false, "explanation": "端（duān）与段（duàn）声调不同（第一声），意思是一头、开端。"}, {"text": "顿", "is_correct": false, "explanation": "顿（dùn）与段（duàn）只差韵腹 a，声调相同，意思是一餐（如“一顿饭”）。"}, {"text": "但", "is_correct": false, "explanation": "但（dàn）与段（duàn）韵母不同（少了介音 u），意思是但是。"}], "explanations": {"段": "段（duàn）：量词，用于时间、路程、话语等分出来的一部分。", "短": "短（duǎn）与段（duàn）声调不同（第三声），意思是长度小、时间短。", "端": "端（duān）与段（duàn）声调不同（第一声），意思是一头、开端。", "顿": "顿（dùn）与段（duàn）只差韵腹 a，声调相同，意思是一餐（如“一顿饭”）。", "但": "但（dàn）与段（duàn）韵母不同（少了介音 u），意思是但是。"}, "sentence_index": null, "correct_answer": "段"}, "level_3": {"options": [{"text": "段", "is_correct": true, "explanation": "段：量词，用于一段时间。"}, {"text": "次", "is_correct": false, "explanation": "语义：「次」计算次数，不计时间的长度，不能修饰“时间”。"}, {"text": "个", "is_correct": false, "explanation": "搭配：「个」不能修饰“时间”，这里应用表示一段时间的量词。"}, {"text": "场", "is_correct": false, "explanation": "搭配：「场」用于比赛、雨等，不能修饰“时间”。"}], "explanations": {"段": "段：量词，用于一段时间。", "次": "语义：「次」计算次数，不计时间的长度，不能修饰“时间”。", "个": "搭配：「个」不能修饰“时间”，这里应用表示一段时间的量词。", "场": "搭配：「场」用于比赛、雨等，不能修饰“时间”。"}, "sentence_index": 0, "correct_answer": "段"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "下了一段雨。", "explanation": "这里应该用〈阵〉。表示短时间的雨要用〈阵〉，段不能用于雨。"}, {"text": "吃了一段饭。", "explanation": "这里应该用〈顿〉。吃饭的次数要用〈顿〉，段不能用于吃饭。"}, {"text": "我们开过一段会。", "explanation": "这里应该用〈次〉。开会的次数要用〈次〉，段不能用于会议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5e7268ba-3204-42e2-9321-ad62f801fb4e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
