INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87401, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "涂是把颜色或东西抹在上面。", "primary_collocate": null, "pronunciation": "tú", "ipa": "tʰu˧˥", "syllable_count": 1, "sentences": [{"text": "他在面包上涂了一层黄油。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "出门前要涂防晒霜。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我的手涂了药。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在纸的背面涂一点胶水。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在嘴上涂了红色的口红。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的脸上涂着奶油。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "睡觉前，我在脸上涂些面霜。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把药涂在伤口上，很快就好了。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他涂过这种药，没有用。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你先把胶水涂在这里，再把纸贴上。", "target_word": "涂", "complexity_tier": "T3", "furigana": "nǐ xiān bǎ jiāoshuǐ tú zài zhèlǐ, zài bǎ zhǐ tiē shàng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "涂了", "label": "体标"}, {"form": "涂着", "label": "体标"}, {"form": "涂过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把药、油、霜、胶水等东西抹在物体或身体上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8eeb9b7-da00-4ad1-a443-5d1569c7e006') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87401, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "涂", "is_correct": true, "explanation": "涂 tú：把颜料、药膏等抹在物体或身体表面，为正确答案。"}, {"text": "土", "is_correct": false, "explanation": "tǔ（第三声）与 tú（第二声）声调不同，意思是泥土。"}, {"text": "兔", "is_correct": false, "explanation": "tù（第四声）与 tú（第二声）声调不同，意思是兔子。"}, {"text": "突", "is_correct": false, "explanation": "tū（第一声）与 tú（第二声）声调不同，意思是突然。"}], "explanations": {"涂": "涂 tú：把颜料、药膏等抹在物体或身体表面，为正确答案。", "土": "tǔ（第三声）与 tú（第二声）声调不同，意思是泥土。", "兔": "tù（第四声）与 tú（第二声）声调不同，意思是兔子。", "突": "tū（第一声）与 tú（第二声）声调不同，意思是突然。"}, "sentence_index": null, "correct_answer": "涂"}, "level_3": {"options": [{"text": "涂", "is_correct": true, "explanation": "涂：把黄油抹在面包上，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下，不能说在面包上吃一层黄油。"}, {"text": "读", "is_correct": false, "explanation": "搭配：“读”的对象是文字、书籍，不能说读黄油。"}, {"text": "砍", "is_correct": false, "explanation": "语义：“砍”是用刀猛击切断，与在面包上加一层东西不符。"}], "explanations": {"涂": "涂：把黄油抹在面包上，符合句意。", "吃": "语义：“吃”指把食物咽下，不能说在面包上吃一层黄油。", "读": "搭配：“读”的对象是文字、书籍，不能说读黄油。", "砍": "语义：“砍”是用刀猛击切断，与在面包上加一层东西不符。"}, "sentence_index": 0, "correct_answer": "涂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用抹布把桌子涂干净了。", "explanation": "这里应该用〈擦〉。涂是把东西抹在表面上，擦去污渍要用擦。"}, {"text": "他把花涂在瓶子里。", "explanation": "这里应该用〈插〉。涂是抹在表面上，把花放进瓶中要用插。"}, {"text": "他用手把纸涂成两半。", "explanation": "这里应该用〈撕〉。涂是抹在表面上，把纸分成两半要用撕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87401, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "涂", "is_correct": true, "explanation": "涂 tú：把颜料、药膏等抹在物体或身体表面，为正确答案。"}, {"text": "吐", "is_correct": false, "explanation": "tǔ（第三声）与 tú（第二声）声调不同，意思是吐出。"}, {"text": "秃", "is_correct": false, "explanation": "tū（第一声）与 tú（第二声）声调不同，意思是没有头发。"}, {"text": "凸", "is_correct": false, "explanation": "tū（第一声）与 tú（第二声）声调不同，意思是向外鼓起。"}], "explanations": {"涂": "涂 tú：把颜料、药膏等抹在物体或身体表面，为正确答案。", "吐": "tǔ（第三声）与 tú（第二声）声调不同，意思是吐出。", "秃": "tū（第一声）与 tú（第二声）声调不同，意思是没有头发。", "凸": "tū（第一声）与 tú（第二声）声调不同，意思是向外鼓起。"}, "sentence_index": null, "correct_answer": "涂"}, "level_3": {"options": [{"text": "涂", "is_correct": true, "explanation": "涂：把面霜抹在脸上，符合句意。"}, {"text": "撕", "is_correct": false, "explanation": "语义：“撕”是把东西扯开或扯下，与“在脸上加面霜”的意思相反。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣物，不能说穿面霜。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是饮品，面霜不能喝。"}], "explanations": {"涂": "涂：把面霜抹在脸上，符合句意。", "撕": "语义：“撕”是把东西扯开或扯下，与“在脸上加面霜”的意思相反。", "穿": "搭配：“穿”的对象是衣物，不能说穿面霜。", "喝": "搭配：“喝”的对象是饮品，面霜不能喝。"}, "sentence_index": 6, "correct_answer": "涂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈把豆子涂在水里过了一夜。", "explanation": "这里应该用〈泡〉。涂是抹在表面上，把东西浸在水中要用泡。"}, {"text": "他把垃圾涂进了垃圾桶。", "explanation": "这里应该用〈扔〉。涂是抹在表面上，把垃圾丢进桶里要用扔。"}, {"text": "妈妈用勺子把饭涂进宝宝嘴里。", "explanation": "这里应该用〈喂〉。涂是抹在表面上，让别人吃饭要用喂。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
