INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87401, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐把护手霜涂了在手上。", "corrected_sentence": "姐姐把护手霜涂在手上。", "error_description": "错误：“涂了在手上”，正确：“涂在手上”。“了”不能插在动词“涂”与处所补语“在手上”之间，应删去。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
