INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87402, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用颜料、油漆等抹在物体表面。", "primary_collocate": null, "pronunciation": "tú", "ipa": "tʰu˧˥", "syllable_count": 1, "sentences": [{"text": "工人在墙上涂了白色油漆。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把门涂成了蓝色。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在给桌子涂油漆。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子在纸上涂红色颜料。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个房间的墙涂过两次了。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用黄色把小鸟涂得很漂亮。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥把旧椅子涂成绿色。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这块板涂上黑漆。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "画好以后，再涂上一层颜料。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着刷子涂门窗。", "target_word": "涂", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "涂了", "label": "体标"}, {"form": "涂着", "label": "体标"}, {"form": "涂过", "label": "体标"}], "register": "中性", "sense_fingerprint": "用刷子把油漆、颜料等涂在墙、门、纸等表面上", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd8eeb9b7-da00-4ad1-a443-5d1569c7e006') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87402, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "涂", "is_correct": true, "explanation": "涂 tú：用颜料、油漆等抹在物体表面，为正确答案。"}, {"text": "土", "is_correct": false, "explanation": "tǔ（第三声）与 tú（第二声）声调不同，意思是泥土。"}, {"text": "兔", "is_correct": false, "explanation": "tù（第四声）与 tú（第二声）声调不同，意思是兔子。"}, {"text": "突", "is_correct": false, "explanation": "tū（第一声）与 tú（第二声）声调不同，意思是突然。"}], "explanations": {"涂": "涂 tú：用颜料、油漆等抹在物体表面，为正确答案。", "土": "tǔ（第三声）与 tú（第二声）声调不同，意思是泥土。", "兔": "tù（第四声）与 tú（第二声）声调不同，意思是兔子。", "突": "tū（第一声）与 tú（第二声）声调不同，意思是突然。"}, "sentence_index": null, "correct_answer": "涂"}, "level_3": {"options": [{"text": "涂", "is_correct": true, "explanation": "涂：用油漆把墙刷上颜色，符合句意。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指把食物咽下，与在墙上涂油漆的意思不符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣物，不能说在墙上穿油漆。"}, {"text": "读", "is_correct": false, "explanation": "搭配：“读”的对象是文字，不能说读油漆。"}], "explanations": {"涂": "涂：用油漆把墙刷上颜色，符合句意。", "吃": "语义：“吃”指把食物咽下，与在墙上涂油漆的意思不符。", "穿": "搭配：“穿”的对象是衣物，不能说在墙上穿油漆。", "读": "搭配：“读”的对象是文字，不能说读油漆。"}, "sentence_index": 0, "correct_answer": "涂"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把照片涂在墙上。", "explanation": "这里应该用〈挂〉。涂是把颜料抹在表面上，把照片挂起来要用挂。"}, {"text": "妈妈用熨斗涂衣服。", "explanation": "这里应该用〈烫〉。涂是把颜料抹上，熨平衣物要用烫。"}, {"text": "他把贴纸涂在本子上。", "explanation": "这里应该用〈粘〉。涂是把颜料抹上，把贴纸粘到本子上要用粘。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87402, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "涂", "is_correct": true, "explanation": "涂 tú：用颜料、油漆等抹在物体表面，为正确答案。"}, {"text": "吐", "is_correct": false, "explanation": "tǔ（第三声）与 tú（第二声）声调不同，意思是吐出。"}, {"text": "秃", "is_correct": false, "explanation": "tū（第一声）与 tú（第二声）声调不同，意思是没有头发。"}, {"text": "凸", "is_correct": false, "explanation": "tū（第一声）与 tú（第二声）声调不同，意思是向外鼓起。"}], "explanations": {"涂": "涂 tú：用颜料、油漆等抹在物体表面，为正确答案。", "吐": "tǔ（第三声）与 tú（第二声）声调不同，意思是吐出。", "秃": "tū（第一声）与 tú（第二声）声调不同，意思是没有头发。", "凸": "tū（第一声）与 tú（第二声）声调不同，意思是向外鼓起。"}, "sentence_index": null, "correct_answer": "涂"}, "level_3": {"options": [{"text": "涂", "is_correct": true, "explanation": "涂：把油漆刷成绿色，符合句意。"}, {"text": "剪", "is_correct": false, "explanation": "语义：“剪”是切断，与把椅子变成绿色的意思不符。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿成”不能表示改变颜色。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”是去除污物，与改变颜色不符。"}], "explanations": {"涂": "涂：把油漆刷成绿色，符合句意。", "剪": "语义：“剪”是切断，与把椅子变成绿色的意思不符。", "穿": "搭配：“穿成”不能表示改变颜色。", "洗": "语义：“洗”是去除污物，与改变颜色不符。"}, "sentence_index": 6, "correct_answer": "涂"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "哥哥用扫帚涂地。", "explanation": "这里应该用〈扫〉。涂是把颜料抹在表面上，用扫帚清扫地面要用扫。"}, {"text": "他用剪刀涂纸。", "explanation": "这里应该用〈裁〉。涂是把颜料抹在表面上，用刀具把纸切开要用裁。"}, {"text": "他用吸管涂水。", "explanation": "这里应该用〈喝〉。涂是把颜料抹在表面上，用吸管把水送进嘴里要用喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87402, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用油漆把铁门涂了成红色。", "corrected_sentence": "他用油漆把铁门涂成了红色。", "error_description": "错误：“涂了成”，正确：“涂成了”。结果补语“成”应紧跟动词，“了”放在补语之后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87402, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把颜料涂铁栏杆上。", "corrected_sentence": "工人把颜料涂在铁栏杆上。", "error_description": "错误：“涂铁栏杆上”，正确：“涂在铁栏杆上”。表示处所的“在”不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e9f44bb-1b42-4c1e-8695-cf84254f4d99') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
