INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87403, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "收购是把很多别人的东西买下来。", "primary_collocate": null, "pronunciation": "shōu gòu", "ipa": "ʂoʊ˥ koʊ˥˩", "syllable_count": 2, "sentences": [{"text": "小王到村里收购农民的鸡蛋。", "target_word": "收购", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板每天早上都来收购我们的旧报纸。", "target_word": "收购", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "秋天，商人开车去山里收购苹果。", "target_word": "收购", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他家收购了很多旧书。", "target_word": "收购", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店专门收购旧手机。", "target_word": "收购", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她把旧瓶子卖给了收购废品的人。", "target_word": "收购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商人来村里收购过我们的玉米。", "target_word": "收购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们一直在收购茶农的新茶。", "target_word": "收购", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在有人收购旧衣服，你要卖吗？", "target_word": "收购", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司想收购一千斤梨，价钱很好。", "target_word": "收购", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "收购了", "label": "完成体"}, {"form": "收购过", "label": "经验体"}, {"form": "收购站", "label": "复合词"}, {"form": "收購", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把很多别人的东西买下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73f8ce2d-5317-42df-bc29-59888134a3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87403, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收购", "is_correct": true, "explanation": "正确。收购指大量从各处买进农副产品，与“到村里”“农民的鸡蛋”相符。"}, {"text": "种", "is_correct": false, "explanation": "语义：鸡蛋不能种，“种农民的鸡蛋”说不通。"}, {"text": "养", "is_correct": false, "explanation": "搭配：“养”搭配动物或植物，不能说“养鸡蛋”。"}, {"text": "修", "is_correct": false, "explanation": "语义：鸡蛋不能修理，“修农民的鸡蛋”说不通。"}], "explanations": {"收购": "正确。收购指大量从各处买进农副产品，与“到村里”“农民的鸡蛋”相符。", "种": "语义：鸡蛋不能种，“种农民的鸡蛋”说不通。", "养": "搭配：“养”搭配动物或植物，不能说“养鸡蛋”。", "修": "语义：鸡蛋不能修理，“修农民的鸡蛋”说不通。"}, "sentence_index": 0, "correct_answer": "收购"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在商店收购了一本旧书。", "explanation": "这里应该用〈购买〉。收购指大量从各处买进（农副产品、旧物等）以便转卖，在商店买一本书要用购买。"}, {"text": "孩子们在海边收购了很多贝壳。", "explanation": "这里应该用〈捡〉。收购是花钱大量买进，孩子在海边拿起贝壳不花钱，要用捡。"}, {"text": "他用钱收购了一个警察。", "explanation": "这里应该用〈收买〉。收购指买进东西或企业，用钱拉拢人要用收买，不能说收购一个人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87403, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收购", "is_correct": true, "explanation": "正确。“收购过”表示曾经大量买进，与“商人来村里”“我们的玉米”相符。"}, {"text": "拆", "is_correct": false, "explanation": "搭配：“拆”搭配房屋、机器等，不能搭配玉米。"}, {"text": "雇", "is_correct": false, "explanation": "配价：“雇”的对象要是人，玉米不能被雇。"}, {"text": "出租", "is_correct": false, "explanation": "语义：玉米不能出租，“出租过我们的玉米”说不通。"}], "explanations": {"收购": "正确。“收购过”表示曾经大量买进，与“商人来村里”“我们的玉米”相符。", "拆": "搭配：“拆”搭配房屋、机器等，不能搭配玉米。", "雇": "配价：“雇”的对象要是人，玉米不能被雇。", "出租": "语义：玉米不能出租，“出租过我们的玉米”说不通。"}, "sentence_index": 6, "correct_answer": "收购"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我收购了一封信。", "explanation": "这里应该用〈收到〉。收购是买进，收到是接受别人送来的东西，信不是买来的。"}, {"text": "他收购了一下房间。", "explanation": "这里应该用〈收拾〉。收购是买进，不表示整理，房间也不能用买进的方式处理。"}, {"text": "我在桌上收购了钥匙。", "explanation": "这里应该用〈找到〉。收购是买进，找回放错的东西不能用收购。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87403, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "小王去年收购了过我们村的鸡蛋。", "corrected_sentence": "小王去年收购过我们村的鸡蛋。", "error_description": "错误：“收购了过”。“了”与“过”不能同用，表示经历只用“过”，去掉“了”。正确：“小王去年收购过我们村的鸡蛋。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87403, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "商人来村里收购的过我们的茶叶。", "corrected_sentence": "商人来村里收购过我们的茶叶。", "error_description": "错误：“收购的过”。“的”不能插在动词和“过”之间，表示经历的“过”应紧跟动词，应说“收购过”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
