INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87404, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从各处买进（农副产品、物品或企业等）。", "primary_collocate": null, "pronunciation": "shōu gòu", "ipa": "ʂoʊ˥ koʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这家大公司去年收购了一家小工厂。", "target_word": "收购", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市场上有人收购粮食，价钱不低。", "target_word": "收购", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想收购那家快要关门的饭店。", "target_word": "收购", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司收购了三家小店，生意更大了。", "target_word": "收购", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国家在各地收购棉花，再卖给工厂。", "target_word": "收购", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们从各个村子收购蔬菜，送到城里。", "target_word": "收购", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那家企业收购过很多外国公司。", "target_word": "收购", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板打算收购隔壁的服装店。", "target_word": "收购", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店从农民手里收购水果，再卖给客人。", "target_word": "收购", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司正在收购一家小网站。", "target_word": "收购", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "收购了", "label": "完成体"}, {"form": "收购过", "label": "经验体"}, {"form": "收购价", "label": "复合词"}, {"form": "收購", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从各处买进农副产品、物品或企业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73f8ce2d-5317-42df-bc29-59888134a3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87404, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "收购", "is_correct": true, "explanation": "正确。收购指大量买进企业或物品，与“大公司”“一家小工厂”相符。"}, {"text": "养", "is_correct": false, "explanation": "搭配：“养”搭配动植物，工厂不能被养。"}, {"text": "喂", "is_correct": false, "explanation": "配价：“喂”的对象要有生命，小工厂不能被喂。"}, {"text": "生", "is_correct": false, "explanation": "语义：“生”指生育或产出，“生了一家小工厂”说不通。"}], "explanations": {"收购": "正确。收购指大量买进企业或物品，与“大公司”“一家小工厂”相符。", "养": "搭配：“养”搭配动植物，工厂不能被养。", "喂": "配价：“喂”的对象要有生命，小工厂不能被喂。", "生": "语义：“生”指生育或产出，“生了一家小工厂”说不通。"}, "sentence_index": 0, "correct_answer": "收购"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在菜市场收购了一个西瓜。", "explanation": "这里应该用〈买〉。收购是大量从各处买进，只买一个西瓜不用收购。"}, {"text": "老师收购了全班的作业。", "explanation": "这里应该用〈收齐〉。收购是买进，作业是学生交上来的，不是买来的。"}, {"text": "他用钱收购了证人。", "explanation": "这里应该用〈收买〉。收购指买进东西或企业，用钱拉拢人要用收买，不能说收购证人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87404, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "收购", "is_correct": true, "explanation": "正确。收购指大量买进企业或物品，与“那家企业”“很多外国公司”相符。"}, {"text": "雇", "is_correct": false, "explanation": "配价：“雇”的对象要是人，外国公司不能被雇。"}, {"text": "教", "is_correct": false, "explanation": "配价：“教”的对象要是人，不能说教公司。"}, {"text": "修", "is_correct": false, "explanation": "语义：公司不能被修理，“修过很多外国公司”说不通。"}], "explanations": {"收购": "正确。收购指大量买进企业或物品，与“那家企业”“很多外国公司”相符。", "雇": "配价：“雇”的对象要是人，外国公司不能被雇。", "教": "配价：“教”的对象要是人，不能说教公司。", "修": "语义：公司不能被修理，“修过很多外国公司”说不通。"}, "sentence_index": 6, "correct_answer": "收购"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我收购了一份礼物。", "explanation": "这里应该用〈收到〉。收购是买进，收到是接受别人送来的东西，礼物不是买来的。"}, {"text": "他收购了一下行李。", "explanation": "这里应该用〈收拾〉。收购是买进，不表示整理，行李不能用买进的方式处理。"}, {"text": "姐姐在柜子里收购了照片。", "explanation": "这里应该用〈找到〉。收购是买进，在柜子里找回照片不能用收购。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87404, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家大公司今年收购了过两家小饭店。", "corrected_sentence": "这家大公司今年收购过两家小饭店。", "error_description": "错误：“收购了过”。“了”与“过”不能同用，表示有过这种经历只用“过”，去掉“了”。正确：“这家大公司今年收购过两家小饭店。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87404, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家公司正在收购了一家小商店。", "corrected_sentence": "这家公司正在收购一家小商店。", "error_description": "错误：“正在……了”。“正在”表示进行中，与“了”不能同用，“收购”前不加“了”。正确：“正在收购一家小商店”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
