INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87405, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每年是一年一年，年年都这样。", "primary_collocate": null, "pronunciation": "měi nián", "ipa": "meɪ˨˩˦ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "每年过年，全家人都在一起吃饭。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年生日，妈妈都给我做面条。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们每年都在这家店吃月饼。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年这个时候，天气都很热。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每年都种一些花。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年考试前，他都很紧张。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里每年六月都会下大雨。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每年都说要减肥。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每年都去看一次牙医。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年国庆节，街上都很热闹。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "时间词，强调年年如此、每年都重复同样的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf41015-8ec0-4664-ad3d-be3fa4f8add0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87405, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每年", "is_correct": true, "explanation": "每年：指年年都这样，与“过年”的年度周期一致。"}, {"text": "每月", "is_correct": false, "explanation": "语义：过年是一年一度的节日，“每月”的周期与之冲突。"}, {"text": "每周", "is_correct": false, "explanation": "语义：“每周”表示每星期，与过年的年度周期冲突。"}, {"text": "一年", "is_correct": false, "explanation": "搭配：“一年”是数量，不能与“过年”搭配表示重复。"}], "explanations": {"每年": "每年：指年年都这样，与“过年”的年度周期一致。", "每月": "语义：过年是一年一度的节日，“每月”的周期与之冲突。", "每周": "语义：“每周”表示每星期，与过年的年度周期冲突。", "一年": "搭配：“一年”是数量，不能与“过年”搭配表示重复。"}, "sentence_index": 0, "correct_answer": "每年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每年都去一次洗手间。", "explanation": "这里应该用〈每天〉。去洗手间是日常的事，按年计算不合常理。"}, {"text": "这座桥每年建成于一九八八年。", "explanation": "这里应删去〈每年〉。“建成”只发生一次，与具体年份“一九八八年”冲突，应直接说“这座桥建成于一九八八年”。"}, {"text": "我每年都要洗一次手。", "explanation": "这里应该用〈每天〉。洗手是每天都要做很多次的事，按年计算不合常理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87405, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每年", "is_correct": true, "explanation": "每年：指每一年，与“六月”搭配，表示每年六月都下大雨。"}, {"text": "每晚", "is_correct": false, "explanation": "语义：“每晚”指夜里，与“六月”这个月份冲突。"}, {"text": "每日", "is_correct": false, "explanation": "搭配：“每日”指每天，不能修饰“六月”这样的月份。"}, {"text": "每秒", "is_correct": false, "explanation": "语义：“每秒”的时间单位太短，无法指一个月。"}], "explanations": {"每年": "每年：指每一年，与“六月”搭配，表示每年六月都下大雨。", "每晚": "语义：“每晚”指夜里，与“六月”这个月份冲突。", "每日": "搭配：“每日”指每天，不能修饰“六月”这样的月份。", "每秒": "语义：“每秒”的时间单位太短，无法指一个月。"}, "sentence_index": 6, "correct_answer": "每年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每年都要刷一次牙。", "explanation": "这里应该用〈每天〉。刷牙是日常习惯，按年计算不合常理。"}, {"text": "我们每年都要吃一次早饭。", "explanation": "这里应该用〈每天〉。早饭是每天都吃的，按年计算不合常理。"}, {"text": "我每年都要看一次时间。", "explanation": "这里应该用〈每分钟〉。看时间是随时都会做的事，按年计算不合常理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87405, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们2019年每年都去海边玩。", "corrected_sentence": "我们每年都去海边玩。", "error_description": "错误：“每年”与具体年份“2019年”不能同时使用。“每年”指年年反复，“2019年”指某一个年份。正确：去掉“2019年”，说“我们每年都去海边玩。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87405, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每年偶尔都给奶奶写一封信。", "corrected_sentence": "我每年都给奶奶写一封信。", "error_description": "错误：“偶尔”与“每年都”表示的频率相冲突：“偶尔”指不经常，“每年都”指年年都做。正确：去掉“偶尔”，说“我每年都给奶奶写一封信。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
