INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87406, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87406, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "每一年；年年。", "primary_collocate": null, "pronunciation": "měi nián", "ipa": "meɪ˨˩˦ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "每年春天，我们都去爬山。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每年给奶奶寄一张卡片。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家每年都去海边玩。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年冬天，这里都下很多雪。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每年读二十本书。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司每年开一次大会。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年夏天，我都回老家看爸妈。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市每年有很多游客来。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每年九月，新生都来学校报到。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每年都给自己买一件新衣服。", "target_word": "每年", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "时间词，指每一个年份，作时间状语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf41015-8ec0-4664-ad3d-be3fa4f8add0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87406, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每年", "is_correct": true, "explanation": "每年：指每一年，与“春天”搭配，表示每年春天都去爬山。"}, {"text": "每月", "is_correct": false, "explanation": "语义：“每月”指每个月，与“春天”这个季节时段冲突。"}, {"text": "每周", "is_correct": false, "explanation": "语义：“每周”指每星期，与“春天”这个季节时段冲突。"}, {"text": "一年", "is_correct": false, "explanation": "搭配：“一年”表示一个年度的数量，不能与“都”表示反复发生的意思搭配。"}], "explanations": {"每年": "每年：指每一年，与“春天”搭配，表示每年春天都去爬山。", "每月": "语义：“每月”指每个月，与“春天”这个季节时段冲突。", "每周": "语义：“每周”指每星期，与“春天”这个季节时段冲突。", "一年": "搭配：“一年”表示一个年度的数量，不能与“都”表示反复发生的意思搭配。"}, "sentence_index": 0, "correct_answer": "每年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每年都要吃三顿饭。", "explanation": "这里应该用〈每天〉。三顿饭按天计算，“每年”指一年一次，与日常饮食的周期不合。"}, {"text": "他每年出生在北京。", "explanation": "这里应该用〈那一年〉或具体年份。“每年”表示年年反复，“出生”只发生一次，二者的时间概念相冲突。"}, {"text": "心脏每年跳动七十多次。", "explanation": "这里应该用〈每分钟〉。心跳按分钟计算，“每年”的周期太长，与常识不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87406, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每年", "is_correct": true, "explanation": "每年：指每一年，与“夏天”“都”搭配，表示每年夏天都回老家。"}, {"text": "每晚", "is_correct": false, "explanation": "语义：“每晚”指夜里，与“夏天”不属于同一时段。"}, {"text": "每日", "is_correct": false, "explanation": "搭配：“每日”表示每天，不能修饰“夏天”这样的季节。"}, {"text": "每秒", "is_correct": false, "explanation": "语义：“每秒”的时间单位太短，无法指整个夏天。"}], "explanations": {"每年": "每年：指每一年，与“夏天”“都”搭配，表示每年夏天都回老家。", "每晚": "语义：“每晚”指夜里，与“夏天”不属于同一时段。", "每日": "搭配：“每日”表示每天，不能修饰“夏天”这样的季节。", "每秒": "语义：“每秒”的时间单位太短，无法指整个夏天。"}, "sentence_index": 6, "correct_answer": "每年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每年都要喝一杯水。", "explanation": "这里应该用〈每小时〉或〈每天〉。喝水要按小时或按天安排，“每年”的周期太长，与日常饮水不合。"}, {"text": "他每年都要洗一次头。", "explanation": "这里应该用〈每天〉。洗头是日常的事，按年计算不合常理。"}, {"text": "他每年都要呼吸一次。", "explanation": "这里应该用〈每分钟〉。呼吸按分钟计算，“每年”的周期过长，与生理常识不合。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87406, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每年去一年海边。", "corrected_sentence": "我们每年去一次海边。", "error_description": "错误：“一年”表示时段，不能表示动作的次数；与“每年”搭配计算去海边的次数时应用量词“次”。正确：把“一年”改为“一次”，说“我们每年去一次海边。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87406, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我每年夏天都偶尔回一次老家看外婆。", "corrected_sentence": "我每年夏天都回一次老家看外婆。", "error_description": "错误：“偶尔”与“每年夏天都”表示的频率相冲突：“偶尔”指不经常，“每年夏天都”指每年夏天都做。正确：去掉“偶尔”，说“我每年夏天都回一次老家看外婆。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
