INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87407, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "自己所在地以外的别的地方。", "primary_collocate": null, "pronunciation": "wài dì", "ipa": "wai̯˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "我不是本地人，是从外地来的。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在外地工作，很少回家。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外地的朋友给我寄了一些水果。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店有很多外地客人。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春节时，外地的人都回家了。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去外地看看大山。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王的女儿在外地上大学。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外地的天气和这里不一样。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说话有外地口音。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我要去外地见一个老朋友。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外地人", "label": "复合"}], "register": "中性", "sense_fingerprint": "外地：自己所在地以外的别的地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1eb026d-f55f-4628-a2a2-eaf33fe1d183') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87407, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外地", "is_correct": true, "explanation": "正确。“外地”指本地以外的地方，与“我不是本地人，是从……来的”的语境吻合。"}, {"text": "报纸", "is_correct": false, "explanation": "搭配：人不能从“报纸”来，表示来源的地点不能是报纸。"}, {"text": "篮球", "is_correct": false, "explanation": "搭配：“篮球”不能作“来”的起点，说“从篮球来”不通。"}, {"text": "语文", "is_correct": false, "explanation": "语义：“语文”是学科名称，不是来源地，与句中“本地人”的语境相矛盾。"}], "explanations": {"外地": "正确。“外地”指本地以外的地方，与“我不是本地人，是从……来的”的语境吻合。", "报纸": "搭配：人不能从“报纸”来，表示来源的地点不能是报纸。", "篮球": "搭配：“篮球”不能作“来”的起点，说“从篮球来”不通。", "语文": "语义：“语文”是学科名称，不是来源地，与句中“本地人”的语境相矛盾。"}, "sentence_index": 0, "correct_answer": "外地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去外地留学三年。", "explanation": "这里应该用〈外国〉。外地指国内本地以外的地方，出国留学要用〈外国〉。"}, {"text": "他是外地人，祖籍在美国。", "explanation": "这里应该用〈外国人〉。外地人指国内其他地方的人，美国人要说〈外国人〉。"}, {"text": "他大学毕业后就去外地定居了，再也没回过中国。", "explanation": "这里应该用〈国外〉。外地指国内本地以外的地方，定居后再也没回过中国，说明去的是国外，要说〈国外〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87407, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外地", "is_correct": true, "explanation": "正确。“外地”指本地以外的地方，与“小王的女儿在……上大学”的语境相符。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：“黑板”不是可以上大学的地点，与句意明显矛盾。"}, {"text": "午饭", "is_correct": false, "explanation": "搭配：“午饭”不能作“上大学”的场所，说“在午饭上大学”搭配不当。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”不是学校或学习的地点，与“上大学”的语境相矛盾。"}], "explanations": {"外地": "正确。“外地”指本地以外的地方，与“小王的女儿在……上大学”的语境相符。", "黑板": "语义：“黑板”不是可以上大学的地点，与句意明显矛盾。", "午饭": "搭配：“午饭”不能作“上大学”的场所，说“在午饭上大学”搭配不当。", "冰箱": "语义：“冰箱”不是学校或学习的地点，与“上大学”的语境相矛盾。"}, "sentence_index": 6, "correct_answer": "外地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家店的货物都从外地进口。", "explanation": "这里应该用〈国外〉。进口的货物来自国外，外地指国内其他地方，要说〈国外〉。"}, {"text": "他去外地留学，要先办理签证。", "explanation": "这里应该用〈海外〉。留学办签证是为出国，外地指国内其他地方，要说〈海外〉。"}, {"text": "这位外地教师来自英国。", "explanation": "这里应该用〈外籍〉。外地指国内其他地方，来自英国的教师要说〈外籍〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87407, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹外地来看我。", "corrected_sentence": "我妹妹从外地来看我。", "error_description": "错误：缺少介词“从”。表示起点时应说“从外地来”，“外地”前要加“从”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87407, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个城市有很多外地。", "corrected_sentence": "这个城市有很多外地人。", "error_description": "错误：“外地”本身指地方，不能直接表示“很多人”。要说“外地人”，用“人”来指人。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
