INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87408, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "本地以外的地方。", "primary_collocate": null, "pronunciation": "wài dì", "ipa": "wai̯˥˩ ti˥˩", "syllable_count": 2, "sentences": [{"text": "外地车不能进这条路。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多学生从外地来这里上学。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他常去外地出差，一个月只在家住几天。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外地游客喜欢来这里买茶叶。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在外地生活，要学会照顾自己。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种菜本地没有，要从外地运来。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外地学生可以住学校的宿舍。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的手机在外地也能用。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她嫁到了外地，一年回来一次。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "给外地打电话，要先打区号。", "target_word": "外地", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外地人", "label": "复合"}], "register": "中性", "sense_fingerprint": "外地：与本地相对，本地以外的地区", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd1eb026d-f55f-4628-a2a2-eaf33fe1d183') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87408, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外地", "is_correct": true, "explanation": "正确。“外地”指本地以外的地方，修饰“车”表示外来的车，符合句意。"}, {"text": "数学", "is_correct": false, "explanation": "语义：“数学”是学科，不是车的类别，无法修饰“车”构成有意义的说法。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“星期”是时间单位，不能作为车的类别，句意不通。"}, {"text": "微笑", "is_correct": false, "explanation": "搭配：“微笑”不能直接修饰“车”来表示一类车，搭配不当。"}], "explanations": {"外地": "正确。“外地”指本地以外的地方，修饰“车”表示外来的车，符合句意。", "数学": "语义：“数学”是学科，不是车的类别，无法修饰“车”构成有意义的说法。", "星期": "语义：“星期”是时间单位，不能作为车的类别，句意不通。", "微笑": "搭配：“微笑”不能直接修饰“车”来表示一类车，搭配不当。"}, "sentence_index": 0, "correct_answer": "外地"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子在外地玩，别让他走远。", "explanation": "这里应该用〈外面〉。外地指本地以外、距离较远的地方，孩子在附近玩要说〈外面〉。"}, {"text": "我们不能把配方告诉外地。", "explanation": "这里应该用〈外人〉。外地是地方，不能作为“告诉”的对象；配方要保密，告诉的对象是人，应说〈外人〉。"}, {"text": "我的外地在南方，那里很潮湿。", "explanation": "这里应该用〈家乡〉。外地泛指本地以外的地方，不能当作自己出生长大的地方来说，要说〈家乡〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87408, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外地", "is_correct": true, "explanation": "正确。“外地”指本地以外的地方，与“学生可以住学校的宿舍”的语境相符。"}, {"text": "走读", "is_correct": false, "explanation": "语义：“走读”指每天通勤上下学的学生，与“住学校的宿舍”的语境矛盾。"}, {"text": "粉笔", "is_correct": false, "explanation": "搭配：“粉笔”不能修饰“学生”表示类别，说“粉笔学生”搭配不当。"}, {"text": "海鲜", "is_correct": false, "explanation": "搭配：“海鲜”不能修饰“学生”表示类别，句子不通。"}], "explanations": {"外地": "正确。“外地”指本地以外的地方，与“学生可以住学校的宿舍”的语境相符。", "走读": "语义：“走读”指每天通勤上下学的学生，与“住学校的宿舍”的语境矛盾。", "粉笔": "搭配：“粉笔”不能修饰“学生”表示类别，说“粉笔学生”搭配不当。", "海鲜": "搭配：“海鲜”不能修饰“学生”表示类别，句子不通。"}, "sentence_index": 6, "correct_answer": "外地"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他坐在外地，一起看电影。", "explanation": "这里应该用〈旁边〉。外地指本地以外的地方，不能用来表示身边的位置，要说〈旁边〉。"}, {"text": "这种茶叶产自外地的日本。", "explanation": "这里应该用〈国外〉。外地指国内本地以外的地方，日本不在国内，要说〈国外〉。"}, {"text": "超市就在外地，走两分钟就到。", "explanation": "这里应该用〈附近〉。外地指本地以外、离得较远的地方，走两分钟就到的地方要说〈附近〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87408, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我妹妹外地读书，很少回家。", "corrected_sentence": "我妹妹在外地读书，很少回家。", "error_description": "错误：缺少介词“在”。表示地点时应说“在外地读书”，“外地”前要加“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87408, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他明天外地出差，下周才回来。", "corrected_sentence": "他明天去外地出差，下周才回来。", "error_description": "错误：缺少动词“去”。“外地”是地点，不能直接接“出差”，应说“去外地出差”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7ad1484d-216c-4b7f-b82e-57b8044a9490') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87410, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "物质生活", "is_correct": true, "explanation": "反义：“物质生活”指衣食住行等物质方面的生活，与“精神生活”相对。"}, {"text": "电脑", "is_correct": false, "explanation": "电脑是电子设备，与“精神生活”没有反义关系。"}, {"text": "海洋", "is_correct": false, "explanation": "海洋是地理事物，与“精神生活”没有反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "石头是矿物，与“精神生活”没有反义关系。"}], "correct_answer": "物质生活", "explanations": {"物质生活": "反义：“物质生活”指衣食住行等物质方面的生活，与“精神生活”相对。", "电脑": "电脑是电子设备，与“精神生活”没有反义关系。", "海洋": "海洋是地理事物，与“精神生活”没有反义关系。", "石头": "石头是矿物，与“精神生活”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87410, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "物质生活", "is_correct": true, "explanation": "反义：“物质生活”指衣食住行等物质方面的生活，与“精神生活”相对。"}, {"text": "钢琴", "is_correct": false, "explanation": "钢琴是乐器，与“精神生活”没有反义关系。"}, {"text": "森林", "is_correct": false, "explanation": "森林是地理事物，与“精神生活”没有反义关系。"}, {"text": "桌子", "is_correct": false, "explanation": "桌子是家具，与“精神生活”没有反义关系。"}], "correct_answer": "物质生活", "explanations": {"物质生活": "反义：“物质生活”指衣食住行等物质方面的生活，与“精神生活”相对。", "钢琴": "钢琴是乐器，与“精神生活”没有反义关系。", "森林": "森林是地理事物，与“精神生活”没有反义关系。", "桌子": "桌子是家具，与“精神生活”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87410, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人在思想、感情、文化等方面的生活。", "primary_collocate": null, "pronunciation": "jīng shén shēng huó", "ipa": "tɕiŋ˥ ʂən˧˥ ʂɤŋ˥ xuo˧˥", "syllable_count": 4, "sentences": [{"text": "人除了吃饭穿衣，还需要精神生活。", "target_word": "精神生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人退休以后，精神生活变得更重要。", "target_word": "精神生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的精神生活很丰富。", "target_word": "精神生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他有钱，可是精神生活很空虚。", "target_word": "精神生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校常常办活动，让学生有更好的精神生活。", "target_word": "精神生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农村人的物质生活好了，也想要精神生活。", "target_word": "精神生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们不能只看钱，也要关心精神生活。", "target_word": "精神生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作太忙，他没有时间想自己的精神生活。", "target_word": "精神生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家发展了，大家的精神生活也要跟上。", "target_word": "精神生活", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子长大了，精神生活比以前复杂了。", "target_word": "精神生活", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "精神生活：人在思想、感情、文化方面的生活", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dac0efc-fc80-403b-ae86-f40de6bf3e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87410, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精神生活", "is_correct": true, "explanation": "正确：“还需要精神生活”与“除了吃饭穿衣”形成并列，指思想、文化方面的需要。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不是人的生活需要，“还需要石头”句意不通。"}, {"text": "钉子", "is_correct": false, "explanation": "语义：钉子是金属小件，不是人在吃饭穿衣之外还需要的生活内容，句意不通。"}, {"text": "垃圾", "is_correct": false, "explanation": "语义：垃圾是人需要清除的东西，不是人需要的生活内容。"}], "explanations": {"精神生活": "正确：“还需要精神生活”与“除了吃饭穿衣”形成并列，指思想、文化方面的需要。", "石头": "语义：石头不是人的生活需要，“还需要石头”句意不通。", "钉子": "语义：钉子是金属小件，不是人在吃饭穿衣之外还需要的生活内容，句意不通。", "垃圾": "语义：垃圾是人需要清除的东西，不是人需要的生活内容。"}, "sentence_index": 0, "correct_answer": "精神生活"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早睡早起，这把精神生活很规律。", "explanation": "这里应该用〈种〉。“把”用于有柄或可握的东西，不能用于抽象的生活。"}, {"text": "他找到了一条精神生活，过得很充实。", "explanation": "这里应该用〈种〉。“条”用于细长的东西，不能用于抽象的生活。"}, {"text": "她家里有一块精神生活，很平静。", "explanation": "这里应该用〈种〉。“块”用于成块的东西，不能用于抽象的生活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87410, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精神生活", "is_correct": true, "explanation": "正确：“不能只看钱，也要关心”的宾语应是与钱相对的内容，即精神生活。"}, {"text": "钱", "is_correct": false, "explanation": "搭配：前文已有“只看钱”，再说“关心钱”与句意矛盾，搭配不当。"}, {"text": "脚印", "is_correct": false, "explanation": "语义：脚印是痕迹，不是人应该“关心”的对象。"}, {"text": "螺丝", "is_correct": false, "explanation": "语义：螺丝是零件，人不会“关心”它，句意不通。"}], "explanations": {"精神生活": "正确：“不能只看钱，也要关心”的宾语应是与钱相对的内容，即精神生活。", "钱": "搭配：前文已有“只看钱”，再说“关心钱”与句意矛盾，搭配不当。", "脚印": "语义：脚印是痕迹，不是人应该“关心”的对象。", "螺丝": "语义：螺丝是零件，人不会“关心”它，句意不通。"}, "sentence_index": 6, "correct_answer": "精神生活"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的精神生活安排得很满，每天都有会议。", "explanation": "这里应该用〈日程〉。“精神生活”指思想、文化方面的生活，安排时间表要用“日程”。"}, {"text": "班里有一张精神生活，大家都很喜欢。", "explanation": "这里应该用〈种〉。“张”用于平面的东西，不能用于抽象的生活。"}, {"text": "这个小镇有一座精神生活，很多人都来看。", "explanation": "这里应该用〈种〉。“座”用于山、房屋等大型固定的东西，不能用于抽象的生活。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87410, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她过着一朵很充实的精神生活。", "corrected_sentence": "她过着一种很充实的精神生活。", "error_description": "量词错误：“精神生活”是抽象名词，不能用量词“朵”（“朵”用于花、云等），应说“一种精神生活”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87410, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这位作家过着一张很丰富的精神生活。", "corrected_sentence": "这位作家过着一种很丰富的精神生活。", "error_description": "量词错误：“精神生活”是抽象名词，不能用量词“张”（“张”用于平面的东西），应说“一种精神生活”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
