INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87411, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "观点是一个人心里对一件事的想法。", "primary_collocate": null, "pronunciation": "guān diǎn", "ipa": "kuan˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "我想听听你的观点。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的观点跟我一样。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友说了他的观点，我觉得很对。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你对这件事有什么观点？", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈听了我的观点，笑了。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个人都有自己的观点。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我改变了对工作的观点。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不爱说话，很少说出自己的观点。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个观点我以前没想过。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的观点有时候很特别。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "一个人心里对一件事的想法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf41015-8ec0-4664-ad3d-be3fa4f8add0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87411, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "观点", "is_correct": true, "explanation": "观点：想法，与“听听你的”搭配，表示想听你的想法。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是色彩，不是想法，不能用“听听”来询问。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”是人的体形，不能用“听听”来询问。"}, {"text": "形状", "is_correct": false, "explanation": "语义：“形状”是物体的外形，不能用“听听”来询问。"}], "explanations": {"观点": "观点：想法，与“听听你的”搭配，表示想听你的想法。", "颜色": "语义：“颜色”是色彩，不是想法，不能用“听听”来询问。", "身高": "语义：“身高”是人的体形，不能用“听听”来询问。", "形状": "语义：“形状”是物体的外形，不能用“听听”来询问。"}, "sentence_index": 0, "correct_answer": "观点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的天气让我的观点很舒服。", "explanation": "这里应该用〈感觉〉。“舒服”形容身体或感受，观点是想法，不能让人觉得舒服。"}, {"text": "我借了一本观点。", "explanation": "观点应该用量词〈个〉或〈种〉，“本”用于书籍，不用于观点。"}, {"text": "这个观点很重，我搬不动。", "explanation": "这里误把〈观点〉当成了〈物品〉。“重”和“搬不动”针对有重量的实物，观点是抽象的想法，没有重量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87411, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "观点", "is_correct": true, "explanation": "观点：对工作的看法，与“改变了对……的”搭配。"}, {"text": "体重", "is_correct": false, "explanation": "语义：“体重”是身体的重量，不是对工作的想法。"}, {"text": "面积", "is_correct": false, "explanation": "语义：“面积”指平面的大小，不能说“对工作的面积”。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“尺寸”不用于抽象事物或想法。"}], "explanations": {"观点": "观点：对工作的看法，与“改变了对……的”搭配。", "体重": "语义：“体重”是身体的重量，不是对工作的想法。", "面积": "语义：“面积”指平面的大小，不能说“对工作的面积”。", "尺寸": "搭配：“尺寸”不用于抽象事物或想法。"}, "sentence_index": 6, "correct_answer": "观点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他骑着一个观点去了学校。", "explanation": "这里误把〈观点〉当成了〈车〉。观点是想法，不能被骑，“骑着”只能用于交通工具。"}, {"text": "这个观点的生日是三月。", "explanation": "这里误把〈观点〉当成了〈人〉。生日只属于人或有生命的事物，想法没有生日，不能说“生日是三月”。"}, {"text": "他一口吃掉了这个观点。", "explanation": "“吃掉”用于食物，观点不能被吃，动词与“观点”搭配不当。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87411, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一本很特别的观点。", "corrected_sentence": "他有一个很特别的观点。", "error_description": "错误：观点的量词用了“本”。正确：应为“个”，“本”用于书籍。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87411, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我很赞成你观点。", "corrected_sentence": "我很赞成你的观点。", "error_description": "错误：“你”与“观点”之间漏掉了领属标记“的”。正确：应为“你的观点”，领属语与中心语之间要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
