INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87412, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从某一立场或角度出发，对事物所持的看法。", "primary_collocate": null, "pronunciation": "guān diǎn", "ipa": "kuan˥ tjɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "站在不同的立场，人们的观点也不同。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从经济的角度看，这个观点有道理。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "作者在文章中提出了一个新观点。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家们的观点很不一致。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这篇报告的观点十分明确。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不赞成这种观点。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的观点代表了公司的立场。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会上，双方都说明了自己的观点。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学者们对历史问题有不同的观点。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用数据支持自己的观点。", "target_word": "观点", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "种", "label": "量词"}], "register": "中性", "sense_fingerprint": "从某立场或角度出发所持的看法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf41015-8ec0-4664-ad3d-be3fa4f8add0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87412, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "观点", "is_correct": true, "explanation": "观点：从立场出发的看法，与“站在不同的立场”呼应，表示人们看法不同。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指商品的价钱，与“人们的”看法无关。"}, {"text": "尺寸", "is_correct": false, "explanation": "搭配：“尺寸”多指物品的大小，不用来说人们在看法上的差别。"}, {"text": "面积", "is_correct": false, "explanation": "语义：“面积”指平面的大小，与“人们的”看法无关。"}], "explanations": {"观点": "观点：从立场出发的看法，与“站在不同的立场”呼应，表示人们看法不同。", "价格": "语义：“价格”指商品的价钱，与“人们的”看法无关。", "尺寸": "搭配：“尺寸”多指物品的大小，不用来说人们在看法上的差别。", "面积": "语义：“面积”指平面的大小，与“人们的”看法无关。"}, "sentence_index": 0, "correct_answer": "观点"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个观点跑得很快，我追不上。", "explanation": "这里误把〈观点〉当成了〈动物〉或〈人〉。“跑得很快”“追不上”用于会移动的事物，观点是抽象的看法，不会跑。"}, {"text": "他把那个观点装进了箱子里。", "explanation": "这里误把〈观点〉当成了〈物品〉。“装进箱子”要求具体的实物，观点是抽象的看法，不能被装。"}, {"text": "他提出了一本观点。", "explanation": "观点应该用量词〈个〉或〈种〉，“本”一般用于书籍，不用于观点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87412, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "观点", "is_correct": true, "explanation": "观点：看法，与“代表了公司的立场”相符。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”指人的身体高度，不能代表公司的立场。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是事物的色彩，不能代表立场。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”是报酬，不能说“代表……立场”。"}], "explanations": {"观点": "观点：看法，与“代表了公司的立场”相符。", "身高": "语义：“身高”指人的身体高度，不能代表公司的立场。", "颜色": "语义：“颜色”是事物的色彩，不能代表立场。", "工资": "搭配：“工资”是报酬，不能说“代表……立场”。"}, "sentence_index": 6, "correct_answer": "观点"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的观点很咸，我吃不下。", "explanation": "这里误把〈观点〉当成了〈食物〉。“咸”形容食物的味道，观点是看法，没有味道。"}, {"text": "这个观点的颜色很鲜艳。", "explanation": "这里误把〈观点〉当成了〈物品〉。“颜色鲜艳”只能形容具体的实物，观点是抽象的看法，没有颜色。"}, {"text": "这个观点很合身。", "explanation": "“合身”用于衣服，观点不能用“合身”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87412, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这篇文章提出了一本新观点，很有说服力。", "corrected_sentence": "这篇文章提出了一个新观点，很有说服力。", "error_description": "错误：观点的量词用了“本”。正确：应为“个”，“本”用于书籍。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87412, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我观点。", "corrected_sentence": "这是我的观点。", "error_description": "错误：“我”与“观点”之间漏掉了领属标记“的”。正确：应为“我的观点”，领属语与中心语之间要用“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
