INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87414, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以七天为一周期的时间单位；也指其中的某一天。", "primary_collocate": null, "pronunciation": "xīng qī", "ipa": "ɕiŋ˥ tɕʰi˥", "syllable_count": 2, "sentences": [{"text": "一个星期有七天。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每个星期去两次健身房。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下个星期我要去北京。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个星期的天气很好。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他上星期生病了。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每星期给妈妈打电话。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在这里住了两个星期。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个星期我们每天都有汉语课。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过了一个星期，他才回家。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们下个星期就放假了。", "target_word": "星期", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "星期天", "label": "复合词"}, {"form": "上星期", "label": "复合词"}, {"form": "下星期", "label": "复合词"}], "register": "中性", "sense_fingerprint": "七天为一周期的时间单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '934308b8-5ea3-4b86-bc2c-3ae9d4ecc7fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87414, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "星期", "is_correct": true, "explanation": "正确答案：星期（xīngqī），以七天为一周期的时间单位。"}, {"text": "兴起", "is_correct": false, "explanation": "xīng 相同，第二音节 qǐ（第三声）与 qī（第一声）声调不同，意思是“兴起、开始流行”。"}, {"text": "刑期", "is_correct": false, "explanation": "第一音节 xíng（第二声）与 xīng（第一声）声调不同，qī 相同，意思是“服刑的时间”。"}, {"text": "腥气", "is_correct": false, "explanation": "第一音节相同，第二音节 qì（第四声）与 qī（第一声）声调不同，意思是“腥味”。"}, {"text": "经期", "is_correct": false, "explanation": "jīng 与 xīng 声母不同，qī 相同，意思是“月经期”。"}], "explanations": {"星期": "正确答案：星期（xīngqī），以七天为一周期的时间单位。", "兴起": "xīng 相同，第二音节 qǐ（第三声）与 qī（第一声）声调不同，意思是“兴起、开始流行”。", "刑期": "第一音节 xíng（第二声）与 xīng（第一声）声调不同，qī 相同，意思是“服刑的时间”。", "腥气": "第一音节相同，第二音节 qì（第四声）与 qī（第一声）声调不同，意思是“腥味”。", "经期": "jīng 与 xīng 声母不同，qī 相同，意思是“月经期”。"}, "sentence_index": null, "correct_answer": "星期"}, "level_3": {"options": [{"text": "星期", "is_correct": true, "explanation": "正确答案：“星期”指以七天为一周期的时间单位，“一个星期有七天”成立。"}, {"text": "小时", "is_correct": false, "explanation": "语义：小时比星期短得多，“一个小时有七天”与常识不符。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：夜晚是一天中的时段，不可能包含七天。"}, {"text": "月份", "is_correct": false, "explanation": "搭配：“一个月份”不这样说，且“月份”指具体的某一个月，不能包含七天。"}], "explanations": {"星期": "正确答案：“星期”指以七天为一周期的时间单位，“一个星期有七天”成立。", "小时": "语义：小时比星期短得多，“一个小时有七天”与常识不符。", "夜晚": "语义：夜晚是一天中的时段，不可能包含七天。", "月份": "搭配：“一个月份”不这样说，且“月份”指具体的某一个月，不能包含七天。"}, "sentence_index": 0, "correct_answer": "星期"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这只星期我很忙。", "explanation": "这里应该用“个”：这个星期。“只”用于动物或成对、单个的物品，不用来修饰表示时间段的“星期”。"}, {"text": "我们过了一次星期，很开心。", "explanation": "这里应该用“个”：一个星期。“次”用于动作或事件的次数，不用来计量一段时间。"}, {"text": "我在这里住了两个星期天。", "explanation": "这里表示一段时间。“星期天”指周日这一天，只能表示“一周中的某一天”，不能计量时长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e465b488-5baf-4d5d-8d0c-f048f967da82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87414, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "星期", "is_correct": true, "explanation": "正确答案：“两个星期”表示一段时间，与“住了”的时长相符。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：“椅子”是家具，不是时间，不能表示住了多长时间。"}, {"text": "时刻", "is_correct": false, "explanation": "搭配：“时刻”指某一个时间点，不与“两个”连用来表示时长。"}, {"text": "角落", "is_correct": false, "explanation": "语义：“角落”是地方，不是时间，不能用来计量住的时长。"}], "explanations": {"星期": "正确答案：“两个星期”表示一段时间，与“住了”的时长相符。", "椅子": "语义：“椅子”是家具，不是时间，不能表示住了多长时间。", "时刻": "搭配：“时刻”指某一个时间点，不与“两个”连用来表示时长。", "角落": "语义：“角落”是地方，不是时间，不能用来计量住的时长。"}, "sentence_index": 6, "correct_answer": "星期"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们下条星期就放假了。", "explanation": "量词错误：“条”用于细长的东西，不用来修饰“星期”。应说“下个星期”。"}, {"text": "我们放假前在这里过了一桩星期。", "explanation": "这里应该用“个”：一个星期。“桩”用于事情或事件，不用来计量“星期”。"}, {"text": "我们放假前已经过了一朵星期。", "explanation": "量词错误：“朵”用于花、云等，不用来计量“星期”。应说“一个星期”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e465b488-5baf-4d5d-8d0c-f048f967da82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87414, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学了两只星期汉语。", "corrected_sentence": "我们学了两个星期汉语。", "error_description": "量词错误：“星期”前应用量词“个”，不能用“只”。应改为“两个星期”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e465b488-5baf-4d5d-8d0c-f048f967da82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87414, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹在上海住了三本星期。", "corrected_sentence": "我妹妹在上海住了三个星期。", "error_description": "量词错误：“星期”前应用量词“个”，不能用“本”（“本”用于书本等）。应改为“三个星期”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e465b488-5baf-4d5d-8d0c-f048f967da82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
