INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87415, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "外水是做完正事以外，多得到的钱。", "primary_collocate": null, "pronunciation": "wài shuǐ", "ipa": "waɪ˥˩ ʂweɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "他白天上班，晚上开车，赚点外水。", "target_word": "外水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做完正事，他还靠帮人修电脑挣外水。", "target_word": "外水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张手巧，每个月都有一笔外水。", "target_word": "外水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这点外水不多，只够买菜了。", "target_word": "外水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她下班后做手工，挣了不少外水。", "target_word": "外水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不想只靠外水过日子。", "target_word": "外水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这笔外水，他全给孩子交了学费。", "target_word": "外水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "忙完正事，他靠卖菜赚外水。", "target_word": "外水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你下班后做小生意，有外水吗？", "target_word": "外水", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他靠周末教书拿到一些外水。", "target_word": "外水", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "做完正事之外多挣的钱", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '63e4ab29-410c-4d06-aa49-0654232e82a9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87415, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外水", "is_correct": true, "explanation": "正确：“赚点”后接的是钱，指做正事以外多挣的钱。"}, {"text": "电脑", "is_correct": false, "explanation": "搭配：“赚点”后接的是钱款，不能说“赚点电脑”。"}, {"text": "体温", "is_correct": false, "explanation": "语义：体温是身体的温度，不是可以赚取的东西。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“赚”的对象是钱，不能说“赚点天气”。"}], "explanations": {"外水": "正确：“赚点”后接的是钱，指做正事以外多挣的钱。", "电脑": "搭配：“赚点”后接的是钱款，不能说“赚点电脑”。", "体温": "语义：体温是身体的温度，不是可以赚取的东西。", "天气": "搭配：“赚”的对象是钱，不能说“赚点天气”。"}, "sentence_index": 0, "correct_answer": "外水"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司每月给他发两千块外水。", "explanation": "这里应该用〈补贴〉。外水是做完正事以外自己挣来的钱，公司每月固定发放的补贴不属于外水。"}, {"text": "他的基本外水是每月三千块。", "explanation": "这里应该用〈工资〉。“基本”后接的是工资，外水指做正事以外多挣的钱，不能作为固定的基本收入。"}, {"text": "年底公司发了一笔外水，大家都很高兴。", "explanation": "这里应该用〈奖金〉。奖金是本职工作的报酬，外水指做正事以外多挣的钱，不能用来指公司发的奖金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87415, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外水", "is_correct": true, "explanation": "正确：外水是他挣来的一笔钱，“这笔”和“交了学费”都指向钱款。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：脾气不是钱款，不能用来交学费。"}, {"text": "房间", "is_correct": false, "explanation": "搭配：“这笔”用于款项，不能说“这笔房间”。"}, {"text": "箱子", "is_correct": false, "explanation": "搭配：“这笔”和“交学费”都针对钱款，不能说“这笔箱子”。"}], "explanations": {"外水": "正确：外水是他挣来的一笔钱，“这笔”和“交了学费”都指向钱款。", "脾气": "语义：脾气不是钱款，不能用来交学费。", "房间": "搭配：“这笔”用于款项，不能说“这笔房间”。", "箱子": "搭配：“这笔”和“交学费”都针对钱款，不能说“这笔箱子”。"}, "sentence_index": 6, "correct_answer": "外水"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的外水每月三千，是他的固定收入。", "explanation": "这里应该用〈底薪〉。外水指做正事以外多挣的钱，不是固定的正式收入。"}, {"text": "他因为迟到被扣了一笔外水。", "explanation": "这里应该用〈罚款〉。外水是自己挣来的钱，不是能被扣掉的款项。"}, {"text": "他向朋友借了一笔外水，说好下月还。", "explanation": "这里应该用〈借款〉。外水是做完正事以外多挣的钱，借来的钱不是挣来的，不能说成外水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87415, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他下班以后做点零活，每月挣一只外水。", "corrected_sentence": "他下班以后做点零活，每月挣一笔外水。", "error_description": "量词错误：“外水”是一笔钱，应说“一笔外水”，不能说“一只外水”。“只”多用于动物或成对器物中的一件，不用于钱款。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87415, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他靠周末教书挣了到一些外水。", "corrected_sentence": "他靠周末教书挣到了一些外水。", "error_description": "补语错误：“到”是“挣”的补语，应紧跟动词说“挣到了”，“了”不能插在“挣”和“到”之间。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe2411fb-f81f-4ec6-96d9-dfb4f7804e08') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
