INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87420, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "指十五六岁到三十岁左右的人。", "primary_collocate": null, "pronunciation": "qīng nián", "ipa": "tɕʰiŋ˥ njɛn˧˥", "syllable_count": 2, "sentences": [{"text": "这个青年今年二十五岁。", "target_word": "青年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公园里有很多青年在跑步。", "target_word": "青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "青年们周末常常一起打球。", "target_word": "青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是个爱读书的青年。", "target_word": "青年", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那位青年向老人问了路。", "target_word": "青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司愿意给青年更多机会。", "target_word": "青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "现在的青年大多会用手机买东西。", "target_word": "青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "三十岁以前的青年都可以参加比赛。", "target_word": "青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "几个青年站在门口等朋友。", "target_word": "青年", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校请来了一位有名的青年作家。", "target_word": "青年", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位青年", "label": "量词"}, {"form": "一名青年", "label": "量词"}, {"form": "青年人", "label": "复合词"}, {"form": "青年节", "label": "复合词"}], "register": "中性", "sense_fingerprint": "十五六岁到三十岁左右的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73f8ce2d-5317-42df-bc29-59888134a3e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87420, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "青年", "is_correct": true, "explanation": "正确。青年指十五六岁到三十岁左右的人，与“这个”“今年二十五岁”相符。"}, {"text": "老人", "is_correct": false, "explanation": "语义：老人的年龄通常远超二十五岁，与“今年二十五岁”冲突。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：小学生不会是二十五岁，与年龄冲突。"}, {"text": "老年", "is_correct": false, "explanation": "搭配：“老年”指年龄阶段，不能用“这个”来指人。"}], "explanations": {"青年": "正确。青年指十五六岁到三十岁左右的人，与“这个”“今年二十五岁”相符。", "老人": "语义：老人的年龄通常远超二十五岁，与“今年二十五岁”冲突。", "小学生": "语义：小学生不会是二十五岁，与年龄冲突。", "老年": "搭配：“老年”指年龄阶段，不能用“这个”来指人。"}, "sentence_index": 0, "correct_answer": "青年"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是个十二岁的青年。", "explanation": "这里应该用〈少年〉。青年指十五六岁到三十岁左右的人，十二岁不在这个年龄范围。"}, {"text": "那位青年已经八十岁了。", "explanation": "这里应该用〈老人〉。青年指年轻人，八十岁的人不能叫青年。"}, {"text": "我叔叔四十五岁了，还是个青年。", "explanation": "这里应该用〈中年人〉。青年指十五六岁到三十岁左右的人，四十五岁属于中年，不能叫青年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87420, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "青年", "is_correct": true, "explanation": "正确。青年指十五六岁到三十岁左右的人，与“现在的”“用手机买东西”相符。"}, {"text": "古人", "is_correct": false, "explanation": "语义：古人不会用手机，与“现在的”冲突。"}, {"text": "猫", "is_correct": false, "explanation": "配价：“买东西”要求人做主语，猫不能用手机买东西。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“买东西”要求人做主语，石头不能用手机买东西。"}], "explanations": {"青年": "正确。青年指十五六岁到三十岁左右的人，与“现在的”“用手机买东西”相符。", "古人": "语义：古人不会用手机，与“现在的”冲突。", "猫": "配价：“买东西”要求人做主语，猫不能用手机买东西。", "石头": "配价：“买东西”要求人做主语，石头不能用手机买东西。"}, "sentence_index": 6, "correct_answer": "青年"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "刚出生的孩子是个青年。", "explanation": "这里应该用〈婴儿〉。青年指十五六岁到三十岁左右的人，刚出生的孩子是婴儿。"}, {"text": "他刚上小学，还是个青年。", "explanation": "这里应该用〈儿童〉。刚上小学的孩子只有六七岁，不在青年的年龄范围内。"}, {"text": "这位老教授六十岁了，还是个青年。", "explanation": "这里应该用〈老年人〉。青年指十五六岁到三十岁左右的人，六十岁属于老年人，不能叫青年。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87420, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口站着一只青年。", "corrected_sentence": "门口站着一个青年。", "error_description": "错误：“一只青年”。“只”用于动物或小件物品，指人应该用“个”。正确：“一个青年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87420, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "几个青年们在公园里散步。", "corrected_sentence": "几个青年在公园里散步。", "error_description": "错误：“几个青年们”。“们”不能和数词连用，应为“几个青年”。正确：“几个青年在公园里散步”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '18c456ca-a08c-4110-b317-e50a36c7e08a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
