INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87421, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "function", "definition": "历史上是说在过去很久很久的时候。", "primary_collocate": null, "pronunciation": "lì shǐ shàng", "ipa": "li˥˩ ʂʅ˨˩˦ ʂɑŋ˥˩", "syllable_count": 3, "sentences": [{"text": "历史上，这里曾经有一片大海。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上人们用石头做刀。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，这条河常常发大水。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上这个地方住过很多人。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，人们靠马来送信。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥在历史上修过三次。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上这里下过一场很大的雪。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上，茶叶从中国卖到了很多国家。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史上这个国家有过两个名字。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个村子历史上很穷。", "target_word": "历史上", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "歷史上", "label": "繁体"}], "register": "书面", "sense_fingerprint": "历史上：时间状语，指很久很久以前的过去", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1493551b-beb8-436c-890d-5f7aa674fb8b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87421, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "历史上", "is_correct": true, "explanation": "历史上：指很久很久以前的过去，正合“曾经有一片大海”。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指刚发生的事，与“曾经”说的久远过去相矛盾。"}, {"text": "马上", "is_correct": false, "explanation": "语义：“马上”指很快要发生，与“曾经有过”的过去相矛盾。"}, {"text": "正在", "is_correct": false, "explanation": "搭配：“正在”表示进行中，不能与“曾经有”这种已经完成的经历搭配。"}], "explanations": {"历史上": "历史上：指很久很久以前的过去，正合“曾经有一片大海”。", "刚刚": "语义：“刚刚”指刚发生的事，与“曾经”说的久远过去相矛盾。", "马上": "语义：“马上”指很快要发生，与“曾经有过”的过去相矛盾。", "正在": "搭配：“正在”表示进行中，不能与“曾经有”这种已经完成的经历搭配。"}, "sentence_index": 0, "correct_answer": "历史上"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我历史上在这家公司工作过。", "explanation": "这里应该用〈以前〉。历史上指很久远的过去、整个历史，个人经历要用以前。"}, {"text": "昨天历史上我去了超市。", "explanation": "历史上只指很久远的过去，不能指昨天这样的近期时间；这里应去掉“历史上”，直接说“昨天我去了超市”。"}, {"text": "历史上这里将会建一座大桥。", "explanation": "这里应该用〈将来〉。历史上只指过去，不能用来说将要进行的建设计划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87421, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "历史上", "is_correct": true, "explanation": "历史上：指很久很久以前的过去，正合“下过一场很大的雪”这样的过去经历。"}, {"text": "一直", "is_correct": false, "explanation": "搭配：“一直”表示持续，不能与“下过一场很大的雪”这种一次性的事搭配。"}, {"text": "永远", "is_correct": false, "explanation": "语义：“永远”指没有终点，与“下过一场很大的雪”这种一次性事件相矛盾。"}, {"text": "特别", "is_correct": false, "explanation": "搭配：“特别”修饰形容词或表示程度，不能修饰“下过”这样的动作。"}], "explanations": {"历史上": "历史上：指很久很久以前的过去，正合“下过一场很大的雪”这样的过去经历。", "一直": "搭配：“一直”表示持续，不能与“下过一场很大的雪”这种一次性的事搭配。", "永远": "语义：“永远”指没有终点，与“下过一场很大的雪”这种一次性事件相矛盾。", "特别": "搭配：“特别”修饰形容词或表示程度，不能修饰“下过”这样的动作。"}, "sentence_index": 6, "correct_answer": "历史上"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "历史上我每周都去游泳。", "explanation": "这里应该用〈以往〉。历史上指历史长河中的事，个人的习惯要用以往。"}, {"text": "历史上我正在写作业。", "explanation": "这里应该用〈现在〉。历史上指很久以前的过去，描述此刻正在进行的动作要用现在。"}, {"text": "历史上我们要去北京旅游。", "explanation": "这里应该用〈将来〉。历史上只指过去，不能用来说将要进行的计划。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87421, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座岛历史上的曾经长满了森林。", "corrected_sentence": "这座岛历史上曾经长满了森林。", "error_description": "错误形式：“历史上的曾经”；正确形式：“历史上曾经”。“的”不能接在“历史上”后面，再接副词“曾经”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87421, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "历史上了这个城市下过一场很大的雪。", "corrected_sentence": "历史上这个城市下过一场很大的雪。", "error_description": "错误形式：“历史上了这个城市”；正确形式：“历史上这个城市”。“历史上”作时间状语，后面不能加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9933c33a-bcba-4800-8359-2188b184abc0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
