INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87423, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "外语是别的国家的人说的话。我们要学才能听懂。", "primary_collocate": null, "pronunciation": "wài yǔ", "ipa": "wai˥˩ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "我在学校学外语。", "target_word": "外语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说的是外语，我听不懂。", "target_word": "外语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我在国外旅游，听不懂当地人说的外语。", "target_word": "外语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈不会说外语。", "target_word": "外语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "你想学哪一门外语？", "target_word": "外语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我每天晚上花一小时学外语。", "target_word": "外语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看电影可以帮我练习外语。", "target_word": "外语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的外语说得很好，像外国人一样。", "target_word": "外语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "到了国外，我才发现外语很重要。", "target_word": "外语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟用手机学外语。", "target_word": "外语", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "一门外语", "label": "量词"}, {"form": "外语课", "label": "复合"}], "register": "中性", "sense_fingerprint": "别的国家的人说的话，要学才能听懂", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4848e3-df86-4870-9771-0c70385a07a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87423, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外语", "is_correct": true, "explanation": "“学外语”指学习外国人说的语言，外语作“学”的宾语，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“学”的宾语应是知识或技能，空气不能学。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不是可以学习的内容。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是实物，不能作为“学”的学习对象，句子不通。"}], "explanations": {"外语": "“学外语”指学习外国人说的语言，外语作“学”的宾语，符合句意。", "空气": "搭配：“学”的宾语应是知识或技能，空气不能学。", "天气": "语义：天气是自然现象，不是可以学习的内容。", "冰箱": "语义：冰箱是实物，不能作为“学”的学习对象，句子不通。"}, "sentence_index": 0, "correct_answer": "外语"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他去银行把人民币换成了外语。", "explanation": "这里应该用〈外汇〉。外语是语言，不是钱；把人民币换成外币，要说“外汇”或“外币”，不能说“换成外语”。"}, {"text": "我想去外语留学。", "explanation": "这里应该用〈外国〉。外语是语言，不是地方，“去……留学”要说地点，应为“去外国留学”。"}, {"text": "我把外语放进了书包里。", "explanation": "这里应该用〈外语书〉。外语是语言，不是实物，不能放进书包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87423, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外语", "is_correct": true, "explanation": "“练习外语”指练习这门语言，符合句意。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“练习”的对象是技能或知识，窗户不能被练习。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视是播放节目的机器，不是可以练习的对象。"}, {"text": "茶叶", "is_correct": false, "explanation": "搭配：“练习”后接的是知识或技能，茶叶不能作练习对象。"}], "explanations": {"外语": "“练习外语”指练习这门语言，符合句意。", "窗户": "搭配：“练习”的对象是技能或知识，窗户不能被练习。", "电视": "语义：电视是播放节目的机器，不是可以练习的对象。", "茶叶": "搭配：“练习”后接的是知识或技能，茶叶不能作练习对象。"}, "sentence_index": 6, "correct_answer": "外语"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我是北京人，我的外语是汉语。", "explanation": "这里应该用〈母语〉。北京人从小说的汉语是母语，“外语”只指别国的语言。"}, {"text": "学校里新来了很多外语。", "explanation": "这里应该用〈外国人〉。外语是语言，不能指人，“来了很多”要说外国人。"}, {"text": "我的表哥是一名外语，每天在公司里翻译文件。", "explanation": "这里应该用〈译员〉。外语是语言，不能指人或职业；表示从事翻译工作的人要说“译员”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87423, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我大学时学了三本外语。", "corrected_sentence": "我大学时学了三门外语。", "error_description": "量词错误：“外语”应用量词“门”，“本”用于书籍等，不用于语言。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87423, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我会说一条外语，可以翻译合同。", "corrected_sentence": "我会说一门外语，可以翻译合同。", "error_description": "量词错误：“外语”应用量词“门”，“条”用于细长的东西，不能用于语言。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87424, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "母语", "is_correct": true, "explanation": "正确：“母语”指本国语言，与“外语”相对。"}, {"text": "窗户", "is_correct": false, "explanation": "与“外语”没有反义关系，“窗户”指房屋的开口。"}, {"text": "白天", "is_correct": false, "explanation": "与“外语”没有反义关系，“白天”指一天中的白昼时间。"}, {"text": "石头", "is_correct": false, "explanation": "与“外语”没有反义关系，“石头”指岩石的小块。"}], "correct_answer": "母语", "explanations": {"母语": "正确：“母语”指本国语言，与“外语”相对。", "窗户": "与“外语”没有反义关系，“窗户”指房屋的开口。", "白天": "与“外语”没有反义关系，“白天”指一天中的白昼时间。", "石头": "与“外语”没有反义关系，“石头”指岩石的小块。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87424, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "母语", "is_correct": true, "explanation": "正确：“母语”指本国语言，与“外语”相对。"}, {"text": "椅子", "is_correct": false, "explanation": "与“外语”没有反义关系，“椅子”指坐具。"}, {"text": "海洋", "is_correct": false, "explanation": "与“外语”没有反义关系，“海洋”指大片的咸水区域。"}, {"text": "树叶", "is_correct": false, "explanation": "与“外语”没有反义关系，“树叶”指树木的叶子。"}], "correct_answer": "母语", "explanations": {"母语": "正确：“母语”指本国语言，与“外语”相对。", "椅子": "与“外语”没有反义关系，“椅子”指坐具。", "海洋": "与“外语”没有反义关系，“海洋”指大片的咸水区域。", "树叶": "与“外语”没有反义关系，“树叶”指树木的叶子。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87424, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "外国的语言。", "primary_collocate": null, "pronunciation": "wài yǔ", "ipa": "wai˥˩ y˨˩˦", "syllable_count": 2, "sentences": [{"text": "学好一门外语需要很长时间。", "target_word": "外语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "除了母语，他还会说三种外语。", "target_word": "外语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们学校从三年级开始教外语。", "target_word": "外语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的外语水平很高，常常帮同事翻译。", "target_word": "外语", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学外语最重要的是多听多说。", "target_word": "外语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "英语是很多学生的第一门外语。", "target_word": "外语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家公司想找会外语的人。", "target_word": "外语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他从小就喜欢学外语。", "target_word": "外语", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在国外工作，会一门外语很有用。", "target_word": "外语", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我买了一本学外语的书。", "target_word": "外语", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一门外语", "label": "量词"}, {"form": "外语课", "label": "复合"}], "register": "中性", "sense_fingerprint": "外国的语言", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9c4848e3-df86-4870-9771-0c70385a07a2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87424, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外语", "is_correct": true, "explanation": "正确：“外语”是可以学习的语言，“学好一门外语”句意通顺。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：“一门”只用于学科、技艺，不能说“学好一门水果”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不是可以学习的内容，句子不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能被“学好”，与句意不符。"}], "explanations": {"外语": "正确：“外语”是可以学习的语言，“学好一门外语”句意通顺。", "水果": "搭配：“一门”只用于学科、技艺，不能说“学好一门水果”。", "房子": "语义：房子不是可以学习的内容，句子不通。", "汽车": "语义：汽车不能被“学好”，与句意不符。"}, "sentence_index": 0, "correct_answer": "外语"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班里来了一位外语。", "explanation": "这里应该用〈外国人〉。外语指语言，不指人。"}, {"text": "我们暑假去外语旅游。", "explanation": "这里应该用〈外国〉。外语指语言，不指地方。"}, {"text": "他手里有很多外语。", "explanation": "这里应该用〈外币〉。外语指语言，不能指钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87424, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外语", "is_correct": true, "explanation": "正确：“会外语”指能说、能用外国语言，符合招聘语境。"}, {"text": "木材", "is_correct": false, "explanation": "语义：“会木材”不是一种能力，句子不通。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是可以“会”的技能。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“会”后接技能、语言，不说“会天空”。"}], "explanations": {"外语": "正确：“会外语”指能说、能用外国语言，符合招聘语境。", "木材": "语义：“会木材”不是一种能力，句子不通。", "冰箱": "语义：冰箱是家电，不是可以“会”的技能。", "天空": "搭配：“会”后接技能、语言，不说“会天空”。"}, "sentence_index": 6, "correct_answer": "外语"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他会说一只外语。", "explanation": "这里应该用〈门〉。外语是学科，量词用“门”，“只”不用于语言。"}, {"text": "她学了一条外语，很努力。", "explanation": "这里应该用〈门〉。“条”用于细长的东西，外语应该用“门”。"}, {"text": "我们学了一张外语。", "explanation": "这里应该用〈门〉。“张”用于纸张、桌子等平面的东西，外语应该用“门”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87424, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个学期我们要学两本外语。", "corrected_sentence": "这个学期我们要学两门外语。", "error_description": "“外语”作为学科要用量词“门”，应说“两门外语”；“本”用于书籍，不能用于外语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87424, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他每天花一个小时学一本外语。", "corrected_sentence": "他每天花一个小时学外语。", "error_description": "量词错误：“一本”用于书籍，不能用于语言；“外语”前不加量词“本”，应去掉“一本”，说“学外语”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f0a60b13-703b-4e62-85a9-0f05821c45f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
