INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87425, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "级长是管一个年级的老师或学生头头。", "primary_collocate": null, "pronunciation": "jí zhǎng", "ipa": "tɕi˧˥ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我们的级长是一位很严的老师。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "级长今天要开会，学生都来了。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是三年级的级长，同学都听他的。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师选他当级长，他很高兴。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "级长请大家明天早点儿到学校。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次考试的事，你可以去问级长。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学习好，又爱帮助同学，所以当了级长。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "级长把作业本发给每个同学。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长管一个班，级长管整个年级。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "级长今天没来，别的老师来帮忙。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "级长：管一个年级的老师或学生头头", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dac0efc-fc80-403b-ae86-f40de6bf3e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87425, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "级长", "is_correct": true, "explanation": "正确：级长管一个年级，是老师或学生头头，与“很严的老师”相符。"}, {"text": "班长", "is_correct": false, "explanation": "语义：班长管的是一个班，是学生干部，不能是“很严的老师”。"}, {"text": "学校", "is_correct": false, "explanation": "语义：“学校”不是老师，不能说“我们的学校是一位很严的老师”。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生是受教育的人，不能被说成“很严的老师”。"}], "explanations": {"级长": "正确：级长管一个年级，是老师或学生头头，与“很严的老师”相符。", "班长": "语义：班长管的是一个班，是学生干部，不能是“很严的老师”。", "学校": "语义：“学校”不是老师，不能说“我们的学校是一位很严的老师”。", "学生": "语义：学生是受教育的人，不能被说成“很严的老师”。"}, "sentence_index": 0, "correct_answer": "级长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这学期，级长只管我们班的同学。", "explanation": "这里应该用〈班长〉。班长管一个班，级长管整个年级，不能说“只管我们班的同学”。"}, {"text": "级长在全校大会上讲话，希望大家努力学习。", "explanation": "这里应该用〈校长〉。全校大会由校长讲话，级长只管一个年级。"}, {"text": "级长负责组织全校的文艺活动。", "explanation": "这里应该用〈学生会主席〉。全校的文艺活动由学生会主席组织，级长只管一个年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87425, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "级长", "is_correct": true, "explanation": "正确：级长是年级里的老师或学生头头，句中“学习好、爱帮助同学”的人适合当。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：小偷是偷东西的人，与“爱帮助同学”矛盾。"}, {"text": "北京", "is_correct": false, "explanation": "搭配：“当了”后接身份或职务，不能接地名“北京”。"}, {"text": "坏人", "is_correct": false, "explanation": "语义：坏人与“爱帮助同学”矛盾，句子说的是好学生。"}], "explanations": {"级长": "正确：级长是年级里的老师或学生头头，句中“学习好、爱帮助同学”的人适合当。", "小偷": "语义：小偷是偷东西的人，与“爱帮助同学”矛盾。", "北京": "搭配：“当了”后接身份或职务，不能接地名“北京”。", "坏人": "语义：坏人与“爱帮助同学”矛盾，句子说的是好学生。"}, "sentence_index": 6, "correct_answer": "级长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "级长每天管好自己班的每个同学，很辛苦。", "explanation": "这里应该用〈班主任〉。班主任管一个班，级长管整个年级，不能只管自己班的同学。"}, {"text": "级长负责全校的水电维修，每天都很忙。", "explanation": "这里应该用〈后勤主任〉。全校的水电维修由后勤主任负责，级长只管一个年级。"}, {"text": "级长负责组织全校的运动会，大家都很期待。", "explanation": "这里应该用〈体育老师〉。全校运动会由体育老师组织，级长只管一个年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87425, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校新来了一只级长，负责高一的事。", "corrected_sentence": "学校新来了一位级长，负责高一的事。", "error_description": "量词错误：“只”用于动物，指人应用“位”或“个”，正确说法是“一位级长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87425, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她是一条很有经验的级长。", "corrected_sentence": "她是一位很有经验的级长。", "error_description": "量词错误：“条”用于细长的东西，指人应用“位”或“个”，正确说法是“一位很有经验的级长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
