INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87426, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "学校中负责管理一个年级事务的人。", "primary_collocate": null, "pronunciation": "jí zhǎng", "ipa": "tɕi˧˥ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "级长负责管理全年级的事。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请王老师做二年级的级长。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生有问题，可以先找级长。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "级长每周都要和老师开会。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当级长已经两年了，对学校很熟。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开学的时候，级长给大家讲了新规定。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的级长很忙，要管一个年级的事。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长希望级长多关心学生的生活。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把这张表交给你们年级的级长。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一年级的级长今天来教室看同学。", "target_word": "级长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "级长：学校里负责管理一个年级事务的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1dac0efc-fc80-403b-ae86-f40de6bf3e10') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87426, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "级长", "is_correct": true, "explanation": "正确：级长管理一个年级的事，与“全年级”的范围相合。"}, {"text": "班长", "is_correct": false, "explanation": "语义：班长只管一个班，与“全年级”的范围矛盾。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“负责管理”的主语应是人，不能是“教室”。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：厨师与“管理全年级的事”毫无关系。"}], "explanations": {"级长": "正确：级长管理一个年级的事，与“全年级”的范围相合。", "班长": "语义：班长只管一个班，与“全年级”的范围矛盾。", "教室": "搭配：“负责管理”的主语应是人，不能是“教室”。", "厨师": "语义：厨师与“管理全年级的事”毫无关系。"}, "sentence_index": 0, "correct_answer": "级长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "级长负责我们班的值日安排。", "explanation": "这里应该用〈班长〉。班长管一个班，级长管整个年级，不能只安排一个班的值日。"}, {"text": "级长每年都要做学校的工作报告。", "explanation": "这里应该用〈校长〉。学校的工作报告由校长做，级长只管一个年级。"}, {"text": "级长负责全校的课程安排。", "explanation": "这里应该用〈教导主任〉。全校的课程安排由教导主任负责，级长只管一个年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87426, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "级长", "is_correct": true, "explanation": "正确：级长要管一个年级的事，与“很忙”相符。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生是受教育的人，不能管一个年级的事。"}, {"text": "墙", "is_correct": false, "explanation": "搭配：“很忙”和“管事”都要求人，不能用“墙”。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房与“管一个年级的事”毫无关系。"}], "explanations": {"级长": "正确：级长要管一个年级的事，与“很忙”相符。", "学生": "语义：学生是受教育的人，不能管一个年级的事。", "墙": "搭配：“很忙”和“管事”都要求人，不能用“墙”。", "厨房": "语义：厨房与“管一个年级的事”毫无关系。"}, "sentence_index": 6, "correct_answer": "级长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "级长每天检查自己班的作业，很辛苦。", "explanation": "这里应该用〈班主任〉。检查班里作业由班主任负责，级长管整个年级，不能只检查一个班。"}, {"text": "级长负责全校的食堂管理，每天都很忙。", "explanation": "这里应该用〈后勤主任〉。全校食堂管理由后勤主任负责，级长只管一个年级。"}, {"text": "级长负责组织全校的文艺活动，大家都很期待。", "explanation": "这里应该用〈学生会主席〉。全校文艺活动由学生会主席组织，级长只管一个年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87426, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "新学期，我们年级换了一只级长。", "corrected_sentence": "新学期，我们年级换了一位级长。", "error_description": "量词错误：“只”用于动物，指人应用“位”或“个”，正确说法是“一位级长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87426, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "姐姐以前是一台级长，很会组织活动。", "corrected_sentence": "姐姐以前是一位级长，很会组织活动。", "error_description": "量词错误：“台”用于机器，指人应用“位”或“个”，正确说法是“一位级长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '690cc4fd-58f2-443c-92c6-b9f3c286a0f1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
