INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87427, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "action", "definition": "体育是跑步、打球这些让身体变好的活动。", "primary_collocate": null, "pronunciation": "tǐ yù", "ipa": "tʰi˨˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "我喜欢体育，常常跑步。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爱好体育，每天打篮球。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体育让我们的身体更好。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多参加体育，身体会越来越好。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就喜欢体育，最爱打篮球。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸最关心的是体育。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家人都喜欢体育。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不爱体育，只爱读书。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他什么体育都喜欢，最爱游泳。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟爱体育，一有空就去踢球。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "體育", "label": "繁体"}], "register": "中性", "sense_fingerprint": "体育：跑步、打球等锻炼身体的运动活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7286d9a-03f3-4664-99b4-2712ee008241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87427, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体育", "is_correct": true, "explanation": "正确：“喜欢体育”指喜欢体育活动，与“常常跑步”相符。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：感冒是疾病，不是喜欢的对象，与“喜欢”矛盾。"}, {"text": "账单", "is_correct": false, "explanation": "搭配：“喜欢”一般不接“账单”，搭配不当。"}, {"text": "胃病", "is_correct": false, "explanation": "语义：胃病是疾病，不能作为喜欢的对象。"}], "explanations": {"体育": "正确：“喜欢体育”指喜欢体育活动，与“常常跑步”相符。", "感冒": "语义：感冒是疾病，不是喜欢的对象，与“喜欢”矛盾。", "账单": "搭配：“喜欢”一般不接“账单”，搭配不当。", "胃病": "语义：胃病是疾病，不能作为喜欢的对象。"}, "sentence_index": 0, "correct_answer": "体育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他跑了十公里，体育还很充沛。", "explanation": "这里应该用〈体力〉。“充沛”形容体力，体育是锻炼活动，不能说“体育充沛”。"}, {"text": "他的体育很强壮，能举起一百公斤。", "explanation": "这里应该用〈身体〉。“体育”指锻炼活动，不指身体；“强壮”形容身体。"}, {"text": "他每天在体育跑步，身体很好。", "explanation": "这里应该用〈操场〉。“体育”指运动活动，不能作跑步的场所。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87427, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体育", "is_correct": true, "explanation": "正确：“我们家人都喜欢体育”指家人喜欢体育活动，语义通顺。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒是病原体，不是人喜欢的对象。"}, {"text": "车祸", "is_correct": false, "explanation": "语义：车祸是意外事故，不能被喜欢。"}, {"text": "噪音", "is_correct": false, "explanation": "搭配：“喜欢”一般不接“噪音”，应说“讨厌”。"}], "explanations": {"体育": "正确：“我们家人都喜欢体育”指家人喜欢体育活动，语义通顺。", "病毒": "语义：病毒是病原体，不是人喜欢的对象。", "车祸": "语义：车祸是意外事故，不能被喜欢。", "噪音": "搭配：“喜欢”一般不接“噪音”，应说“讨厌”。"}, "sentence_index": 6, "correct_answer": "体育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位体育很热情，经常帮助同学。", "explanation": "这里应该用〈老师〉。“体育”指运动活动，不指人。"}, {"text": "这本体育很厚，我看不完。", "explanation": "这里应该用〈体育书〉。“体育”指运动，不指书籍。"}, {"text": "他每天把体育存进银行。", "explanation": "这里应该用〈钱〉。“体育”指运动活动，不能存进银行。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87427, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他非常体育，每天都跑步。", "corrected_sentence": "他非常爱体育，每天都跑步。", "error_description": "错误：“体育”是名词，不能直接受“非常”修饰，要加动词，说“非常爱体育”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87427, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家人都很体育。", "corrected_sentence": "我们家人都很爱体育。", "error_description": "错误：“体育”是名词，不能直接受“很”修饰，要加动词，说“很爱体育”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
