INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87428, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "学校里以锻炼身体、增强体质为目的的课程。", "primary_collocate": null, "pronunciation": "tǐ yù", "ipa": "tʰi˨˩ y˥˩", "syllable_count": 2, "sentences": [{"text": "今天下午第一节是体育。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校每周有两节体育。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体育是学校的一门重要课程。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的体育成绩很好。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要求每个学生都要上体育。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上体育的时候，我们在操场上跑步。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，今天的体育改在教室里上。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他语文不好，可是体育很棒。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我最喜欢的课是体育。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把体育放在上午第二节。", "target_word": "体育", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "體育", "label": "繁体"}], "register": "中性", "sense_fingerprint": "体育：学校里以锻炼身体、增强体质为目的的课程", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7286d9a-03f3-4664-99b4-2712ee008241') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87428, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体育", "is_correct": true, "explanation": "正确：“第一节”指课时，“体育”是学校的一门课程。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：“第一节”指课时，午饭不是课程，二者矛盾。"}, {"text": "周末", "is_correct": false, "explanation": "搭配：“第一节是”后接课程名，不说“第一节是周末”。"}, {"text": "晚饭", "is_correct": false, "explanation": "语义：下午第一节是课程，晚饭在傍晚，与句意矛盾。"}], "explanations": {"体育": "正确：“第一节”指课时，“体育”是学校的一门课程。", "午饭": "语义：“第一节”指课时，午饭不是课程，二者矛盾。", "周末": "搭配：“第一节是”后接课程名，不说“第一节是周末”。", "晚饭": "语义：下午第一节是课程，晚饭在傍晚，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "体育"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们今天的体育把作业写完了。", "explanation": "这里应该用〈同学〉。“体育”是课程，不能写作业。"}, {"text": "他的体育很结实，能扛起一百斤。", "explanation": "这里应该用〈身体〉。“体育”指学校课程，不指身体；“结实”形容身体。"}, {"text": "我们的体育很严格，常常批评同学。", "explanation": "这里应该用〈体育老师〉。“批评同学”的主语应是人，“体育”是课程，不能批评人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87428, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体育", "is_correct": true, "explanation": "正确：体育课可以因下雨改在教室里上，语义通顺。"}, {"text": "比赛", "is_correct": false, "explanation": "搭配：“上”用于课程，比赛应说“进行”，不说“在教室里上”。"}, {"text": "晚会", "is_correct": false, "explanation": "搭配：晚会应说“举行”，不说“在教室里上”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是课程，不能“改在教室里上”。"}], "explanations": {"体育": "正确：体育课可以因下雨改在教室里上，语义通顺。", "比赛": "搭配：“上”用于课程，比赛应说“进行”，不说“在教室里上”。", "晚会": "搭配：晚会应说“举行”，不说“在教室里上”。", "天气": "语义：天气不是课程，不能“改在教室里上”。"}, "sentence_index": 6, "correct_answer": "体育"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们班的体育今天请假了。", "explanation": "这里应该用〈学生〉。“体育”是课程，不是人，不能请假。"}, {"text": "我们每天吃一顿体育，身体很好。", "explanation": "这里应该用〈饭〉之类的食物词。“体育”是课程，不能吃。"}, {"text": "他上个星期穿了两次体育。", "explanation": "这里应该用〈体育服〉。“体育”是课程，不能穿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87428, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每周三下午都做体育课。", "corrected_sentence": "我们每周三下午都上体育课。", "error_description": "错误：上体育课要用动词“上”，说“上体育课”；“做”不能与“体育课”搭配，“做体育课”是动词用错。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87428, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们班今天下午打体育课。", "corrected_sentence": "我们班今天下午上体育课。", "error_description": "错误：课程要用动词“上”，说“上体育课”；“打体育课”是动词用错。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3c268e86-3dc8-4d33-8266-928d516db221') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
