INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87429, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "外长是管和别的国家来往的大官。", "primary_collocate": null, "pronunciation": "wài zhǎng", "ipa": "uai˥˩ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "外长是管外交的大官。", "target_word": "外长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们国家的外长常去别的国家。", "target_word": "外长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外长要和别国的人谈两国的事。", "target_word": "外长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电视里的那位外长正在讲话。", "target_word": "外长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爸爸想当外长，所以学了外语。", "target_word": "外长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外长坐飞机去国外开会了。", "target_word": "外长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "外长每天都很忙，要见很多外国人。", "target_word": "外长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想当外长，就要先学好外语。", "target_word": "外长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻说，外长明天要去美国。", "target_word": "外长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外长和外国朋友一起吃了晚饭。", "target_word": "外长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "外長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "管和别国来往的大官", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a25abb85-5ccf-42fc-84cc-7d66d0607671') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87429, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不是官员，不能“管外交”。"}, {"text": "外长", "is_correct": true, "explanation": "正确：外长是管理与别国往来事务的大官，符合“管外交的大官”。"}, {"text": "小鸟", "is_correct": false, "explanation": "语义：小鸟是动物，不能“管外交”，也不是大官。"}, {"text": "哥们", "is_correct": false, "explanation": "语域：“哥们”是口语说法，与“大官”的正式说法不合。"}], "explanations": {"面包": "语义：面包是食物，不是官员，不能“管外交”。", "外长": "正确：外长是管理与别国往来事务的大官，符合“管外交的大官”。", "小鸟": "语义：小鸟是动物，不能“管外交”，也不是大官。", "哥们": "语域：“哥们”是口语说法，与“大官”的正式说法不合。"}, "sentence_index": 0, "correct_answer": "外长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "外长常驻在外国使馆。", "explanation": "这里应该用〈外交官〉。外长是国内的大官，不常驻外国使馆；常驻使馆的是外交官。"}, {"text": "外长在外国的使馆里工作，代表国家。", "explanation": "这里应该用〈大使〉。外长不在外国使馆工作；驻外代表国家的是大使。"}, {"text": "领事馆里的外长每天接待前来办理签证的人。", "explanation": "这里应该用〈领事〉。外长在国内管对外事务，不在领事馆接待办签证的人；这是领事的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87429, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "手表", "is_correct": false, "explanation": "语义：手表是物品，不能“要见很多外国人”。"}, {"text": "外长", "is_correct": true, "explanation": "正确：外长要与外国人打交道，所以每天很忙，要见很多外国人。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子是建筑，没有工作忙碌或见客人的行为。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜是食物，不能“要见很多外国人”。"}], "explanations": {"手表": "语义：手表是物品，不能“要见很多外国人”。", "外长": "正确：外长要与外国人打交道，所以每天很忙，要见很多外国人。", "房子": "语义：房子是建筑，没有工作忙碌或见客人的行为。", "蔬菜": "语义：蔬菜是食物，不能“要见很多外国人”。"}, "sentence_index": 6, "correct_answer": "外长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "外长站在部长旁边，把他的话翻成外语。", "explanation": "这里应该用〈翻译〉。外长自己就是部长，不做翻译工作；把别人的话翻成外语的是翻译。"}, {"text": "外长要替部长出席重要会议。", "explanation": "这里应该用〈副部长〉。外长本身就是部长，不会替部长出席会议；替部长出席的是副部长。"}, {"text": "外长每天开车送部长去上班。", "explanation": "这里应该用〈司机〉。外长是大官，不负责开车送人；开车送部长的是司机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87429, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一只外长正在美国访问。", "corrected_sentence": "一位外长正在美国访问。", "error_description": "错误：「一只外长」；正确：「一位外长」。外长指人，量词要用「位」，「只」用于动物或小东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87429, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "当外长人要学好外语。", "corrected_sentence": "当外长的人要学好外语。", "error_description": "错误：「当外长人」；正确：「当外长的人」。动词短语「当外长」修饰名词「人」时，中间必须加结构助词「的」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
