INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87430, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "外交部部长的简称，主管一国对外事务的官员。", "primary_collocate": null, "pronunciation": "wài zhǎng", "ipa": "uai˥˩ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "外长今天会见了外国客人。", "target_word": "外长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "两国外长明天在北京举行会谈。", "target_word": "外长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外长表示，两国关系越来越好。", "target_word": "外长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新任外长昨天开始访问三个国家。", "target_word": "外长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中国外长向记者介绍了会谈情况。", "target_word": "外长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国外长都来参加这次会议。", "target_word": "外长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外长在电视上回答了记者的问题。", "target_word": "外长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外长说，这件事要通过谈判解决。", "target_word": "外长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "俄罗斯外长下周将访问中国。", "target_word": "外长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位外长在外交部工作了三十年。", "target_word": "外长", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "外長", "label": "繁体"}], "register": "正式", "sense_fingerprint": "外交部部长的简称；主管对外事务的官员", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a25abb85-5ccf-42fc-84cc-7d66d0607671') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87430, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不能“会见”外国客人。"}, {"text": "外长", "is_correct": true, "explanation": "正确：外长是外交部部长，身份适合与外国客人会见。"}, {"text": "小猫", "is_correct": false, "explanation": "语义：小猫是动物，不能“会见”外国客人。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不能“会见”外国客人。"}], "explanations": {"桌子": "语义：桌子是家具，不能“会见”外国客人。", "外长": "正确：外长是外交部部长，身份适合与外国客人会见。", "小猫": "语义：小猫是动物，不能“会见”外国客人。", "书包": "语义：书包是物品，不能“会见”外国客人。"}, "sentence_index": 0, "correct_answer": "外长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "驻外的外长要学会几门外语。", "explanation": "这里应该用〈外交官〉。外长是国家外交部的部长，留在国内工作，不驻外；驻外工作、需要学外语的是外交官。"}, {"text": "外长常年驻在外国。", "explanation": "这里应该用〈大使〉。外长是国内的部长，不会常年驻在外国；常年驻守外国、代表国家的是大使。"}, {"text": "领事馆里的外长负责给护照和签证盖章。", "explanation": "这里应该用〈领事〉。外长在外交部工作，不在领事馆办理护照和签证；领事馆里负责这类手续的是领事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87430, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：窗户是建筑物的一部分，不能在电视上回答记者的问题。"}, {"text": "外长", "is_correct": true, "explanation": "正确：外长是外交部部长，可以在电视上回答记者的问题。"}, {"text": "沙发", "is_correct": false, "explanation": "语义：沙发是家具，不会回答记者的问题。"}, {"text": "蔬菜", "is_correct": false, "explanation": "语义：蔬菜是食物，不能在电视上回答记者的问题。"}], "explanations": {"窗户": "语义：窗户是建筑物的一部分，不能在电视上回答记者的问题。", "外长": "正确：外长是外交部部长，可以在电视上回答记者的问题。", "沙发": "语义：沙发是家具，不会回答记者的问题。", "蔬菜": "语义：蔬菜是食物，不能在电视上回答记者的问题。"}, "sentence_index": 6, "correct_answer": "外长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "会谈时，外长站在部长身边，把他的话翻成外语。", "explanation": "这里应该用〈翻译〉。外长本身就是部长，不做翻译；会谈时翻译话语的是翻译。"}, {"text": "外长协助部长处理日常工作。", "explanation": "这里应该用〈副部长〉。外长本身就是部长，不会去协助部长；协助部长工作的是副部长。"}, {"text": "外长拿着话筒向部长提问，然后写成新闻。", "explanation": "这里应该用〈记者〉。外长是回答问题的人；提问并写新闻的是记者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87430, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "三位外长们下周将去俄罗斯。", "corrected_sentence": "三位外长下周将去俄罗斯。", "error_description": "错误：「三位外长们」；正确：「三位外长」。已有数词「三」表示数量，名词后不能再加复数词尾「们」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87430, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只外长明天会去北京开会。", "corrected_sentence": "这位外长明天会去北京开会。", "error_description": "错误：「这只外长」；正确：「这位外长」。「只」用于动物或小东西，指人要用量词「位」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b39abac4-41a8-471c-9f79-f136dc0d8927') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
