INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87431, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87431, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "每一遍都发生，一遍也不落下，反复如此。", "primary_collocate": null, "pronunciation": "měi cì", "ipa": "meɪ˨˩˦ tsʰɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "每次下雨，他都忘记带伞。", "target_word": "每次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每次见到我，她都笑。", "target_word": "每次", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每次考试，我都很紧张。", "target_word": "每次", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "每次去北京，我都住在朋友家。", "target_word": "每次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每次做饭，爸爸都帮我洗菜。", "target_word": "每次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每次回家，妈妈都给我做鱼。", "target_word": "每次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每次他来，都带着一些水果。", "target_word": "每次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每次我问他，他都说不知道。", "target_word": "每次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每次听到这首歌，我都想起大学。", "target_word": "每次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每次下课，我们都把桌子放整齐。", "target_word": "每次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每次:一遍又一遍地重复，每一遍都发生", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '986f312e-72c3-468e-8424-eadc7ad44fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87431, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每次", "is_correct": true, "explanation": "正确：每次表示每一遍都发生，与句中的“都”呼应。"}, {"text": "突然", "is_correct": false, "explanation": "语义：突然指一次性的意外发生，与“都忘记带伞”所说的反复情形相冲突。"}, {"text": "从来", "is_correct": false, "explanation": "搭配：从来要与否定词连用，不能直接修饰“下雨”。"}, {"text": "绝对", "is_correct": false, "explanation": "搭配：绝对用于判断或语气的程度，不能修饰下雨这类自然现象。"}], "explanations": {"每次": "正确：每次表示每一遍都发生，与句中的“都”呼应。", "突然": "语义：突然指一次性的意外发生，与“都忘记带伞”所说的反复情形相冲突。", "从来": "搭配：从来要与否定词连用，不能直接修饰“下雨”。", "绝对": "搭配：绝对用于判断或语气的程度，不能修饰下雨这类自然现象。"}, "sentence_index": 0, "correct_answer": "每次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次考试，我每次都很紧张。", "explanation": "这里应删去〈每次〉。“这次考试”只指一场考试，〈每次〉指多次重复中的每一次，二者不能共用。"}, {"text": "他每次都去世了。", "explanation": "这里应删去〈每次〉。〈去世〉只会发生一次，〈每次〉要求动作能反复发生。"}, {"text": "他每次出生在北京。", "explanation": "这里应该删去〈每次〉。〈每次〉要求动作能反复发生，出生只会发生一次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87431, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每次", "is_correct": true, "explanation": "正确：每次表示每一遍都如此，与句中的“都”呼应。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：忽然指突然发生的单次事件，与“都带着一些水果”的反复情形相冲突。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：立刻表示马上发生，只指一次，与“都”所表示的每次如此不符。"}, {"text": "一下子", "is_correct": false, "explanation": "搭配：一下子多表示一次性完成或数量突增，不能与“都带着”的常规重复搭配。"}], "explanations": {"每次": "正确：每次表示每一遍都如此，与句中的“都”呼应。", "忽然": "语义：忽然指突然发生的单次事件，与“都带着一些水果”的反复情形相冲突。", "立刻": "语义：立刻表示马上发生，只指一次，与“都”所表示的每次如此不符。", "一下子": "搭配：一下子多表示一次性完成或数量突增，不能与“都带着”的常规重复搭配。"}, "sentence_index": 6, "correct_answer": "每次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每次都偶尔迟到，老师很生气。", "explanation": "这里应改用〈有时〉。〈每次〉表示每一次都发生、没有例外，〈有时〉才表示间或发生，二者不能共用。"}, {"text": "我每次都在那天回家。", "explanation": "这里应删去〈每次〉。〈那天〉指一个特定的日子，〈每次〉指多次重复，二者不能共用。"}, {"text": "每次同学都很努力。", "explanation": "这里应该用〈每个〉。〈每个〉可修饰人、物等名词，〈每次〉表示一次次的动作，不能直接修饰〈同学〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87431, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每次出生，他都先去超市买菜。", "corrected_sentence": "每次下班，他都先去超市买菜。", "error_description": "错误形式是“每次出生”，〈出生〉只会发生一次，与表示反复的〈每次〉不能搭配。正确形式是“每次下班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87431, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每次出差，都我带一本书。", "corrected_sentence": "每次出差，我都带一本书。", "error_description": "错误形式是“每次出差，都我带一本书”，“都”放在了主语“我”之前。正确形式是“每次出差，我都带一本书”，〈都〉要紧跟在主语之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
