INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87432, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87432, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "每一次；逐次，没有例外。", "primary_collocate": null, "pronunciation": "měi cì", "ipa": "meɪ˨˩˦ tsʰɹ̩˥˩", "syllable_count": 2, "sentences": [{"text": "他每次都来得很早。", "target_word": "每次", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "我们每次开会都有新问题。", "target_word": "每次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店我去了好几次，每次都排队。", "target_word": "每次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每次比赛，他都是第一名。", "target_word": "每次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她每次坐地铁都看书。", "target_word": "每次", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老师每次都先问我们累不累。", "target_word": "每次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "每次买东西，他都要看价格。", "target_word": "每次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我每次给他打电话，他都不在。", "target_word": "每次", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟每次吃饭都玩着手机。", "target_word": "每次", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每次她来这里，都把花放在窗边。", "target_word": "每次", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "每次:逐次，每一次都如此，没有例外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '986f312e-72c3-468e-8424-eadc7ad44fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87432, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "每次", "is_correct": true, "explanation": "正确：每次表示每一次都如此、没有例外，与“都”呼应。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：偶尔表示低频发生，与“都来得很早”的每次如此相冲突。"}, {"text": "一次", "is_correct": false, "explanation": "搭配：〈一次〉与〈都〉连用须带否定，如“一次都没来”，不能说“一次都来得很早”。"}, {"text": "突然", "is_correct": false, "explanation": "语义：突然指一次性的意外，与“都来得很早”所说的重复情形不符。"}], "explanations": {"每次": "正确：每次表示每一次都如此、没有例外，与“都”呼应。", "偶尔": "语义：偶尔表示低频发生，与“都来得很早”的每次如此相冲突。", "一次": "搭配：〈一次〉与〈都〉连用须带否定，如“一次都没来”，不能说“一次都来得很早”。", "突然": "语义：突然指一次性的意外，与“都来得很早”所说的重复情形不符。"}, "sentence_index": 0, "correct_answer": "每次"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天的比赛，他每次拿了第一名。", "explanation": "这里应该用〈那次〉或删去〈每次〉。〈每次〉指多次重复，句中只说昨天的一场比赛。"}, {"text": "每次比赛，他偶尔不是第一名。", "explanation": "这里应该用〈有时〉。〈每次〉表示没有例外，〈有时〉才表示间或如此、间或不如此，与“每次”的全称意义不同。"}, {"text": "比赛每次，他都是第一名。", "explanation": "这里语序错误：〈每次〉作状语须位于小句之前，不能放在名词〈比赛〉之后。正确形式是“每次比赛”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87432, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "每次", "is_correct": true, "explanation": "正确：每次表示每一次都如此，与“都要看价格”呼应。"}, {"text": "立刻", "is_correct": false, "explanation": "语义：立刻表示马上发生，只指一次，与“都要看价格”的反复情形不符。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：忽然指突然发生的单次事件，与“都要看价格”的重复语义相冲突。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：刚才指过去某一个时刻，只发生一次，与“都要看价格”的反复情形不符。"}], "explanations": {"每次": "正确：每次表示每一次都如此，与“都要看价格”呼应。", "立刻": "语义：立刻表示马上发生，只指一次，与“都要看价格”的反复情形不符。", "忽然": "语义：忽然指突然发生的单次事件，与“都要看价格”的重复语义相冲突。", "刚才": "语义：刚才指过去某一个时刻，只发生一次，与“都要看价格”的反复情形不符。"}, "sentence_index": 6, "correct_answer": "每次"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每次都在昨天回家。", "explanation": "这里应删去〈每次〉。〈昨天〉指一个特定的日子，〈每次〉指多次重复，二者不能共用。"}, {"text": "每次员工都很认真。", "explanation": "这里应该用〈每位〉。〈每位〉用于指称人，〈每次〉表示一次次的动作，不能直接修饰〈员工〉。"}, {"text": "我每次都偶尔去看电影。", "explanation": "这里应改用〈有时〉或删去〈偶尔〉。〈每次〉表示没有例外，〈偶尔〉表示很少发生，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87432, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "每次去世，我都买很多水果。", "corrected_sentence": "每次去超市，我都买很多水果。", "error_description": "错误形式是“每次去世”，〈去世〉只会发生一次，与表示反复的〈每次〉不能搭配。正确形式是“每次去超市”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87432, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "每次出生，我都先洗澡。", "corrected_sentence": "每次回家，我都先洗澡。", "error_description": "错误形式是“每次出生”，〈出生〉只会发生一次，与表示反复的〈每次〉不能搭配。正确形式是“每次回家”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87433, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87433, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87433, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "经行是从一个地方走过去。", "primary_collocate": null, "pronunciation": "jīng xíng", "ipa": "tɕiŋ˥ ɕiŋ˧˥", "syllable_count": 2, "sentences": [{"text": "旅行团明天会经行这座古老的小镇。", "target_word": "经行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车经行山区时，窗外的风景很美。", "target_word": "经行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天上班都要经行这条安静的小路。", "target_word": "经行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车队将从北门经行，再往南边去。", "target_word": "经行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们经行那座桥后，即可到达学校。", "target_word": "经行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商队经行沙漠，走了整整十天。", "target_word": "经行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客经行此处，请不要大声说话。", "target_word": "经行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公交车经行市中心，再开往火车站。", "target_word": "经行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候的商人常经行这条山路。", "target_word": "经行", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "参观的队伍缓缓经行花园门口。", "target_word": "经行", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "經行", "label": "繁体"}], "register": "书面", "sense_fingerprint": "从某地走过去、通过某处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f88939-d718-4d2d-bc4c-ca9e6f6115ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87433, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "经行", "is_correct": true, "explanation": "正确。经行读作 jīng xíng，指从某地走过去。"}, {"text": "惊醒", "is_correct": false, "explanation": "xǐng（第三声）与 xíng（第二声）声调不同，“惊醒”意思是从睡梦中醒来。"}, {"text": "精心", "is_correct": false, "explanation": "xīn 与 xíng 韵母不同（in 与 ing），声调也不同，“精心”意思是细致用心。"}, {"text": "进行", "is_correct": false, "explanation": "jìn 与 jīng 韵母不同（in 与 ing），声调也不同，“进行”意思是推进某事。"}, {"text": "警醒", "is_correct": false, "explanation": "jǐng xǐng 与 jīng xíng 两个音节的声调都不同，“警醒”意思是提高警觉。"}], "explanations": {"经行": "正确。经行读作 jīng xíng，指从某地走过去。", "惊醒": "xǐng（第三声）与 xíng（第二声）声调不同，“惊醒”意思是从睡梦中醒来。", "精心": "xīn 与 xíng 韵母不同（in 与 ing），声调也不同，“精心”意思是细致用心。", "进行": "jìn 与 jīng 韵母不同（in 与 ing），声调也不同，“进行”意思是推进某事。", "警醒": "jǐng xǐng 与 jīng xíng 两个音节的声调都不同，“警醒”意思是提高警觉。"}, "sentence_index": null, "correct_answer": "经行"}, "level_3": {"options": [{"text": "驻扎", "is_correct": false, "explanation": "搭配：“驻扎”多指军队在某地扎营，旅行团不能驻扎。"}, {"text": "经行", "is_correct": true, "explanation": "正确。经行表示从某地走过去，这里指旅行团经过这座小镇。"}, {"text": "修建", "is_correct": false, "explanation": "语义：“修建”指建造，旅行团不会去修建已经存在的古镇。"}, {"text": "占领", "is_correct": false, "explanation": "语义：“占领”指用武力夺取某地，与旅行团观光的行程不符。"}], "explanations": {"驻扎": "搭配：“驻扎”多指军队在某地扎营，旅行团不能驻扎。", "经行": "正确。经行表示从某地走过去，这里指旅行团经过这座小镇。", "修建": "语义：“修建”指建造，旅行团不会去修建已经存在的古镇。", "占领": "语义：“占领”指用武力夺取某地，与旅行团观光的行程不符。"}, "sentence_index": 0, "correct_answer": "经行"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他经行了很多困难，终于成功了。", "explanation": "这里应该用〈经历〉。经行表示从某地走过去，不能用来说经历困难；遇到困难要说“经历”。"}, {"text": "这家公司由他经行多年，业绩一直很好。", "explanation": "这里应该用〈经营〉。经行表示从某地走过去，不表示管理公司；“经营公司”才是正确说法。"}, {"text": "我们经行三次讨论，终于做出了决定。", "explanation": "这里应该用〈经过〉。经行只用于空间上的移动，不表示经历一个过程；“经过三次讨论”才是正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87433, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "拆除", "is_correct": false, "explanation": "语义：“拆除”指拆掉建筑物，游客不会去拆除此处。"}, {"text": "经行", "is_correct": true, "explanation": "正确。经行表示从某地走过去，这里指游客经过此处。"}, {"text": "开设", "is_correct": false, "explanation": "语义：“开设”指设立机构或项目，游客不会在此处开设什么。"}, {"text": "装修", "is_correct": false, "explanation": "搭配：“装修”的主体多为施工方或业主，“游客装修此处”不搭配。"}], "explanations": {"拆除": "语义：“拆除”指拆掉建筑物，游客不会去拆除此处。", "经行": "正确。经行表示从某地走过去，这里指游客经过此处。", "开设": "语义：“开设”指设立机构或项目，游客不会在此处开设什么。", "装修": "搭配：“装修”的主体多为施工方或业主，“游客装修此处”不搭配。"}, "sentence_index": 6, "correct_answer": "经行"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次会议经行得很顺利，大家都很满意。", "explanation": "这里应该用〈进行〉。“进行”表示事情的推进；经行只指从某地走过去，不能描述会议的进展。"}, {"text": "他经行了一次很大的考验。", "explanation": "这里应该用〈经受〉。“经受考验”表示承受困难；经行不表示承受考验。"}, {"text": "这份报告经行了领导的审批。", "explanation": "这里应该用〈通过〉。“通过审批”表示获得批准；经行只表示从某地走过去。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87433, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天这辆大巴将经行了市场门口，然后开往码头。", "corrected_sentence": "明天这辆大巴将经行市场门口，然后开往码头。", "error_description": "“将”表示将来，“经行”后不能再加“了”。错误在“经行”带的“了”，应去掉，改为“将经行”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87433, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这列火车经行在小镇，然后开往海边。", "corrected_sentence": "这列火车经行小镇，然后开往海边。", "error_description": "“经行”是及物动词，处所宾语应直接放在它后面，应说“经行小镇”，“经行”后不能加“在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
