INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87435, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "签署是在重要的纸上写下自己的名字，表示同意。", "primary_collocate": null, "pronunciation": "qiān shǔ", "ipa": "tɕʰi̯ɛn˥ ʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "家长需要签署这份同意书。", "target_word": "签署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校要求每位家长签署同意书。", "target_word": "签署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看完合同，就签署了。", "target_word": "签署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "租房合同上，房东和我都要签署。", "target_word": "签署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生请病人签署手术同意书。", "target_word": "签署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你签署之前，一定要认真看内容。", "target_word": "签署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在协议上签署后，交给了经理。", "target_word": "签署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新来的员工今天签署了工作合同。", "target_word": "签署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买车时，我签署了好几份文件。", "target_word": "签署", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "双方签署完协议，就握手了。", "target_word": "签署", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "签署了", "label": "体标"}, {"form": "签署过", "label": "体标"}], "register": "正式", "sense_fingerprint": "在重要的纸上写下名字，表示同意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd4e62db1-d0f4-433b-9204-45f7851b2ab7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87435, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "签署", "is_correct": true, "explanation": "正确答案：签署（qiān shǔ），在重要文件上正式签名表示同意。"}, {"text": "签收", "is_correct": false, "explanation": "签收（qiān shōu）的第二个音节韵母与签署不同（ou 与 u），意思是确认收到。"}, {"text": "前述", "is_correct": false, "explanation": "前述（qián shù）与签署（qiān shǔ）声调不同，意思是前面提到的。"}, {"text": "钱数", "is_correct": false, "explanation": "钱数（qián shù）与签署（qiān shǔ）声调不同，意思是钱的数目。"}, {"text": "签售", "is_correct": false, "explanation": "签售（qiān shòu）的第二个音节韵母与签署不同（òu 与 ǔ），意思是签名售书。"}], "explanations": {"签署": "正确答案：签署（qiān shǔ），在重要文件上正式签名表示同意。", "签收": "签收（qiān shōu）的第二个音节韵母与签署不同（ou 与 u），意思是确认收到。", "前述": "前述（qián shù）与签署（qiān shǔ）声调不同，意思是前面提到的。", "钱数": "钱数（qián shù）与签署（qiān shǔ）声调不同，意思是钱的数目。", "签售": "签售（qiān shòu）的第二个音节韵母与签署不同（òu 与 ǔ），意思是签名售书。"}, "sentence_index": null, "correct_answer": "签署"}, "level_3": {"options": [{"text": "签署", "is_correct": true, "explanation": "正确：签署，在同意书上正式签名。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，同意书不能吃，与“需要”的语境不符。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能接“同意书”作宾语。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用，同意书不能喝，与“需要”的语境不符。"}], "explanations": {"签署": "正确：签署，在同意书上正式签名。", "吃": "语义：“吃”指进食，同意书不能吃，与“需要”的语境不符。", "唱": "搭配：“唱”不能接“同意书”作宾语。", "喝": "语义：“喝”指饮用，同意书不能喝，与“需要”的语境不符。"}, "sentence_index": 0, "correct_answer": "签署"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天早上签署一杯牛奶。", "explanation": "这里应该用〈喝〉。签署只用于文件，牛奶要用“喝”。"}, {"text": "他昨天签署了班主任。", "explanation": "这里应该用〈见〉。签署只用于文件，不指人；见班主任要用“见”。"}, {"text": "我在门口签署了快递。", "explanation": "这里应该用〈签收〉。签收指确认收到快递、信件；签署用于正式文件，不说签署快递。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87435, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "签署", "is_correct": true, "explanation": "正确：签署，在协议上正式签名。"}, {"text": "煮", "is_correct": false, "explanation": "语义：“煮”指加热食物，不能用于协议，与“在协议上”不符。"}, {"text": "咬", "is_correct": false, "explanation": "语义：“咬”指用牙齿咬住，协议不能被咬，与“在协议上”不符。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：在协议上不能进行“跳”这样的动作，与“在协议上”搭配不当。"}], "explanations": {"签署": "正确：签署，在协议上正式签名。", "煮": "语义：“煮”指加热食物，不能用于协议，与“在协议上”不符。", "咬": "语义：“咬”指用牙齿咬住，协议不能被咬，与“在协议上”不符。", "跳": "搭配：在协议上不能进行“跳”这样的动作，与“在协议上”搭配不当。"}, "sentence_index": 6, "correct_answer": "签署"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈每天都签署一首歌。", "explanation": "这里应该用〈唱〉。签署只用于文件、协议，歌曲要用“唱”。"}, {"text": "今天的天气很好，我们签署了天气。", "explanation": "这里应该用〈谈论〉。签署只用于文件、协议，天气不能被签署，谈论天气要用“谈论”。"}, {"text": "大家在电影院里签署了电影。", "explanation": "这里应该用〈看〉。签署只用于文件、协议，电影要用“看”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87435, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "经理在报告的最后一页签署了过。", "corrected_sentence": "经理在报告的最后一页签署了。", "error_description": "体标错误：“了”与“过”不能叠用，应删去“过”，说“签署了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87435, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他还没有签署了合同。", "corrected_sentence": "他还没有签署合同。", "error_description": "体标错误：“没有”与“了”不能同时用在同一动词上，应删去“了”，说“还没有签署合同”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c2e7a7e9-67bd-4f23-9898-ac5580120dba') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
