INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87437, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "件是数衣服、事情的词，比如一件衣服。", "primary_collocate": null, "pronunciation": "jiàn", "ipa": "tɕjɛn˥˩", "syllable_count": 1, "sentences": [{"text": "这件衣服是新买的。", "target_word": "件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我有一件旧大衣。", "target_word": "件", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这件事情很简单。", "target_word": "件", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她昨天穿了一件白衬衫。", "target_word": "件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "柜子里挂着五件衬衫。", "target_word": "件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说了一件让大家高兴的事。", "target_word": "件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给朋友寄了一件衬衫。", "target_word": "件", "complexity_tier": "T3", "furigana": "wǒ gěi péng you jì le yí jiàn chèn shān", "sentence_source": "generated"}, {"text": "这几件事都很重要。", "target_word": "件", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把那件毛衣送给了弟弟。", "target_word": "件", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那件事是谁告诉你的？", "target_word": "件", "complexity_tier": "T3", "furigana": "nà jiàn shì shéi gào su nǐ de", "sentence_source": "generated"}], "morphological_forms": [{"form": "件件", "label": "重叠"}, {"form": "事件", "label": "复合"}, {"form": "文件", "label": "复合"}], "register": "中性", "sense_fingerprint": "量词：数衣服、事情，如一件衣服、一件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f0f3827-7eef-4040-8225-662f43c0b4c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87437, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "件", "is_correct": true, "explanation": "正确答案：量词“件”，用于衣服、事情等个体事物。"}, {"text": "间", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，“间”表示房间，与量词“件”意思不同。"}, {"text": "现", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同（x 与 j），“现”表示现在，与量词“件”意思不同。"}, {"text": "欠", "is_correct": false, "explanation": "qiàn 与 jiàn 声母不同（q 与 j），“欠”表示欠缺，与量词“件”意思不同。"}, {"text": "简", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn 声调不同，“简”表示简单，与量词“件”意思不同。"}], "explanations": {"件": "正确答案：量词“件”，用于衣服、事情等个体事物。", "间": "jiān（第一声）与 jiàn（第四声）声调不同，“间”表示房间，与量词“件”意思不同。", "现": "xiàn 与 jiàn 声母不同（x 与 j），“现”表示现在，与量词“件”意思不同。", "欠": "qiàn 与 jiàn 声母不同（q 与 j），“欠”表示欠缺，与量词“件”意思不同。", "简": "jiǎn（第三声）与 jiàn 声调不同，“简”表示简单，与量词“件”意思不同。"}, "sentence_index": null, "correct_answer": "件"}, "level_3": {"options": [{"text": "件", "is_correct": true, "explanation": "量词“件”，用于“衣服”，正确。"}, {"text": "条", "is_correct": false, "explanation": "搭配：“条”多用于裤子、裙子等有长度的物品，“这条衣服”不常见，与“衣服”搭配不当。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于纸、桌子等平面的物品，不能与“衣服”搭配。"}, {"text": "台", "is_correct": false, "explanation": "搭配：“台”用于机器、电器等，不能与“衣服”搭配。"}], "explanations": {"件": "量词“件”，用于“衣服”，正确。", "条": "搭配：“条”多用于裤子、裙子等有长度的物品，“这条衣服”不常见，与“衣服”搭配不当。", "张": "搭配：“张”用于纸、桌子等平面的物品，不能与“衣服”搭配。", "台": "搭配：“台”用于机器、电器等，不能与“衣服”搭配。"}, "sentence_index": 0, "correct_answer": "件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她昨天穿了一只白衬衫。", "explanation": "这里应该用〈件〉。“只”用于动物或成对器官中的一个，不用于衬衫，量词搭配错误。"}, {"text": "她昨天穿了一张白衬衫。", "explanation": "这里应该用〈件〉。“张”用于纸张、桌子等平面物品，不用于衬衫，量词搭配错误。"}, {"text": "她昨天穿了一条白衬衫。", "explanation": "这里应该用〈件〉。“条”多用于裤子、裙子等有长度的物品，不用于衬衫，量词搭配错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
