INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87438, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "件", "is_correct": true, "explanation": "正确答案：量词“件”，用于衣服、事情等个体事物。"}, {"text": "间", "is_correct": false, "explanation": "jiān（第一声）与 jiàn（第四声）声调不同，“间”表示房间，与“件”的量词意思不同。"}, {"text": "现", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同（x 与 j），“现”表示现在，与量词“件”意思不同。"}, {"text": "欠", "is_correct": false, "explanation": "qiàn 与 jiàn 声母不同（q 与 j），“欠”表示欠缺或欠债，与量词“件”意思不同。"}, {"text": "简", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn 声调不同，“简”表示简单，与量词“件”意思不同。"}], "explanations": {"件": "正确答案：量词“件”，用于衣服、事情等个体事物。", "间": "jiān（第一声）与 jiàn（第四声）声调不同，“间”表示房间，与“件”的量词意思不同。", "现": "xiàn 与 jiàn 声母不同（x 与 j），“现”表示现在，与量词“件”意思不同。", "欠": "qiàn 与 jiàn 声母不同（q 与 j），“欠”表示欠缺或欠债，与量词“件”意思不同。", "简": "jiǎn（第三声）与 jiàn 声调不同，“简”表示简单，与量词“件”意思不同。"}, "sentence_index": null, "correct_answer": "件"}, "level_3": {"options": [{"text": "件", "is_correct": true, "explanation": "量词“件”，用于“衣服”，正确。"}, {"text": "条", "is_correct": false, "explanation": "搭配：“条”多用于裤子、裙子等有长度的物品，“一条红色的衣服”不常见，与“衣服”搭配不当。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于纸、桌子等平面的物品，不能与“衣服”搭配。"}, {"text": "台", "is_correct": false, "explanation": "搭配：“台”用于机器、电器等，不能与“衣服”搭配。"}], "explanations": {"件": "量词“件”，用于“衣服”，正确。", "条": "搭配：“条”多用于裤子、裙子等有长度的物品，“一条红色的衣服”不常见，与“衣服”搭配不当。", "张": "搭配：“张”用于纸、桌子等平面的物品，不能与“衣服”搭配。", "台": "搭配：“台”用于机器、电器等，不能与“衣服”搭配。"}, "sentence_index": 0, "correct_answer": "件"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他送给我一只很好的礼物。", "explanation": "这里应该用〈件〉。“只”用于动物或成对器官中的一个，不用于礼物，量词搭配错误。"}, {"text": "他送给我一张很好的礼物。", "explanation": "这里应该用〈件〉。“张”用于纸张、桌子等平面物品，不用于礼物，量词搭配错误。"}, {"text": "他送给我一棵很好的礼物。", "explanation": "这里应该用〈件〉。“棵”用于植物，不用于礼物，量词搭配错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87438, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "件", "is_correct": true, "explanation": "正确答案：量词“件”，用于个体事物。"}, {"text": "尖", "is_correct": false, "explanation": "jiān（第一声）与 jiàn 声调不同，“尖”表示尖锐，与量词“件”意思不同。"}, {"text": "剪", "is_correct": false, "explanation": "jiǎn（第三声）与 jiàn 声调不同，“剪”表示剪刀或剪切，与量词“件”意思不同。"}, {"text": "县", "is_correct": false, "explanation": "xiàn 与 jiàn 声母不同（x 与 j），“县”表示行政区划，与量词“件”意思不同。"}], "explanations": {"件": "正确答案：量词“件”，用于个体事物。", "尖": "jiān（第一声）与 jiàn 声调不同，“尖”表示尖锐，与量词“件”意思不同。", "剪": "jiǎn（第三声）与 jiàn 声调不同，“剪”表示剪刀或剪切，与量词“件”意思不同。", "县": "xiàn 与 jiàn 声母不同（x 与 j），“县”表示行政区划，与量词“件”意思不同。"}, "sentence_index": null, "correct_answer": "件"}, "level_3": {"options": [{"text": "件", "is_correct": true, "explanation": "量词“件”，用于“行李”，正确。"}, {"text": "台", "is_correct": false, "explanation": "搭配：“台”用于机器、电器等，不能与“行李”搭配。"}, {"text": "根", "is_correct": false, "explanation": "搭配：“根”用于细长的物品，不能与“行李”搭配。"}, {"text": "把", "is_correct": false, "explanation": "搭配：“把”是用于有柄物品的量词，不能与“行李”搭配。"}], "explanations": {"件": "量词“件”，用于“行李”，正确。", "台": "搭配：“台”用于机器、电器等，不能与“行李”搭配。", "根": "搭配：“根”用于细长的物品，不能与“行李”搭配。", "把": "搭配：“把”是用于有柄物品的量词，不能与“行李”搭配。"}, "sentence_index": 6, "correct_answer": "件"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今天遇到了一只奇怪的事。", "explanation": "这里应该用〈件〉。“只”不用于事情，量词搭配错误。"}, {"text": "他今天遇到了一张奇怪的事。", "explanation": "这里应该用〈件〉。“张”不用于事情，量词搭配错误。"}, {"text": "他今天遇到了一条奇怪的事。", "explanation": "这里应该用〈件〉。“条”不用于事情，量词搭配错误。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87438, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天买了一个件新衬衫。", "corrected_sentence": "我昨天买了一件新衬衫。", "error_description": "错误形式：“一个件新衬衫”；正确形式：“一件新衬衫”。“件”是专用量词，前面不能再加通用量词“个”，重复用量词，搭配错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87438, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他出差带了两件的行李。", "corrected_sentence": "他出差带了两件行李。", "error_description": "错误形式：“两件的行李”；正确形式：“两件行李”。量词“件”之后直接接名词，中间不能插入“的”，错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
