INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87440, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "县政府所在地的城镇。", "primary_collocate": null, "pronunciation": "xiàn chéng", "ipa": "ɕjɛn˥˩ ʈʂʰɤŋ˧˥", "syllable_count": 2, "sentences": [{"text": "县城是县政府所在的地方。", "target_word": "县城", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "县里的人办证件都要去县城。", "target_word": "县城", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "县城里有县政府和县医院。", "target_word": "县城", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他大学毕业后回到县城工作。", "target_word": "县城", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个县城不大，有一条河。", "target_word": "县城", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "县城离省城有三百多公里。", "target_word": "县城", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他每天骑车去县城上班。", "target_word": "县城", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们县城新修了一座桥。", "target_word": "县城", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "县城里的学校比村里的好。", "target_word": "县城", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在县城住了二十年。", "target_word": "县城", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "座", "label": "量词"}], "register": "中性", "sense_fingerprint": "县政府所在的行政中心城镇", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9918d052-1adb-48b9-9d27-8bde39cc1f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87440, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "省城", "is_correct": false, "explanation": "语义：县政府所在地是县城，省城是省政府所在地，“省城是县政府所在的地方”不成立。"}, {"text": "首都", "is_correct": false, "explanation": "语义：首都是国家政府所在地，与“县政府”不符。"}, {"text": "村庄", "is_correct": false, "explanation": "语义：村庄不是县政府所在地，县政府设在县城里。"}, {"text": "县城", "is_correct": true, "explanation": "正确：县城是县政府所在的地方。"}], "explanations": {"省城": "语义：县政府所在地是县城，省城是省政府所在地，“省城是县政府所在的地方”不成立。", "首都": "语义：首都是国家政府所在地，与“县政府”不符。", "村庄": "语义：村庄不是县政府所在地，县政府设在县城里。", "县城": "正确：县城是县政府所在的地方。"}, "sentence_index": 0, "correct_answer": "县城"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "县城是省政府所在的地方。", "explanation": "这里应该用〈省城〉。县城是县政府所在地，省政府所在地要说省城。"}, {"text": "县城是国家政府所在的地方。", "explanation": "这里应该用〈首都〉。县城是县政府所在地，国家政府所在地是首都。"}, {"text": "我们去了一片县城。", "explanation": "这里应该用〈座〉。县城是城镇，量词用“座”或“个”，不用“片”（“片”多用于大面积的区域或成片的东西）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87440, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海底", "is_correct": false, "explanation": "语义：海底不是上班的地方，骑车去海底不可能。"}, {"text": "太空", "is_correct": false, "explanation": "语义：骑车无法去太空，与“骑车去”矛盾。"}, {"text": "火星", "is_correct": false, "explanation": "语义：骑车无法去火星，与“骑车去上班”矛盾。"}, {"text": "县城", "is_correct": true, "explanation": "正确：他每天骑车去县城上班，符合语境。"}], "explanations": {"海底": "语义：海底不是上班的地方，骑车去海底不可能。", "太空": "语义：骑车无法去太空，与“骑车去”矛盾。", "火星": "语义：骑车无法去火星，与“骑车去上班”矛盾。", "县城": "正确：他每天骑车去县城上班，符合语境。"}, "sentence_index": 6, "correct_answer": "县城"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在一块县城住了二十年。", "explanation": "这里应该用〈座〉。县城是城镇，量词用“座”或“个”，不用“块”。"}, {"text": "我在一本县城住了二十年。", "explanation": "这里应该用〈座〉。县城是城镇，量词用“座”或“个”，不用“本”（“本”用于书籍、册子）。"}, {"text": "我在一张县城住了二十年。", "explanation": "这里应该用〈座〉。县城是城镇，量词用“座”或“个”，不用“张”（“张”多用于平面的东西）。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87440, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他住在一条小县城里。", "corrected_sentence": "他住在一座小县城里。", "error_description": "量词错误：错误形式“一条县城”；正确形式“一座县城”（或“一个县城”）。“条”用于细长的东西，县城是城镇，用“座”或“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87440, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候常跟父母县城看电影。", "corrected_sentence": "他小时候常跟父母去县城看电影。", "error_description": "漏掉动词“去”。“去县城”是动词加地点，地点“县城”前要有“去”，错误形式“跟父母县城看电影”，应为“跟父母去县城看电影”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
