INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87441, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "美女是长得很漂亮的女人。", "primary_collocate": null, "pronunciation": "měi nǚ", "ipa": "meɪ̯˧˥ ny˨˩˦", "syllable_count": 2, "sentences": [{"text": "那位美女是我们新来的同事。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的老板娘是个大美女。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片里的美女笑得很甜。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一位美女走过来问我路。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看见美女，脸一下子红了。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我姐姐是公认的美女，大家都这么说。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的美女穿着红色的长裙。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班里有三位美女，都很爱笑。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就是个美女，走到哪儿都有人看。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个美女还会说三种语言。", "target_word": "美女", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "美女们", "label": "复数"}], "register": "口语", "sense_fingerprint": "长得很漂亮的女人：一位美女、大美女", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '323a0647-864a-43f9-9cfa-c61cbd356ead') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87441, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "病人", "is_correct": false, "explanation": "语义：病人不是工作的人，不能和“新来的同事”是同一类人，与句子语境冲突。"}, {"text": "美女", "is_correct": true, "explanation": "符合语境：指长得漂亮的女子，可以是新来的同事。"}, {"text": "宝石", "is_correct": false, "explanation": "搭配：量词“位”只用于人，不能说“那位宝石”。"}, {"text": "小学生", "is_correct": false, "explanation": "语义：小学生是学生，不是同事，与“新来的同事”矛盾。"}], "explanations": {"病人": "语义：病人不是工作的人，不能和“新来的同事”是同一类人，与句子语境冲突。", "美女": "符合语境：指长得漂亮的女子，可以是新来的同事。", "宝石": "搭配：量词“位”只用于人，不能说“那位宝石”。", "小学生": "语义：小学生是学生，不是同事，与“新来的同事”矛盾。"}, "sentence_index": 0, "correct_answer": "美女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的美女让人印象深刻。", "explanation": "这里应该用〈美丽〉。“美女”指长得漂亮的女子，是指人的名词，不表示“美丽”这种抽象的性质。"}, {"text": "他是我们公司新来的美女，工作很认真。", "explanation": "这里应该用〈帅哥〉。“美女”只用来称赞女性的容貌，形容男性要说“帅哥”。"}, {"text": "她的职业是美女，经常上杂志。", "explanation": "这里应该用〈模特〉。“美女”描述外貌，不是职业名称，职业要说“模特”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87441, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "桌子", "is_correct": false, "explanation": "配价：“穿”的主语须是人，桌子不能穿衣服。"}, {"text": "美女", "is_correct": true, "explanation": "符合语境：指电影中的女性角色，穿长裙与语境一致。"}, {"text": "树", "is_correct": false, "explanation": "配价：“穿”的主语须是人，树不能穿衣服。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“穿”的主语须是人，窗户不能穿衣服。"}], "explanations": {"桌子": "配价：“穿”的主语须是人，桌子不能穿衣服。", "美女": "符合语境：指电影中的女性角色，穿长裙与语境一致。", "树": "配价：“穿”的主语须是人，树不能穿衣服。", "窗户": "配价：“穿”的主语须是人，窗户不能穿衣服。"}, "sentence_index": 6, "correct_answer": "美女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑是个美女，很多人都喜欢它。", "explanation": "这里应该用〈好东西〉。“美女”指长得漂亮的女子，只用于人，不能用来称呼电脑这样的物品。"}, {"text": "这个问题是个美女，大家都很想解决它。", "explanation": "这里应该用〈难题〉。“美女”指漂亮的女子，不用来称呼问题这类抽象事物；指难以解决的问题要说“难题”。"}, {"text": "这张桌子是个美女，客人们都喜欢坐。", "explanation": "这里应该用〈好桌子〉。“美女”指人，不能用来称呼家具这样的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87441, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只美女是我的朋友。", "corrected_sentence": "那个美女是我的朋友。", "error_description": "量词错误：“美女”指人，应用量词“个”或“位”，不能用“只”（“只”多用于动物或成对物品中的一个）。正确形式是“那个美女”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87441, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "班里有三美女在跳舞。", "corrected_sentence": "班里有三位美女在跳舞。", "error_description": "量词缺失：数词“三”与名词“美女”之间要加量词，应说“三位美女”或“三个美女”，漏掉量词是常见错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed6d7fc-2936-4a9c-a6a1-b4a0883859f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
