INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87443, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "信是写给别人看的话，放在信封里寄出去。", "primary_collocate": null, "pronunciation": "xìn", "ipa": "ɕin˥˩", "syllable_count": 1, "sentences": [{"text": "我给妈妈写了一封信。", "target_word": "信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桌子上有一封信。", "target_word": "信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他把信放进信封里。", "target_word": "信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天收到了朋友的信。", "target_word": "信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这封信是谁写的？", "target_word": "信", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你帮我把信寄出去。", "target_word": "信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷每个月给我写一封信。", "target_word": "信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他看着信，高兴地笑了。", "target_word": "信", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信已经寄走了，明天就能到。", "target_word": "信", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我没有回他的信。", "target_word": "信", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "封", "label": "量词"}, {"form": "信封", "label": "复合"}, {"form": "信纸", "label": "复合"}], "register": "中性", "sense_fingerprint": "信：名词，装进信封寄出的书信", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '81d15118-0c81-46f0-82ea-032f2bef765b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87443, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "信", "is_correct": true, "explanation": "正确答案：信（xìn），意思是书信。"}, {"text": "心", "is_correct": false, "explanation": "xīn（第一声）与 xìn（第四声）声调不同，意思是心脏、心思。"}, {"text": "性", "is_correct": false, "explanation": "xìng 与 xìn 只差韵尾 -ng 和 -n，意思是性格、性质。"}, {"text": "新", "is_correct": false, "explanation": "xīn（第一声）与 xìn（第四声）声调不同，意思是新的。"}, {"text": "辛", "is_correct": false, "explanation": "xīn（第一声）与 xìn（第四声）声调不同，意思是辛苦、辣。"}], "explanations": {"信": "正确答案：信（xìn），意思是书信。", "心": "xīn（第一声）与 xìn（第四声）声调不同，意思是心脏、心思。", "性": "xìng 与 xìn 只差韵尾 -ng 和 -n，意思是性格、性质。", "新": "xīn（第一声）与 xìn（第四声）声调不同，意思是新的。", "辛": "xīn（第一声）与 xìn（第四声）声调不同，意思是辛苦、辣。"}, "sentence_index": null, "correct_answer": "信"}, "level_3": {"options": [{"text": "信", "is_correct": true, "explanation": "“一封信”是书信的常用量词搭配，符合句意。"}, {"text": "作文", "is_correct": false, "explanation": "搭配：作文的量词是“篇”，不用“封”，不说“写了一封作文”。"}, {"text": "字", "is_correct": false, "explanation": "搭配：“封”不能用于“字”，不说“写了一封字”。"}, {"text": "歌", "is_correct": false, "explanation": "语义：歌是唱的，不能说“写了一封歌”，与“写”的对象不符。"}], "explanations": {"信": "“一封信”是书信的常用量词搭配，符合句意。", "作文": "搭配：作文的量词是“篇”，不用“封”，不说“写了一封作文”。", "字": "搭配：“封”不能用于“字”，不说“写了一封字”。", "歌": "语义：歌是唱的，不能说“写了一封歌”，与“写”的对象不符。"}, "sentence_index": 0, "correct_answer": "信"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今天收到了朋友的信，就把它种在花园里了。", "explanation": "这里的〈信〉被当成植物，信不能种；〈信〉指写给别人看、装在信封里寄出的文字。"}, {"text": "我今天收到了朋友的信，它在门口叫了半天。", "explanation": "这里的〈信〉被当成会叫的动物，不合常理；〈信〉是寄来的书信，不会叫。"}, {"text": "我今天收到了朋友的信，穿上它就出门了。", "explanation": "这里的〈信〉被当成衣服，信不能穿；〈信〉指寄来的书信。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87443, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "信", "is_correct": true, "explanation": "正确答案：信（xìn），意思是书信。"}, {"text": "兴", "is_correct": false, "explanation": "xìng 与 xìn 只差韵尾 -ng 和 -n，意思是兴趣、高兴。"}, {"text": "薪", "is_correct": false, "explanation": "xīn（第一声）与 xìn（第四声）声调不同，意思是薪水。"}, {"text": "迅", "is_correct": false, "explanation": "xùn 与 xìn 只差韵母 in 和 un，意思是迅速。"}], "explanations": {"信": "正确答案：信（xìn），意思是书信。", "兴": "xìng 与 xìn 只差韵尾 -ng 和 -n，意思是兴趣、高兴。", "薪": "xīn（第一声）与 xìn（第四声）声调不同，意思是薪水。", "迅": "xùn 与 xìn 只差韵母 in 和 un，意思是迅速。"}, "sentence_index": null, "correct_answer": "信"}, "level_3": {"options": [{"text": "信", "is_correct": true, "explanation": "“一封信”是书信的常用量词搭配，符合句意。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业是练习题，不是写给人看的文字，不能说“写一封作业”。"}, {"text": "故事", "is_correct": false, "explanation": "搭配：“故事”不用量词“封”，不说“写一封故事”。"}, {"text": "诗", "is_correct": false, "explanation": "搭配：诗的量词是“首”，“封”不能用于诗。"}], "explanations": {"信": "“一封信”是书信的常用量词搭配，符合句意。", "作业": "语义：作业是练习题，不是写给人看的文字，不能说“写一封作业”。", "故事": "搭配：“故事”不用量词“封”，不说“写一封故事”。", "诗": "搭配：诗的量词是“首”，“封”不能用于诗。"}, "sentence_index": 6, "correct_answer": "信"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把朋友的信当成充电宝，给手机充电。", "explanation": "这里的〈信〉被当成充电宝用，不合常理；〈信〉指写给对方的文字，不能用来充电。"}, {"text": "我把朋友的信煮熟了，当作晚饭吃。", "explanation": "这里的〈信〉被当成食物，信不能吃；书信的〈信〉指写给对方的文字，不能用于烹饪。"}, {"text": "他把朋友的信挂在墙上当窗帘。", "explanation": "这里的〈信〉被当成窗帘用，不合常理；书信的〈信〉应放在信封里寄出或收到，不作装饰。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87443, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他昨天寄来了一张信。", "corrected_sentence": "他昨天寄来了一封信。", "error_description": "量词错误：书信的量词是“封”，不能用“张”。正确说法是“他昨天寄来了一封信”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87443, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把那些信们都读完了。", "corrected_sentence": "我把那些信都读完了。", "error_description": "“们”只用于指人的名词或代词，“信”不能加“们”。正确说法是“那些信都读完了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '84db387b-9851-407c-b28e-aebbf04c37ad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
