INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87445, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "落实是把说好的事真的去做，一点一点做到。", "primary_collocate": null, "pronunciation": "luò shí", "ipa": "luɔ˥˩ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "你说要学英语，就要一点一点落实。", "target_word": "落实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别只说不做，要落实到行动上。", "target_word": "落实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都把计划一点点落实。", "target_word": "落实", "complexity_tier": "T3", "furigana": "tā měi tiān dōu bǎ jì huà yì diǎn diǎn luò shí", "sentence_source": "generated"}, {"text": "说好周末打扫房间，我们落实了吗？", "target_word": "落实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的减肥计划终于落实了。", "target_word": "落实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想法再好，也要落实才有用。", "target_word": "落实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我答应帮你搬家，就一定落实这件事。", "target_word": "落实", "complexity_tier": "T3", "furigana": "wǒ dā ying bāng nǐ bān jiā jiù yí dìng luò shí zhè jiàn shì", "sentence_source": "generated"}, {"text": "每个月的存钱计划，她都落实了。", "target_word": "落实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他答应每天早起，这次真的落实了。", "target_word": "落实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈的早睡计划，今晚终于落实了。", "target_word": "落实", "complexity_tier": "T3", "furigana": "mā ma de zǎo shuì jì huà jīn wǎn zhōng yú luò shí le", "sentence_source": "generated"}], "morphological_forms": [{"form": "落实了", "label": "体标"}, {"form": "落实过", "label": "体标"}], "register": "中性", "sense_fingerprint": "把说好的事真的去做并做到", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf41015-8ec0-4664-ad3d-be3fa4f8add0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87445, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "落实", "is_correct": true, "explanation": "“一点一点落实”表示把说好的事一步步真正做到，与“你说要学英语”相符。"}, {"text": "拒绝", "is_correct": false, "explanation": "语义：“拒绝”与“你说要学英语”的意愿相反，句意矛盾。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”需要可以扔掉的东西，不能与“英语”这类学习内容搭配。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与“学英语”无关，句子说的是学习，不是唱歌。"}], "explanations": {"落实": "“一点一点落实”表示把说好的事一步步真正做到，与“你说要学英语”相符。", "拒绝": "语义：“拒绝”与“你说要学英语”的意愿相反，句意矛盾。", "扔": "搭配：“扔”需要可以扔掉的东西，不能与“英语”这类学习内容搭配。", "唱": "语义：“唱”与“学英语”无关，句子说的是学习，不是唱歌。"}, "sentence_index": 0, "correct_answer": "落实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他终于落实了那首歌。", "explanation": "这里应该用〈完成〉。歌曲、作品要说完成，落实用于说好的事、计划付诸行动。"}, {"text": "她家终于落实了一只小狗。", "explanation": "这里应该用〈养〉。小狗要说养，落实用于说好的事、计划付诸行动。"}, {"text": "这个月我的工资落实了三百块。", "explanation": "这里应该用〈增加〉。工资等数量要说增加，落实不用于表示数量的变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87445, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "落实", "is_correct": true, "explanation": "“就一定落实这件事”表示答应的事一定要真正做到，与“答应帮你搬家”相符。"}, {"text": "忘", "is_correct": false, "explanation": "语义：“答应帮忙”后说“一定忘这件事”，与答应的意思相反。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，“这件事”不能被“吃”。"}, {"text": "躲", "is_correct": false, "explanation": "语义：“一定躲这件事”与“答应”的承诺矛盾。"}], "explanations": {"落实": "“就一定落实这件事”表示答应的事一定要真正做到，与“答应帮你搬家”相符。", "忘": "语义：“答应帮忙”后说“一定忘这件事”，与答应的意思相反。", "吃": "搭配：“吃”的对象是食物，“这件事”不能被“吃”。", "躲": "语义：“一定躲这件事”与“答应”的承诺矛盾。"}, "sentence_index": 6, "correct_answer": "落实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这次终于落实了好成绩。", "explanation": "这里应该用〈取得〉。成绩、成果要说取得，落实用于说好的事、计划付诸行动。"}, {"text": "我终于落实了那个真相。", "explanation": "这里应该用〈发现〉。真相要说发现，落实不用于事实。"}, {"text": "他终于落实了自信。", "explanation": "这里应该用〈树立〉。自信要说树立，落实用于说好的事、计划付诸行动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87445, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "咱们说好的计划，要一点一点落实行动上。", "corrected_sentence": "咱们说好的计划，要一点一点落实到行动上。", "error_description": "错误形式：落实行动上；正确形式：落实到行动上；原因：“落实”后面要用“到”引出落实的地方，漏掉“到”不符合习惯说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87445, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我答应的事，就一定落实很彻底。", "corrected_sentence": "我答应的事，就一定落实得很彻底。", "error_description": "错误形式：落实很彻底；正确形式：落实得很彻底；原因：“落实”后面带表示做得怎样的补语时要用“得”连接，漏掉“得”则句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
