INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87446, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使计划、政策、措施等得到切实执行或确定下来。", "primary_collocate": null, "pronunciation": "luò shí", "ipa": "luɔ˥˩ ʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "公司已经落实了新的安全措施。", "target_word": "落实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项政策要尽快落实到每个学校。", "target_word": "落实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理要求把工作计划落实到人。", "target_word": "落实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年的计划到现在还没落实。", "target_word": "落实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府落实了对农民的补贴。", "target_word": "落实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "会议结束后，各部门要马上落实任务。", "target_word": "落实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要落实好这个方案，需要更多的钱。", "target_word": "落实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校落实了新的作息时间。", "target_word": "落实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些规定必须认真落实。", "target_word": "落实", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地方政府已经落实了环保政策。", "target_word": "落实", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "落实了", "label": "体标"}, {"form": "落实过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使计划政策措施得到切实执行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abf41015-8ec0-4664-ad3d-be3fa4f8add0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87446, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "落实", "is_correct": true, "explanation": "“落实”指让新的安全措施真正执行，与“已经……了”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：安全措施不是食物，“吃”与“安全措施”语义不合。"}, {"text": "丢失", "is_correct": false, "explanation": "搭配：“丢失”用于东西、钱财，不能与“安全措施”搭配。"}, {"text": "落空", "is_correct": false, "explanation": "配价：“落空”是不及物动词，后面不能直接带“安全措施”作宾语。"}], "explanations": {"落实": "“落实”指让新的安全措施真正执行，与“已经……了”搭配。", "吃": "语义：安全措施不是食物，“吃”与“安全措施”语义不合。", "丢失": "搭配：“丢失”用于东西、钱财，不能与“安全措施”搭配。", "落空": "配价：“落空”是不及物动词，后面不能直接带“安全措施”作宾语。"}, "sentence_index": 0, "correct_answer": "落实"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天落实了一部电影。", "explanation": "这里应该用〈看〉。电影要说看，落实用于计划、政策、措施。"}, {"text": "他终于落实了这份作业。", "explanation": "这里应该用〈完成〉。作业要说完成，落实用于计划、政策、措施。"}, {"text": "他终于落实了那道难题。", "explanation": "这里应该用〈解决〉。难题要说解决，落实不用于问题本身。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87446, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "落实", "is_correct": true, "explanation": "“落实好这个方案”表示把方案切实执行好，与“需要更多的钱”的语境相符。"}, {"text": "忘", "is_correct": false, "explanation": "语义：“忘”表示忘记，与“要……好这个方案”的执行意思不合。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，不能与“方案”搭配。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于桌面、表面等，不能与“方案”搭配。"}], "explanations": {"落实": "“落实好这个方案”表示把方案切实执行好，与“需要更多的钱”的语境相符。", "忘": "语义：“忘”表示忘记，与“要……好这个方案”的执行意思不合。", "唱": "搭配：“唱”的对象是歌曲，不能与“方案”搭配。", "擦": "搭配：“擦”用于桌面、表面等，不能与“方案”搭配。"}, "sentence_index": 6, "correct_answer": "落实"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个月公司的利润落实了三成。", "explanation": "这里应该用〈增加〉。利润、数量要说增加，落实用于计划、政策、措施。"}, {"text": "我终于落实了那个秘密。", "explanation": "这里应该用〈发现〉。秘密要说发现，落实不用于事实或秘密。"}, {"text": "他终于落实了信心。", "explanation": "这里应该用〈树立〉。信心要说树立，落实用于计划、政策、措施。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87446, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市里的新交通计划已经落实每个区了。", "corrected_sentence": "市里的新交通计划已经落实到每个区了。", "error_description": "错误形式：落实每个区了；正确形式：落实到每个区了；原因：“落实”后面要用“到”引出落实的范围，漏掉“到”不符合习惯说法。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87446, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校已经把新的作息时间落实很好了。", "corrected_sentence": "学校已经把新的作息时间落实得很好了。", "error_description": "错误形式：落实很好了；正确形式：落实得很好了；原因：“落实”后面带表示做得怎样的补语时要用“得”连接，漏掉“得”则句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940791c-b5ba-4c67-9c26-a4699bd13ea4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
