INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87448, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "老路比喻旧的做法，即沿用过去的老套路。", "primary_collocate": null, "pronunciation": "lǎo lù", "ipa": "lau̯˨˩ lu˥˩", "syllable_count": 2, "sentences": [{"text": "他不想再走老路，决定换个办法。", "target_word": "老路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别总走老路，我们试试新方法吧。", "target_word": "老路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校改了教法，不再走老路。", "target_word": "老路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理说，今年不能走老路了。", "target_word": "老路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做事总走老路，很难有新进步。", "target_word": "老路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店走老路，客人越来越少。", "target_word": "老路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老路走不通，只好另找出路。", "target_word": "老路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他又回到老路上，还是天天熬夜。", "target_word": "老路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要找新路子，不能只靠老路。", "target_word": "老路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个项目还在走老路，效率一直上不去。", "target_word": "老路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "口语", "sense_fingerprint": "比喻旧的做法；沿用过去的老套路", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77dd5244-fd53-4152-b5ae-74a62c865356') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87448, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "老路", "is_correct": true, "explanation": "老路：比喻旧的做法，与“决定换个办法”相呼应，符合句意。"}, {"text": "人群", "is_correct": false, "explanation": "语义：“走”的对象不能是人群，与“换个办法”的语境不符，句子读不通。"}, {"text": "高楼", "is_correct": false, "explanation": "语义：高楼不能被“走”，“不想再走高楼”没有意义。"}, {"text": "火车", "is_correct": false, "explanation": "搭配：“走”不接火车，应说“坐火车”，“不想再走火车”说不通。"}], "explanations": {"老路": "老路：比喻旧的做法，与“决定换个办法”相呼应，符合句意。", "人群": "语义：“走”的对象不能是人群，与“换个办法”的语境不符，句子读不通。", "高楼": "语义：高楼不能被“走”，“不想再走高楼”没有意义。", "火车": "搭配：“走”不接火车，应说“坐火车”，“不想再走火车”说不通。"}, "sentence_index": 0, "correct_answer": "老路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他决心探索一条老路，走别人没走过的路。", "explanation": "这里应该用〈新路〉。“探索”和“走别人没走过的路”指未知的新方向，“老路”指以前走过的路，二者矛盾。"}, {"text": "这位工程师发明了一条老路，很多人都在用。", "explanation": "这里应该用〈新方法〉。“发明”指创造从未有过的新事物，“老路”指以前用过的旧做法，二者矛盾。"}, {"text": "他每天早上都吃老路当早饭。", "explanation": "这里“老路”被当成了食物，实际指道路或旧做法，不能吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87448, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "老路", "is_correct": true, "explanation": "老路：比喻旧的做法，“走不通”说明这种做法行不通，符合句意。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：“走不通”用于路径，电话不能说“走不通”，应说“打不通”。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流不是做法，“走不通”与“只好另找出路”的语境不符。"}, {"text": "大门", "is_correct": false, "explanation": "搭配：“走不通”多用于道路、路线，大门不能这样说。"}], "explanations": {"老路": "老路：比喻旧的做法，“走不通”说明这种做法行不通，符合句意。", "电话": "搭配：“走不通”用于路径，电话不能说“走不通”，应说“打不通”。", "河流": "语义：河流不是做法，“走不通”与“只好另找出路”的语境不符。", "大门": "搭配：“走不通”多用于道路、路线，大门不能这样说。"}, "sentence_index": 6, "correct_answer": "老路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个项目还在走一只老路，效率一直上不去。", "explanation": "量词错误：这里应该用〈条〉。“只”多用于动物，不能用于路线或做法。"}, {"text": "她戴上了老路，显得很漂亮。", "explanation": "这里“老路”被当成了〈饰品〉，实际指道路或旧做法，不能戴在身上。"}, {"text": "老路是新规定，所有人都要遵守。", "explanation": "这里“老路”被当成了〈规章〉，实际指道路或旧做法，不能作为规章制度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87448, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校不再走这只老路，改用了新教材。", "corrected_sentence": "学校不再走这条老路，改用了新教材。", "error_description": "量词错误：“老路”作比喻义时，量词仍应为〈条〉，不能用“只”。正确说法是“这条老路”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87448, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店还在走一块老路，客人越来越少。", "corrected_sentence": "这家店还在走一条老路，客人越来越少。", "error_description": "量词错误：“老路”作比喻义时量词仍用〈条〉，“块”用于成片的东西，不能说“一块老路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f594faad-37eb-47e7-8bae-409dfee625fc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
