INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87449, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "公布是把事情正式告诉大家。", "primary_collocate": null, "pronunciation": "gōng bù", "ipa": "kʊŋ˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "老师公布了比赛的时间。", "target_word": "公布", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王把好消息公布给大家。", "target_word": "公布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长公布了这次考试的成绩。", "target_word": "公布", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们正式公布了结婚的消息。", "target_word": "公布", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "经理明天会公布新的名单。", "target_word": "公布", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学校公布了放假的日期。", "target_word": "公布", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛的结果什么时候公布？", "target_word": "公布", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这件事先不要公布，等经理决定。", "target_word": "公布", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公司公布了新的上班时间，大家都知道了。", "target_word": "公布", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师还没公布成绩，同学们都很紧张。", "target_word": "公布", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "公布了", "label": "体标"}, {"form": "公布过", "label": "体标"}, {"form": "公佈", "label": "繁体"}], "register": "书面", "sense_fingerprint": "公布·把事情正式告诉大家", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '02e6c952-5557-4423-80e1-8c7df400d0c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87449, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "公布", "is_correct": true, "explanation": "公布，gōng bù，把事情正式告诉大家。"}, {"text": "中部", "is_correct": false, "explanation": "zhōng 与 gōng 声母不同（zh 与 g），意思是中部。"}, {"text": "东部", "is_correct": false, "explanation": "dōng 与 gōng 声母不同（d 与 g），意思是东部。"}, {"text": "公路", "is_correct": false, "explanation": "lù 与 bù 声母不同（l 与 b），意思是公路。"}, {"text": "公诉", "is_correct": false, "explanation": "sù 与 bù 声母不同（s 与 b），意思是公诉。"}], "explanations": {"公布": "公布，gōng bù，把事情正式告诉大家。", "中部": "zhōng 与 gōng 声母不同（zh 与 g），意思是中部。", "东部": "dōng 与 gōng 声母不同（d 与 g），意思是东部。", "公路": "lù 与 bù 声母不同（l 与 b），意思是公路。", "公诉": "sù 与 bù 声母不同（s 与 b），意思是公诉。"}, "sentence_index": null, "correct_answer": "公布"}, "level_3": {"options": [{"text": "公布", "is_correct": true, "explanation": "公布表示把比赛时间正式告诉大家，与“比赛的时间”搭配，句意通顺。"}, {"text": "修理", "is_correct": false, "explanation": "语义：修理指修复物品，不能用于“比赛的时间”，句子不通。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”的宾语应是活动，“比赛的时间”不能作参加的对象。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃指进食，不能用于“比赛的时间”，句子不通。"}], "explanations": {"公布": "公布表示把比赛时间正式告诉大家，与“比赛的时间”搭配，句意通顺。", "修理": "语义：修理指修复物品，不能用于“比赛的时间”，句子不通。", "参加": "配价：“参加”的宾语应是活动，“比赛的时间”不能作参加的对象。", "吃": "语义：吃指进食，不能用于“比赛的时间”，句子不通。"}, "sentence_index": 0, "correct_answer": "公布"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我公布了一把雨伞。", "explanation": "这里公布误作〈撑开〉的意思。公布只用于消息、名单等信息的公开，不能用于雨伞这样的实物，应说〈撑开〉。"}, {"text": "她公布了一个微笑。", "explanation": "这里公布误作〈露出〉的意思。公布只能用于消息、信息，不能用于微笑这样的表情，应说〈露出〉。"}, {"text": "我公布了一只铅笔。", "explanation": "这里公布误作〈拿出〉的意思。公布只用于消息、名单等信息的公开，不能用于铅笔这样的实物，应说〈拿出〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87449, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "公布", "is_correct": true, "explanation": "公布表示正式告诉大家结果，与“比赛的结果”搭配，问句通顺。"}, {"text": "举行", "is_correct": false, "explanation": "语义：举行指活动开展，不能用于“比赛的结果”，问句不通。"}, {"text": "打扫", "is_correct": false, "explanation": "语义：打扫指清除脏物，不能用于“比赛的结果”，问句不通。"}, {"text": "报名", "is_correct": false, "explanation": "配价：“报名”的对象是比赛本身，不能以“结果”为宾语。"}], "explanations": {"公布": "公布表示正式告诉大家结果，与“比赛的结果”搭配，问句通顺。", "举行": "语义：举行指活动开展，不能用于“比赛的结果”，问句不通。", "打扫": "语义：打扫指清除脏物，不能用于“比赛的结果”，问句不通。", "报名": "配价：“报名”的对象是比赛本身，不能以“结果”为宾语。"}, "sentence_index": 6, "correct_answer": "公布"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她公布了一块饼干。", "explanation": "这里公布误作〈送〉的意思。公布只用于消息、名单等信息的公开，不能用于饼干这类实物，应说〈送〉。"}, {"text": "他公布了一杯茶给客人。", "explanation": "这里公布误作〈端〉的意思。公布只用于消息、名单等信息的公开，不能用于茶这样的实物，应说〈端〉。"}, {"text": "妈妈公布了一把椅子给我。", "explanation": "这里应该用〈搬〉。公布误作〈分发〉之义，只用于消息、名单等信息的公开，不能用于椅子这样的实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87449, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班长正式公布着了放假的消息。", "corrected_sentence": "班长正式公布了放假的消息。", "error_description": "错误：“着”表示持续，“了”表示完成，二者不能同时用在“公布”上，只保留“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87449, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事还没有公布了，先别告诉别人。", "corrected_sentence": "这件事还没有公布，先别告诉别人。", "error_description": "“没有”与“了”不能同时用在“公布”上，“没有公布”后面不加“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2d0cd963-e96f-4786-a089-af747ce07287') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
