INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87451, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "血是在我们身体里面流的红色的水。", "primary_collocate": null, "pronunciation": "xiě", "ipa": "ɕjɛ˨˩˦", "syllable_count": 1, "sentences": [{"text": "你的脸上有血！", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他摔倒了，膝盖上流了血。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "红红的血看起来很吓人。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我看到血就害怕。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给他擦掉了手上的血。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他咬到了舌头，嘴里有血。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他鼻子里的血一直在流。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上的血已经干了。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怕血，不敢看打针。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗的腿上有血，快带它去看医生。", "target_word": "血", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "血液", "label": "复合词"}, {"form": "流血", "label": "复合词"}], "register": "口语", "sense_fingerprint": "身体里流的红色的水", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '934308b8-5ea3-4b86-bc2c-3ae9d4ecc7fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87451, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "血", "is_correct": true, "explanation": "正确答案：血（xiě），口语中指身体里流的红色的水。"}, {"text": "些", "is_correct": false, "explanation": "xiē（第一声）与 xiě（第三声）声调不同，意思是“一些”。"}, {"text": "鞋", "is_correct": false, "explanation": "xié（第二声）与 xiě（第三声）声调不同，意思是“鞋子”。"}, {"text": "谢", "is_correct": false, "explanation": "xiè（第四声）与 xiě（第三声）声调不同，意思是“感谢”。"}], "explanations": {"血": "正确答案：血（xiě），口语中指身体里流的红色的水。", "些": "xiē（第一声）与 xiě（第三声）声调不同，意思是“一些”。", "鞋": "xié（第二声）与 xiě（第三声）声调不同，意思是“鞋子”。", "谢": "xiè（第四声）与 xiě（第三声）声调不同，意思是“感谢”。"}, "sentence_index": null, "correct_answer": "血"}, "level_3": {"options": [{"text": "血", "is_correct": true, "explanation": "正确答案：“你的脸上有血”指脸上沾着或流着血，符合语境。"}, {"text": "脚", "is_correct": false, "explanation": "语义：“脚”是身体部位，不会出现在脸上。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“脸上有”一般说痕迹或污物，“窗户”不能这样搭配。"}, {"text": "轮子", "is_correct": false, "explanation": "语义：“轮子”不会出现在脸上。"}], "explanations": {"血": "正确答案：“你的脸上有血”指脸上沾着或流着血，符合语境。", "脚": "语义：“脚”是身体部位，不会出现在脸上。", "窗户": "搭配：“脸上有”一般说痕迹或污物，“窗户”不能这样搭配。", "轮子": "语义：“轮子”不会出现在脸上。"}, "sentence_index": 0, "correct_answer": "血"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我看到一根血就害怕。", "explanation": "量词错误：“血”不用“根”计量，应说“一滴血”。"}, {"text": "我一看到一个血就害怕。", "explanation": "量词错误：“血”不用“个”计量，应说“一滴血”。"}, {"text": "我看到一头血就害怕。", "explanation": "量词错误：“头”用于大型动物，不用来计量“血”。应说“一滴血”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e465b488-5baf-4d5d-8d0c-f048f967da82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87451, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "血", "is_correct": true, "explanation": "正确答案：血（xiě），口语中指身体里流的红色的水。"}, {"text": "歇", "is_correct": false, "explanation": "xiē（第一声）与 xiě（第三声）声调不同，意思是“休息”。"}, {"text": "斜", "is_correct": false, "explanation": "xié（第二声）与 xiě（第三声）声调不同，意思是“倾斜”。"}, {"text": "屑", "is_correct": false, "explanation": "xiè（第四声）与 xiě（第三声）声调不同，意思是“碎末”。"}], "explanations": {"血": "正确答案：血（xiě），口语中指身体里流的红色的水。", "歇": "xiē（第一声）与 xiě（第三声）声调不同，意思是“休息”。", "斜": "xié（第二声）与 xiě（第三声）声调不同，意思是“倾斜”。", "屑": "xiè（第四声）与 xiě（第三声）声调不同，意思是“碎末”。"}, "sentence_index": null, "correct_answer": "血"}, "level_3": {"options": [{"text": "血", "is_correct": true, "explanation": "正确答案：“鼻子里的血一直在流”描述鼻血，符合语境。"}, {"text": "字", "is_correct": false, "explanation": "语义：“字”不是能从鼻子里流出的东西。"}, {"text": "时间", "is_correct": false, "explanation": "语义：“时间”虽然常说“流逝”，但不会从鼻子里流出。"}, {"text": "节奏", "is_correct": false, "explanation": "搭配：“节奏”一般不说在身体里“流”，与“鼻子里的”搭配不当。"}], "explanations": {"血": "正确答案：“鼻子里的血一直在流”描述鼻血，符合语境。", "字": "语义：“字”不是能从鼻子里流出的东西。", "时间": "语义：“时间”虽然常说“流逝”，但不会从鼻子里流出。", "节奏": "搭配：“节奏”一般不说在身体里“流”，与“鼻子里的”搭配不当。"}, "sentence_index": 6, "correct_answer": "血"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "小狗的腿上有一颗血，快带它去看医生。", "explanation": "量词错误：“颗”用于颗粒状的东西，不用来计量“血”。应说“一滴血”或“一摊血”。"}, {"text": "小狗的腿上有一朵血，快带它去看医生。", "explanation": "量词错误：“朵”用于花、云等，不用来计量“血”。应说“一滴血”或“一摊血”。"}, {"text": "小狗的腿上有一本血，快带它去看医生。", "explanation": "量词错误：“本”用于书册，不用来计量“血”。应说“一滴血”或“一摊血”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e465b488-5baf-4d5d-8d0c-f048f967da82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87451, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你的脸上有一个血。", "corrected_sentence": "你的脸上有一滴血。", "error_description": "量词错误：“血”不用“个”计量，应用“滴”，说“一滴血”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e465b488-5baf-4d5d-8d0c-f048f967da82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87451, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的脚破了，把流血了。", "corrected_sentence": "他的脚破了，流血了。", "error_description": "“把”字句错误：“流血”是不及物动词，不能用于“把”字句。应去掉“把”，说“流血了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e465b488-5baf-4d5d-8d0c-f048f967da82') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
