INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87453, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "表示假设的让步：就算前面的情况成立，后面的结果也不会改变。", "primary_collocate": null, "pronunciation": "jí shǐ", "ipa": "tɕi˧˥ ʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "即使下雨，我们也要去公园。", "target_word": "即使", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "即使你不说，我也知道你很累。", "target_word": "即使", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "即使你现在走，也赶不上火车了。", "target_word": "即使", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "即使天气很冷，她也每天跑步。", "target_word": "即使", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "即使有人反对，我也不会改变主意。", "target_word": "即使", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "即使明天考试，他今天也不紧张。", "target_word": "即使", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "即使你给我很多钱，我也不卖这本书。", "target_word": "即使", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "即使路很远，我们也会走着去看你。", "target_word": "即使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即使他来过这里，也可能找不到路。", "target_word": "即使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即使把门关着，外面的声音也能听到。", "target_word": "即使", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "即使:就算前面的情况成立，结果也不变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '986f312e-72c3-468e-8424-eadc7ad44fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87453, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "即使", "is_correct": true, "explanation": "“即使”表示假设让步，与后面的“也”呼应，是听到的词。"}, {"text": "集市", "is_correct": false, "explanation": "“集市”第二个音节是第四声，与“即使”的第三声不同，意思是定期开放的交易场所。"}, {"text": "基石", "is_correct": false, "explanation": "“基石”两个音节的声调都与“即使”不同，意思是建筑的基础石块。"}, {"text": "技师", "is_correct": false, "explanation": "“技师”两个音节的声调都与“即使”不同，意思是有专门技术的人员。"}, {"text": "纪实", "is_correct": false, "explanation": "“纪实”两个音节的声调都与“即使”不同，意思是如实记录。"}], "explanations": {"即使": "“即使”表示假设让步，与后面的“也”呼应，是听到的词。", "集市": "“集市”第二个音节是第四声，与“即使”的第三声不同，意思是定期开放的交易场所。", "基石": "“基石”两个音节的声调都与“即使”不同，意思是建筑的基础石块。", "技师": "“技师”两个音节的声调都与“即使”不同，意思是有专门技术的人员。", "纪实": "“纪实”两个音节的声调都与“即使”不同，意思是如实记录。"}, "sentence_index": null, "correct_answer": "即使"}, "level_3": {"options": [{"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，下雨不能作为去公园的理由，句意不通。"}, {"text": "即使", "is_correct": true, "explanation": "“即使”引出假设让步，与后面的“也”呼应，符合句意。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示结果，前面需要有已知原因，不能引出“下雨”这样的假设。"}, {"text": "只有", "is_correct": false, "explanation": "搭配：“只有”要与“才”呼应，不能与“也”呼应。"}], "explanations": {"因为": "语义：“因为”表示原因，下雨不能作为去公园的理由，句意不通。", "即使": "“即使”引出假设让步，与后面的“也”呼应，符合句意。", "因此": "语义：“因此”表示结果，前面需要有已知原因，不能引出“下雨”这样的假设。", "只有": "搭配：“只有”要与“才”呼应，不能与“也”呼应。"}, "sentence_index": 0, "correct_answer": "即使"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我很喜欢他，即使他很友好。", "explanation": "这里应该用〈因为〉。“他很友好”是喜欢他的原因，不是让步；“即使”表示假设让步，用在这里句意不通。"}, {"text": "他的汉语很好，即使能写诗。", "explanation": "这里应该用〈甚至〉。“即使”表示假设让步，不能表示程度上的递进；“他的汉语很好，甚至能写诗”是程度递进，换成“即使”后句意不通。"}, {"text": "即使天气很好，我们去爬山了。", "explanation": "这里应该用〈因为〉。“即使”表示假设让步，后句要用“也”呼应，不能陈述已经发生的原因；“因为天气很好，我们去爬山了”才是自然的说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87453, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "即使", "is_correct": true, "explanation": "“即使”表示假设让步，是听到的词。"}, {"text": "即时", "is_correct": false, "explanation": "“即时”第二个音节是第二声，与“即使”的第三声不同，意思是立刻。"}, {"text": "急事", "is_correct": false, "explanation": "“急事”第二个音节是第四声，与“即使”的第三声不同，意思是紧急的事情。"}, {"text": "记事", "is_correct": false, "explanation": "“记事”两个音节的声调都与“即使”不同，意思是把事情记录下来。"}], "explanations": {"即使": "“即使”表示假设让步，是听到的词。", "即时": "“即时”第二个音节是第二声，与“即使”的第三声不同，意思是立刻。", "急事": "“急事”第二个音节是第四声，与“即使”的第三声不同，意思是紧急的事情。", "记事": "“记事”两个音节的声调都与“即使”不同，意思是把事情记录下来。"}, "sentence_index": null, "correct_answer": "即使"}, "level_3": {"options": [{"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示因果结论，与“也不卖”的让步语义相冲突。"}, {"text": "即使", "is_correct": true, "explanation": "“即使”引出假设让步，与“也不卖”呼应，符合句意。"}, {"text": "既然", "is_correct": false, "explanation": "语义：“既然”表示已知的理由，与“也不卖”的让步语义不符。"}, {"text": "只要", "is_correct": false, "explanation": "搭配：“只要”要与“就”呼应，不能与“也”呼应。"}], "explanations": {"所以": "语义：“所以”表示因果结论，与“也不卖”的让步语义相冲突。", "即使": "“即使”引出假设让步，与“也不卖”呼应，符合句意。", "既然": "语义：“既然”表示已知的理由，与“也不卖”的让步语义不符。", "只要": "搭配：“只要”要与“就”呼应，不能与“也”呼应。"}, "sentence_index": 6, "correct_answer": "即使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "即使他答应了，我们就放心吧。", "explanation": "这里应该用〈既然〉。“即使”表示假设，不能用来说明已经确定的理由；后句“就放心吧”是据此得出的结论。"}, {"text": "他不是老师，即使是学生。", "explanation": "这里应该用〈而是〉。“即使”表示让步假设，不能引出与前句对立的正确判断。"}, {"text": "即使多练习，就能进步。", "explanation": "这里应该用〈只要〉。“即使”表示让步，不能引出“就能进步”这种充分条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87453, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "即使有困难，我们就会坚持下去。", "corrected_sentence": "即使有困难，我们也会坚持下去。", "error_description": "错误：“即使”应与“也”呼应，这里误用了“就”。“即使”表示让步，后一分句要用“也”，应改为“我们也会坚持下去”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87453, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "即使没有钱，他要也买这本书。", "corrected_sentence": "即使没有钱，他也要买这本书。", "error_description": "错误：“也”放在了“要”之后，位置不对。“也”应放在主语之后、“要”之前，应改为“他也要买这本书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
