INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87454, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示假设的让步，引出不受影响的结果。", "primary_collocate": null, "pronunciation": "jí shǐ", "ipa": "tɕi˧˥ ʂɻ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "即使生病，他也不想休息。", "target_word": "即使", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "即使别人不同意，我也要试试。", "target_word": "即使", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "即使明天下雪，比赛也不会改期。", "target_word": "即使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即使你再努力，也不一定能赢。", "target_word": "即使", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "即使工作很忙，她也每天给妈妈打电话。", "target_word": "即使", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "即使我们住得很远，也能经常联系。", "target_word": "即使", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "即使这道菜很贵，我也想让你尝尝。", "target_word": "即使", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "即使你说得对，我也不想马上做。", "target_word": "即使", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "即使你学过这个词，考试时也可能写错。", "target_word": "即使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "即使把门窗都关上，屋里也很吵。", "target_word": "即使", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "即使:假设让步连词，与也/都搭配引出不变的结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '986f312e-72c3-468e-8424-eadc7ad44fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87454, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "即使", "is_correct": true, "explanation": "“即使”表示假设让步，是听到的词。"}, {"text": "集市", "is_correct": false, "explanation": "“集市”第二个音节是第四声，与“即使”的第三声不同，意思是定期开放的交易场所。"}, {"text": "基石", "is_correct": false, "explanation": "“基石”两个音节的声调都与“即使”不同，意思是建筑的基础石块。"}, {"text": "技师", "is_correct": false, "explanation": "“技师”两个音节的声调都与“即使”不同，意思是有专门技术的人员。"}], "explanations": {"即使": "“即使”表示假设让步，是听到的词。", "集市": "“集市”第二个音节是第四声，与“即使”的第三声不同，意思是定期开放的交易场所。", "基石": "“基石”两个音节的声调都与“即使”不同，意思是建筑的基础石块。", "技师": "“技师”两个音节的声调都与“即使”不同，意思是有专门技术的人员。"}, "sentence_index": null, "correct_answer": "即使"}, "level_3": {"options": [{"text": "因为", "is_correct": false, "explanation": "语义：“因为”表示原因，生病不能作为“不想休息”的理由，句意不通。"}, {"text": "即使", "is_correct": true, "explanation": "“即使”引出假设让步，与后面的“也”呼应，符合句意。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”表示结论，与“也不想休息”的让步语义相冲突。"}, {"text": "只有", "is_correct": false, "explanation": "搭配：“只有”要与“才”呼应，不能与“也”呼应。"}], "explanations": {"因为": "语义：“因为”表示原因，生病不能作为“不想休息”的理由，句意不通。", "即使": "“即使”引出假设让步，与后面的“也”呼应，符合句意。", "所以": "语义：“所以”表示结论，与“也不想休息”的让步语义相冲突。", "只有": "搭配：“只有”要与“才”呼应，不能与“也”呼应。"}, "sentence_index": 0, "correct_answer": "即使"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的字写得很好，即使能当老师。", "explanation": "这里应该用〈甚至〉。“即使”表示假设让步，不能表示程度上的递进；“他的字写得很好，甚至能当老师”是程度递进，换成“即使”后句意不通。"}, {"text": "他很聪明，即使很努力。", "explanation": "这里应该用〈而且〉。“即使”表示假设让步，不能用来补充并列的情况；“他很聪明，而且很努力”表示递进补充，换成“即使”后句意矛盾。"}, {"text": "即使他没带钱，我们就回家了。", "explanation": "这里应该用〈因为〉。“即使”表示假设让步，后句要用“也”或“还是”呼应，不能表示因果；“因为他没带钱，我们就回家了”才是自然的说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87454, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "即使", "is_correct": true, "explanation": "“即使”表示假设让步，是听到的词。"}, {"text": "即时", "is_correct": false, "explanation": "“即时”第二个音节是第二声，与“即使”的第三声不同，意思是立刻。"}, {"text": "急事", "is_correct": false, "explanation": "“急事”第二个音节是第四声，与“即使”的第三声不同，意思是紧急的事情。"}, {"text": "记事", "is_correct": false, "explanation": "“记事”两个音节的声调都与“即使”不同，意思是把事情记录下来。"}], "explanations": {"即使": "“即使”表示假设让步，是听到的词。", "即时": "“即时”第二个音节是第二声，与“即使”的第三声不同，意思是立刻。", "急事": "“急事”第二个音节是第四声，与“即使”的第三声不同，意思是紧急的事情。", "记事": "“记事”两个音节的声调都与“即使”不同，意思是把事情记录下来。"}, "sentence_index": null, "correct_answer": "即使"}, "level_3": {"options": [{"text": "既然", "is_correct": false, "explanation": "语义：“既然”表示已知的理由，与“也想让你尝尝”的让步语义相冲突。"}, {"text": "即使", "is_correct": true, "explanation": "“即使”引出假设让步，与“也想让你尝尝”呼应，符合句意。"}, {"text": "只要", "is_correct": false, "explanation": "搭配：“只要”要与“就”呼应，不能与“也”呼应。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”表示结果，需要已知的原因，不能引出“很贵”这种让步条件。"}], "explanations": {"既然": "语义：“既然”表示已知的理由，与“也想让你尝尝”的让步语义相冲突。", "即使": "“即使”引出假设让步，与“也想让你尝尝”呼应，符合句意。", "只要": "搭配：“只要”要与“就”呼应，不能与“也”呼应。", "因此": "语义：“因此”表示结果，需要已知的原因，不能引出“很贵”这种让步条件。"}, "sentence_index": 6, "correct_answer": "即使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "即使他答应了，我们就放心吧。", "explanation": "这里应该用〈既然〉。“即使”表示假设，不能用来说明已经确定的理由；后句“就放心吧”是据此得出的结论。"}, {"text": "他不是老师，即使是学生。", "explanation": "这里应该用〈而是〉。“即使”表示让步假设，不能引出与前句对立的正确判断。"}, {"text": "即使认真，就能学好。", "explanation": "这里应该用〈只要〉。“即使”表示让步，不能引出“就能学好”这种充分条件。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87454, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "即使生病，我就要去上班。", "corrected_sentence": "即使生病，我也要去上班。", "error_description": "错误：“即使”的呼应词应是“也”，这里误用了“就”。应改为“我也要去上班”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87454, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "即使天气不好，我们会也按时到达。", "corrected_sentence": "即使天气不好，我们也会按时到达。", "error_description": "错误：“也”放在了“会”之后，位置不对。“也”应放在主语之后、“会”之前，应改为“我们也会按时到达”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'be528465-bd94-493b-b734-18aa1c035366') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
