INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87455, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87455, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听不到是声音太小或太远，耳朵没有听见。", "primary_collocate": null, "pronunciation": "tīng bu dào", "ipa": "tʰiŋ˥ pu taʊ˥˩", "syllable_count": 3, "sentences": [{"text": "你的声音太小了，我根本听不到。", "target_word": "听不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他站得太远，我听不到他说什么。", "target_word": "听不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教室太大，后排的同学听不到老师讲课。", "target_word": "听不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师说话很轻，坐在后面的我听不到。", "target_word": "听不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山那边太远了，我们听不到他的喊声。", "target_word": "听不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷年纪大了，听不到小声说话。", "target_word": "听不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请大声一点，大家都听不到你的话。", "target_word": "听不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在楼下小声说话，我在楼上听不到。", "target_word": "听不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河对面太远，我听不到她在喊什么。", "target_word": "听不到", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "音箱的声音太小，远处的人听不到。", "target_word": "听不到", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "听得到", "label": "可能补语肯定式"}, {"form": "没听到", "label": "否定式"}], "register": "口语", "sense_fingerprint": "因声音太小或距离太远，耳朵没有听见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9918d052-1adb-48b9-9d27-8bde39cc1f98') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87455, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "看不到", "is_correct": false, "explanation": "搭配：“看不到”的对象是能看见的东西，不能接“你的声音”。"}, {"text": "闻不到", "is_correct": false, "explanation": "搭配：“闻不到”只用于气味，不能用于声音。"}, {"text": "听得到", "is_correct": false, "explanation": "语义：“听得到”表示能听见，与“你的声音太小”矛盾。"}, {"text": "听不到", "is_correct": true, "explanation": "正确：声音太小，所以我没有听见。"}], "explanations": {"看不到": "搭配：“看不到”的对象是能看见的东西，不能接“你的声音”。", "闻不到": "搭配：“闻不到”只用于气味，不能用于声音。", "听得到": "语义：“听得到”表示能听见，与“你的声音太小”矛盾。", "听不到": "正确：声音太小，所以我没有听见。"}, "sentence_index": 0, "correct_answer": "听不到"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "刚到南方，这里的方言我还听不到。", "explanation": "这里应该用〈听不惯〉。听不惯指还不习惯某种声音；听不到说明声音没有传到耳朵里，而方言是能听见的，问题在于不习惯。"}, {"text": "他说的是外语，我听不到他的意思。", "explanation": "这里应该用〈听不懂〉。声音听见了，只是不明白意思；听不到说明声音没有传到耳朵里。"}, {"text": "录音的声音很清楚，我却听不到是谁的声音。", "explanation": "这里应该用〈听不出〉。听不出指凭声音分辨不出是谁；听不到说明声音根本没有传过来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87455, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听得到", "is_correct": false, "explanation": "语义：“听得到”表示能听见，与“请大声一点”的前提矛盾。"}, {"text": "摸不到", "is_correct": false, "explanation": "搭配：“摸”只能用于有形的东西，“话”不能用手摸。"}, {"text": "看不见", "is_correct": false, "explanation": "搭配：“看不见”的对象是能看到的东西，不能用来接“你的话”。"}, {"text": "听不到", "is_correct": true, "explanation": "正确：请大声一点，说明大家现在听不到，符合语境。"}], "explanations": {"听得到": "语义：“听得到”表示能听见，与“请大声一点”的前提矛盾。", "摸不到": "搭配：“摸”只能用于有形的东西，“话”不能用手摸。", "看不见": "搭配：“看不见”的对象是能看到的东西，不能用来接“你的话”。", "听不到": "正确：请大声一点，说明大家现在听不到，符合语境。"}, "sentence_index": 6, "correct_answer": "听不到"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我是南方人，北方人的大嗓门我一直听不到。", "explanation": "这里应该用〈听不惯〉。大嗓门是能听见的，问题在于不习惯；听不到说明声音没有传到耳朵里。"}, {"text": "这门外语太难，我听不到。", "explanation": "这里应该用〈听不懂〉。听不懂指听见了却不明白；听不到指声音没有传到耳朵里。"}, {"text": "老师讲得太快，学生听不到。", "explanation": "这里应该用〈听不清〉。声音传到了耳朵里，只是太快听不清楚；听不到说明声音根本没有传过来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87455, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门关着，我在屋里听不到过院子里的狗叫。", "corrected_sentence": "门关着，我在屋里听不到院子里的狗叫。", "error_description": "错误形式“听不到过”。“听不到”是可能补语，后面不能再加“过”，应为“听不到院子里的狗叫”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87455, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "会场很大，后面的人听不到过发言人的声音。", "corrected_sentence": "会场很大，后面的人听不到发言人的声音。", "error_description": "错误形式“听不到过”。“听不到”是可能补语，后面不能再加“过”，应为“听不到发言人的声音”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f60d9a46-2ba1-452a-b3c2-3285ff2ef274') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
