INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87461, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87461, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "胸部是身体上，脖子下面、肚子上面的那一块。", "primary_collocate": null, "pronunciation": "xiōng bù", "ipa": "ɕjʊŋ˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "脖子下面、肚子上面就是胸部。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步以后，我感到胸部很闷。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把手放在胸部，深深吸了口气。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "摔倒时他胸部先着地，疼得说不出话。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张图画出了人体胸部里面的骨头。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天要注意胸部保暖，以免感冒。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动员的胸部上贴着号码。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，坐着的时候胸部要挺直。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院里有专门检查胸部的科室。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的胸部起伏得很快，可能是跑累了。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "身体上脖子下面肚子上面的那一块", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f88939-d718-4d2d-bc4c-ca9e6f6115ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87461, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "头部", "is_correct": false, "explanation": "语义：头部在脖子上面，不在脖子下面。"}, {"text": "胸部", "is_correct": true, "explanation": "正确。胸部就是身体上脖子下面、肚子上面的那一块。"}, {"text": "手腕", "is_correct": false, "explanation": "语义：手腕位于手臂末端，与脖子、肚子的位置不符。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：“身材”指整体体形，不是脖子与肚子之间的一块部位。"}], "explanations": {"头部": "语义：头部在脖子上面，不在脖子下面。", "胸部": "正确。胸部就是身体上脖子下面、肚子上面的那一块。", "手腕": "语义：手腕位于手臂末端，与脖子、肚子的位置不符。", "身材": "体貌：“身材”指整体体形，不是脖子与肚子之间的一块部位。"}, "sentence_index": 0, "correct_answer": "胸部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "张叔叔胸部很宽，从不计较别人的错误。", "explanation": "这里应该用〈胸怀〉。胸部指身体部位，形容气量大要说“胸怀宽广”。"}, {"text": "他的胸部跳得厉害，声音都在抖。", "explanation": "这里应该用〈心脏〉。“心跳得厉害”是常见说法，胸部本身不会跳动。"}, {"text": "王老师的胸部很大，学生犯了错他从不生气。", "explanation": "这里应该用〈胸怀〉。胸部指身体部位，说一个人度量大、能包容别人要说“胸怀宽广”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87461, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "眼睛", "is_correct": false, "explanation": "语义：号码要贴在躯干上，不会贴在眼睛上。"}, {"text": "胸部", "is_correct": true, "explanation": "正确。运动员的号码通常贴在胸前，所以说“胸部上贴着号码”。"}, {"text": "名字", "is_correct": false, "explanation": "语义：名字是抽象的称呼，不能贴号码。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：脸色是面部表情，不是可以贴东西的部位。"}], "explanations": {"眼睛": "语义：号码要贴在躯干上，不会贴在眼睛上。", "胸部": "正确。运动员的号码通常贴在胸前，所以说“胸部上贴着号码”。", "名字": "语义：名字是抽象的称呼，不能贴号码。", "脸色": "体貌：脸色是面部表情，不是可以贴东西的部位。"}, "sentence_index": 6, "correct_answer": "胸部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听说这件事后，他的胸部很伤心。", "explanation": "这里应该用〈心〉。“伤心”是心里的感受，胸部不能伤心。"}, {"text": "这位老人的胸部活量很大，每天都能爬山。", "explanation": "这里应该用〈肺〉。“肺活量”指肺的容量，“胸部活量”不成立。"}, {"text": "他弯下胸部捡起地上的书。", "explanation": "这里应该用〈腰〉。弯身子要说“弯腰”，胸部不能弯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87461, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他受伤地胸部需要包扎。", "corrected_sentence": "他受伤的胸部需要包扎。", "error_description": "“受伤”修饰“胸部”，应用“的”，不能用“地”（“地”修饰动词）。应改为“受伤的胸部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87461, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "裁判要求选手的一只胸部贴上号码。", "corrected_sentence": "裁判要求选手的胸部贴上号码。", "error_description": "“只”用于成对器官中的一个，“胸部”是整体，前面不能加“一只”；应去掉“一只”，说“选手的胸部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
