INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87462, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87462, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "人体或动物躯干上颈以下、腹以上的部分。", "primary_collocate": null, "pronunciation": "xiōng bù", "ipa": "ɕjʊŋ˥ pu˥˩", "syllable_count": 2, "sentences": [{"text": "医生用听诊器检查病人的胸部。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的胸部受了伤，需要住院治疗。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游泳时，水一直没过我的胸部。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说要给他的胸部拍一张片子。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸟的胸部有很强壮的肌肉。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他胸部疼了好几天，所以去看医生。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "练习俯卧撑可以锻炼胸部肌肉。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的胸部有一个小口袋。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的胸部被球打到了，疼得蹲下来。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "护士在孩子的胸部贴了几个小圆片。", "target_word": "胸部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "人或动物躯干颈以下腹以上的部位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '00f88939-d718-4d2d-bc4c-ca9e6f6115ae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87462, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "脚趾", "is_correct": false, "explanation": "语义：听诊器用来听胸腹内部的声音，脚趾不需要用听诊器检查。"}, {"text": "胸部", "is_correct": true, "explanation": "正确。“检查病人的胸部”指用听诊器听胸部内脏的声音。"}, {"text": "头发", "is_correct": false, "explanation": "语义：头发不是身体内部器官，不能用听诊器检查。"}, {"text": "脸色", "is_correct": false, "explanation": "体貌：脸色要靠眼睛观察，不能用听诊器检查。"}], "explanations": {"脚趾": "语义：听诊器用来听胸腹内部的声音，脚趾不需要用听诊器检查。", "胸部": "正确。“检查病人的胸部”指用听诊器听胸部内脏的声音。", "头发": "语义：头发不是身体内部器官，不能用听诊器检查。", "脸色": "体貌：脸色要靠眼睛观察，不能用听诊器检查。"}, "sentence_index": 0, "correct_answer": "胸部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的胸部很宽广，能容下很多人。", "explanation": "这里应该用〈胸怀〉。胸部指身体部位，形容心胸宽广要说“胸怀宽广”。"}, {"text": "他拍着胸部保证，一定按时完成。", "explanation": "这里应该用〈胸脯〉。“拍胸脯”是固定说法，表示保证；胸部不能这样用。"}, {"text": "医生说要给他的一把胸部拍一张片子。", "explanation": "这里不能用量词〈把〉。“把”用于有把手的物品，胸部不用这个量词，直接说“他的胸部”即可。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87462, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "牙齿", "is_correct": false, "explanation": "语义：牙齿没有肌肉，不能用俯卧撑来锻炼。"}, {"text": "胸部", "is_correct": true, "explanation": "正确。俯卧撑主要锻炼胸部的肌肉，“胸部肌肉”是常用搭配。"}, {"text": "指甲", "is_correct": false, "explanation": "语义：指甲不是肌肉组织，不能用俯卧撑来锻炼。"}, {"text": "皮肤", "is_correct": false, "explanation": "搭配：“肌肉”指身体的运动组织，“皮肤肌肉”不成立。"}], "explanations": {"牙齿": "语义：牙齿没有肌肉，不能用俯卧撑来锻炼。", "胸部": "正确。俯卧撑主要锻炼胸部的肌肉，“胸部肌肉”是常用搭配。", "指甲": "语义：指甲不是肌肉组织，不能用俯卧撑来锻炼。", "皮肤": "搭配：“肌肉”指身体的运动组织，“皮肤肌肉”不成立。"}, "sentence_index": 6, "correct_answer": "胸部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "听到这个消息，我的胸部很难过。", "explanation": "这里应该用〈心〉。“难过”是心里的感受，胸部是身体部位，不能感到难过。"}, {"text": "她的胸部跳得厉害，手都在抖。", "explanation": "这里应该用〈心脏〉。“心脏跳得厉害”是常见说法，胸部本身不会跳动。"}, {"text": "这位运动员的胸部活量很大，跑步很有耐力。", "explanation": "这里应该用〈肺〉。“肺活量”指肺的容量，“胸部活量”不成立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87462, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "医生给他的一只胸部做了检查。", "corrected_sentence": "医生给他的胸部做了检查。", "error_description": "“只”是用于成对器官中一个的量词，“胸部”是整体，前面不能加“一只”；应去掉“一只”，说“他的胸部”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87462, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他受伤地胸部开始渗血了。", "corrected_sentence": "他受伤的胸部开始渗血了。", "error_description": "“受伤”修饰名词“胸部”，应用“的”；“地”用于修饰动词，这里用“地”是错误，应改为“受伤的胸部”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e46fd107-a302-4424-8988-27b2811a6f93') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87463, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "奴役", "is_correct": true, "explanation": "反义：“解放”使人摆脱被奴役的处境，“奴役”正是它所针对的状态，二者相对。"}, {"text": "保护", "is_correct": false, "explanation": "无关：“保护”是护卫、维护，不是“解放”的反义词。"}, {"text": "建设", "is_correct": false, "explanation": "无关：“建设”指修建、发展，与“解放”不构成反义关系。"}, {"text": "团结", "is_correct": false, "explanation": "无关：“团结”指人与人齐心合作，与“解放”没有反义关系。"}], "correct_answer": "奴役", "explanations": {"奴役": "反义：“解放”使人摆脱被奴役的处境，“奴役”正是它所针对的状态，二者相对。", "保护": "无关：“保护”是护卫、维护，不是“解放”的反义词。", "建设": "无关：“建设”指修建、发展，与“解放”不构成反义关系。", "团结": "无关：“团结”指人与人齐心合作，与“解放”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87463, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "奴役", "is_correct": true, "explanation": "反义：“解放”使人摆脱被奴役的处境，“奴役”正是它所针对的状态，二者相对。"}, {"text": "管理", "is_correct": false, "explanation": "无关：“管理”指料理、约束，不是“解放”的反义词。"}, {"text": "开发", "is_correct": false, "explanation": "无关：“开发”指利用资源、促进发展，与“解放”不构成反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "无关：“研究”指探求事理，与“解放”没有反义关系。"}], "correct_answer": "奴役", "explanations": {"奴役": "反义：“解放”使人摆脱被奴役的处境，“奴役”正是它所针对的状态，二者相对。", "管理": "无关：“管理”指料理、约束，不是“解放”的反义词。", "开发": "无关：“开发”指利用资源、促进发展，与“解放”不构成反义关系。", "研究": "无关：“研究”指探求事理，与“解放”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87463, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "解放是让被关住的人自由，让他们不再受苦。", "primary_collocate": null, "pronunciation": "jiě fàng", "ipa": "tɕjɛ˨˩ fɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "国王解放了所有的奴隶。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "林肯解放了很多黑人奴隶。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们解放了关在山洞里的人。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们把关着的工人都解放了。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位将军解放了几百个战俘。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奴隶得到解放，不用再受苦了。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想解放这些关在矿里的孩子。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好心的老板解放了他的仆人。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束后，战俘终于得到了解放。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们解放了关在牢里的好人。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解放了", "label": "体标"}, {"form": "解放过", "label": "体标"}], "register": "书面", "sense_fingerprint": "让被关押或被奴役的人获得自由、不再受苦", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d85bd0-60c5-4d83-8a6e-d2ea5b52a1af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87463, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解放", "is_correct": true, "explanation": "正确。解放奴隶指让奴隶获得自由、不再受奴役，与句意相符。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：辞退是解除雇员的职务，奴隶不是雇员，句意不通。"}, {"text": "解散", "is_correct": false, "explanation": "搭配：“解散”用于组织、团体，不能说解散奴隶。"}, {"text": "投降", "is_correct": false, "explanation": "配价：“投降”是不及物动词，不能带“所有的奴隶”作宾语，要说“向……投降”。"}], "explanations": {"解放": "正确。解放奴隶指让奴隶获得自由、不再受奴役，与句意相符。", "辞退": "语义：辞退是解除雇员的职务，奴隶不是雇员，句意不通。", "解散": "搭配：“解散”用于组织、团体，不能说解散奴隶。", "投降": "配价：“投降”是不及物动词，不能带“所有的奴隶”作宾语，要说“向……投降”。"}, "sentence_index": 0, "correct_answer": "解放"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把那一整箱饮料都解放了。", "explanation": "这里应该用〈打开〉。解放指使人或群体获得自由，不用于饮料等物品；开启一箱饮料要用打开。"}, {"text": "医生解放了那个垂危的病人。", "explanation": "这里应该用〈拯救〉。解放不用于挽救生命，使病人脱离死亡要用拯救。"}, {"text": "他用钱解放了自己的房子。", "explanation": "这里应该用〈赎回〉。解放指让人或群体获得自由，不用于财物；用钱把抵押的房子收回要用赎回。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87463, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解放", "is_correct": true, "explanation": "正确。解放这些孩子指让他们摆脱被关押的处境，与句意相符。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”用于场所、展览，不能说参观这些孩子。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：欢迎多用于来访的客人，与被关在矿里的孩子的处境不合。"}, {"text": "种植", "is_correct": false, "explanation": "搭配：“种植”的对象是植物，不能说种植孩子。"}], "explanations": {"解放": "正确。解放这些孩子指让他们摆脱被关押的处境，与句意相符。", "参观": "搭配：“参观”用于场所、展览，不能说参观这些孩子。", "欢迎": "语义：欢迎多用于来访的客人，与被关在矿里的孩子的处境不合。", "种植": "搭配：“种植”的对象是植物，不能说种植孩子。"}, "sentence_index": 6, "correct_answer": "解放"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "搬完箱子，他终于解放了发酸的双手。", "explanation": "这里是「摆脱束缚、使身体松快」的意思，指身体的动作，不指使被关押或被奴役的人获得自由，不符合本句的意思。"}, {"text": "我们要解放思想，大胆尝试新方法。", "explanation": "这里的“解放”是「破除旧观念的束缚」的意思，对象是思想，不指让被关住的人自由，不符合本句的意思。"}, {"text": "新机器解放了生产力，工厂产量大大提高。", "explanation": "这里的“解放”是「消除限制、使能力发挥出来」的意思，对象是生产力，不指让被关住的人自由，不符合本句的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87463, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "战士们把这群奴隶从矿里解放进去了。", "corrected_sentence": "战士们把这群奴隶从矿里解放出来了。", "error_description": "补语用错：从矿里脱离出来要用“出来”，“进去”方向相反，不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87463, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "战士们解放了过这座矿场里的奴隶，附近的人都知道。", "corrected_sentence": "战士们解放过这座矿场里的奴隶，附近的人都知道。", "error_description": "体标用错：“解放”表示曾经有过这种经历只用“过”，不能同时带“了”和“过”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87464, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "压迫", "is_correct": true, "explanation": "反义：“解放”是使地区摆脱压迫，“压迫”正是它所推翻的状态，二者相对。"}, {"text": "保护", "is_correct": false, "explanation": "无关：“保护”是护卫、维护，不是“解放”的反义词。"}, {"text": "建设", "is_correct": false, "explanation": "无关：“建设”指修建、发展，与“解放”不构成反义关系。"}, {"text": "团结", "is_correct": false, "explanation": "无关：“团结”指人与人齐心合作，与“解放”没有反义关系。"}], "correct_answer": "压迫", "explanations": {"压迫": "反义：“解放”是使地区摆脱压迫，“压迫”正是它所推翻的状态，二者相对。", "保护": "无关：“保护”是护卫、维护，不是“解放”的反义词。", "建设": "无关：“建设”指修建、发展，与“解放”不构成反义关系。", "团结": "无关：“团结”指人与人齐心合作，与“解放”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87464, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "压迫", "is_correct": true, "explanation": "反义：“解放”是使地方摆脱压迫，“压迫”正是它所推翻的状态，二者相对。"}, {"text": "管理", "is_correct": false, "explanation": "无关：“管理”指料理、约束，不是“解放”的反义词。"}, {"text": "开发", "is_correct": false, "explanation": "无关：“开发”指利用资源、促进发展，与“解放”不构成反义关系。"}, {"text": "研究", "is_correct": false, "explanation": "无关：“研究”指探求事理，与“解放”没有反义关系。"}], "correct_answer": "压迫", "explanations": {"压迫": "反义：“解放”是使地方摆脱压迫，“压迫”正是它所推翻的状态，二者相对。", "管理": "无关：“管理”指料理、约束，不是“解放”的反义词。", "开发": "无关：“开发”指利用资源、促进发展，与“解放”不构成反义关系。", "研究": "无关：“研究”指探求事理，与“解放”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87464, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "推翻压迫，使人或地方得到自由和发展。", "primary_collocate": null, "pronunciation": "jiě fàng", "ipa": "tɕjɛ˨˩ fɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "军队解放了这座城市，人们都很高兴。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们为了解放人民，战斗了很多年。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家终于得到了解放，人民有了自由。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他带领大家解放了整个地区。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战士们解放了许多村子，农民有了自己的土地。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想解放受压迫的穷人，让大家过上好日子。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "革命的目的是解放人民，发展经济。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座小城解放以后，生活慢慢变好了。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争结束时，军队解放了那个小岛。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们要解放这个地方，让人们自由地生活。", "target_word": "解放", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "解放了", "label": "体标"}, {"form": "解放过", "label": "体标"}], "register": "书面", "sense_fingerprint": "推翻压迫、使人民或地区获得自由与发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '28d85bd0-60c5-4d83-8a6e-d2ea5b52a1af') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87464, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "解放", "is_correct": true, "explanation": "正确。解放指推翻压迫、使城市获得自由，与后半句“人们都很高兴”相符。"}, {"text": "轰炸", "is_correct": false, "explanation": "语义：轰炸会毁坏城市，人们不会因此高兴，与后半句矛盾。"}, {"text": "围困", "is_correct": false, "explanation": "语义：围困使城内的人无法自由出入，与“人们都很高兴”矛盾。"}, {"text": "解散", "is_correct": false, "explanation": "搭配：“解散”用于组织、队伍，不能说解散一座城市。"}], "explanations": {"解放": "正确。解放指推翻压迫、使城市获得自由，与后半句“人们都很高兴”相符。", "轰炸": "语义：轰炸会毁坏城市，人们不会因此高兴，与后半句矛盾。", "围困": "语义：围困使城内的人无法自由出入，与“人们都很高兴”矛盾。", "解散": "搭配：“解散”用于组织、队伍，不能说解散一座城市。"}, "sentence_index": 0, "correct_answer": "解放"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察解放了那个没有犯罪的嫌疑人，让他回家了。", "explanation": "这里应该用〈释放〉。解放指推翻压迫、使人或地方获得自由，此处并无压迫可推翻；放走被拘留的嫌疑人要用释放。"}, {"text": "消防员解放了被困在楼里的孩子。", "explanation": "这里应该用〈解救〉。解放用于推翻压迫的社会层面；从危险中救出被困的人要用解救。"}, {"text": "这位医生解放了那个濒临死亡的病人。", "explanation": "这里应该用〈拯救〉。解放不用于挽救生命，使人脱离死亡要用拯救。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87464, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "解放", "is_correct": true, "explanation": "正确。革命的目的是解放人民，即使人民摆脱压迫，与句意相符。"}, {"text": "压迫", "is_correct": false, "explanation": "语义：压迫与革命的目的相反，革命要解放人民，不是压迫人民。"}, {"text": "欺骗", "is_correct": false, "explanation": "语义：欺骗人民同样与革命的目的相反，不符合句意。"}, {"text": "参加", "is_correct": false, "explanation": "配价：“参加”要带活动、组织作宾语，不能说参加人民。"}], "explanations": {"解放": "正确。革命的目的是解放人民，即使人民摆脱压迫，与句意相符。", "压迫": "语义：压迫与革命的目的相反，革命要解放人民，不是压迫人民。", "欺骗": "语义：欺骗人民同样与革命的目的相反，不符合句意。", "参加": "配价：“参加”要带活动、组织作宾语，不能说参加人民。"}, "sentence_index": 6, "correct_answer": "解放"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他终于解放了那双被绳子绑住的手。", "explanation": "这里的“解放”是「解开束缚、使身体活动自由」的意思，指手脚的活动，不指推翻压迫、使地方获得自由和发展，不符合本句的意思。"}, {"text": "我们要解放思想，大胆尝试新方法。", "explanation": "这里的“解放”是「破除旧观念的束缚」的意思，对象是思想，不指推翻压迫、使地方获得自由和发展，不符合本句的意思。"}, {"text": "洗衣机解放了家里人的双手。", "explanation": "这里的“解放”是「使人摆脱繁重劳动」的意思，指省去家务，不指推翻压迫、使地方获得自由和发展，不符合本句的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87464, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "战士们把这个村子从敌人手里解放进去了。", "corrected_sentence": "战士们把这个村子从敌人手里解放出来了。", "error_description": "补语用错：从敌人手里脱出要用“出来”，“进去”方向相反，不成立。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87464, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这支军队解放了过这座城市，老人们都记得。", "corrected_sentence": "这支军队解放过这座城市，老人们都记得。", "error_description": "体标用错：“解放”后表示曾经有过这种经历只用“过”，不能同时带“了”和“过”，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9e93f148-eaa8-4931-b753-d5770c685b2f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
