INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87467, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "至此是到了这里，或到了这个时候。", "primary_collocate": null, "pronunciation": "zhì cǐ", "ipa": "ʈʂɻ̩˥˩ tsʰɹ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "至此，他们的旅行结束了。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走了一天，至此才看到村子。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "全部问题都解决了，至此大家放心了。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车开到山口，至此路就断了。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他等了十年，至此终于见到了女儿。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "至此，这个故事讲完了。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试结束，至此一学期的学习完成了。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车开到海边，至此不能再往前了。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他努力多年，至此才有了自己的房子。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "至此，一切都清楚了。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词：到了这里或这个时候，表示事情进行到此处", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5557fc-539b-4cb6-b9b1-8d2660c41b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87467, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "至此", "is_correct": true, "explanation": "至此：到了这里，旅行才结束，符合句意。"}, {"text": "一直", "is_correct": false, "explanation": "语义：“一直”表示动作持续不断，不能放在句首引出“旅行结束了”这样的完成结果。"}, {"text": "随即", "is_correct": false, "explanation": "语义：“随即”表示紧接某事之后，句中没有可以接续的前一事件。"}, {"text": "正在", "is_correct": false, "explanation": "语法：“正在”表示动作进行中，与“结束了”的完成义矛盾。"}], "explanations": {"至此": "至此：到了这里，旅行才结束，符合句意。", "一直": "语义：“一直”表示动作持续不断，不能放在句首引出“旅行结束了”这样的完成结果。", "随即": "语义：“随即”表示紧接某事之后，句中没有可以接续的前一事件。", "正在": "语法：“正在”表示动作进行中，与“结束了”的完成义矛盾。"}, "sentence_index": 0, "correct_answer": "至此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "至此，我们将每周见面。", "explanation": "这里应该用〈今后〉。至此指到目前为止，不能与表示将来的“将”搭配。"}, {"text": "我们至此要准备材料。", "explanation": "这里应该用〈首先〉。至此表示到目前为止，不用来表示先做某件事。"}, {"text": "他吃完饭，至此去散步。", "explanation": "这里应该用〈然后〉。至此表示到目前为止，不表示接着发生的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87467, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "至此", "is_correct": true, "explanation": "至此：到这个时候，一学期的学习才完成，符合句意。"}, {"text": "仍旧", "is_correct": false, "explanation": "语义：“仍旧”表示延续不变，与“学习完成”的结束不合。"}, {"text": "竟然", "is_correct": false, "explanation": "语义：“竟然”表示出乎意料，句中并没有意外的情况。"}, {"text": "立即", "is_correct": false, "explanation": "搭配：“立即”需要紧接动作，不能用来修饰“一学期的学习完成了”这样的结果。"}], "explanations": {"至此": "至此：到这个时候，一学期的学习才完成，符合句意。", "仍旧": "语义：“仍旧”表示延续不变，与“学习完成”的结束不合。", "竟然": "语义：“竟然”表示出乎意料，句中并没有意外的情况。", "立即": "搭配：“立即”需要紧接动作，不能用来修饰“一学期的学习完成了”这样的结果。"}, "sentence_index": 6, "correct_answer": "至此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她一边做饭，至此听音乐。", "explanation": "这里应该用〈同时〉。至此表示到目前为止，不表示两个动作同时进行。"}, {"text": "他听到消息，至此哭了起来。", "explanation": "这里应该用〈当即〉。至此表示到了这个时候，不表示立刻发生。"}, {"text": "我们十年前至此开了一家店。", "explanation": "这里应该用〈当时〉。至此指到目前为止，不能用来指过去的某个时间点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87467, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "到至此，他们的工作全部完成了。", "corrected_sentence": "至此，他们的工作全部完成了。", "error_description": "“至此”本身已含“到”的意思，前面不能再加“到”，应说“至此”，不说“到至此”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87467, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很至此，一切问题都解决了。", "corrected_sentence": "至此，一切问题都解决了。", "error_description": "“至此”是副词，不能受程度副词“很”修饰，应删去“很”，说“至此，一切问题都解决了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
