INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87468, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "到这里；到这个时候。", "primary_collocate": null, "pronunciation": "zhì cǐ", "ipa": "ʈʂɻ̩˥˩ tsʰɹ̩˨˩˦", "syllable_count": 2, "sentences": [{"text": "会议开了三个小时，至此才结束。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "路修到山下，至此已经不能走车了。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他找了一年工作，至此终于成功。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "至此，我们的计划全部完成。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师讲完课文，至此今天的课结束了。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛打了三场，至此他们赢了两场。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "至此，大家才知道真话。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水流到山下，至此变宽了。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书读到最后，至此我才明白他的意思。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "信写到最后，至此我想说的都说了。", "target_word": "至此", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "副词：到这里、到这个时候，指地点或时间的终点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb5557fc-539b-4cb6-b9b1-8d2660c41b8d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87468, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "至此", "is_correct": true, "explanation": "至此：到这个时候才结束，正符合句中“开了三个小时”的时间过程。"}, {"text": "立即", "is_correct": false, "explanation": "语义：“立即”表示马上，与“开了三个小时”的时间跨度矛盾。"}, {"text": "从此", "is_correct": false, "explanation": "搭配：“从此”表示从某时起的新状态，不能用在“才结束”前。"}, {"text": "同时", "is_correct": false, "explanation": "语义：“同时”表示同一时间，与“开了三个小时才结束”的先后顺序不合。"}], "explanations": {"至此": "至此：到这个时候才结束，正符合句中“开了三个小时”的时间过程。", "立即": "语义：“立即”表示马上，与“开了三个小时”的时间跨度矛盾。", "从此": "搭配：“从此”表示从某时起的新状态，不能用在“才结束”前。", "同时": "语义：“同时”表示同一时间，与“开了三个小时才结束”的先后顺序不合。"}, "sentence_index": 0, "correct_answer": "至此"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "至此，我们将搬进新房子。", "explanation": "这里应该用〈届时〉。至此指到目前为止，不能与表示将来的“将”搭配。"}, {"text": "因为下大雨，至此比赛取消了。", "explanation": "这里应该用〈因此〉。至此表示到这个时候为止，不能表示因果关系。"}, {"text": "我下班后，至此去健身房锻炼了。", "explanation": "这里应该用〈之后〉。至此表示到目前为止，不能接在动作后表示先后顺序。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87468, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "至此", "is_correct": true, "explanation": "至此：到了这一步，大家才知道真话，符合句意。"}, {"text": "随即", "is_correct": false, "explanation": "语义：“随即”表示紧接着发生，与“才知道”的迟迟才明白不合。"}, {"text": "仍旧", "is_correct": false, "explanation": "语义：“仍旧”表示延续不变，与“才知道”表示新的发现不合。"}, {"text": "顿时", "is_correct": false, "explanation": "语义：“顿时”表示突然，与“才”表示的迟缓不合。"}], "explanations": {"至此": "至此：到了这一步，大家才知道真话，符合句意。", "随即": "语义：“随即”表示紧接着发生，与“才知道”的迟迟才明白不合。", "仍旧": "语义：“仍旧”表示延续不变，与“才知道”表示新的发现不合。", "顿时": "语义：“顿时”表示突然，与“才”表示的迟缓不合。"}, "sentence_index": 6, "correct_answer": "至此"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一边吃饭，至此看书。", "explanation": "这里应该用〈同时〉。至此表示到目前为止，不表示两个动作同时进行。"}, {"text": "他听完消息，至此离开了。", "explanation": "这里应该用〈当即〉。至此表示到了这个时候，不表示立刻发生。"}, {"text": "他听到门铃，至此去开门了。", "explanation": "这里应该用〈随即〉。至此表示到目前为止，不表示紧接着发生的动作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87468, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "到至此，他们终于完成了任务。", "corrected_sentence": "至此，他们终于完成了任务。", "error_description": "“至此”本身已含“到”的意思，前面不能再加“到”，应说“至此”，不说“到至此”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87468, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "很至此，他终于明白了这件事的原因。", "corrected_sentence": "至此，他终于明白了这件事的原因。", "error_description": "“至此”是副词，不能受程度副词“很”修饰，应删去“很”，说“至此，他终于明白了这件事的原因”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49ae9169-ef07-43c7-8a80-89a7fba3a92a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87469, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87469, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87469, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "警告是提前告诉别人这样做不行，不然会有坏事。", "primary_collocate": null, "pronunciation": "jǐng gào", "ipa": "tɕiŋ˨˩˦ kau˥˩", "syllable_count": 2, "sentences": [{"text": "医生警告他，再不戒烟会生病。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师警告大家，考试作弊就要退学。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸警告我，河边很危险，别去。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板警告客人，别碰热锅，不然会烫伤。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "气象台警告市民，明天有暴雨，不要出门。", "target_word": "警告", "complexity_tier": "T3", "furigana": "qì xiàng tái jǐng gào shì mín, míng tiān yǒu bào yǔ, bù yào chū mén.", "sentence_source": "generated"}, {"text": "妈妈警告过我，糖吃多了牙会坏。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他警告朋友，这样做会有大麻烦。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "牌子警告游客，水很深，不能游泳。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生早就警告过他，喝酒太多不好。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我警告你，再不走就赶不上火车了。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "警告了", "label": "体标"}, {"form": "警告过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：提前告诉别人某种做法有危险或会有坏结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f0f3827-7eef-4040-8225-662f43c0b4c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87469, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "警告", "is_correct": true, "explanation": "“警告”指提前告诉别人某种做法有危险或会有坏结果。"}, {"text": "敬告", "is_correct": false, "explanation": "jìng 与 jǐng 声调不同（第四声与第三声），意思是恭敬地告知，不是提醒危险。"}, {"text": "警报", "is_correct": false, "explanation": "bào 与 gào 声母不同（b 与 g），意思是紧急情况下发出的信号。"}, {"text": "警号", "is_correct": false, "explanation": "hào 与 gào 声母不同（h 与 g），意思是警察的编号。"}], "explanations": {"警告": "“警告”指提前告诉别人某种做法有危险或会有坏结果。", "敬告": "jìng 与 jǐng 声调不同（第四声与第三声），意思是恭敬地告知，不是提醒危险。", "警报": "bào 与 gào 声母不同（b 与 g），意思是紧急情况下发出的信号。", "警号": "hào 与 gào 声母不同（h 与 g），意思是警察的编号。"}, "sentence_index": null, "correct_answer": "警告"}, "level_3": {"options": [{"text": "警告", "is_correct": true, "explanation": "“警告”指提前告知有坏结果的做法，与“再不戒烟会生病”一致。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：表扬是肯定好的表现，与“再不戒烟会生病”的警示相反。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”针对值得肯定的行为，不能接坏结果的警示。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：感谢是对帮助的回应，与“会生病”的警示毫无关联。"}], "explanations": {"警告": "“警告”指提前告知有坏结果的做法，与“再不戒烟会生病”一致。", "表扬": "语义：表扬是肯定好的表现，与“再不戒烟会生病”的警示相反。", "赞美": "搭配：“赞美”针对值得肯定的行为，不能接坏结果的警示。", "感谢": "语义：感谢是对帮助的回应，与“会生病”的警示毫无关联。"}, "sentence_index": 0, "correct_answer": "警告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司警告员工，明天放假。", "explanation": "这里应该用〈通知〉。警告提示的是危险或坏结果，放假是好事，不能用警告。"}, {"text": "老师警告大家，明天去公园玩。", "explanation": "这里应该用〈通知〉。警告提示的是危险或坏结果，去公园玩是好事，只是告诉大家安排，应用通知。"}, {"text": "医生警告他每天散步。", "explanation": "这里应该用〈建议〉。警告说的是有危险或坏结果的事，每天散步是有益的，应用建议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87469, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警告", "is_correct": true, "explanation": "“警告”指提前告知有危险的做法，与“这样做会有大麻烦”一致。"}, {"text": "恭喜", "is_correct": false, "explanation": "语义：恭喜是祝贺好事，与“会有大麻烦”的警示矛盾。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：安慰是宽慰对方，与“大麻烦”的警示正好相反。"}, {"text": "称赞", "is_correct": false, "explanation": "搭配：“称赞”针对好的表现，“这样做”指不当的做法，搭配不当。"}], "explanations": {"警告": "“警告”指提前告知有危险的做法，与“这样做会有大麻烦”一致。", "恭喜": "语义：恭喜是祝贺好事，与“会有大麻烦”的警示矛盾。", "安慰": "语义：安慰是宽慰对方，与“大麻烦”的警示正好相反。", "称赞": "搭配：“称赞”针对好的表现，“这样做”指不当的做法，搭配不当。"}, "sentence_index": 6, "correct_answer": "警告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朋友警告我，周末去看电影。", "explanation": "这里应该用〈邀请〉。警告说的是有危险或坏结果的事，邀请看电影不是坏事。"}, {"text": "老师警告他字写得好。", "explanation": "这里应该用〈表扬〉。警告提示的是危险或坏结果，字写得好不是坏结果。"}, {"text": "我警告他买一本书。", "explanation": "这里应该用〈劝〉。警告说的是有危险或坏结果的事，买书不是坏事，应用劝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87469, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈警告我过，别在河边玩，很危险。", "corrected_sentence": "妈妈警告过我，别在河边玩，很危险。", "error_description": "“过”应紧跟动词“警告”表示经历，应说“警告过我”；写成“警告我过”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87469, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他警告了我过，别再碰那根电线。", "corrected_sentence": "他警告了我，别再碰那根电线。", "error_description": "“了”与“过”不能同时附在动词“警告”后面；这里表示已完成的告诫，应去掉“过”，说“警告了我”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
