INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87470, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对做错事或将做错事的人提出告诫，使其引起注意。", "primary_collocate": null, "pronunciation": "jǐng gào", "ipa": "tɕiŋ˨˩˦ kau˥˩", "syllable_count": 2, "sentences": [{"text": "老师严厉警告我们，不许再迟到。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察警告他，不要再酒后开车。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈警告过弟弟，不许再玩火。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司警告了常常迟到的小王。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我警告你，再说谎我就不理你了。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长严厉警告打架的学生。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师已经警告他两次了，他还是不听。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "裁判警告了那个犯规的球员。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察警告过他，不许在这里停车。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "邻居警告我们别再吵了，不然就报警。", "target_word": "警告", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "警告了", "label": "体标"}, {"form": "警告过", "label": "体标"}], "register": "中性", "sense_fingerprint": "动词：对做错事或将做错事的人严肃告诫，要求其改正", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9f0f3827-7eef-4040-8225-662f43c0b4c8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87470, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "警告", "is_correct": true, "explanation": "“警告”正是对做错事的人严厉告诫，使其引起注意。"}, {"text": "敬告", "is_correct": false, "explanation": "jìng 与 jǐng 声调不同（第四声与第三声），意思是恭敬地告知，不是严厉告诫。"}, {"text": "警报", "is_correct": false, "explanation": "bào 与 gào 声母不同（b 与 g），意思是紧急情况下发出的信号，不是告诫。"}, {"text": "警号", "is_correct": false, "explanation": "hào 与 gào 声母不同（h 与 g），意思是警察的编号。"}], "explanations": {"警告": "“警告”正是对做错事的人严厉告诫，使其引起注意。", "敬告": "jìng 与 jǐng 声调不同（第四声与第三声），意思是恭敬地告知，不是严厉告诫。", "警报": "bào 与 gào 声母不同（b 与 g），意思是紧急情况下发出的信号，不是告诫。", "警号": "hào 与 gào 声母不同（h 与 g），意思是警察的编号。"}, "sentence_index": null, "correct_answer": "警告"}, "level_3": {"options": [{"text": "警告", "is_correct": true, "explanation": "“警告”是严厉告诫，与“严厉”和“不许再迟到”一致。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：表扬是肯定好的表现，与“不许再迟到”的训斥语气相反。"}, {"text": "赞美", "is_correct": false, "explanation": "搭配：“赞美”针对值得肯定的行为，与“严厉”不搭配。"}, {"text": "感谢", "is_correct": false, "explanation": "配价：“感谢”不能把“不许再迟到”这类禁令作为内容，句子不通。"}], "explanations": {"警告": "“警告”是严厉告诫，与“严厉”和“不许再迟到”一致。", "表扬": "语义：表扬是肯定好的表现，与“不许再迟到”的训斥语气相反。", "赞美": "搭配：“赞美”针对值得肯定的行为，与“严厉”不搭配。", "感谢": "配价：“感谢”不能把“不许再迟到”这类禁令作为内容，句子不通。"}, "sentence_index": 0, "correct_answer": "警告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈警告我，今天要带伞。", "explanation": "这里应该用〈提醒〉。警告针对做错事或将做错事的人，带伞不是错事，只是提示，应用提醒。"}, {"text": "老板警告员工，这个月的奖金多发一倍。", "explanation": "这里应该用〈宣布〉。警告针对做错事或将做错事的人，发奖金是好消息，不是错事，应用宣布。"}, {"text": "学校警告我们，下周放假。", "explanation": "这里应该用〈告知〉。警告针对做错事的人；放假不是错事，只是把消息告诉大家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87470, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "警告", "is_correct": true, "explanation": "“警告”表示严厉告诫，与“已经两次了，他还是不听”的责备语境一致。"}, {"text": "夸奖", "is_correct": false, "explanation": "搭配：“夸奖”针对做得好的事，“他还是不听”是不好的表现，不能这样搭配。"}, {"text": "恭喜", "is_correct": false, "explanation": "语义：恭喜是祝贺好事，与“两次了，他还是不听”的责备语境相反。"}, {"text": "安慰", "is_correct": false, "explanation": "语义：安慰是宽慰对方，与“他还是不听”所表达的责备不符。"}], "explanations": {"警告": "“警告”表示严厉告诫，与“已经两次了，他还是不听”的责备语境一致。", "夸奖": "搭配：“夸奖”针对做得好的事，“他还是不听”是不好的表现，不能这样搭配。", "恭喜": "语义：恭喜是祝贺好事，与“两次了，他还是不听”的责备语境相反。", "安慰": "语义：安慰是宽慰对方，与“他还是不听”所表达的责备不符。"}, "sentence_index": 6, "correct_answer": "警告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我警告他买一本书。", "explanation": "这里应该用〈劝〉。警告针对做错事或将做错事的人，买书不是错事，应用劝。"}, {"text": "老师警告他作业写得认真。", "explanation": "这里应该用〈表扬〉。警告针对做错事的人，作业写得认真是好的表现，应用表扬。"}, {"text": "医生警告他每天散步。", "explanation": "这里应该用〈建议〉。警告针对做错事或将做错事的人，每天散步不是错事，应用建议。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87470, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸警告弟弟过，不要在马路上跑。", "corrected_sentence": "爸爸警告过弟弟，不要在马路上跑。", "error_description": "“过”应紧跟动词“警告”，应说“警告过弟弟”；写成“警告弟弟过”是错误的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87470, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我已经警告他了一次。", "corrected_sentence": "我已经警告了他一次。", "error_description": "“了”应紧跟动词“警告”，写成“警告他了一次”是错误的，应说“警告了他一次”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ef175001-3b2f-40fa-a90b-63d5df1dce81') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
