INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (87471, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "提是用手拿着东西，让它垂在下面。", "primary_collocate": null, "pronunciation": "tí", "ipa": "tʰi˧˥", "syllable_count": 1, "sentences": [{"text": "他手里提着一个大箱子。", "target_word": "提", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈提着菜回家。", "target_word": "提", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我帮你提这个包吧。", "target_word": "提", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他一只手提水桶。", "target_word": "提", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "小孩提不动那桶水。", "target_word": "提", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她把行李提上了楼。", "target_word": "提", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你提着这么多东西，累不累？", "target_word": "提", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他提了两大桶水，手很疼。", "target_word": "提", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用一只手提着书包，走进教室。", "target_word": "提", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人用右手提着灯走在前面。", "target_word": "提", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "提着", "label": "持续体"}, {"form": "提过", "label": "经历体"}, {"form": "提了", "label": "完成体"}], "register": "中性", "sense_fingerprint": "提:用手拎着东西，东西垂在手下", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '986f312e-72c3-468e-8424-eadc7ad44fc3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
